package com.waypointer.preset;

import com.waypointer.model.Category;
import com.waypointer.model.Library;
import com.waypointer.model.Waypoint;
import com.waypointer.model.WorldPointPacker;
import com.waypointer.service.WaypointStore;
import java.util.Arrays;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;

public class PresetImportTest
{
    private static Preset preset(String category, PresetWaypoint... wps)
    {
        return new Preset(category, "set description", 99, Arrays.asList(wps));
    }

    @Test
    public void singleEntryLibraryMapsEveryField()
    {
        PresetWaypoint wp = new PresetWaypoint("GE", "central hub", 3164, 3486, 0);
        Library lib = PresetImport.singleEntryLibrary(preset("Banks", wp), wp);

        assertEquals(1, lib.getCategories().size());
        Category c = lib.getCategories().get(0);
        assertEquals("Banks", c.getName());
        assertTrue("preset category must be flagged bundled", c.isBundled());
        assertEquals(Integer.valueOf(99), c.getIconId());

        assertEquals(1, lib.getWaypoints().size());
        Waypoint w = lib.getWaypoints().get(0);
        assertEquals("GE", w.getName());
        assertEquals("central hub", w.getNotes());
        assertEquals(c.getId(), w.getCategoryId());
        assertEquals(WorldPointPacker.pack(3164, 3486, 0), w.getPackedWorldPoint());
    }

    @Test
    public void nullDescriptionBecomesEmptyNotes()
    {
        PresetWaypoint wp = new PresetWaypoint("Spot", null, 3000, 3000, 0);
        Library lib = PresetImport.singleEntryLibrary(preset("Cat", wp), wp);
        assertEquals("", lib.getWaypoints().get(0).getNotes());
    }

    @Test
    public void addingThroughStoreCreatesThenMergesByCategoryName()
    {
        WaypointStore store = new WaypointStore();
        store.bootstrap(new Library());

        PresetWaypoint a = new PresetWaypoint("GE", "", 3164, 3486, 0);
        PresetWaypoint b = new PresetWaypoint("Falador", "", 2945, 3368, 0);
        store.importMerge(PresetImport.singleEntryLibrary(preset("Banks", a), a));
        store.importMerge(PresetImport.singleEntryLibrary(preset("Banks", b), b));

        Category banks = store.getCategoryByName("Banks");
        assertNotNull("Banks category created by the first add", banks);
        assertEquals("second add merges into the existing category",
            2, store.getWaypointsInCategory(banks.getId()).size());
    }
}

package com.waypointer.preset;

import com.google.gson.Gson;
import java.util.List;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

public class PresetCatalogTest
{
    private final Gson gson = new Gson();
    private final PresetCatalog catalog = new PresetCatalog(gson);

    @Test
    public void parsesValidJson()
    {
        String json = "{\"presets\":[{\"category\":\"Banks\",\"description\":\"d\","
            + "\"icon\":12,\"waypoints\":[{\"name\":\"GE\",\"description\":\"hub\","
            + "\"x\":3164,\"y\":3486,\"plane\":0}]}]}";
        List<Preset> presets = catalog.parse(json);
        assertEquals(1, presets.size());
        Preset p = presets.get(0);
        assertEquals("Banks", p.getCategory());
        assertEquals(Integer.valueOf(12), p.getIcon());
        assertEquals(1, p.getWaypoints().size());
        assertEquals("GE", p.getWaypoints().get(0).getName());
        assertEquals(3164, p.getWaypoints().get(0).getX());
    }

    @Test
    public void malformedJsonYieldsEmptyList()
    {
        assertTrue(catalog.parse("{not valid json").isEmpty());
    }

    @Test
    public void nullAndEmptyObjectYieldEmptyList()
    {
        assertTrue(catalog.parse("null").isEmpty());
        assertTrue(catalog.parse("{}").isEmpty());
    }

    @Test
    public void loadsBundledResource()
    {
        assertFalse("bundled preset-waypoints.json should contain presets",
            catalog.getPresets().isEmpty());
    }
}

package com.waypointer.preset;

import com.google.gson.Gson;
import java.util.List;
import org.junit.Test;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;

public class PresetFileValidityTest
{
    @Test
    public void bundledPresetsAreInternallyConsistent()
    {
        Gson gson = new Gson();
        List<Preset> presets = new PresetCatalog(gson).getPresets();
        assertFalse("preset catalog must not be empty", presets.isEmpty());
        for (Preset p : presets)
        {
            assertNotNull("preset category must be set", p.getCategory());
            assertFalse("preset category must be non-blank", p.getCategory().trim().isEmpty());
            assertNotNull("preset waypoint list must be set", p.getWaypoints());
            for (PresetWaypoint wp : p.getWaypoints())
            {
                assertNotNull("waypoint name must be set", wp.getName());
                assertFalse("waypoint name must be non-blank", wp.getName().trim().isEmpty());
                assertTrue("x out of range: " + wp.getX(), wp.getX() >= 0 && wp.getX() <= 32767);
                assertTrue("y out of range: " + wp.getY(), wp.getY() >= 0 && wp.getY() <= 32767);
                assertTrue("plane out of range: " + wp.getPlane(),
                    wp.getPlane() >= 0 && wp.getPlane() <= 3);
            }
        }
    }
}

package com.waypointer.model;

import net.runelite.api.coords.WorldPoint;
import org.junit.Test;
import static org.junit.Assert.*;

public class WorldPointPackerTest
{
    @Test
    public void packAndUnpackRoundTrip()
    {
        WorldPoint wp = new WorldPoint(3200, 3200, 0);
        int packed = WorldPointPacker.pack(wp);
        WorldPoint back = WorldPointPacker.unpack(packed);
        assertEquals(wp.getX(), back.getX());
        assertEquals(wp.getY(), back.getY());
        assertEquals(wp.getPlane(), back.getPlane());
    }

    @Test
    public void packPreservesPlane()
    {
        WorldPoint wp = new WorldPoint(2500, 9800, 3);
        int packed = WorldPointPacker.pack(wp);
        assertEquals(2500, WorldPointPacker.getX(packed));
        assertEquals(9800, WorldPointPacker.getY(packed));
        assertEquals(3, WorldPointPacker.getPlane(packed));
    }

    @Test
    public void undefinedSentinelDistinguishable()
    {
        assertEquals(WorldPointPacker.UNDEFINED, WorldPointPacker.UNDEFINED);
        assertNotEquals(WorldPointPacker.UNDEFINED, WorldPointPacker.pack(new WorldPoint(0, 0, 0)));
    }

    @Test
    public void arrivedTrueWithinRadiusSamePlane()
    {
        int target = WorldPointPacker.pack(new WorldPoint(3200, 3200, 0));
        assertTrue(WorldPointPacker.arrived(target, new WorldPoint(3200, 3200, 0), 3));
        assertTrue(WorldPointPacker.arrived(target, new WorldPoint(3203, 3200, 0), 3));
    }

    @Test
    public void arrivedFalseOutsideRadius()
    {
        int target = WorldPointPacker.pack(new WorldPoint(3200, 3200, 0));
        assertFalse(WorldPointPacker.arrived(target, new WorldPoint(3203, 3203, 0), 3));
    }

    @Test
    public void arrivedFalseOnDifferentPlane()
    {
        int target = WorldPointPacker.pack(new WorldPoint(3200, 3200, 0));
        assertFalse(WorldPointPacker.arrived(target, new WorldPoint(3200, 3200, 1), 3));
    }
}

package com.waypointer.model.route;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotEquals;
import static org.junit.Assert.assertNull;
import com.waypointer.model.WorldPointPacker;
import java.time.Instant;
import java.util.ArrayList;
import java.util.UUID;
import org.junit.Test;

public class RouteModelTest
{
    @Test
    public void waypointFactorySetsTypeAndTile()
    {
        RouteStep s = RouteStep.waypoint(WorldPointPacker.pack(3200, 3200, 0), "Bank");
        assertEquals(StepType.WAYPOINT, s.getType());
        assertEquals("Bank", s.getLabel());
        assertEquals(WorldPointPacker.pack(3200, 3200, 0), s.getPackedWorldPoint());
        assertNull(s.getSourceWaypointId());
    }

    @Test
    public void manualFactorySetsTypeAndUndefinedTile()
    {
        RouteStep s = RouteStep.manual("Withdraw seeds");
        assertEquals(StepType.MANUAL, s.getType());
        assertEquals("Withdraw seeds", s.getLabel());
        assertEquals(WorldPointPacker.UNDEFINED, s.getPackedWorldPoint());
    }

    @Test
    public void stepEqualityIsByIdentity()
    {
        UUID id = UUID.randomUUID();
        RouteStep a = new RouteStep(id, StepType.MANUAL, "x", WorldPointPacker.UNDEFINED, null, null);
        RouteStep b = new RouteStep(id, StepType.MANUAL, "different", WorldPointPacker.UNDEFINED, null, null);
        RouteStep c = new RouteStep(UUID.randomUUID(), StepType.MANUAL, "x", WorldPointPacker.UNDEFINED, null, null);
        assertEquals(a, b);
        assertNotEquals(a, c);
    }

    @Test
    public void routeEqualityIsByIdentity()
    {
        UUID id = UUID.randomUUID();
        Route a = new Route(id, "A", new ArrayList<>(), false, Instant.now(), 0);
        Route b = new Route(id, "B", new ArrayList<>(), true, Instant.now(), 9);
        assertEquals(a, b);
    }

    @Test
    public void newRouteLibraryHasCurrentSchemaAndEmptyRoutes()
    {
        RouteLibrary lib = new RouteLibrary();
        assertEquals(RouteLibrary.CURRENT_SCHEMA_VERSION, lib.getSchemaVersion());
        assertEquals(0, lib.getRoutes().size());
    }

    @Test
    public void boxTextOrLabelFallsBackToLabelWhenUnset()
    {
        RouteStep s = RouteStep.manual("Withdraw seeds");
        assertNull(s.getBoxText());
        assertEquals("Withdraw seeds", s.boxTextOrLabel());
    }

    @Test
    public void boxTextOrLabelFallsBackToLabelWhenEmpty()
    {
        RouteStep s = RouteStep.manual("Withdraw seeds");
        s.setBoxText("");
        assertEquals("Withdraw seeds", s.boxTextOrLabel());
    }

    @Test
    public void boxTextOrLabelUsesBoxTextWhenSet()
    {
        RouteStep s = RouteStep.manual("Bank");
        s.setBoxText("Withdraw 5 ranarr seeds");
        assertEquals("Withdraw 5 ranarr seeds", s.boxTextOrLabel());
    }
}

package com.waypointer.model;

import java.time.Instant;
import java.util.UUID;
import org.junit.Test;
import static org.junit.Assert.*;

public class LibraryTest
{
    @Test
    public void emptyLibraryHasNoWaypointsAndCurrentSchemaVersion()
    {
        Library lib = new Library();
        assertEquals(Library.CURRENT_SCHEMA_VERSION, lib.getSchemaVersion());
        assertTrue(lib.getCategories().isEmpty());
        assertTrue(lib.getWaypoints().isEmpty());
    }

    @Test
    public void canAddCategoryAndWaypoint()
    {
        Library lib = new Library();
        Category c = new Category(UUID.randomUUID(), "Bossing", 0, false, null, false);
        lib.getCategories().add(c);

        Waypoint w = new Waypoint(
            UUID.randomUUID(), "Vorkath",
            42, c.getId(), null, "", Instant.parse("2026-05-02T00:00:00Z"), 0, false, null, false);
        lib.getWaypoints().add(w);

        assertEquals(1, lib.getCategories().size());
        assertEquals(1, lib.getWaypoints().size());
        assertEquals(c.getId(), lib.getWaypoints().get(0).getCategoryId());
    }

    @Test
    public void uncategorizedSentinelDetectableViaFlag()
    {
        Category uncat = new Category(UUID.randomUUID(), "Uncategorized", 0, true, null, false);
        Category bossing = new Category(UUID.randomUUID(), "Bossing", 1, false, null, false);
        assertTrue(uncat.isUncategorized());
        assertFalse(bossing.isUncategorized());
    }

    @Test
    public void newFieldsDefaultToFalseAndNullViaNoArgsConstructor()
    {
        Waypoint w = new Waypoint();
        assertFalse(w.isPinned());
        assertNull(w.getPinnedAt());
        assertFalse(w.isBypassWildernessConfirm());
    }
}

package com.waypointer.ui;

import com.waypointer.WaypointerConfig;
import com.waypointer.model.Library;
import com.waypointer.model.Waypoint;
import com.waypointer.model.WorldPointPacker;
import com.waypointer.service.WaypointStore;
import java.awt.Component;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.ArgumentMatchers.nullable;
import static org.mockito.Mockito.*;

public class WaypointerPanelWildernessConfirmTest
{
    private WaypointStore store;
    private WaypointerConfig config;
    private Waypoint wildWp;
    private Waypoint safeWp;

    @Before
    public void setUp()
    {
        store = new WaypointStore();
        store.bootstrap(new Library());
        config = mock(WaypointerConfig.class);
        when(config.confirmBeforeWildernessPlay()).thenReturn(true);

        wildWp = store.createWaypoint(
            WorldPointPacker.pack(3093, 3525, 0), "Edgeville lever", store.getUncategorized().getId());
        safeWp = store.createWaypoint(
            WorldPointPacker.pack(3200, 3300, 0), "Varrock bank", store.getUncategorized().getId());
    }

    private static WildernessConfirmGate stubGate(boolean proceed, boolean dontAsk)
    {
        WildernessConfirmGate g = mock(WildernessConfirmGate.class);
        when(g.prompt(nullable(Component.class), any(Waypoint.class)))
            .thenReturn(new WildernessConfirmGate.Result(proceed, dontAsk));
        return g;
    }

    @Test
    public void configOffSkipsGateForWildTile()
    {
        when(config.confirmBeforeWildernessPlay()).thenReturn(false);
        WildernessConfirmGate gate = stubGate(false, false);
        assertTrue(WildernessConfirmGuard.shouldProceed(wildWp, config, gate, null, store));
        verifyNoInteractions(gate);
    }

    @Test
    public void safeTileSkipsGate()
    {
        WildernessConfirmGate gate = stubGate(false, false);
        assertTrue(WildernessConfirmGuard.shouldProceed(safeWp, config, gate, null, store));
        verifyNoInteractions(gate);
    }

    @Test
    public void bypassFlagOnWaypointSkipsGate()
    {
        store.setWaypointBypassWildernessConfirm(wildWp.getId(), true);
        WildernessConfirmGate gate = stubGate(false, false);
        assertTrue(WildernessConfirmGuard.shouldProceed(wildWp, config, gate, null, store));
        verifyNoInteractions(gate);
    }

    @Test
    public void gateProceedsWithoutDontAsk_PathRequestedNoBypassStored()
    {
        WildernessConfirmGate gate = stubGate(true, false);
        assertTrue(WildernessConfirmGuard.shouldProceed(wildWp, config, gate, null, store));
        assertFalse(store.getWaypointById(wildWp.getId()).isBypassWildernessConfirm());
    }

    @Test
    public void gateProceedsWithDontAsk_BypassStored()
    {
        WildernessConfirmGate gate = stubGate(true, true);
        assertTrue(WildernessConfirmGuard.shouldProceed(wildWp, config, gate, null, store));
        assertTrue(store.getWaypointById(wildWp.getId()).isBypassWildernessConfirm());
    }

    @Test
    public void gateCancels_ReturnsFalse_NoBypassStored()
    {
        WildernessConfirmGate gate = stubGate(false, false);
        assertFalse(WildernessConfirmGuard.shouldProceed(wildWp, config, gate, null, store));
        assertFalse(store.getWaypointById(wildWp.getId()).isBypassWildernessConfirm());
    }

    @Test
    public void gateCancelsWithDontAskTrue_ReturnsFalse_BypassNotStored()
    {
        WildernessConfirmGate gate = stubGate(false, true);
        assertFalse(WildernessConfirmGuard.shouldProceed(wildWp, config, gate, null, store));
        assertFalse(store.getWaypointById(wildWp.getId()).isBypassWildernessConfirm());
    }
}

package com.waypointer.ui;

import com.waypointer.model.Category;
import com.waypointer.model.Library;
import com.waypointer.service.WaypointStore;
import java.util.UUID;
import javax.swing.JComboBox;
import org.junit.Test;
import static org.junit.Assert.*;

public class CategoryComboControllerTest
{
    private static WaypointStore freshStore()
    {
        // In-memory store, bootstrapped with an empty library (no debounced persistence wired).
        // Mirrors the existing CaptureFormTest setup.
        WaypointStore store = new WaypointStore();
        store.bootstrap(new Library());
        return store;
    }

    @Test
    public void rebuildListsOrderedCategoriesPlusSentinel()
    {
        WaypointStore store = freshStore();
        Category a = store.createCategory("Alpha");
        JComboBox<CategoryComboItem> combo = new JComboBox<>();
        CategoryComboController c = new CategoryComboController(combo, store);

        c.rebuild(a.getId());

        // last item is the "+ New category..." sentinel
        CategoryComboItem last = combo.getItemAt(combo.getItemCount() - 1);
        assertTrue("last item should be the sentinel", last.isSentinel());
        // the requested id is selected
        CategoryComboItem sel = (CategoryComboItem) combo.getSelectedItem();
        assertNotNull(sel);
        assertEquals(a.getId(), sel.id());
    }

    @Test
    public void resolveSelectedIdReturnsUncategorizedForSentinel()
    {
        WaypointStore store = freshStore();
        JComboBox<CategoryComboItem> combo = new JComboBox<>();
        CategoryComboController c = new CategoryComboController(combo, store);
        c.rebuild(store.getUncategorized().getId());

        // select the sentinel (last item)
        combo.setSelectedIndex(combo.getItemCount() - 1);

        assertTrue(c.isSentinelSelected());
        assertEquals(store.getUncategorized().getId(), c.resolveSelectedId());
    }

    @Test
    public void resolveSelectedIdReturnsRealCategoryWhenSelected()
    {
        WaypointStore store = freshStore();
        Category a = store.createCategory("Alpha");
        JComboBox<CategoryComboItem> combo = new JComboBox<>();
        CategoryComboController c = new CategoryComboController(combo, store);
        c.rebuild(a.getId());

        assertFalse(c.isSentinelSelected());
        assertEquals(a.getId(), c.resolveSelectedId());
    }

    @Test
    public void rebuildWithUnknownIdSelectsFirstItemAndLeavesLastNonSentinelNull()
    {
        WaypointStore store = freshStore();
        store.createCategory("Alpha");
        JComboBox<CategoryComboItem> combo = new JComboBox<>();
        CategoryComboController c = new CategoryComboController(combo, store);

        // An id that is not in the store: rebuild finds no match, so it selects nothing
        // explicitly -- JComboBox defaults to index 0 -- and lastNonSentinel stays null.
        c.rebuild(UUID.randomUUID());

        assertEquals(0, combo.getSelectedIndex());
        assertFalse("first item is a real category, not the sentinel", c.isSentinelSelected());
        assertNull("no match means lastNonSentinel was never assigned", c.lastNonSentinel());
    }
}

package com.waypointer.ui;

import com.google.gson.Gson;
import java.util.HashMap;
import java.util.Map;
import java.util.UUID;
import org.junit.Test;
import static org.junit.Assert.*;

public class CollapseStateCodecTest
{
    private final CollapseStateCodec codec = new CollapseStateCodec(new Gson());

    @Test
    public void decodeEmptyStringYieldsEmptyMap()
    {
        assertTrue(codec.decode("").isEmpty());
        assertTrue(codec.decode("{}").isEmpty());
    }

    @Test
    public void encodeAndDecodeRoundTrip()
    {
        Map<UUID, Boolean> map = new HashMap<>();
        UUID a = UUID.randomUUID();
        UUID b = UUID.randomUUID();
        map.put(a, true);
        map.put(b, false);

        Map<UUID, Boolean> back = codec.decode(codec.encode(map));
        assertEquals(2, back.size());
        assertTrue(back.get(a));
        assertFalse(back.get(b));
    }

    @Test
    public void decodeMalformedReturnsEmpty()
    {
        assertTrue(codec.decode("not json").isEmpty());
    }
}

package com.waypointer.ui;

