package com.waypointer.ui;

import com.waypointer.WaypointerConfig;
import com.waypointer.model.WorldPointPacker;
import com.waypointer.service.WaypointPathfinder;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.when;

public class ActivePathBannerTest
{
    private WaypointPathfinder pathfinder;
    private WaypointerConfig config;
    private ActivePathBanner banner;
    // Flipped by tests that exercise the saved-waypoint suppression branch. Default false so the
    // existing rowless-path assertions (landmark/preset/route) keep showing the banner.
    private boolean targetHasRow;

    @Before
    public void setUp()
    {
        pathfinder = mock(WaypointPathfinder.class);
        config = mock(WaypointerConfig.class);
        when(config.showPathingBanner()).thenReturn(true);
        when(pathfinder.getActiveTarget()).thenReturn(WorldPointPacker.UNDEFINED);
        targetHasRow = false;
        banner = new ActivePathBanner(pathfinder, config, packed -> targetHasRow);
    }

    @Test
    public void hiddenWhenNoActiveTarget()
    {
        banner.refresh();
        assertFalse(banner.isVisible());
    }

    @Test
    public void visibleAndLabelledWhenPathActive()
    {
        when(pathfinder.getActiveTarget()).thenReturn(WorldPointPacker.pack(3162, 3486, 0));
        when(pathfinder.getActiveName()).thenReturn("Vorkath");
        banner.refresh();
        assertTrue(banner.isVisible());
        assertTrue("label should mention the destination, got: " + banner.getLabelText(),
            banner.getLabelText().contains("Vorkath"));
    }

    @Test
    public void hiddenWhenSettingDisabledEvenWithActiveTarget()
    {
        when(pathfinder.getActiveTarget()).thenReturn(WorldPointPacker.pack(3162, 3486, 0));
        when(pathfinder.getActiveName()).thenReturn("Vorkath");
        when(config.showPathingBanner()).thenReturn(false);
        banner.refresh();
        assertFalse(banner.isVisible());
    }

    @Test
    public void hidesAfterClearedTarget()
    {
        when(pathfinder.getActiveTarget()).thenReturn(WorldPointPacker.pack(3162, 3486, 0));
        when(pathfinder.getActiveName()).thenReturn("Vorkath");
        banner.refresh();
        assertTrue(banner.isVisible());

        when(pathfinder.getActiveTarget()).thenReturn(WorldPointPacker.UNDEFINED);
        when(pathfinder.getActiveName()).thenReturn(null);
        banner.refresh();
        assertFalse(banner.isVisible());
    }

    @Test
    public void stopButtonClearsPath()
    {
        when(pathfinder.getActiveTarget()).thenReturn(WorldPointPacker.pack(3162, 3486, 0));
        when(pathfinder.getActiveName()).thenReturn("Vorkath");
        banner.refresh();
        banner.clickStopForTest();
        verify(pathfinder).clearPath();
    }

    @Test
    public void hiddenWhenTargetHasSavedWaypointRow()
    {
        when(pathfinder.getActiveTarget()).thenReturn(WorldPointPacker.pack(3162, 3486, 0));
        when(pathfinder.getActiveName()).thenReturn("Vorkath");
        targetHasRow = true; // the row's Stop square covers this target
        banner.refresh();
        assertFalse(banner.isVisible());
    }

    @Test
    public void escapesHtmlInWaypointName()
    {
        when(pathfinder.getActiveTarget()).thenReturn(WorldPointPacker.pack(3162, 3486, 0));
        when(pathfinder.getActiveName()).thenReturn("<b>cheeky</b>");
        banner.refresh();
        String html = banner.getLabelText();
        assertFalse("raw <b> should not appear in label HTML, got: " + html,
            html.contains("<b>cheeky</b>"));
        assertTrue("escaped marker should appear, got: " + html, html.contains("&lt;b&gt;"));
    }
}

package com.waypointer.ui;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

import java.awt.BorderLayout;
import java.awt.event.MouseEvent;
import java.awt.event.MouseListener;
import java.util.ArrayList;
import java.util.List;
import javax.swing.JLabel;
import javax.swing.JPanel;
import org.junit.Test;

public class CollapsibleSectionTest
{
    // Minimal concrete section: a chevron + fixed title, two collapse-change notifications
    // captured so the test can assert toggle wiring.
    private static final class TestSection extends CollapsibleSection
    {
        private final List<Boolean> changes;

        TestSection(boolean collapsed, List<Boolean> changes)
        {
            super(collapsed, changes::add);
            this.changes = changes;
            JPanel headerRow = buildHeaderRow(2);
            add(headerRow, BorderLayout.NORTH);
            attachBody();
        }

        @Override
        protected String headerText()
        {
            return (collapsed ? "▶" : "▼") + " Test";
        }

        JLabel header() { return headerLabel; }
        JPanel bodyPanel() { return body; }
    }

    @Test
    public void startsExpandedShowsBodyAndDownChevron()
    {
        TestSection s = new TestSection(false, new ArrayList<>());
        assertTrue(s.bodyPanel().isVisible());
        assertEquals("▼ Test", s.header().getText());
        assertFalse(s.isCollapsed());
    }

    @Test
    public void clickingHeaderTogglesCollapseAndFiresCallback()
    {
        List<Boolean> changes = new ArrayList<>();
        TestSection s = new TestSection(false, changes);
        clickFirstListener(s.header());
        assertTrue(s.isCollapsed());
        assertFalse(s.bodyPanel().isVisible());
        assertEquals("▶ Test", s.header().getText());
        assertEquals(1, changes.size());
        assertEquals(Boolean.TRUE, changes.get(0));
    }

    @Test
    public void setExpandedTransientDoesNotFireCallback()
    {
        List<Boolean> changes = new ArrayList<>();
        TestSection s = new TestSection(true, changes);
        s.setExpandedTransient(true);
        assertFalse(s.isCollapsed());
        assertTrue(s.bodyPanel().isVisible());
        assertTrue("transient expand must not persist", changes.isEmpty());
        s.confirmTransientExpand();
        assertEquals(1, changes.size());
        assertEquals(Boolean.FALSE, changes.get(0));
    }

    @Test
    public void maximumSizeIsHeightCapped()
    {
        TestSection s = new TestSection(false, new ArrayList<>());
        assertEquals(Integer.MAX_VALUE, s.getMaximumSize().width);
        assertEquals(s.getPreferredSize().height, s.getMaximumSize().height);
    }

    private static void clickFirstListener(JLabel target)
    {
        MouseEvent click = new MouseEvent(target, MouseEvent.MOUSE_CLICKED,
            System.currentTimeMillis(), 0, 5, 5, 1, false);
        for (MouseListener ml : target.getMouseListeners())
        {
            ml.mouseClicked(click);
        }
    }
}

package com.waypointer.ui;

import com.waypointer.model.Category;
import com.waypointer.model.Library;
import com.waypointer.model.Waypoint;
import java.time.Instant;
import java.util.UUID;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

public class WaypointPickerModelTest
{
    private static Waypoint wp(UUID id, UUID catId)
    {
        return new Waypoint(id, "w", 1, catId, null, "",
            Instant.parse("2026-05-02T00:00:00Z"), 0, false, null, false);
    }

    @Test
    public void defaultsToAllChecked()
    {
        UUID cat = UUID.randomUUID();
        UUID a = UUID.randomUUID();
        Library lib = new Library();
        lib.getCategories().add(new Category(cat, "C", 0, false, null, false));
        lib.getWaypoints().add(wp(a, cat));

        WaypointPickerModel m = new WaypointPickerModel(lib);
        assertTrue(m.isWaypointChecked(a));
        assertEquals(WaypointPickerModel.Tri.CHECKED, m.categoryState(cat));
        assertFalse(m.isEmptySelection());
    }

    @Test
    public void childTogglesRollUpToPartialThenUnchecked()
    {
        UUID cat = UUID.randomUUID();
        UUID a = UUID.randomUUID();
        UUID b = UUID.randomUUID();
        Library lib = new Library();
        lib.getCategories().add(new Category(cat, "C", 0, false, null, false));
        lib.getWaypoints().add(wp(a, cat));
        lib.getWaypoints().add(wp(b, cat));

        WaypointPickerModel m = new WaypointPickerModel(lib);
        m.setWaypointChecked(a, false);
        assertEquals(WaypointPickerModel.Tri.PARTIAL, m.categoryState(cat));
        m.setWaypointChecked(b, false);
        assertEquals(WaypointPickerModel.Tri.UNCHECKED, m.categoryState(cat));
    }

    @Test
    public void categoryToggleCascadesToChildren()
    {
        UUID cat = UUID.randomUUID();
        UUID a = UUID.randomUUID();
        UUID b = UUID.randomUUID();
        Library lib = new Library();
        lib.getCategories().add(new Category(cat, "C", 0, false, null, false));
        lib.getWaypoints().add(wp(a, cat));
        lib.getWaypoints().add(wp(b, cat));

        WaypointPickerModel m = new WaypointPickerModel(lib);
        m.setCategoryChecked(cat, false);
        assertFalse(m.isWaypointChecked(a));
        assertFalse(m.isWaypointChecked(b));
        assertTrue(m.getSelectedWaypointIds().isEmpty());

        m.setCategoryChecked(cat, true);
        assertTrue(m.isWaypointChecked(a));
        assertEquals(2, m.getSelectedWaypointIds().size());
    }

    @Test
    public void emptyCategoryCheckTrackedExplicitly()
    {
        UUID cat = UUID.randomUUID();
        Library lib = new Library();
        lib.getCategories().add(new Category(cat, "Empty", 0, false, null, false));

        WaypointPickerModel m = new WaypointPickerModel(lib);
        assertEquals(WaypointPickerModel.Tri.CHECKED, m.categoryState(cat));
        assertTrue(m.getSelectedCategoryIds().contains(cat));

        m.setCategoryChecked(cat, false);
        assertEquals(WaypointPickerModel.Tri.UNCHECKED, m.categoryState(cat));
        assertTrue(m.isEmptySelection());
    }

    @Test
    public void selectNoneThenSelectAll()
    {
        UUID cat = UUID.randomUUID();
        UUID a = UUID.randomUUID();
        Library lib = new Library();
        lib.getCategories().add(new Category(cat, "C", 0, false, null, false));
        lib.getWaypoints().add(wp(a, cat));

        WaypointPickerModel m = new WaypointPickerModel(lib);
        m.selectNone();
        assertTrue(m.isEmptySelection());
        assertTrue(m.getSelectedWaypointIds().isEmpty());
        m.selectAll();
        assertEquals(1, m.getSelectedWaypointIds().size());
    }

    @Test
    public void partialCategoryIsExcludedFromSelectedCategoryIds()
    {
        UUID cat = UUID.randomUUID();
        UUID a = UUID.randomUUID();
        UUID b = UUID.randomUUID();
        Library lib = new Library();
        lib.getCategories().add(new Category(cat, "C", 0, false, null, false));
        lib.getWaypoints().add(wp(a, cat));
        lib.getWaypoints().add(wp(b, cat));

        WaypointPickerModel m = new WaypointPickerModel(lib);
        m.setWaypointChecked(a, false);
        assertEquals(WaypointPickerModel.Tri.PARTIAL, m.categoryState(cat));
        assertFalse(m.getSelectedCategoryIds().contains(cat));
        assertEquals(1, m.getSelectedWaypointIds().size());

        m.setWaypointChecked(a, true);
        assertEquals(WaypointPickerModel.Tri.CHECKED, m.categoryState(cat));
    }

    @Test
    public void fullyCheckedNonEmptyCategoryIsInSelectedCategoryIds()
    {
        UUID cat = UUID.randomUUID();
        UUID a = UUID.randomUUID();
        Library lib = new Library();
        lib.getCategories().add(new Category(cat, "C", 0, false, null, false));
        lib.getWaypoints().add(wp(a, cat));

        WaypointPickerModel m = new WaypointPickerModel(lib);
        assertTrue(m.getSelectedCategoryIds().contains(cat));
    }

    @Test
    public void selectAllCoversEveryCategory()
    {
        UUID c1 = UUID.randomUUID();
        UUID c2 = UUID.randomUUID();
        UUID a = UUID.randomUUID();
        UUID b = UUID.randomUUID();
        Library lib = new Library();
        lib.getCategories().add(new Category(c1, "One", 0, false, null, false));
        lib.getCategories().add(new Category(c2, "Two", 1, false, null, false));
        lib.getWaypoints().add(wp(a, c1));
        lib.getWaypoints().add(wp(b, c2));

        WaypointPickerModel m = new WaypointPickerModel(lib);
        m.selectNone();
        assertTrue(m.isEmptySelection());
        m.selectAll();
        assertEquals(2, m.getSelectedWaypointIds().size());
        assertEquals(WaypointPickerModel.Tri.CHECKED, m.categoryState(c1));
        assertEquals(WaypointPickerModel.Tri.CHECKED, m.categoryState(c2));
    }

    @Test
    public void uncategorizedSortsFirst()
    {
        UUID user = UUID.randomUUID();
        UUID unc = UUID.randomUUID();
        Library lib = new Library();
        lib.getCategories().add(new Category(user, "Banks", 0, false, null, false));
        lib.getCategories().add(new Category(unc, "Uncategorized", 5, true, null, false));

        WaypointPickerModel m = new WaypointPickerModel(lib);
        assertTrue(m.getOrderedCategories().get(0).isUncategorized());
    }
}

package com.waypointer.ui;

import java.awt.event.ActionEvent;
import java.awt.event.KeyEvent;
import javax.swing.JButton;
import javax.swing.JComponent;
import javax.swing.JPanel;
import javax.swing.JTextField;
import javax.swing.KeyStroke;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;

public class EditorKeyBindingsTest
{
    @Test
    public void enterOnFieldClicksPrimaryEscapeOnPanelClicksCancel()
    {
        JPanel panel = new JPanel();
        JTextField field = new JTextField();
        JButton primary = new JButton();
        JButton cancel = new JButton();
        int[] hits = {0, 0};
        primary.addActionListener(e -> hits[0]++);
        cancel.addActionListener(e -> hits[1]++);

        EditorKeyBindings.commitOnEnterCancelOnEscape(panel, field, primary, cancel);

        // The Enter keystroke is registered on the field's WHEN_FOCUSED input map, mapped to the
        // "editorCommit" action, which clicks the primary button.
        assertEquals("editorCommit", field.getInputMap(JComponent.WHEN_FOCUSED)
            .get(KeyStroke.getKeyStroke(KeyEvent.VK_ENTER, 0)));
        assertNotNull(field.getActionMap().get("editorCommit"));
        field.getActionMap().get("editorCommit")
            .actionPerformed(new ActionEvent(field, ActionEvent.ACTION_PERFORMED, ""));
        assertEquals(1, hits[0]);
        assertEquals(0, hits[1]);

        // The Escape keystroke is registered on the panel's WHEN_ANCESTOR_OF_FOCUSED_COMPONENT
        // input map, mapped to the "editorCancel" action, which clicks the cancel button.
        assertEquals("editorCancel", panel.getInputMap(JComponent.WHEN_ANCESTOR_OF_FOCUSED_COMPONENT)
            .get(KeyStroke.getKeyStroke(KeyEvent.VK_ESCAPE, 0)));
        assertNotNull(panel.getActionMap().get("editorCancel"));
        panel.getActionMap().get("editorCancel")
            .actionPerformed(new ActionEvent(panel, ActionEvent.ACTION_PERFORMED, ""));
        assertEquals(1, hits[0]);
        assertEquals(1, hits[1]);
    }
}

package com.waypointer.ui;

import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.when;
import com.waypointer.model.route.Route;
import com.waypointer.model.route.RouteStep;
import com.waypointer.service.RoutePlaybackEngine;
import java.time.Instant;
import java.util.Arrays;
import java.util.UUID;
import org.junit.Test;
import org.junit.runner.RunWith;
import org.mockito.Mock;
import org.mockito.junit.MockitoJUnitRunner;

@RunWith(MockitoJUnitRunner.class)
public class RoutePlaybackBarTest
{
    @Mock private RoutePlaybackEngine engine;

    private Route route()
    {
        return new Route(UUID.randomUUID(), "R",
            Arrays.asList(RouteStep.manual("a"), RouteStep.manual("b")), false, Instant.now(), 0);
    }

    @Test
    public void hiddenWhenNoActiveRoute()
    {
        // getActiveRoute() returns null by default -> bar hides; no stub needed.
        RoutePlaybackBar bar = new RoutePlaybackBar(engine);
        bar.refresh();
        assertFalse(bar.isVisible());
    }

    @Test
    public void visibleAndLabelledWhenActive()
    {
        when(engine.getActiveRoute()).thenReturn(route());
        when(engine.getCurrentIndex()).thenReturn(0);
        RoutePlaybackBar bar = new RoutePlaybackBar(engine);
        bar.refresh();
        assertTrue(bar.isVisible());
        assertTrue(bar.getLabelTextForTest().contains("Step 1 / 2"));
    }

    @Test
    public void nextButtonCallsAdvance()
    {
        when(engine.getActiveRoute()).thenReturn(route());
        RoutePlaybackBar bar = new RoutePlaybackBar(engine);
        bar.refresh();
        bar.clickNextForTest();
        verify(engine).advance();
    }

    @Test
    public void backButtonCallsBack()
    {
        when(engine.getActiveRoute()).thenReturn(route());
        RoutePlaybackBar bar = new RoutePlaybackBar(engine);
        bar.refresh();
        bar.clickBackForTest();
        verify(engine).back();
    }

    @Test
    public void stopButtonCallsStop()
    {
        when(engine.getActiveRoute()).thenReturn(route());
        RoutePlaybackBar bar = new RoutePlaybackBar(engine);
        bar.refresh();
        bar.clickStopForTest();
        verify(engine).stop();
    }
}

package com.waypointer.ui;

import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import java.util.UUID;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

public class BulkSelectionTest
{
    @Test
    public void toggleAddsThenRemoves()
    {
        BulkSelection s = new BulkSelection();
        UUID a = UUID.randomUUID();
        assertTrue(s.isEmpty());
        s.toggle(a);
        assertTrue(s.ids().contains(a));
        assertEquals(1, s.size());
        s.toggle(a);
        assertFalse(s.ids().contains(a));
        assertTrue(s.isEmpty());
    }

    @Test
    public void selectRangeForwardIsInclusiveAndAdditive()
    {
        BulkSelection s = new BulkSelection();
        UUID a = UUID.randomUUID(), b = UUID.randomUUID(), c = UUID.randomUUID(), d = UUID.randomUUID();
        List<UUID> ordered = Arrays.asList(a, b, c, d);
        s.selectRange(ordered, b, d);
        assertTrue(s.ids().contains(b));
        assertTrue(s.ids().contains(c));
        assertTrue(s.ids().contains(d));
        assertFalse(s.ids().contains(a));
    }

    @Test
    public void selectRangeBackwardAnchorWorks()
    {
        BulkSelection s = new BulkSelection();
        UUID a = UUID.randomUUID(), b = UUID.randomUUID(), c = UUID.randomUUID();
        List<UUID> ordered = Arrays.asList(a, b, c);
        s.selectRange(ordered, c, a); // anchor after target
        assertEquals(3, s.size());
    }

    @Test
    public void selectRangeWithMissingAnchorIsNoOp()
    {
        BulkSelection s = new BulkSelection();
        UUID a = UUID.randomUUID(), b = UUID.randomUUID();
        s.selectRange(Arrays.asList(a, b), UUID.randomUUID(), b);
        assertTrue(s.isEmpty());
    }

    @Test
    public void setCategorySelectsAndDeselects()
    {
        BulkSelection s = new BulkSelection();
        UUID a = UUID.randomUUID(), b = UUID.randomUUID();
        List<UUID> cat = Arrays.asList(a, b);
        s.setCategory(cat, true);
        assertEquals(2, s.size());
        s.setCategory(cat, false);
        assertTrue(s.isEmpty());
    }

    @Test
    public void categoryStateTriState()
    {
        BulkSelection s = new BulkSelection();
        UUID a = UUID.randomUUID(), b = UUID.randomUUID();
        List<UUID> cat = Arrays.asList(a, b);
        assertEquals(BulkSelection.TriState.NONE, s.categoryState(cat));
        s.toggle(a);
        assertEquals(BulkSelection.TriState.PARTIAL, s.categoryState(cat));
        s.toggle(b);
        assertEquals(BulkSelection.TriState.ALL, s.categoryState(cat));
    }

    @Test
    public void emptyCategoryStateIsNone()
    {
        BulkSelection s = new BulkSelection();
        assertEquals(BulkSelection.TriState.NONE, s.categoryState(Collections.emptyList()));
    }

    @Test
    public void clearEmptiesSelection()
    {
        BulkSelection s = new BulkSelection();
        s.toggle(UUID.randomUUID());
        s.clear();
        assertTrue(s.isEmpty());
    }

    @Test
    public void selectionIsIdKeyedAndSurvivesADifferentVisibleList()
    {
        BulkSelection s = new BulkSelection();
        UUID a = UUID.randomUUID();
        s.toggle(a);
        // A later visible list that does not even contain 'a'; id-keyed selection must stand
        // and the range adds on top of it.
        UUID x = UUID.randomUUID(), y = UUID.randomUUID();
        s.selectRange(Arrays.asList(x, y), x, y);
        assertTrue(s.ids().contains(a));
        assertEquals(3, s.size());
    }

    @Test
    public void idsPreservesInsertionOrder()
    {
        BulkSelection s = new BulkSelection();
        UUID a = UUID.randomUUID(), b = UUID.randomUUID(), c = UUID.randomUUID();
        s.toggle(b);
        s.toggle(a);
        s.toggle(c);
        assertEquals(Arrays.asList(b, a, c), new java.util.ArrayList<>(s.ids()));
    }

    @Test
    public void idsReturnsACopy()
    {
        BulkSelection s = new BulkSelection();
        UUID a = UUID.randomUUID();
        s.toggle(a);
        s.ids().clear(); // mutating the returned set must not affect internal state
        assertTrue(s.ids().contains(a));
    }

    @Test
    public void selectRangeFromEqualsToSelectsExactlyOne()
    {
        BulkSelection s = new BulkSelection();
        UUID a = UUID.randomUUID(), b = UUID.randomUUID(), c = UUID.randomUUID();
        s.selectRange(Arrays.asList(a, b, c), b, b);
        assertEquals(1, s.size());
        assertTrue(s.ids().contains(b));
    }

    @Test
    public void setCategoryOverlapKeepsExistingAndAddsRest()
    {
        BulkSelection s = new BulkSelection();
        UUID a = UUID.randomUUID(), b = UUID.randomUUID();
        s.toggle(a);                                   // pre-existing partial selection
        s.setCategory(Arrays.asList(a, b), true);      // overlap: a already in
        assertEquals(2, s.size());
        assertTrue(s.ids().contains(a));
        assertTrue(s.ids().contains(b));
    }
}

package com.waypointer.ui;

import com.waypointer.model.Waypoint;
import java.time.Instant;
import java.util.UUID;
import org.junit.Test;
import static org.junit.Assert.*;

/** Tests for {@link WaypointRow}'s pure helpers. The row itself is Swing-driven and untested. */
public class WaypointRowTest
{
    private static Waypoint wp(String name, String notes)
    {
        return new Waypoint(UUID.randomUUID(), name, 0, UUID.randomUUID(), null,
            notes == null ? "" : notes, Instant.parse("2026-05-02T00:00:00Z"), 0, false, null, false);
    }

    @Test
    public void emptyNotesReturnNamePlain()
    {
        assertEquals("Vorkath", WaypointRow.buildHoverTooltip(wp("Vorkath", "")));
        assertEquals("Vorkath", WaypointRow.buildHoverTooltip(wp("Vorkath", null)));
    }

    @Test
    public void notesPreviewWrapsNameAndFirstLineInHtml()
    {
        String tip = WaypointRow.buildHoverTooltip(wp("Vorkath", "Drops dragonbones"));
        assertTrue("expected HTML tooltip with name + notes preview, got: " + tip,
            tip.startsWith("<html>"));
        assertTrue(tip.contains("Vorkath"));
        assertTrue(tip.contains("Drops dragonbones"));
    }

    @Test
    public void multilineNotesShowOnlyFirstLine()
    {
        String tip = WaypointRow.buildHoverTooltip(
            wp("Yew", "100k/hr at 90 wc\nbring axe and energy pots\nbank at varrock"));
        assertTrue(tip.contains("100k/hr at 90 wc"));
        assertFalse("only first line of notes belongs in the preview",
            tip.contains("bring axe"));
    }

    @Test
    public void whitespaceOnlyFirstLineFallsBackToBareName()
    {
        // notes starts with newlines / blank line: preview is empty, so show name only.
        String tip = WaypointRow.buildHoverTooltip(wp("Yew", "   \n actual content"));
        assertEquals("Yew", tip);
    }

    @Test
    public void htmlInUserFieldsIsEscaped()
    {
        String tip = WaypointRow.buildHoverTooltip(
            wp("<script>alert('x')</script>", "more <evil> stuff"));
        assertFalse("name must be HTML-escaped", tip.contains("<script>"));
        assertTrue(tip.contains("&lt;script&gt;"));
        assertTrue(tip.contains("&lt;evil&gt;"));
    }

    @Test
    public void originCategoryAppendedAsThirdTooltipLine()
    {
        Waypoint w = wp("Home", "");
        String tip = WaypointRow.buildHoverTooltip(w, "Houses");
        assertTrue("expected html, got: " + tip, tip.startsWith("<html>"));
        assertTrue(tip.contains("Home"));
        assertTrue(tip.contains("Houses"));
        assertTrue("origin tag should appear", tip.contains("in Houses"));
    }

    @Test
    public void nullOriginCategoryFallsBackToOriginalTooltip()
    {
        Waypoint w = wp("Home", "Personal");
        assertEquals(WaypointRow.buildHoverTooltip(w), WaypointRow.buildHoverTooltip(w, null));
    }

    @Test
    public void accessibleNamePlainWhenNoState()
    {
        assertEquals("Varrock", WaypointRow.accessibleName("Varrock", false, false));
    }

    @Test
    public void accessibleNameAppendsWilderness()
    {
        assertEquals("Chaos Altar (in Wilderness)",
            WaypointRow.accessibleName("Chaos Altar", true, false));
    }

    @Test
    public void accessibleNameAppendsPinned()
    {
        assertEquals("Home (pinned)", WaypointRow.accessibleName("Home", false, true));
    }

    @Test
    public void accessibleNameAppendsBothInOrder()
    {
        assertEquals("Rev Caves (in Wilderness) (pinned)",
            WaypointRow.accessibleName("Rev Caves", true, true));
    }

    @Test
    public void accessibleNameNullBaseIsEmptyPrefix()
    {
        assertEquals(" (pinned)", WaypointRow.accessibleName(null, false, true));
    }
}

