import org.junit.Assume;
import org.junit.Before;
import org.junit.Test;

public class DialogsTest
{
    @Before
    public void requireDisplay()
    {
        // JDialog construction throws HeadlessException with no display; skip rather than fail.
        Assume.assumeFalse(GraphicsEnvironment.isHeadless());
    }

    @Test
    public void appliesDarkContentPaneWithDefaultGap()
    {
        JDialog d = new JDialog((Window) null);
        JPanel content = Dialogs.applyDarkContentPane(d);

        assertEquals(content, d.getContentPane());
        assertEquals(ColorScheme.DARK_GRAY_COLOR, content.getBackground());
        assertEquals(WindowConstants.DISPOSE_ON_CLOSE, d.getDefaultCloseOperation());

        BorderLayout layout = (BorderLayout) content.getLayout();
        assertEquals(8, layout.getHgap());
        assertEquals(8, layout.getVgap());

        Border border = content.getBorder();
        assertTrue(border instanceof EmptyBorder);
        Insets in = ((EmptyBorder) border).getBorderInsets();
        assertEquals(new Insets(8, 8, 8, 8), in);
    }

    @Test
    public void gapOverloadIsHonored()
    {
        JDialog d = new JDialog((Window) null);
        JPanel content = Dialogs.applyDarkContentPane(d, 0, 6);

        BorderLayout layout = (BorderLayout) content.getLayout();
        assertEquals(0, layout.getHgap());
        assertEquals(6, layout.getVgap());
    }

    @Test
    public void bindEscapeRegistersAction()
    {
        JDialog d = new JDialog((Window) null);
        Dialogs.bindEscape(d);

        KeyStroke esc = KeyStroke.getKeyStroke(KeyEvent.VK_ESCAPE, 0);
        Object actionKey = d.getRootPane()
            .getInputMap(JComponent.WHEN_IN_FOCUSED_WINDOW).get(esc);
        assertNotNull("ESC should map to an action key", actionKey);
        assertNotNull("action key should resolve to an action",
            d.getRootPane().getActionMap().get(actionKey));
    }
}

package com.waypointer.ui;

import com.waypointer.service.BboxIndex;
import com.waypointer.service.LandmarkType;
import com.waypointer.service.WaypointPathfinder;
import java.awt.Component;
import java.awt.Container;
import java.awt.image.BufferedImage;
import java.util.ArrayList;
import java.util.List;
import java.util.function.Consumer;
import javax.swing.AbstractButton;
import javax.swing.JButton;
import javax.swing.SwingUtilities;
import net.runelite.api.Client;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.game.SpriteManager;
import org.junit.Test;
import org.junit.runner.RunWith;
import org.mockito.ArgumentCaptor;
import org.mockito.Mock;
import org.mockito.junit.MockitoJUnitRunner;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;
import static org.junit.Assert.assertEquals;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.ArgumentMatchers.anyInt;
import static org.mockito.ArgumentMatchers.anyString;
import static org.mockito.Mockito.atLeastOnce;
import static org.mockito.Mockito.never;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.when;

@RunWith(MockitoJUnitRunner.class)
public class NearestLandmarkBarTest
{
    @Mock private BboxIndex bbox;
    @Mock private WaypointPathfinder pathfinder;
    @Mock private Client client;
    @Mock private ClientThread clientThread;
    @Mock private SpriteManager spriteManager;
    @Mock private com.waypointer.WaypointerConfig config;
    private final com.google.gson.Gson gson = new com.google.gson.Gson();

    @org.junit.Before
    public void setUpConfig()
    {
        when(config.landmarkSelectionJson()).thenReturn("");
    }

    private static final class CapturingToasts implements Toasts
    {
        String lastText;
        String lastActionLabel;
        Runnable lastOnClick;

        @Override
        public void show(String text)
        {
            this.lastText = text;
            this.lastActionLabel = null;
            this.lastOnClick = null;
        }

        @Override
        public void show(String text, String actionLabel, Runnable onClick)
        {
            this.lastText = text;
            this.lastActionLabel = actionLabel;
            this.lastOnClick = onClick;
        }
    }

    @Test
    public void barHasFourDefaultButtonsPlusOverflow()
    {
        NearestLandmarkBar bar = new NearestLandmarkBar(bbox, pathfinder, client, clientThread, spriteManager, config, gson);

        Container iconRow = (Container) bar.getComponent(0);
        int buttonCount = 0;
        for (Component c : iconRow.getComponents())
        {
            if (c instanceof JButton) buttonCount++;
        }
        // 4 default-selected type buttons + 1 overflow button.
        assertEquals(5, buttonCount);
    }

    @Test
    public void applyHitRequestsPath()
    {
        NearestLandmarkBar bar = new NearestLandmarkBar(bbox, pathfinder, client, clientThread, spriteManager, config, gson);

        BboxIndex.Hit hit = new BboxIndex.Hit(123456, "Edgeville Bank", 7);
        bar.applyHit(LandmarkType.BANK, hit);

        verify(pathfinder).requestPath(123456, "Edgeville Bank");
    }

    @Test
    public void applyHitWithNullHitSkipsPathRequest()
    {
        NearestLandmarkBar bar = new NearestLandmarkBar(bbox, pathfinder, client, clientThread, spriteManager, config, gson);

        bar.applyHit(LandmarkType.BANK, null);

        verify(pathfinder, never()).requestPath(anyInt(), anyString());
    }

    @Test
    public void applyHitWithNullHitShowsToast()
    {
        NearestLandmarkBar bar = new NearestLandmarkBar(bbox, pathfinder, client, clientThread, spriteManager, config, gson);
        CapturingToasts toasts = new CapturingToasts();
        bar.setToasts(toasts);

        bar.applyHit(LandmarkType.BANK, null);

        assertNotNull("expected toast on null hit", toasts.lastText);
        assertTrue("expected toast to mention bank, got: " + toasts.lastText,
            toasts.lastText.toLowerCase().contains("bank"));
    }

    @Test
    public void onPickShortcircuitsWhenShortestPathUnavailable()
    {
        when(pathfinder.isAvailable()).thenReturn(false);
        NearestLandmarkBar bar = new NearestLandmarkBar(bbox, pathfinder, client, clientThread, spriteManager, config, gson);
        CapturingToasts toasts = new CapturingToasts();
        bar.setToasts(toasts);

        bar.onPick(LandmarkType.BANK);

        verify(clientThread, never()).invoke(any(Runnable.class));
        verify(bbox, never()).nearest(any(LandmarkType.class), anyInt());
        assertNotNull("expected a toast to be shown", toasts.lastText);
        assertTrue("expected toast to mention shortest path, got: " + toasts.lastText,
            toasts.lastText.toLowerCase().contains("shortest path"));
    }

    @Test
    public void setLoggedInTogglesLandmarkButtonEnabledState()
    {
        NearestLandmarkBar bar = new NearestLandmarkBar(bbox, pathfinder, client, clientThread, spriteManager, config, gson);

        // Bar contents: 4 landmark buttons then the customize (▾) button. ▾ is always enabled.
        List<JButton> allButtons = findLandmarkButtons(bar);

        for (JButton b : allButtons)
        {
            assertFalse("expected disabled at construction", b.isEnabled());
        }

        bar.setLoggedIn(true);
        for (JButton b : allButtons)
        {
            assertTrue("expected enabled after setLoggedIn(true)", b.isEnabled());
        }

        bar.setLoggedIn(false);
        for (JButton b : allButtons)
        {
            assertFalse("expected disabled after setLoggedIn(false)", b.isEnabled());
        }
    }

    @Test
    public void barWithEmptySelection_showsOnlyOverflowButton()
    {
        // Stub config to return a valid JSON with empty selection (all unchecked).
        com.google.gson.Gson realGson = new com.google.gson.Gson();
        LandmarkSelection empty = LandmarkSelection.canonicalDefault();
        for (LandmarkType t : LandmarkType.values())
        {
            empty = empty.withSelected(t, false);
        }
        String emptyJson = empty.toJson(realGson);
        when(config.landmarkSelectionJson()).thenReturn(emptyJson);
        // Use the real Gson here so the constructor's parse(...) reconstructs the empty selection.
        NearestLandmarkBar bar = new NearestLandmarkBar(bbox, pathfinder, client, clientThread, spriteManager, config, realGson);

        Container iconRow = (Container) bar.getComponent(0);
        int buttonCount = 0;
        for (Component c : iconRow.getComponents())
        {
            if (c instanceof JButton) buttonCount++;
        }
        assertEquals("expected only the overflow button when nothing is selected", 1, buttonCount);
    }

    @Test
    public void iconRowPreferredHeightFitsEveryButtonWhenWrapped()
    {
        // Select every landmark type so the icon row (one 34 px button per type plus the
        // overflow toggle) cannot fit on a single row at the panel width. The row must report
        // a preferred height tall enough for the wrapped rows; otherwise the parent BoxLayout
        // allocates only one row's worth of height and the wrapped buttons -- including the
        // overflow toggle -- are clipped out of view and become unclickable.
        com.google.gson.Gson realGson = new com.google.gson.Gson();
        LandmarkSelection all = LandmarkSelection.canonicalDefault();
        for (LandmarkType t : LandmarkType.values())
        {
            all = all.withSelected(t, true);
        }
        when(config.landmarkSelectionJson()).thenReturn(all.toJson(realGson));
        NearestLandmarkBar bar = new NearestLandmarkBar(bbox, pathfinder, client, clientThread, spriteManager, config, realGson);

        bar.setSize(net.runelite.client.ui.PluginPanel.PANEL_WIDTH, 600);
        bar.doLayout(); // BoxLayout sizes the icon row to the bar width

        Container iconRow = (Container) bar.getComponent(0);
        iconRow.doLayout(); // FlowLayout wraps the buttons within that width
        int rowWidth = iconRow.getWidth();
        assertTrue("icon row should have been laid out with a real width", rowWidth > 0);

        int maxBottom = 0;
        int buttonCount = 0;
        for (Component c : iconRow.getComponents())
        {
            if (!(c instanceof JButton)) continue;
            buttonCount++;
            maxBottom = Math.max(maxBottom, c.getY() + c.getHeight());
        }
        assertEquals("expected 11 type buttons + overflow", 12, buttonCount);
        assertTrue("buttons must have wrapped past one row for this test to be meaningful",
            maxBottom > 34);
        assertTrue("icon row preferred height (" + iconRow.getPreferredSize().height
                + ") must accommodate the lowest button (bottom " + maxBottom + ")",
            iconRow.getPreferredSize().height >= maxBottom);
    }

    @Test
    public void iconRowStaysSingleRowWhenWidthMomentarilyCollapses()
    {
        // Regression: on first launch the icon row's width transiently collapses toward a
        // single button while the panel is being realised. The wrap layout used to honour that
        // narrow width, stacking all five default buttons one-per-row and leaving a tall gap
        // above the search field that only a Customize toggle could clear. The row only ever
        // renders in the fixed-width sidebar, so a momentarily narrow width must not inflate the
        // reported height -- it should stay a single row.
        NearestLandmarkBar bar = new NearestLandmarkBar(bbox, pathfinder, client, clientThread, spriteManager, config, gson);

        Container iconRow = (Container) bar.getComponent(0);
        iconRow.setSize(34, 10); // one BUTTON_SIZE wide -- the collapsed transient width

        int height = iconRow.getPreferredSize().height;
        assertTrue("icon row must report a single-row height when momentarily narrow, was " + height,
            height <= 40);
    }

    // Returns only the landmark buttons in the icon row (all buttons except the trailing overflow).
    private static List<JButton> findLandmarkButtons(NearestLandmarkBar bar)
    {
        Container iconRow = (Container) bar.getComponent(0);
        List<JButton> all = new ArrayList<>();
        for (Component c : iconRow.getComponents())
        {
            if (c instanceof JButton) all.add((JButton) c);
        }
        // Drop trailing overflow button.
        if (!all.isEmpty()) all.remove(all.size() - 1);
        return all;
    }

    @Test
    public void landmarkButtonsHaveGrayFilteredDisabledIcon()
        throws java.lang.reflect.InvocationTargetException, InterruptedException,
               NoSuchFieldException, IllegalAccessException
    {
        // The spec wants disabled landmark buttons to read as obviously disabled. Swing
        // swaps to the disabled icon when isEnabled() == false; this test checks that
        // applySprite seeded one alongside the enabled icon. The test simulates sprite
        // arrival by capturing the SpriteManager.getSpriteAsync callback and feeding it
        // a small placeholder BufferedImage.
        BufferedImage stub = new BufferedImage(
            16, 16, BufferedImage.TYPE_INT_ARGB);
        ArgumentCaptor<Consumer> callback =
            ArgumentCaptor.forClass(Consumer.class);

        NearestLandmarkBar bar = new NearestLandmarkBar(
            bbox, pathfinder, client, clientThread, spriteManager, config, gson);

        verify(spriteManager, atLeastOnce()).getSpriteAsync(anyInt(), anyInt(), callback.capture());
        for (Consumer<BufferedImage> cb : callback.getAllValues())
        {
            cb.accept(stub);
        }
        // Drain the EDT so the invokeLater that sets the icons runs.
        SwingUtilities.invokeAndWait(() -> {});

        Container iconRow = (Container) bar.getComponent(0);
        // Read AbstractButton.disabledIcon via reflection so the assertion checks an
        // explicit setDisabledIcon call rather than the LAF's lazy auto-synthesis on
        // first getDisabledIcon() invocation. Without this peek the test would pass
        // even if applySprite never called setDisabledIcon.
        java.lang.reflect.Field disabledIconField =
            AbstractButton.class.getDeclaredField("disabledIcon");
        disabledIconField.setAccessible(true);

        int landmarkCount = 0;
        for (Component c : iconRow.getComponents())
        {
            if (!(c instanceof JButton)) continue;
            JButton jb = (JButton) c;
            if (jb.getIcon() == null) continue; // overflow button has no icon
            landmarkCount++;
            Object explicit = disabledIconField.get(jb);
            assertNotNull(
                "applySprite must explicitly setDisabledIcon (GrayFilter); got null",
                explicit);
        }
        assertTrue("at least one landmark button rendered", landmarkCount > 0);
    }
}

package com.waypointer.ui;

import com.google.gson.Gson;
import com.google.gson.GsonBuilder;
import com.waypointer.codec.LibraryJsonCodec;
import com.waypointer.codec.WaypointShareCodec;
import com.waypointer.model.Category;
import com.waypointer.model.Library;
import com.waypointer.model.Waypoint;
import com.waypointer.service.WaypointStore;
import com.waypointer.testsupport.Headless;
import java.time.Instant;
import java.util.UUID;
import org.junit.Before;
import org.junit.Test;
import org.mockito.ArgumentCaptor;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.times;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.when;

public class ImportPickerDialogTest
{
    private WaypointShareCodec shareCodec;

    @Before
    public void setUp()
    {
        Gson gson = new GsonBuilder()
            .registerTypeAdapter(Instant.class,
                (com.google.gson.JsonSerializer<Instant>) (src, t, c) ->
                    new com.google.gson.JsonPrimitive(src.toString()))
            .registerTypeAdapter(Instant.class,
                (com.google.gson.JsonDeserializer<Instant>) (e, t, c) ->
                    Instant.parse(e.getAsString()))
            .create();
        LibraryJsonCodec libraryCodec = new LibraryJsonCodec(gson);
        shareCodec = new WaypointShareCodec(gson, libraryCodec);
    }

    private static Library oneWaypointLibrary()
    {
        Library lib = new Library();
        UUID cat = UUID.randomUUID();
        lib.getCategories().add(new Category(cat, "Banks", 0, false, null, false));
        lib.getWaypoints().add(new Waypoint(UUID.randomUUID(), "GE", 9, cat, null, "",
            Instant.parse("2026-05-02T00:00:00Z"), 0, false, null, false));
        return lib;
    }

    private ImportPickerDialog newDialog(WaypointStore store)
    {
        return new ImportPickerDialog(null, store, shareCodec, Toasts.NO_OP);
    }

    @Test
    public void codeSourceDecodesAndPopulatesTree()
    {
        Headless.assumeDisplay();
        String code = shareCodec.encodeLibrary(oneWaypointLibrary());

        WaypointStore store = new WaypointStore();
        store.bootstrap(new Library());
        ImportPickerDialog d = newDialog(store);

        Library decoded = d.decodeCodeOrNull(code);
        assertNotNull(decoded);
        d.populate(decoded);
        assertTrue(d.hasLoadedSource());
    }

    @Test
    public void malformedSourceLeavesTreeEmpty()
    {
        Headless.assumeDisplay();
        WaypointStore store = new WaypointStore();
        store.bootstrap(new Library());
        ImportPickerDialog d = newDialog(store);

        assertNull(d.decodeCodeOrNull("not a real code"));         // no magic
        assertNull(d.decodeCodeOrNull("WPL1:@@@not-base64@@@"));    // right magic, junk body
        assertFalse(d.hasLoadedSource());
    }

    @Test
    public void importBuildsSelectedSubsetAndMergesOnce()
    {
        Headless.assumeDisplay();
        String code = shareCodec.encodeLibrary(oneWaypointLibrary());

        WaypointStore store = mock(WaypointStore.class);
        when(store.importMerge(any())).thenReturn(new WaypointStore.ImportResult());
        ImportPickerDialog d = newDialog(store);

        d.populate(d.decodeCodeOrNull(code));
        d.importSelected();

        ArgumentCaptor<Library> captor = ArgumentCaptor.forClass(Library.class);
        verify(store, times(1)).importMerge(captor.capture());
        Library captured = captor.getValue();
        assertEquals(1, captured.getWaypoints().size());
        assertEquals("GE", captured.getWaypoints().get(0).getName());
        assertEquals(1, captured.getCategories().size());
        assertEquals("Banks", captured.getCategories().get(0).getName());
        assertEquals(captured.getCategories().get(0).getId(),
            captured.getWaypoints().get(0).getCategoryId());
    }
}

