package com.waypointer.ui;

import java.util.Set;
import java.util.UUID;
import org.junit.Test;
import static org.junit.Assert.*;

public class AutoExpandControllerTest
{
    @Test
    public void recordAndIsTransientlyExpanded()
    {
        AutoExpandController c = new AutoExpandController();
        UUID a = UUID.randomUUID();
        assertFalse(c.isTransientlyExpanded(a));
        c.recordTransientExpand(a);
        assertTrue(c.isTransientlyExpanded(a));
    }

    @Test
    public void onHoverInsideAutoExpandedDoesNotRevertIt()
    {
        AutoExpandController c = new AutoExpandController();
        UUID a = UUID.randomUUID();
        c.recordTransientExpand(a);
        Set<UUID> reverted = c.onHover(a);
        assertTrue(reverted.isEmpty());
        assertTrue(c.isTransientlyExpanded(a));
    }

    @Test
    public void onHoverOutsideAutoExpandedRevertsIt()
    {
        AutoExpandController c = new AutoExpandController();
        UUID a = UUID.randomUUID();
        UUID other = UUID.randomUUID();
        c.recordTransientExpand(a);
        Set<UUID> reverted = c.onHover(other);
        assertEquals(java.util.Collections.singleton(a), reverted);
        assertFalse(c.isTransientlyExpanded(a));
    }

    @Test
    public void onHoverWithMultipleAutoExpandedRevertsOnlyOutsideOnes()
    {
        AutoExpandController c = new AutoExpandController();
        UUID a = UUID.randomUUID();
        UUID b = UUID.randomUUID();
        c.recordTransientExpand(a);
        c.recordTransientExpand(b);
        Set<UUID> reverted = c.onHover(a);
        assertEquals(java.util.Collections.singleton(b), reverted);
        assertTrue(c.isTransientlyExpanded(a));
        assertFalse(c.isTransientlyExpanded(b));
    }

    @Test
    public void onDropAtAutoExpandedConfirmsIt()
    {
        AutoExpandController c = new AutoExpandController();
        UUID a = UUID.randomUUID();
        c.recordTransientExpand(a);
        AutoExpandController.DropResolution r = c.onDropAt(a);
        assertEquals(a, r.getToConfirm());
        assertTrue(r.getToRevert().isEmpty());
        assertFalse(c.isTransientlyExpanded(a));
    }

    @Test
    public void onDropAtAutoExpandedRevertsOthers()
    {
        AutoExpandController c = new AutoExpandController();
        UUID a = UUID.randomUUID();
        UUID b = UUID.randomUUID();
        c.recordTransientExpand(a);
        c.recordTransientExpand(b);
        AutoExpandController.DropResolution r = c.onDropAt(a);
        assertEquals(a, r.getToConfirm());
        assertEquals(java.util.Collections.singleton(b), r.getToRevert());
        assertFalse(c.isTransientlyExpanded(a));
        assertFalse(c.isTransientlyExpanded(b));
    }

    @Test
    public void onDropAtNonAutoExpandedRevertsAll()
    {
        AutoExpandController c = new AutoExpandController();
        UUID a = UUID.randomUUID();
        UUID b = UUID.randomUUID();
        UUID dest = UUID.randomUUID();
        c.recordTransientExpand(a);
        c.recordTransientExpand(b);
        AutoExpandController.DropResolution r = c.onDropAt(dest);
        assertNull(r.getToConfirm());
        assertEquals(2, r.getToRevert().size());
        assertTrue(r.getToRevert().contains(a));
        assertTrue(r.getToRevert().contains(b));
    }

    @Test
    public void onDragEndReturnsAllAutoExpandedAndClears()
    {
        AutoExpandController c = new AutoExpandController();
        UUID a = UUID.randomUUID();
        UUID b = UUID.randomUUID();
        c.recordTransientExpand(a);
        c.recordTransientExpand(b);
        Set<UUID> reverted = c.onDragEnd();
        assertEquals(2, reverted.size());
        assertTrue(reverted.contains(a));
        assertTrue(reverted.contains(b));
        assertFalse(c.isTransientlyExpanded(a));
        assertFalse(c.isTransientlyExpanded(b));
    }

    @Test
    public void onDragEndWithNothingExpandedReturnsEmpty()
    {
        AutoExpandController c = new AutoExpandController();
        assertTrue(c.onDragEnd().isEmpty());
    }
}

package com.waypointer.ui;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import java.util.UUID;
import org.junit.Test;
import static org.junit.Assert.*;

public class DragAndDropHandlerTest
{
    @Test
    public void moveInsertsBeforeTarget()
    {
        UUID a = UUID.randomUUID(), b = UUID.randomUUID(), c = UUID.randomUUID(), d = UUID.randomUUID();
        List<UUID> ids = Arrays.asList(a, b, c, d);
        List<UUID> moved = DragAndDropHandler.move(new ArrayList<>(ids), a, c);
        assertEquals(Arrays.asList(b, a, c, d), moved);
    }

    @Test
    public void moveBackwardInsertsBeforeTarget()
    {
        UUID a = UUID.randomUUID(), b = UUID.randomUUID(), c = UUID.randomUUID(), d = UUID.randomUUID();
        List<UUID> ids = Arrays.asList(a, b, c, d);
        List<UUID> moved = DragAndDropHandler.move(new ArrayList<>(ids), d, b);
        assertEquals(Arrays.asList(a, d, b, c), moved);
    }

    @Test
    public void moveTwoMiddleEntries()
    {
        UUID a = UUID.randomUUID();
        UUID b = UUID.randomUUID();
        UUID c = UUID.randomUUID();
        UUID d = UUID.randomUUID();
        // Drag b onto c: b is removed from position 1, then inserted before c (now at index 1).
        // Result: [a, b, c, d] -> remove b -> [a, c, d] -> insert before c (index 1) -> [a, b, c, d].
        // That means dragging b before c when b is already just before c is a no-movement case.
        // Instead test: drag c onto b (insert c before b): [a, b, c, d] -> [a, c, b, d].
        List<UUID> result = DragAndDropHandler.move(new ArrayList<>(Arrays.asList(a, b, c, d)), c, b);
        assertEquals(Arrays.asList(a, c, b, d), result);
    }

    @Test
    public void moveFirstBeforeLast()
    {
        UUID a = UUID.randomUUID();
        UUID b = UUID.randomUUID();
        UUID c = UUID.randomUUID();
        // Drag a onto c (insert a before c): [a, b, c] -> remove a -> [b, c] -> insert before c (index 1) -> [b, a, c].
        List<UUID> result = DragAndDropHandler.move(new ArrayList<>(Arrays.asList(a, b, c)), a, c);
        assertEquals(Arrays.asList(b, a, c), result);
    }

    @Test
    public void moveSameAsTargetReturnsNull()
    {
        UUID a = UUID.randomUUID();
        UUID b = UUID.randomUUID();
        List<UUID> result = DragAndDropHandler.move(new ArrayList<>(Arrays.asList(a, b)), a, a);
        assertNull(result);
    }

    @Test
    public void missingIdReturnsNullSentinelForCallerToNoOp()
    {
        UUID present = UUID.randomUUID();
        UUID absent = UUID.randomUUID();
        assertNull(DragAndDropHandler.move(new ArrayList<>(Arrays.asList(present)), present, absent));
        assertNull(DragAndDropHandler.move(new ArrayList<>(Arrays.asList(present)), absent, present));
    }

    @Test
    public void inputListNotMutated()
    {
        UUID a = UUID.randomUUID();
        UUID b = UUID.randomUUID();
        List<UUID> input = new ArrayList<>(Arrays.asList(a, b));
        DragAndDropHandler.move(new ArrayList<>(input), a, b);
        // Verify original list is untouched.
        assertEquals(a, input.get(0));
        assertEquals(b, input.get(1));
    }

    @Test
    public void decideMode_waypointOnRow_returnsBorderAndTint()
    {
        assertEquals(DropIndicatorMode.BORDER_AND_TINT,
            DragAndDropHandler.decideMode("waypoint:" + UUID.randomUUID(),
                DragAndDropHandler.TargetKind.WAYPOINT_ROW));
    }

    @Test
    public void decideMode_waypointOnHeader_returnsTintOnly()
    {
        assertEquals(DropIndicatorMode.TINT,
            DragAndDropHandler.decideMode("waypoint:" + UUID.randomUUID(),
                DragAndDropHandler.TargetKind.CATEGORY_HEADER));
    }

    @Test
    public void decideMode_categoryOnHeader_returnsBorderAndTint()
    {
        assertEquals(DropIndicatorMode.BORDER_AND_TINT,
            DragAndDropHandler.decideMode("category:" + UUID.randomUUID(),
                DragAndDropHandler.TargetKind.CATEGORY_HEADER));
    }

    @Test
    public void decideMode_categoryOnRow_returnsNone()
    {
        assertEquals(DropIndicatorMode.NONE,
            DragAndDropHandler.decideMode("category:" + UUID.randomUUID(),
                DragAndDropHandler.TargetKind.WAYPOINT_ROW));
    }

    @Test
    public void tailZoneAcceptsWaypointPayload()
    {
        assertTrue(DragAndDropHandler.tailZoneAccepts("waypoint:" + UUID.randomUUID()));
    }

    @Test
    public void tailZoneRejectsCategoryPayload()
    {
        assertFalse(DragAndDropHandler.tailZoneAccepts("category:" + UUID.randomUUID()));
    }

    @Test
    public void tailZoneRejectsNullPayload()
    {
        assertFalse(DragAndDropHandler.tailZoneAccepts(null));
    }
}

package com.waypointer.ui;

import com.waypointer.codec.WaypointShareCodec;
import com.waypointer.model.Category;
import com.waypointer.model.Library;
import com.waypointer.model.Waypoint;
import com.waypointer.service.WaypointStore;
import java.awt.Window;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import static org.mockito.Mockito.mock;

public class BulkSelectControllerTest
{
    // No-op host: counts rebuilds, never touches a real window.
    private static final class CountingHost implements BulkSelectController.Host
    {
        int rebuilds;
        @Override public void rebuild() { rebuilds++; }
        @Override public void revalidateAndRepaint() { }
        @Override public Window windowAncestor() { return null; }
    }

    private static WaypointStore freshStore()
    {
        WaypointStore store = new WaypointStore();
        store.bootstrap(new Library());
        return store;
    }

    private static BulkSelectController newController(WaypointStore store, CountingHost host)
    {
        return new BulkSelectController(
            store,
            Toasts.NO_OP,
            mock(WaypointShareCodec.class),
            host);
    }

    @Test
    public void enterAndExitSelectModeFlipTheFlag()
    {
        WaypointStore store = freshStore();
        BulkSelectController c = newController(store, new CountingHost());

        assertFalse(c.isSelectMode());
        c.enterSelectMode();
        assertTrue(c.isSelectMode());
        c.exitSelectMode();
        assertFalse(c.isSelectMode());
    }

    @Test
    public void toggleSelectModeFlipsTheFlag()
    {
        WaypointStore store = freshStore();
        BulkSelectController c = newController(store, new CountingHost());

        assertFalse(c.isSelectMode());
        c.toggleSelectMode();
        assertTrue(c.isSelectMode());
        c.toggleSelectMode();
        assertFalse(c.isSelectMode());
    }

    @Test
    public void bulkDeleteRemovesSelectedAndClearsSelection()
    {
        WaypointStore store = freshStore();
        Category cat = store.getUncategorized();
        Waypoint a = store.createWaypoint(1, "A", cat.getId());
        Waypoint b = store.createWaypoint(2, "B", cat.getId());

        CountingHost host = new CountingHost();
        BulkSelectController c = newController(store, host);
        c.toggleSelectMode();
        c.onRowSelectClicked(a, false);
        c.onRowSelectClicked(b, false);
        assertEquals(2, c.selection().size());

        c.bulkDeleteForTest();

        assertTrue("selection cleared after delete", c.selection().isEmpty());
        assertTrue("both waypoints removed from the store",
            store.getWaypointsInCategory(cat.getId()).isEmpty());
    }

    @Test
    public void bulkMoveReassignsCategoryAndClearsSelection()
    {
        WaypointStore store = freshStore();
        Category src = store.getUncategorized();
        Category dst = store.createCategory("Dest");
        Waypoint a = store.createWaypoint(1, "A", src.getId());

        CountingHost host = new CountingHost();
        BulkSelectController c = newController(store, host);
        c.toggleSelectMode();
        c.onRowSelectClicked(a, false);

        c.bulkMoveToForTest(dst.getId());

        assertTrue("selection cleared after move", c.selection().isEmpty());
        assertEquals(1, store.getWaypointsInCategory(dst.getId()).size());
        assertTrue(store.getWaypointsInCategory(src.getId()).isEmpty());
    }
}

