package com.waypointer.ui;

import javax.swing.JLabel;
import org.junit.Test;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

public class ToastOverlayTest
{
    @Test
    public void wrapsContentAndStartsWithCardHidden()
    {
        JLabel content = new JLabel("inner");
        ToastOverlay overlay = new ToastOverlay(content);

        // The wrapped content is a direct child of the overlay (in some layer).
        boolean found = false;
        for (java.awt.Component c : overlay.getComponents())
        {
            if (c == content) found = true;
        }
        assertTrue("expected content to be a child of the overlay", found);

        // No card is visible until show() is called.
        assertFalse("toast card should be hidden initially", overlay.cardIsVisibleForTest());
    }

    @Test
    public void showMakesCardVisibleAndSetsText()
    {
        ToastOverlay overlay = new ToastOverlay(new JLabel("inner"));
        overlay.setSize(200, 300); // give it a non-zero bound so layout runs

        overlay.show("Added Varrock");

        assertTrue("card should be visible after show()", overlay.cardIsVisibleForTest());
        assertTrue("expected label to mention the message, got: " + overlay.cardLabelTextForTest(),
            overlay.cardLabelTextForTest().contains("Added Varrock"));
    }

    @Test
    public void showEscapesHtmlInMessage()
    {
        ToastOverlay overlay = new ToastOverlay(new JLabel("inner"));
        overlay.setSize(200, 300);

        overlay.show("<b>cheeky</b>");

        String rendered = overlay.cardLabelTextForTest();
        assertFalse("raw <b> should not appear in label HTML, got: " + rendered,
            rendered.contains("<b>cheeky</b>"));
        assertTrue("escaped marker should appear, got: " + rendered, rendered.contains("&lt;b&gt;"));
    }

    @Test
    public void showSchedulesAutoHideAtDefaultDuration()
    {
        ToastOverlay overlay = new ToastOverlay(new JLabel("inner"));
        overlay.setSize(200, 300);

        overlay.show("hi");

        javax.swing.Timer t = overlay.autoHideTimerForTest();
        org.junit.Assert.assertNotNull("expected timer to exist after show()", t);
        org.junit.Assert.assertTrue("expected timer to be running", t.isRunning());
        org.junit.Assert.assertEquals(2500, t.getDelay());
    }

    @Test
    public void showWithActionRendersActionLabel()
    {
        ToastOverlay overlay = new ToastOverlay(new JLabel("inner"));
        overlay.setSize(200, 300);

        overlay.show("Deleted Catherby", "Undo", () -> {});

        JLabel action = overlay.actionLabelForTest();
        org.junit.Assert.assertNotNull("expected action label to be rendered", action);
        org.junit.Assert.assertTrue("expected action label text 'Undo', got: " + action.getText(),
            action.getText().contains("Undo"));
        org.junit.Assert.assertTrue("expected action label visible", action.isVisible());
    }

    @Test
    public void clickingActionInvokesRunnableAndHidesCard()
    {
        ToastOverlay overlay = new ToastOverlay(new JLabel("inner"));
        overlay.setSize(200, 300);
        java.util.concurrent.atomic.AtomicInteger calls = new java.util.concurrent.atomic.AtomicInteger();
        overlay.show("Deleted Catherby", "Undo", calls::incrementAndGet);

        // Simulate a mouse click on the action label by dispatching the canonical click event.
        JLabel action = overlay.actionLabelForTest();
        java.awt.event.MouseEvent click = new java.awt.event.MouseEvent(
            action, java.awt.event.MouseEvent.MOUSE_CLICKED, System.currentTimeMillis(),
            0, 0, 0, 1, false);
        for (java.awt.event.MouseListener l : action.getMouseListeners()) l.mouseClicked(click);

        org.junit.Assert.assertEquals("runnable should fire exactly once", 1, calls.get());
        assertFalse("card should hide after action click", overlay.cardIsVisibleForTest());
    }

    @Test
    public void showWithActionUsesLongerDuration()
    {
        ToastOverlay overlay = new ToastOverlay(new JLabel("inner"));
        overlay.setSize(200, 300);

        overlay.show("Deleted Catherby", "Undo", () -> {});

        org.junit.Assert.assertEquals(6000, overlay.autoHideTimerForTest().getDelay());
    }

    @Test
    public void rapidShowReusesSameEntryAndDoesNotIncrementAnimationCount()
    {
        ToastOverlay overlay = new ToastOverlay(new JLabel("inner"));
        overlay.setSize(200, 300);

        overlay.show("first");
        int afterFirst = overlay.entryAnimationCountForTest();
        overlay.show("second");
        int afterSecond = overlay.entryAnimationCountForTest();

        org.junit.Assert.assertEquals(
            "second show() should reuse visible card, entry animation count must not increment",
            afterFirst, afterSecond);
        org.junit.Assert.assertTrue("expected second show() text to be reflected",
            overlay.cardLabelTextForTest().contains("second"));
    }

    @Test
    public void firstShowStartsAnimationOffScreenAndSettlesAtRestingY()
    {
        ToastOverlay overlay = new ToastOverlay(new JLabel("inner"));
        overlay.setSize(200, 300);

        overlay.show("hello");

        // Right after show(), the card should be at the off-screen start position.
        int startY = overlay.cardCurrentYForTest();
        org.junit.Assert.assertEquals("card should start at the bottom edge", 300, startY);

        // Finish the animation synchronously.
        overlay.completeEntryAnimationForTest();
        int settledY = overlay.cardCurrentYForTest();
        org.junit.Assert.assertTrue("card must settle above the bottom edge, got y=" + settledY,
            settledY < 300);
    }

    @Test
    public void replaceInPlacePulsesWithoutReanimatingEntry()
    {
        ToastOverlay overlay = new ToastOverlay(new JLabel("inner"));
        overlay.setSize(200, 300);

        overlay.show("first");
        int entryAfterFirst = overlay.entryAnimationCountForTest();
        org.junit.Assert.assertEquals("first show() slides in, it must not pulse",
            0, overlay.pulseCountForTest());

        overlay.show("second");

        org.junit.Assert.assertEquals("replace must not re-run the slide entry",
            entryAfterFirst, overlay.entryAnimationCountForTest());
        org.junit.Assert.assertEquals("replace must pulse exactly once",
            1, overlay.pulseCountForTest());
    }
}

package com.waypointer.service;

import com.google.gson.Gson;
import com.google.gson.GsonBuilder;
import com.waypointer.codec.LibraryJsonCodec;
import com.waypointer.model.Category;
import com.waypointer.model.Library;
import java.time.Instant;
import java.util.UUID;
import net.runelite.client.config.ConfigManager;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.ArgumentMatchers.anyString;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.never;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.when;

public class WaypointStorePersistenceTest
{
    private ConfigManager configManager;
    private LibraryJsonCodec codec;
    private WaypointStorePersistence persistence;

    private static Gson buildGson()
    {
        return new GsonBuilder()
            .registerTypeAdapter(Instant.class,
                (com.google.gson.JsonSerializer<Instant>) (src, t, c) ->
                    new com.google.gson.JsonPrimitive(src.toString()))
            .registerTypeAdapter(Instant.class,
                (com.google.gson.JsonDeserializer<Instant>) (e, t, c) ->
                    Instant.parse(e.getAsString()))
            .create();
    }

    @Before
    public void setUp()
    {
        configManager = mock(ConfigManager.class);
        codec = new LibraryJsonCodec(buildGson());
        persistence = new WaypointStorePersistence(configManager, codec);
    }

    private Library oneCategory()
    {
        Library lib = new Library();
        lib.getCategories().add(new Category(UUID.randomUUID(), "Mining", 1, false, null, false));
        return lib;
    }

    @Test
    public void loadReturnsEmptyWhenNoConfigValue()
    {
        when(configManager.getRSProfileConfiguration("waypointer", "library")).thenReturn(null);
        Library lib = persistence.load();
        assertNotNull(lib);
        assertTrue(lib.getWaypoints().isEmpty());
    }

    @Test
    public void saveWritesEncodedLibraryToRsProfileConfig()
    {
        Library lib = oneCategory();
        persistence.save(lib);
        verify(configManager).setRSProfileConfiguration("waypointer", "library", codec.encode(lib));
    }

    @Test
    public void saveAndLoadRoundTripThroughConfig()
    {
        Library lib = oneCategory();
        when(configManager.getRSProfileConfiguration("waypointer", "library"))
            .thenReturn(codec.encode(lib));
        Library loaded = persistence.load();
        assertTrue(loaded.getCategories().stream().anyMatch(c -> "Mining".equals(c.getName())));
    }

    @Test
    public void corruptValueFreezesSavesAndReturnsEmpty()
    {
        when(configManager.getRSProfileConfiguration("waypointer", "library"))
            .thenReturn("{ not valid json");
        Library lib = persistence.load();
        assertTrue(lib.getWaypoints().isEmpty());
        assertTrue(persistence.isRefusingSaves());
        persistence.save(new Library());
        verify(configManager, never()).setRSProfileConfiguration(anyString(), anyString(), any());
    }

    @Test
    public void clearUnsetsConfigAndLiftsFreeze()
    {
        when(configManager.getRSProfileConfiguration("waypointer", "library"))
            .thenReturn("{ bad");
        persistence.load();
        assertTrue(persistence.isRefusingSaves());
        persistence.clear();
        verify(configManager).unsetRSProfileConfiguration("waypointer", "library");
        assertFalse(persistence.isRefusingSaves());
    }
}

package com.waypointer.service;

import com.waypointer.model.Category;
import com.waypointer.model.CategorySortMode;
import com.waypointer.model.Library;
import com.waypointer.model.Waypoint;
import java.time.Instant;
import java.util.Collections;
import java.util.HashSet;
import java.util.UUID;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

public class LibrarySubsetBuilderTest
{
    private static Waypoint wp(UUID id, UUID catId, String name)
    {
        return new Waypoint(id, name, 1, catId, null, "",
            Instant.parse("2026-05-02T00:00:00Z"), 0, false, null, false);
    }

    @Test
    public void includesOnlySelectedWaypoints()
    {
        UUID cat = UUID.randomUUID();
        UUID keep = UUID.randomUUID();
        UUID drop = UUID.randomUUID();
        Library src = new Library();
        src.getCategories().add(new Category(cat, "Banks", 0, false, null, false));
        src.getWaypoints().add(wp(keep, cat, "GE"));
        src.getWaypoints().add(wp(drop, cat, "Falador"));

        Library out = LibrarySubsetBuilder.build(src,
            new HashSet<>(Collections.singletonList(keep)), Collections.emptySet());

        assertEquals(1, out.getWaypoints().size());
        assertEquals("GE", out.getWaypoints().get(0).getName());
    }

    @Test
    public void pullsInCategoryDefForReferencedCategory()
    {
        UUID cat = UUID.randomUUID();
        UUID wpId = UUID.randomUUID();
        Library src = new Library();
        src.getCategories().add(new Category(cat, "Banks", 3, false, 99, false));
        src.getWaypoints().add(wp(wpId, cat, "GE"));

        Library out = LibrarySubsetBuilder.build(src,
            new HashSet<>(Collections.singletonList(wpId)), Collections.emptySet());

        assertEquals(1, out.getCategories().size());
        assertEquals("Banks", out.getCategories().get(0).getName());
        assertEquals(Integer.valueOf(99), out.getCategories().get(0).getIconId());
    }

    @Test
    public void includesExplicitlyCheckedEmptyCategory()
    {
        UUID cat = UUID.randomUUID();
        Library src = new Library();
        src.getCategories().add(new Category(cat, "Empty", 0, false, null, false));

        Library out = LibrarySubsetBuilder.build(src,
            Collections.emptySet(), new HashSet<>(Collections.singletonList(cat)));

        assertEquals(1, out.getCategories().size());
        assertTrue(out.getWaypoints().isEmpty());
    }

    @Test
    public void includesUncategorizedSentinelWhenReferenced()
    {
        UUID unc = UUID.randomUUID();
        UUID wpId = UUID.randomUUID();
        Library src = new Library();
        src.getCategories().add(new Category(unc, "Uncategorized", 0, true, null, false));
        src.getWaypoints().add(wp(wpId, unc, "Loose"));

        Library out = LibrarySubsetBuilder.build(src,
            new HashSet<>(Collections.singletonList(wpId)), Collections.emptySet());

        assertEquals(1, out.getCategories().size());
        assertTrue(out.getCategories().get(0).isUncategorized());
    }

    @Test
    public void doesNotMutateSource()
    {
        UUID cat = UUID.randomUUID();
        UUID wpId = UUID.randomUUID();
        Library src = new Library();
        src.getCategories().add(new Category(cat, "Banks", 0, false, null, false));
        src.getWaypoints().add(wp(wpId, cat, "GE"));

        LibrarySubsetBuilder.build(src,
            new HashSet<>(Collections.singletonList(wpId)), Collections.emptySet());

        assertEquals(1, src.getWaypoints().size());
        assertEquals(1, src.getCategories().size());
    }

    @Test
    public void includesOnlyTheSelectedWaypointFromAMultiWaypointCategory()
    {
        UUID cat = UUID.randomUUID();
        UUID keep = UUID.randomUUID();
        UUID drop1 = UUID.randomUUID();
        UUID drop2 = UUID.randomUUID();
        Library src = new Library();
        src.getCategories().add(new Category(cat, "Banks", 0, false, null, false));
        src.getWaypoints().add(wp(keep, cat, "GE"));
        src.getWaypoints().add(wp(drop1, cat, "Falador"));
        src.getWaypoints().add(wp(drop2, cat, "Varrock"));

        Library out = LibrarySubsetBuilder.build(src,
            new HashSet<>(Collections.singletonList(keep)), Collections.emptySet());

        assertEquals(1, out.getWaypoints().size());
        assertEquals("GE", out.getWaypoints().get(0).getName());
        assertEquals(1, out.getCategories().size());
    }

    @Test
    public void preservesCategorySortMode()
    {
        UUID cat = UUID.randomUUID();
        UUID wpId = UUID.randomUUID();
        Library src = new Library();
        Category source = new Category(cat, "Banks", 0, false, null, false);
        source.setSortMode(CategorySortMode.NAME);
        src.getCategories().add(source);
        src.getWaypoints().add(wp(wpId, cat, "GE"));

        Library out = LibrarySubsetBuilder.build(src,
            new HashSet<>(Collections.singletonList(wpId)), Collections.emptySet());

        assertEquals(CategorySortMode.NAME, out.getCategories().get(0).getSortMode());
    }

    @Test
    public void subsetCarriesCurrentSchemaVersion()
    {
        Library out = LibrarySubsetBuilder.build(new Library(),
            Collections.emptySet(), Collections.emptySet());
        assertEquals(Library.CURRENT_SCHEMA_VERSION, out.getSchemaVersion());
    }

    @Test
    public void orphanWaypointWithUnknownCategoryCarriesNoCategory()
    {
        UUID unknownCat = UUID.randomUUID();
        UUID wpId = UUID.randomUUID();
        Library src = new Library();
        // source has no category matching unknownCat
        src.getWaypoints().add(wp(wpId, unknownCat, "Orphan"));

        Library out = LibrarySubsetBuilder.build(src,
            new HashSet<>(Collections.singletonList(wpId)), Collections.emptySet());

        assertEquals(1, out.getWaypoints().size());
        assertTrue(out.getCategories().isEmpty());
    }

    @Test
    public void nullSetsAreTreatedAsEmpty()
    {
        UUID cat = UUID.randomUUID();
        UUID wpId = UUID.randomUUID();
        Library src = new Library();
        src.getCategories().add(new Category(cat, "Banks", 0, false, null, false));
        src.getWaypoints().add(wp(wpId, cat, "GE"));

        Library out = LibrarySubsetBuilder.build(src, null, null);

        assertEquals(0, out.getWaypoints().size());
        assertEquals(0, out.getCategories().size());
        // source must not be touched
        assertEquals(1, src.getWaypoints().size());
        assertEquals(1, src.getCategories().size());
    }
}

