package com.waypointer.service;

import com.waypointer.model.route.RouteLibrary;
import org.junit.Test;
import static org.junit.Assert.assertEquals;

public class RouteStoreWiringTest
{
    @Test
    public void saverFiresOnEachMutation()
    {
        RouteStore store = new RouteStore();
        int[] count = {0};
        store.enablePersistence(() -> count[0]++);
        store.createRoute("A");
        store.createRoute("B");
        assertEquals(2, count[0]);
    }

    @Test
    public void enablePersistenceIsIdempotent()
    {
        RouteStore store = new RouteStore();
        int[] count = {0};
        Runnable saver = () -> count[0]++;
        store.enablePersistence(saver);
        store.enablePersistence(saver);
        store.createRoute("A");
        assertEquals(1, count[0]);
    }

    @Test
    public void disablePersistenceStopsTheSaver()
    {
        RouteStore store = new RouteStore();
        int[] count = {0};
        store.enablePersistence(() -> count[0]++);
        store.disablePersistence();
        store.createRoute("A");
        assertEquals(0, count[0]);
    }

    @Test
    public void saverReadsLiveLibraryAfterBootstrap()
    {
        RouteStore store = new RouteStore();
        int[] lastSeenRouteCount = {-1};
        store.enablePersistence(() -> lastSeenRouteCount[0] = store.getLibrary().getRoutes().size());
        store.bootstrap(new RouteLibrary());
        assertEquals(store.getLibrary().getRoutes().size(), lastSeenRouteCount[0]);
    }
}

package com.waypointer.service;

import static org.junit.Assert.assertEquals;
import com.waypointer.model.WorldPointPacker;
import com.waypointer.model.route.Route;
import com.waypointer.model.route.RouteLibrary;
import com.waypointer.model.route.StepType;
import net.runelite.api.coords.WorldPoint;
import org.junit.Before;
import org.junit.Test;

public class RouteRecorderTest
{
    private RouteStore store;

    @Before
    public void setUp()
    {
        store = new RouteStore();
        store.bootstrap(new RouteLibrary());
    }

    // Test recorder: tile supplied directly, naming stubbed to a fixed string so we can assert
    // the label comes from the naming function (not a hardcoded "Waypoint").
    private RouteRecorder recorderAt(WorldPoint tile)
    {
        return new RouteRecorder(store, () -> tile, packed -> "Auto name");
    }

    @Test
    public void addCurrentLocationToAppendsAutoNamedWaypoint()
    {
        Route r = store.createRoute("R");
        recorderAt(new WorldPoint(3200, 3200, 0)).addCurrentLocationTo(r.getId());

        Route saved = store.getRouteById(r.getId());
        assertEquals(1, saved.getSteps().size());
        assertEquals(StepType.WAYPOINT, saved.getSteps().get(0).getType());
        assertEquals(WorldPointPacker.pack(3200, 3200, 0),
            saved.getSteps().get(0).getPackedWorldPoint());
        assertEquals("Auto name", saved.getSteps().get(0).getLabel());
    }

    @Test
    public void addCurrentLocationToIsNoOpWhenNotLoggedIn()
    {
        Route r = store.createRoute("R");
        recorderAt(null).addCurrentLocationTo(r.getId());
        assertEquals(0, store.getRouteById(r.getId()).getSteps().size());
    }

    @Test
    public void addCurrentLocationToIsNoOpForNullRoute()
    {
        Route r = store.createRoute("R");
        recorderAt(new WorldPoint(3200, 3200, 0)).addCurrentLocationTo(null);
        assertEquals(0, store.getRouteById(r.getId()).getSteps().size());
    }
}

package com.waypointer.service;

import com.waypointer.WaypointerConfig;
import com.waypointer.model.WorldPointPacker;
import net.runelite.api.Actor;
import net.runelite.api.Client;
import net.runelite.api.Player;
import net.runelite.api.WorldView;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.events.ActorDeath;
import org.junit.Before;
import org.junit.Test;
import static org.mockito.ArgumentMatchers.anyInt;
import static org.mockito.ArgumentMatchers.anyString;
import static org.mockito.ArgumentMatchers.eq;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.never;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.when;

public class DeathAutoPathfinderTest
{
    private Client client;
    private WaypointPathfinder pathfinder;
    private WaypointerConfig config;
    private Player localPlayer;
    private WorldView worldView;
    private DeathAutoPathfinder subject;

    @Before
    public void setUp()
    {
        client = mock(Client.class);
        pathfinder = mock(WaypointPathfinder.class);
        config = mock(WaypointerConfig.class);
        localPlayer = mock(Player.class);

        // Default "happy" wiring; individual tests override what they need.
        when(config.autoPathOnDeath()).thenReturn(true);
        when(pathfinder.isAvailable()).thenReturn(true);
        worldView = mock(WorldView.class);
        when(client.getTopLevelWorldView()).thenReturn(worldView);
        when(worldView.isInstance()).thenReturn(false);
        when(client.getLocalPlayer()).thenReturn(localPlayer);
        when(localPlayer.getWorldLocation()).thenReturn(new WorldPoint(3200, 3200, 0));

        subject = new DeathAutoPathfinder(client, pathfinder, config);
    }

    @Test
    public void pathsToDeathTileOnLocalPlayerDeath()
    {
        subject.onActorDeath(new ActorDeath(localPlayer));

        int expected = WorldPointPacker.pack(3200, 3200, 0);
        verify(pathfinder).requestPath(eq(expected), eq("Death location"));
    }

    @Test
    public void doesNothingWhenDisabled()
    {
        when(config.autoPathOnDeath()).thenReturn(false);
        subject.onActorDeath(new ActorDeath(localPlayer));
        verify(pathfinder, never()).requestPath(anyInt(), anyString());
    }

    @Test
    public void doesNothingWhenShortestPathUnavailable()
    {
        when(pathfinder.isAvailable()).thenReturn(false);
        subject.onActorDeath(new ActorDeath(localPlayer));
        verify(pathfinder, never()).requestPath(anyInt(), anyString());
    }

    @Test
    public void ignoresNonLocalActorDeath()
    {
        Actor other = mock(Actor.class);
        subject.onActorDeath(new ActorDeath(other));
        verify(pathfinder, never()).requestPath(anyInt(), anyString());
    }

    @Test
    public void doesNothingInInstancedRegion()
    {
        when(worldView.isInstance()).thenReturn(true);
        subject.onActorDeath(new ActorDeath(localPlayer));
        verify(pathfinder, never()).requestPath(anyInt(), anyString());
    }

    @Test
    public void doesNothingWhenLocalPlayerNull()
    {
        when(client.getLocalPlayer()).thenReturn(null);
        subject.onActorDeath(new ActorDeath(localPlayer));
        verify(pathfinder, never()).requestPath(anyInt(), anyString());
    }

    @Test
    public void doesNothingWhenWorldLocationNull()
    {
        when(localPlayer.getWorldLocation()).thenReturn(null);
        subject.onActorDeath(new ActorDeath(localPlayer));
        verify(pathfinder, never()).requestPath(anyInt(), anyString());
    }
}

package com.waypointer.service;

import com.waypointer.model.WorldPointPacker;
import java.util.Arrays;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

public class CacheLabelIndexTest
{
    @Test
    public void loadsAtLeastOneRowFromMapLabelsTsv()
    {
        CacheLabelIndex idx = new CacheLabelIndex();
        assertTrue(idx.size() > 0);
    }

    @Test
    public void repeatedPoiHitWithinThreeTilesReturnsPoiTier()
    {
        // Two entries with the same name -> nameCounts=2 -> no promotion, tight 3-tile radius.
        CacheLabelIndex idx = CacheLabelIndex.forTesting(Arrays.asList(
            new CacheLabelIndex.Entry(WorldPointPacker.pack(3208, 3220, 0), "Bank", 0),
            new CacheLabelIndex.Entry(WorldPointPacker.pack(3253, 3420, 0), "Bank", 0)));

        LookupHit h = idx.lookup(WorldPointPacker.pack(3210, 3221, 0));
        assertNotNull(h);
        assertEquals("Bank", h.getName());
        assertEquals(LookupHit.Tier.POI, h.getTier());
    }

    @Test
    public void repeatedPoiOutOfRadiusReturnsNull()
    {
        CacheLabelIndex idx = CacheLabelIndex.forTesting(Arrays.asList(
            new CacheLabelIndex.Entry(WorldPointPacker.pack(3208, 3220, 0), "Bank", 0),
            new CacheLabelIndex.Entry(WorldPointPacker.pack(3253, 3420, 0), "Bank", 0)));

        assertNull(idx.lookup(WorldPointPacker.pack(3215, 3220, 0))); // 7 tiles from nearest, > 3
    }

    @Test
    public void uniqueNamePoiPromotedToFiftyTileRadius()
    {
        CacheLabelIndex idx = CacheLabelIndex.forTesting(Arrays.asList(
            new CacheLabelIndex.Entry(WorldPointPacker.pack(3168, 3477, 0), "Grand Exchange", 0)));

        // 30 tiles from the label tile -- outside old 3-tile POI radius, inside 50-tile promoted radius.
        LookupHit h = idx.lookup(WorldPointPacker.pack(3168, 3507, 0));
        assertNotNull(h);
        assertEquals("Grand Exchange", h.getName());
        assertEquals(LookupHit.Tier.POI, h.getTier()); // Tier stays POI -> no coords appended.
    }

    @Test
    public void uniqueNamePoiStopsAtFiftyTileRadius()
    {
        CacheLabelIndex idx = CacheLabelIndex.forTesting(Arrays.asList(
            new CacheLabelIndex.Entry(WorldPointPacker.pack(3168, 3477, 0), "Grand Exchange", 0)));

        // 60 tiles from the label tile -- past the 50-tile promoted radius.
        assertNull(idx.lookup(WorldPointPacker.pack(3168, 3537, 0)));
    }

    @Test
    public void uniquePoiBeatsCityWhenInRange()
    {
        CacheLabelIndex idx = CacheLabelIndex.forTesting(Arrays.asList(
            new CacheLabelIndex.Entry(WorldPointPacker.pack(3210, 3424, 0), "Varrock", 2),
            new CacheLabelIndex.Entry(WorldPointPacker.pack(3168, 3477, 0), "Grand Exchange", 0)));

        // 5 tiles from GE, 55 tiles from Varrock label. Both in their respective radii.
        LookupHit h = idx.lookup(WorldPointPacker.pack(3168, 3482, 0));
        assertNotNull(h);
        assertEquals("Grand Exchange", h.getName());
        assertEquals(LookupHit.Tier.POI, h.getTier());
    }

    @Test
    public void cityHitWithinTwoHundredTilesReturnsCityTier()
    {
        CacheLabelIndex idx = CacheLabelIndex.forTesting(Arrays.asList(
            new CacheLabelIndex.Entry(WorldPointPacker.pack(3210, 3424, 0), "Varrock", 2)));

        LookupHit h = idx.lookup(WorldPointPacker.pack(3270, 3450, 0)); // 60 tiles away
        assertNotNull(h);
        assertEquals("Varrock", h.getName());
        assertEquals(LookupHit.Tier.CITY, h.getTier());
    }

    @Test
    public void poiBeatsCityWhenBothInRange()
    {
        CacheLabelIndex idx = CacheLabelIndex.forTesting(Arrays.asList(
            new CacheLabelIndex.Entry(WorldPointPacker.pack(3210, 3424, 0), "Varrock", 2),
            new CacheLabelIndex.Entry(WorldPointPacker.pack(3253, 3422, 0), "Bank", 0)));

        // Stand 2 tiles from the bank. POI tier wins.
        LookupHit h = idx.lookup(WorldPointPacker.pack(3254, 3422, 0));
        assertNotNull(h);
        assertEquals("Bank", h.getName());
        assertEquals(LookupHit.Tier.POI, h.getTier());
    }

    @Test
    public void ignoresOtherPlanes()
    {
        CacheLabelIndex idx = CacheLabelIndex.forTesting(Arrays.asList(
            new CacheLabelIndex.Entry(WorldPointPacker.pack(3208, 3220, 0), "Bank", 0)));

        assertNull(idx.lookup(WorldPointPacker.pack(3208, 3220, 1)));
    }
}

package com.waypointer.service;

import com.waypointer.preset.Preset;
import com.waypointer.preset.PresetWaypoint;
import com.waypointer.service.PresetImportResolver.Choice;
import com.waypointer.service.PresetImportResolver.PendingConflict;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

public class PresetImportConflictTest
{
    @Test
    public void noConflictsStageAllAsAdds()
    {
        List<Preset> current = new ArrayList<>();
        List<Preset> imported = Arrays.asList(new Preset("Bosses", null, null,
            Arrays.asList(new PresetWaypoint("Vorkath", "", 1, 1, 0))));
        PresetImportResolver r = new PresetImportResolver(current, imported);
        assertTrue(r.conflicts().isEmpty());
        assertEquals(1, r.staged().size());
    }

    @Test
    public void duplicateWaypointSurfacesConflict()
    {
        List<Preset> current = Arrays.asList(new Preset("Bosses", null, null,
            Arrays.asList(new PresetWaypoint("Vorkath", "old", 1, 1, 0))));
        List<Preset> imported = Arrays.asList(new Preset("Bosses", null, null,
            Arrays.asList(new PresetWaypoint("Vorkath", "new", 2, 2, 0))));
        PresetImportResolver r = new PresetImportResolver(current, imported);
        assertEquals(1, r.conflicts().size());
    }

    @Test
    public void replaceResolutionStagesImport()
    {
        List<Preset> current = Arrays.asList(new Preset("Bosses", null, null,
            Arrays.asList(new PresetWaypoint("Vorkath", "old", 1, 1, 0))));
        List<Preset> imported = Arrays.asList(new Preset("Bosses", null, null,
            Arrays.asList(new PresetWaypoint("Vorkath", "new", 2, 2, 0))));
        PresetImportResolver r = new PresetImportResolver(current, imported);
        for (PendingConflict c : r.conflicts()) r.resolve(c, Choice.REPLACE);
        assertEquals(1, r.staged().size());
        assertEquals("new", r.staged().get(0).getDescription());
    }

    @Test
    public void skipResolutionStagesNothing()
    {
        List<Preset> current = Arrays.asList(new Preset("Bosses", null, null,
            Arrays.asList(new PresetWaypoint("Vorkath", "old", 1, 1, 0))));
        List<Preset> imported = Arrays.asList(new Preset("Bosses", null, null,
            Arrays.asList(new PresetWaypoint("Vorkath", "new", 2, 2, 0))));
        PresetImportResolver r = new PresetImportResolver(current, imported);
        for (PendingConflict c : r.conflicts()) r.resolve(c, Choice.SKIP);
        assertTrue(r.staged().isEmpty());
    }
}

package com.waypointer.service;

import com.waypointer.model.WorldPointPacker;
import java.util.Arrays;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

public class BboxIndexTest
{
    @Test
    public void loadsBundledTsvs()
    {
        BboxIndex idx = new BboxIndex();
        // (0, 0, 0) is outside every known bbox so the bundled-resource ctor must return null
        // rather than throwing — proves loadResource walked every TSV without error.
        assertNull(idx.lookup(WorldPointPacker.pack(0, 0, 0)));
    }

    @Test
    public void forTestingBuildsFromLiteralEntries()
    {
        BboxIndex idx = BboxIndex.forTesting(Arrays.asList(
            new BboxIndex.Entry(3087, 3486, 3103, 3502, 0, "Edgeville Bank")));
        assertEquals("Edgeville Bank", idx.lookup(WorldPointPacker.pack(3094, 3493, 0)));
    }

    @Test
    public void entryComputesAreaInclusive()
    {
        BboxIndex.Entry e = new BboxIndex.Entry(0, 0, 4, 4, 0, "x");
        assertTrue(e.area == 25); // (4-0+1) * (4-0+1)
    }

    @Test
    public void tileInsideBboxReturnsName()
    {
        BboxIndex idx = BboxIndex.forTesting(Arrays.asList(
            new BboxIndex.Entry(3087, 3486, 3103, 3502, 0, "Edgeville Bank")));

        assertEquals("Edgeville Bank", idx.lookup(WorldPointPacker.pack(3094, 3493, 0)));
    }

    @Test
    public void tileOutsideBboxReturnsNull()
    {
        BboxIndex idx = BboxIndex.forTesting(Arrays.asList(
            new BboxIndex.Entry(3087, 3486, 3103, 3502, 0, "Edgeville Bank")));

        assertNull(idx.lookup(WorldPointPacker.pack(3200, 3200, 0)));
    }

    @Test
    public void smallestAreaWinsOnOverlap()
    {
        // Outer 100x100 polygon, inner 5x5 polygon, point inside both.
        BboxIndex idx = BboxIndex.forTesting(Arrays.asList(
            new BboxIndex.Entry(3000, 3000, 3099, 3099, 0, "Big Area"),
            new BboxIndex.Entry(3050, 3050, 3054, 3054, 0, "Small POI")));

        assertEquals("Small POI", idx.lookup(WorldPointPacker.pack(3052, 3052, 0)));
    }

    @Test
    public void ignoresOtherPlanes()
    {
        BboxIndex idx = BboxIndex.forTesting(Arrays.asList(
            new BboxIndex.Entry(3087, 3486, 3103, 3502, 0, "Edgeville Bank")));

        assertNull(idx.lookup(WorldPointPacker.pack(3094, 3493, 1)));
    }

    @Test
    public void degenerateOneByOneBboxMatchesExactTile()
    {
        BboxIndex idx = BboxIndex.forTesting(Arrays.asList(
            new BboxIndex.Entry(2412, 4434, 2412, 4434, 0, "Zanaris Fairy Ring")));

        assertEquals("Zanaris Fairy Ring", idx.lookup(WorldPointPacker.pack(2412, 4434, 0)));
        assertNull(idx.lookup(WorldPointPacker.pack(2413, 4434, 0)));
    }

    @Test
    public void bundledTsvsCoverEdgevilleBank()
    {
        BboxIndex idx = new BboxIndex();
        String name = idx.lookup(WorldPointPacker.pack(3094, 3493, 0));
        assertEquals("Edgeville Bank", name);
    }

    @Test
    public void bundledTsvsCoverGrandExchangePlaza()
    {
        BboxIndex idx = new BboxIndex();
        String name = idx.lookup(WorldPointPacker.pack(3163, 3490, 0));
        assertNotNull(name);
        assertTrue("expected GE-area bbox, got " + name, name.toLowerCase().contains("grand exchange"));
    }

    // --- nearest(type, from) -----------------------------------------------------

    @Test
    public void nearest_picksClosestOfRequestedType()
    {
        // Two banks at different distances; player at (3094, 3493). The Edgeville one
        // (centre ~3094, 3494) is right next to the player; Falador (~3014, 3357) is far.
        BboxIndex idx = BboxIndex.forTesting(java.util.Arrays.asList(
            new BboxIndex.Entry(3087, 3486, 3103, 3502, 0, "Edgeville Bank", LandmarkType.BANK),
            new BboxIndex.Entry(3010, 3353, 3018, 3361, 0, "Falador West Bank", LandmarkType.BANK)));

        BboxIndex.Hit hit = idx.nearest(LandmarkType.BANK, WorldPointPacker.pack(3094, 3493, 0));

        assertNotNull(hit);
        assertEquals("Edgeville Bank", hit.name);
    }

    @Test
    public void nearest_distanceClampsToEdgeButTargetsCentre()
    {
        // 5x5 bank at (3050..3054, 3050..3054). Player at (3056, 3052) is 2 tiles east of the
        // bbox: distance ranks by the nearest edge (2), but the path target is the bbox CENTRE
        // (3052, 3052) so quick-nav ends inside the bank, not on its boundary.
        BboxIndex idx = BboxIndex.forTesting(java.util.Collections.singletonList(
            new BboxIndex.Entry(3050, 3050, 3054, 3054, 0, "Test Bank", LandmarkType.BANK)));

        BboxIndex.Hit hit = idx.nearest(LandmarkType.BANK, WorldPointPacker.pack(3056, 3052, 0));

        assertNotNull(hit);
        assertEquals(2, hit.distance);
        assertEquals(3052, WorldPointPacker.getX(hit.packed));
        assertEquals(3052, WorldPointPacker.getY(hit.packed));
        assertEquals(0, WorldPointPacker.getPlane(hit.packed));
    }

    @Test
    public void nearest_isPlaneAgnostic()
    {
        // Player on plane 1 (dungeon), only bank is on plane 0 (overworld).
        // Plane-agnostic search returns it, and the Hit carries the bbox's plane (0).
        BboxIndex idx = BboxIndex.forTesting(java.util.Collections.singletonList(
            new BboxIndex.Entry(3087, 3486, 3103, 3502, 0, "Edgeville Bank", LandmarkType.BANK)));

        BboxIndex.Hit hit = idx.nearest(LandmarkType.BANK, WorldPointPacker.pack(3094, 3493, 1));

        assertNotNull(hit);
        assertEquals(0, WorldPointPacker.getPlane(hit.packed));
    }

    @Test
    public void nearest_returnsNullWhenNoEntriesOfType()
    {
        BboxIndex idx = BboxIndex.forTesting(java.util.Collections.singletonList(
            new BboxIndex.Entry(3087, 3486, 3103, 3502, 0, "Edgeville Bank", LandmarkType.BANK)));

        // No altars in the index at all.
        assertNull(idx.nearest(LandmarkType.ALTAR, WorldPointPacker.pack(3094, 3493, 0)));
    }

    @Test
    public void nearest_chebyshevDiagonalIsOne()
    {
        // 1x1 bank at (3050, 3050). Player at (3051, 3051) is one tile diagonally away.
        // Chebyshev gives 1 (matches OSRS movement), not sqrt(2).
        BboxIndex idx = BboxIndex.forTesting(java.util.Collections.singletonList(
            new BboxIndex.Entry(3050, 3050, 3050, 3050, 0, "Tile Bank", LandmarkType.BANK)));

        BboxIndex.Hit hit = idx.nearest(LandmarkType.BANK, WorldPointPacker.pack(3051, 3051, 0));

        assertNotNull(hit);
        assertEquals(1, hit.distance);
    }

    @Test
    public void nearest_includesBankChests()
    {
        // Use the production constructor so the bank-chests TSV's BANK mapping is actually
        // exercised. The Lunar Isle bank chest lives around (2099, 3919). Asking for the
        // nearest BANK from that tile must return a hit (could be the chest or a Piscarilius
        // bank further away -- both are LandmarkType.BANK).
        BboxIndex idx = new BboxIndex();
        BboxIndex.Hit hit = idx.nearest(LandmarkType.BANK, WorldPointPacker.pack(2099, 3919, 0));

        assertNotNull(hit);
        // distance to the nearest BANK from inside the dataset must be small (this point
        // sits on or near the Lunar Isle bank chest itself).
        assertTrue("expected nearby bank, got distance " + hit.distance, hit.distance < 10);
    }
}

package com.waypointer.service;

import com.waypointer.model.Category;
import com.waypointer.model.Waypoint;
import java.time.Instant;
import java.util.UUID;
import org.junit.Test;
import static org.junit.Assert.*;

public class WaypointFilterTest
{
    private static Category cat(String name)
    {
        return new Category(UUID.randomUUID(), name, 0, false, null, false);
    }

    private static Waypoint wp(String name, String notes, UUID catId)
    {
        return new Waypoint(UUID.randomUUID(), name, 0, catId, null,
            notes == null ? "" : notes, Instant.parse("2026-05-02T00:00:00Z"), 0, false, null, false);
    }

    @Test
    public void emptyFilterMatchesEverything()
    {
        Category c = cat("Bossing");
        Waypoint w = wp("Vorkath", "drops dragonbone", c.getId());
        assertTrue(WaypointFilter.matches(w, c, ""));
        assertTrue(WaypointFilter.matches(w, c, null));
    }

    @Test
    public void nameMatchIsCaseInsensitive()
    {
        Category c = cat("Bossing");
        Waypoint w = wp("Vorkath", "", c.getId());
        assertTrue(WaypointFilter.matches(w, c, "vork"));
        assertTrue(WaypointFilter.matches(w, c, "VORK"));
        assertTrue(WaypointFilter.matches(w, c, "VorK"));
    }

    @Test
    public void notesMatchIsCaseInsensitive()
    {
        Category c = cat("Bossing");
        Waypoint w = wp("Vorkath", "Drops dragonbones for prayer", c.getId());
        assertTrue(WaypointFilter.matches(w, c, "prayer"));
        assertTrue(WaypointFilter.matches(w, c, "DRAGON"));
    }

    @Test
    public void categoryNameMatchReturnsTrueRegardlessOfWaypointContents()
    {
        Category c = cat("Bossing");
        Waypoint w = wp("Vorkath", "drops dragonbone", c.getId());
        // "boss" is not in waypoint name or notes, but is in category name.
        assertTrue(WaypointFilter.matches(w, c, "boss"));
    }

    @Test
    public void nonMatchReturnsFalse()
    {
        Category c = cat("Bossing");
        Waypoint w = wp("Vorkath", "drops dragonbones", c.getId());
        assertFalse(WaypointFilter.matches(w, c, "skilling"));
        assertFalse(WaypointFilter.matches(w, c, "xyz"));
    }

    @Test
    public void nullCategoryStillMatchesOnWaypointFields()
    {
        Waypoint w = wp("Vorkath", "drops dragonbone", UUID.randomUUID());
        assertTrue(WaypointFilter.matches(w, null, "vork"));
        assertFalse(WaypointFilter.matches(w, null, "boss"));
    }

    @Test
    public void categoryNameMatchesHelper()
    {
        Category c = cat("Bossing");
        assertTrue(WaypointFilter.categoryNameMatches(c, "boss"));
        assertTrue(WaypointFilter.categoryNameMatches(c, "BOSS"));
        assertFalse(WaypointFilter.categoryNameMatches(c, "skilling"));
        // Empty / null filter is treated as "match all".
        assertTrue(WaypointFilter.categoryNameMatches(c, ""));
        assertTrue(WaypointFilter.categoryNameMatches(c, null));
    }

    @Test
    public void nullWaypointFieldsDoNotCrash()
    {
        Category c = cat("Bossing");
        // Use raw constructor to make name/notes null.
        Waypoint w = new Waypoint(UUID.randomUUID(), null, 0, c.getId(), null, null,
            Instant.parse("2026-05-02T00:00:00Z"), 0, false, null, false);
        // Filter that matches category name still passes.
        assertTrue(WaypointFilter.matches(w, c, "boss"));
        // Filter that matches nothing returns false without NPE.
        assertFalse(WaypointFilter.matches(w, c, "vork"));
    }
}

package com.waypointer.service;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import com.waypointer.model.WorldPointPacker;
import com.waypointer.model.route.Route;
import com.waypointer.model.route.RouteLibrary;
import com.waypointer.model.route.RouteStep;
import com.waypointer.model.route.StepType;
import java.util.Arrays;
import java.util.List;
import java.util.UUID;
import java.util.concurrent.atomic.AtomicInteger;
import org.junit.Before;
import org.junit.Test;

public class RouteStoreTest
{
    private RouteStore store;

    @Before
    public void setUp()
    {
        store = new RouteStore();
        store.bootstrap(new RouteLibrary());
    }

    @Test
    public void createRouteAppearsInOrderedList()
    {
        Route r = store.createRoute("Herb run");
        assertEquals(1, store.getRoutesOrdered().size());
        assertEquals("Herb run", store.getRoutesOrdered().get(0).getName());
        assertEquals(r.getId(), store.getRouteById(r.getId()).getId());
    }

    @Test
    public void mutationsFireListeners()
    {
        AtomicInteger fires = new AtomicInteger();
        store.subscribe(fires::incrementAndGet);
        store.createRoute("A");
        assertEquals(1, fires.get());
    }

    @Test
    public void addWaypointAndManualSteps()
    {
        Route r = store.createRoute("R");
        store.addWaypointStep(r.getId(), WorldPointPacker.pack(3200, 3200, 0), "Bank", null);
        store.addManualStep(r.getId(), "Withdraw");
        List<RouteStep> steps = store.getRouteById(r.getId()).getSteps();
        assertEquals(2, steps.size());
        assertEquals(StepType.WAYPOINT, steps.get(0).getType());
        assertEquals(StepType.MANUAL, steps.get(1).getType());
    }

    @Test
    public void updateStepLabelChangesText()
    {
        Route r = store.createRoute("R");
        store.addManualStep(r.getId(), "old");
        UUID stepId = r.getSteps().get(0).getId();
        store.updateStepLabel(r.getId(), stepId, "new");
        assertEquals("new", store.getRouteById(r.getId()).getSteps().get(0).getLabel());
    }

    @Test
    public void deleteStepRemovesIt()
    {
        Route r = store.createRoute("R");
        store.addManualStep(r.getId(), "a");
        store.addManualStep(r.getId(), "b");
        UUID first = r.getSteps().get(0).getId();
        store.deleteStep(r.getId(), first);
        List<RouteStep> steps = store.getRouteById(r.getId()).getSteps();
        assertEquals(1, steps.size());
        assertEquals("b", steps.get(0).getLabel());
    }

    @Test
    public void reorderStepsAppliesOrder()
    {
        Route r = store.createRoute("R");
        store.addManualStep(r.getId(), "a");
        store.addManualStep(r.getId(), "b");
        UUID a = r.getSteps().get(0).getId();
        UUID b = r.getSteps().get(1).getId();
        store.reorderSteps(r.getId(), Arrays.asList(b, a));
        List<RouteStep> steps = store.getRouteById(r.getId()).getSteps();
        assertEquals("b", steps.get(0).getLabel());
        assertEquals("a", steps.get(1).getLabel());
    }

    @Test
    public void setRepeatingToggles()
    {
        Route r = store.createRoute("R");
        assertFalse(r.isRepeating());
        store.setRepeating(r.getId(), true);
        assertTrue(store.getRouteById(r.getId()).isRepeating());
    }

    @Test
    public void duplicateRouteCopiesStepsWithNewIds()
    {
        Route r = store.createRoute("R");
        store.addManualStep(r.getId(), "a");
        Route copy = store.duplicateRoute(r.getId());
        assertEquals(2, store.getRoutesOrdered().size());
        assertEquals(1, copy.getSteps().size());
        assertFalse(copy.getSteps().get(0).getId().equals(r.getSteps().get(0).getId()));
        assertFalse(copy.getId().equals(r.getId()));
    }

    @Test
    public void deleteRouteRemovesIt()
    {
        Route r = store.createRoute("R");
        store.deleteRoute(r.getId());
        assertEquals(0, store.getRoutesOrdered().size());
        assertNull(store.getRouteById(r.getId()));
    }

    @Test
    public void reorderRoutesAppliesSortOrder()
    {
        Route a = store.createRoute("A");
        Route b = store.createRoute("B");
        store.reorderRoutes(Arrays.asList(b.getId(), a.getId()));
        assertEquals("B", store.getRoutesOrdered().get(0).getName());
        assertEquals("A", store.getRoutesOrdered().get(1).getName());
    }

    @Test
    public void updateStepTextSetsBothFieldsAndFiresOnce()
    {
        Route r = store.createRoute("R");
        store.addManualStep(r.getId(), "old");
        UUID stepId = r.getSteps().get(0).getId();

        AtomicInteger fires = new AtomicInteger();
        store.subscribe(fires::incrementAndGet);
        store.updateStepText(r.getId(), stepId, "Bank", "Withdraw 5 seeds");

        RouteStep s = store.getRouteById(r.getId()).getSteps().get(0);
        assertEquals("Bank", s.getLabel());
        assertEquals("Withdraw 5 seeds", s.getBoxText());
        assertEquals(1, fires.get());
    }

    @Test
    public void duplicateRouteCopiesBoxText()
    {
        Route r = store.createRoute("R");
        store.addManualStep(r.getId(), "Bank");
        UUID stepId = r.getSteps().get(0).getId();
        store.updateStepText(r.getId(), stepId, "Bank", "Withdraw 5 seeds");

        Route copy = store.duplicateRoute(r.getId());
        assertEquals("Withdraw 5 seeds", copy.getSteps().get(0).getBoxText());
    }
}

