package com.waypointer.service;

import java.util.HashMap;
import java.util.Map;
import java.util.function.BooleanSupplier;
import net.runelite.api.Client;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.EventBus;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.events.PluginMessage;
import org.junit.Before;
import org.junit.Test;
import org.mockito.ArgumentCaptor;
import static org.junit.Assert.*;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.Mockito.*;

public class WaypointPathfinderTest
{
    private EventBus eventBus;
    private ClientThread clientThread;
    private Client client;
    private ConfigManager configManager;
    private WaypointPathfinder pathfinder;

    @Before
    public void setUp()
    {
        eventBus = mock(EventBus.class);
        clientThread = mock(ClientThread.class);
        client = mock(Client.class);
        configManager = mock(ConfigManager.class);
        // Run any BooleanSupplier passed to ClientThread.invoke synchronously so we can verify
        // the eventBus.post side-effect within the test.
        doAnswer(invocation -> {
            BooleanSupplier s = invocation.getArgument(0);
            s.getAsBoolean();
            return null;
        }).when(clientThread).invoke(any(BooleanSupplier.class));
        pathfinder = new WaypointPathfinder(eventBus, clientThread, client, configManager);
    }

    @Test
    public void unavailableByDefault()
    {
        assertFalse(pathfinder.isAvailable());
    }

    @Test
    public void availableWhenConfigProbeFindsPersistedKey()
    {
        when(configManager.getConfiguration("shortestpath", "recalculateDistance")).thenReturn("true");
        WaypointPathfinder p = new WaypointPathfinder(eventBus, clientThread, client, configManager);
        assertTrue(p.isAvailable());
    }

    @Test
    public void availableAfterReceivingShortestPathPluginMessage()
    {
        pathfinder.onPluginMessage(new PluginMessage("shortestpath", "transports", new HashMap<>()));
        assertTrue(pathfinder.isAvailable());
    }

    @Test
    public void ignoresPluginMessageFromOtherNamespace()
    {
        pathfinder.onPluginMessage(new PluginMessage("someotherplugin", "hello", new HashMap<>()));
        assertFalse(pathfinder.isAvailable());
    }

    @Test
    public void doesNotSelfDetectOnOwnOutboundPathOrClear()
    {
        // EventBus delivers posts to all subscribers including the poster. Our own outbound
        // `path` / `clear` messages must not be treated as proof of shortest-path's presence.
        pathfinder.onPluginMessage(new PluginMessage("shortestpath", "path", new HashMap<>()));
        assertFalse("path is sent by Waypointer, not by shortest-path", pathfinder.isAvailable());
        pathfinder.onPluginMessage(new PluginMessage("shortestpath", "clear", new HashMap<>()));
        assertFalse("clear is sent by Waypointer, not by shortest-path", pathfinder.isAvailable());
    }

    @Test
    public void availableAfterConfigChangedInShortestPathGroup()
    {
        ConfigChanged e = new ConfigChanged();
        e.setGroup("shortestpath");
        e.setKey("drawTransports");
        pathfinder.onConfigChanged(e);
        assertTrue(pathfinder.isAvailable());
    }

    @Test
    public void ignoresConfigChangedInOtherGroup()
    {
        ConfigChanged e = new ConfigChanged();
        e.setGroup("waypointer");
        e.setKey("anything");
        pathfinder.onConfigChanged(e);
        assertFalse(pathfinder.isAvailable());
    }

    @Test
    public void availabilityIsSticky()
    {
        pathfinder.onPluginMessage(new PluginMessage("shortestpath", "transports", new HashMap<>()));
        // Subsequent unrelated events must not reset the flag.
        ConfigChanged unrelated = new ConfigChanged();
        unrelated.setGroup("waypointer");
        pathfinder.onConfigChanged(unrelated);
        assertTrue(pathfinder.isAvailable());
    }

    @Test
    public void availabilityChangeFiresListenersOnce()
    {
        Runnable listener = mock(Runnable.class);
        pathfinder.subscribe(listener);
        pathfinder.onPluginMessage(new PluginMessage("shortestpath", "transports", new HashMap<>()));
        // Second message should not re-fire: already available.
        pathfinder.onPluginMessage(new PluginMessage("shortestpath", "transports", new HashMap<>()));
        verify(listener, times(1)).run();
    }

    @Test
    public void requestPathPostsExpectedPluginMessageOnClientThread()
    {
        pathfinder.requestPath(12345, "test");

        verify(clientThread).invoke(any(BooleanSupplier.class));
        ArgumentCaptor<PluginMessage> captor = ArgumentCaptor.forClass(PluginMessage.class);
        verify(eventBus).post(captor.capture());
        PluginMessage msg = captor.getValue();
        assertEquals("shortestpath", msg.getNamespace());
        assertEquals("path", msg.getName());
        Map<String, Object> data = msg.getData();
        assertEquals(Integer.valueOf(12345), data.get("target"));
        assertNull("v1 sends no start; shortest-path uses local player", data.get("start"));
    }

    @Test
    public void clearPathPostsClearMessageOnClientThread()
    {
        pathfinder.clearPath();

        verify(clientThread).invoke(any(BooleanSupplier.class));
        ArgumentCaptor<PluginMessage> captor = ArgumentCaptor.forClass(PluginMessage.class);
        verify(eventBus).post(captor.capture());
        assertEquals("clear", captor.getValue().getName());
    }
}

package com.waypointer.service;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import static org.mockito.Mockito.verify;
import com.waypointer.model.WorldPointPacker;
import com.waypointer.model.route.Route;
import com.waypointer.model.route.RouteStep;
import java.time.Instant;
import java.util.Arrays;
import java.util.UUID;
import net.runelite.api.coords.WorldPoint;
import org.junit.Before;
import org.junit.Test;
import org.junit.runner.RunWith;
import org.mockito.Mock;
import org.mockito.junit.MockitoJUnitRunner;

@RunWith(MockitoJUnitRunner.class)
public class RoutePlaybackEngineTest
{
    @Mock private WaypointPathfinder pathfinder;
    @Mock private RouteStore store;

    private RoutePlaybackEngine engine;

    private static final int BANK = WorldPointPacker.pack(3200, 3200, 0);
    private static final int PATCH = WorldPointPacker.pack(3000, 3000, 0);

    @Before
    public void setUp()
    {
        engine = new RoutePlaybackEngine(pathfinder, store);
    }

    private Route route(boolean repeating, RouteStep... steps)
    {
        return new Route(UUID.randomUUID(), "R", Arrays.asList(steps), repeating, Instant.now(), 0);
    }

    @Test
    public void startEntersFirstStepAndPathsWhenWaypoint()
    {
        Route r = route(false, RouteStep.waypoint(BANK, "Bank"), RouteStep.manual("Withdraw"));
        engine.start(r);
        assertTrue(engine.isActive());
        assertEquals(0, engine.getCurrentIndex());
        verify(pathfinder).requestPath(BANK, "Bank");
    }

    @Test
    public void manualFirstStepDoesNotPath()
    {
        Route r = route(false, RouteStep.manual("Read me"));
        engine.start(r);
        verify(pathfinder).clearPath();
    }

    @Test
    public void advanceMovesToNextStep()
    {
        Route r = route(false, RouteStep.manual("a"), RouteStep.manual("b"));
        engine.start(r);
        engine.advance();
        assertEquals(1, engine.getCurrentIndex());
        assertEquals("b", engine.getCurrentStep().getLabel());
    }

    @Test
    public void advancePastEndStopsWhenNotRepeating()
    {
        Route r = route(false, RouteStep.manual("only"));
        engine.start(r);
        engine.advance();
        assertFalse(engine.isActive());
        assertNull(engine.getCurrentStep());
    }

    @Test
    public void advancePastEndRestartsAndIncrementsLapWhenRepeating()
    {
        Route r = route(true, RouteStep.manual("a"), RouteStep.manual("b"));
        engine.start(r);
        assertEquals(1, engine.getLap());
        engine.advance();   // -> b
        engine.advance();   // wrap -> a, lap 2
        assertTrue(engine.isActive());
        assertEquals(0, engine.getCurrentIndex());
        assertEquals(2, engine.getLap());
    }

    @Test
    public void backMovesToPreviousStepClampedAtZero()
    {
        Route r = route(false, RouteStep.manual("a"), RouteStep.manual("b"));
        engine.start(r);
        engine.advance();
        engine.back();
        assertEquals(0, engine.getCurrentIndex());
        engine.back();
        assertEquals(0, engine.getCurrentIndex());
    }

    @Test
    public void arrivalWithinRadiusAdvancesWaypointStep()
    {
        Route r = route(false, RouteStep.waypoint(BANK, "Bank"), RouteStep.manual("done"));
        engine.start(r);
        engine.handleTick(new WorldPoint(3201, 3202, 0)); // within 3 tiles
        assertEquals(1, engine.getCurrentIndex());
    }

    @Test
    public void arrivalIgnoredWhenTooFarOrWrongPlane()
    {
        Route r = route(false, RouteStep.waypoint(BANK, "Bank"));
        engine.start(r);
        engine.handleTick(new WorldPoint(3260, 3260, 0)); // far
        assertEquals(0, engine.getCurrentIndex());
        engine.handleTick(new WorldPoint(3200, 3200, 1)); // right tile, wrong plane
        assertEquals(0, engine.getCurrentIndex());
    }

    @Test
    public void manualStepDoesNotAutoAdvanceOnTick()
    {
        Route r = route(false, RouteStep.manual("read"), RouteStep.manual("next"));
        engine.start(r);
        engine.handleTick(new WorldPoint(3200, 3200, 0));
        assertEquals(0, engine.getCurrentIndex());
    }

    @Test
    public void stopClearsPathAndDeactivates()
    {
        Route r = route(false, RouteStep.waypoint(BANK, "Bank"));
        engine.start(r);
        engine.stop();
        assertFalse(engine.isActive());
        verify(pathfinder).clearPath();
    }

    @Test
    public void storeDeletionOfActiveRouteStops()
    {
        Route r = route(false, RouteStep.manual("a"));
        engine.start(r);
        assertTrue(engine.isActive());
        // The mock store returns null for getRouteById, i.e. the active route was deleted.
        engine.onStoreChanged();
        assertFalse(engine.isActive());
    }
}

package com.waypointer.service;

import com.google.gson.Gson;
import com.google.gson.GsonBuilder;
import com.waypointer.codec.RouteJsonCodec;
import com.waypointer.model.route.Route;
import com.waypointer.model.route.RouteLibrary;
import com.waypointer.model.route.RouteStep;
import java.time.Instant;
import java.util.UUID;
import net.runelite.client.config.ConfigManager;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.ArgumentMatchers.anyString;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.never;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.when;

public class RouteStorePersistenceTest
{
    private ConfigManager configManager;
    private RouteJsonCodec codec;
    private RouteStorePersistence persistence;

    private static Gson buildGson()
    {
        return new GsonBuilder()
            .registerTypeAdapter(Instant.class,
                (com.google.gson.JsonSerializer<Instant>) (src, t, c) ->
                    new com.google.gson.JsonPrimitive(src.toString()))
            .registerTypeAdapter(Instant.class,
                (com.google.gson.JsonDeserializer<Instant>) (e, t, c) ->
                    Instant.parse(e.getAsString()))
            .create();
    }

    @Before
    public void setUp()
    {
        configManager = mock(ConfigManager.class);
        codec = new RouteJsonCodec(buildGson());
        persistence = new RouteStorePersistence(configManager, codec);
    }

    private RouteLibrary oneRoute()
    {
        RouteLibrary lib = new RouteLibrary();
        Route r = new Route(UUID.randomUUID(), "R1", new java.util.ArrayList<>(), false, Instant.now(), 0);
        r.getSteps().add(RouteStep.manual("step"));
        lib.getRoutes().add(r);
        return lib;
    }

    @Test
    public void loadReturnsEmptyWhenNoConfigValue()
    {
        when(configManager.getConfiguration("waypointer", "routes")).thenReturn(null);
        assertEquals(0, persistence.load().getRoutes().size());
    }

    @Test
    public void saveWritesEncodedRoutesToConfig()
    {
        RouteLibrary lib = oneRoute();
        persistence.save(lib);
        verify(configManager).setConfiguration("waypointer", "routes", codec.encode(lib));
    }

    @Test
    public void saveAndLoadRoundTripThroughConfig()
    {
        RouteLibrary lib = oneRoute();
        when(configManager.getConfiguration("waypointer", "routes")).thenReturn(codec.encode(lib));
        RouteLibrary loaded = persistence.load();
        assertEquals(1, loaded.getRoutes().size());
        assertEquals("R1", loaded.getRoutes().get(0).getName());
    }

    @Test
    public void corruptValueFreezesSavesAndReturnsEmpty()
    {
        when(configManager.getConfiguration("waypointer", "routes")).thenReturn("{ not json");
        assertEquals(0, persistence.load().getRoutes().size());
        assertTrue(persistence.isRefusingSaves());
        persistence.save(oneRoute());
        verify(configManager, never()).setConfiguration(anyString(), anyString(), any());
    }

    @Test
    public void clearUnsetsConfigAndLiftsFreeze()
    {
        when(configManager.getConfiguration("waypointer", "routes")).thenReturn("{ bad");
        persistence.load();
        assertTrue(persistence.isRefusingSaves());
        persistence.clear();
        verify(configManager).unsetConfiguration("waypointer", "routes");
        assertFalse(persistence.isRefusingSaves());
    }
}

