    private Toasts toasts = Toasts.NO_OP;
    // Fires when dev-mode landmark overrides reload BboxIndex; rebuilds the row so button
    // text and click targets reflect the current data. Closed in dispose(); the field is
    // nullable because the BboxIndex mock in unit tests returns null from subscribe(...).
    private final com.waypointer.util.Listeners.Subscription bboxSub;

    public void setToasts(Toasts toasts)
    {
        this.toasts = toasts;
    }

    @Inject
    public NearestLandmarkBar(BboxIndex bbox, WaypointPathfinder pathfinder, Client client,
        ClientThread clientThread, SpriteManager spriteManager,
        WaypointerConfig config, Gson gson)
    {
        this.bbox = bbox;
        this.pathfinder = pathfinder;
        this.client = client;
        this.clientThread = clientThread;
        this.spriteManager = spriteManager;
        this.config = config;
        this.gson = gson;

        this.selection = LandmarkSelection.parse(config.landmarkSelectionJson(), gson);
        String canonical = selection.toJson(gson);
        if (!canonical.equals(config.landmarkSelectionJson()))
        {
            config.setLandmarkSelectionJson(canonical);
        }

        setLayout(new BoxLayout(this, BoxLayout.Y_AXIS));
        setBackground(ColorScheme.DARK_GRAY_COLOR);
        setBorder(BorderFactory.createEmptyBorder(2, 0, 2, 0));
        setAlignmentX(LEFT_ALIGNMENT);

        // WrapLayout (not stock FlowLayout) so the row reports a tall-enough preferred height
        // when the selected icons plus the overflow toggle spill onto a second row. With plain
        // FlowLayout the parent BoxLayout sizes the row for one row only and clips the wrapped
        // buttons -- including the overflow toggle, leaving the picker with no close affordance.
        iconRow = new JPanel(new WrapLayout(FlowLayout.CENTER, 2, 0));
        iconRow.setBackground(ColorScheme.DARK_GRAY_COLOR);
        iconRow.setAlignmentX(LEFT_ALIGNMENT);
        add(iconRow);

        picker = new ConfigureLandmarksPanel(
            spriteManager,
            SPRITE_IDS,
            selection,
            this::onPickerToggle,
            this::onPickerReorder,
            this::hidePicker);
        // Match the icon row's left alignment; a mismatched alignmentX makes BoxLayout narrow
        // the icon row when the picker is shown, forcing the bar to wrap earlier than it should.
        picker.setAlignmentX(LEFT_ALIGNMENT);
        add(picker);

        rebuildBar();

        this.bboxSub = bbox.subscribe(() ->
            SwingUtilities.invokeLater(this::rebuildBar));
    }

    /**
     * Releases the {@link BboxIndex} subscription so the bar doesn't outlive the plugin
     * lifecycle. Called from {@link WaypointerPanel#dispose()}.
     */
    public void dispose()
    {
        if (bboxSub != null) bboxSub.close();
    }

    /**
     * Rebuilds the icon row from the current selection. Old buttons leave the component
     * hierarchy along with their hover listeners; new buttons get a fresh
     * HoverHint.shared().attach in the per-type loop and on the overflow button.
     */
    private void rebuildBar()
    {
        iconRow.removeAll();
        primaryButtons.clear();

        for (LandmarkType type : selection.selectedInBarOrder())
        {
            JButton b = makeButton();
            b.addActionListener(e -> onPick(type));
            b.getAccessibleContext().setAccessibleName("Path to nearest " + type.displayName());
            applySprite(b, type);
            primaryButtons.put(type, b);
            iconRow.add(b);
            HoverHint.shared().attach(b, () -> type.displayName());
        }

        overflowBtn = makeButton();
        overflowBtn.setText("⋮"); // U+22EE vertical ellipsis
        overflowBtn.getAccessibleContext().setAccessibleName("Customise landmark bar");
        overflowBtn.addActionListener(e -> {
            picker.setVisible(!picker.isVisible());
            revalidate();
            repaint();
        });
        iconRow.add(overflowBtn);
        HoverHint.shared().attach(overflowBtn, () -> "Customise");

        applyEnabledState();
        iconRow.revalidate();
        iconRow.repaint();
    }

    // Closes the inline picker (the X in its header, or the overflow toggle).
    private void hidePicker()
    {
        picker.setVisible(false);
        revalidate();
        repaint();
    }

    // The first layout computes the icon row's WrapLayout preferred height before the row has a
    // real width, so the icons can wrap to a phantom second row and leave a tall gap above the
    // search field. Once the row has bounds, a deferred revalidate recomputes against the true
    // width and collapses it back to a single row -- the same effect the user got by toggling the
    // picker open and closed. Runs each time the bar joins a displayable hierarchy.
    @Override
    public void addNotify()
    {
        super.addNotify();
        SwingUtilities.invokeLater(() -> {
            revalidate();
            repaint();
        });
    }

    private void onPickerToggle(LandmarkType type, boolean include)
    {
        applySelection(selection.withSelected(type, include));
    }

    private void onPickerReorder(int fromIndex, int toIndex)
    {
        applySelection(selection.withOrderMove(fromIndex, toIndex));
    }

    private void applySelection(LandmarkSelection next)
    {
        if (next == selection) return;
        selection = next;
        config.setLandmarkSelectionJson(selection.toJson(gson));
        rebuildBar();
        picker.setSelection(selection);
    }

    private JButton makeButton()
    {
        JButton b = new JButton();
        Styles.secondaryButton(b);
        Dimension d = new Dimension(BUTTON_SIZE, BUTTON_SIZE);
        b.setPreferredSize(d);
        b.setMinimumSize(d);
        b.setMaximumSize(d);
        return b;
    }

    private void applyEnabledState()
    {
        // setEnabled(false) triggers Swing's setDisabledIcon swap (see applySprite),
        // which is the only visible signal we need. Tooltips were replaced by the
        // immediate hover hint in rebuildBar.
        for (JButton b : primaryButtons.values()) b.setEnabled(loggedIn);
        // The customize button stays enabled regardless of login state.
        if (overflowBtn != null) overflowBtn.setEnabled(true);
    }

    public void setLoggedIn(boolean loggedIn)
    {
        this.loggedIn = loggedIn;
        applyEnabledState();
    }

    private void applySprite(AbstractButton b, LandmarkType type)
    {
        Integer id = SPRITE_IDS.get(type);
        if (id == null || spriteManager == null) return;
        spriteManager.getSpriteAsync(id, 0, img -> {
            if (img == null) return;
            SwingUtilities.invokeLater(() -> {
                Image scaled = scaleDownIfNeeded(img);
                b.setIcon(new ImageIcon(scaled));
                // GrayFilter produces a desaturated copy so the disabled (logged-out)
                // state reads as obviously inactive on the RuneLite dark theme.
                b.setDisabledIcon(new ImageIcon(GrayFilter.createDisabledImage(scaled)));
                b.revalidate();
                b.repaint();
            });
        });
    }

    private static Image scaleDownIfNeeded(BufferedImage src)
    {
        int w = src.getWidth();
        int h = src.getHeight();
        int longest = Math.max(w, h);
        if (longest <= MAX_ICON_PX) return src;
        double scale = (double) MAX_ICON_PX / longest;
        return src.getScaledInstance((int) Math.round(w * scale),
            (int) Math.round(h * scale), Image.SCALE_SMOOTH);
    }

    void onPick(LandmarkType type)
    {
        if (!pathfinder.isAvailable())
        {
            toasts.show("Install the Shortest Path plugin to use Play.", Toasts.Severity.WARN);
            return;
        }
        clientThread.invoke(() -> {
            if (client.getGameState() != GameState.LOGGED_IN) return true;
            Player p = client.getLocalPlayer();
            if (p == null) return true;
            WorldPoint loc = p.getWorldLocation();
            if (loc == null) return true;
            int fromPacked = WorldPointPacker.pack(loc);
            BboxIndex.Hit hit = bbox.nearest(type, fromPacked);
            SwingUtilities.invokeLater(() -> applyHit(type, hit));
            return true;
        });
    }

    void applyHit(LandmarkType type, @javax.annotation.Nullable BboxIndex.Hit hit)
    {
        if (hit == null)
        {
            toasts.show("No " + type.displayName().toLowerCase() + " found.", Toasts.Severity.WARN);
            return;
        }
        pathfinder.requestPath(hit.packed, hit.name);
    }

    private static Map<LandmarkType, Integer> spriteIds()
    {
        // IDs correspond to net.runelite.api.SpriteID constants. RuneLite has no
        // dedicated SpriteID for fairy rings, spirit trees, or charter ships -- the
        // stock WorldMapPlugin uses bundled PNGs for those. We substitute the closest
        // visual match from the MAP_ICON_* sprite set instead.
        EnumMap<LandmarkType, Integer> m = new EnumMap<>(LandmarkType.class);
        m.put(LandmarkType.BANK,           1453);  // MAP_ICON_BANK
        m.put(LandmarkType.ALTAR,          1467);  // MAP_ICON_ALTAR
        m.put(LandmarkType.ANVIL,          1458);  // MAP_ICON_ANVIL
        m.put(LandmarkType.FURNACE,        1457);  // MAP_ICON_FURNACE
        m.put(LandmarkType.LOOM,           1507);  // MAP_ICON_LOOM
        m.put(LandmarkType.SPINNING_WHEEL, 1483);  // MAP_ICON_SPINNING_WHEEL
        m.put(LandmarkType.TANNER,         1481);  // MAP_ICON_TANNERY
        m.put(LandmarkType.SPIRIT_TREE,    1482);  // MAP_ICON_RARE_TREES (tree silhouette)
        m.put(LandmarkType.CHARTER_SHIP,   7290);  // MINIMAP_BOAT_SLOOP
        m.put(LandmarkType.FAIRY_RING,     1504);  // MAP_ICON_TRANSPORTATION
        m.put(LandmarkType.SLAYER_MASTER,  1499);  // MAP_ICON_SLAYER_MASTER
        return m;
    }

    /**
     * FlowLayout that measures every wrapped row instead of assuming a single one. Stock
     * FlowLayout lays out wrapped rows in {@code layoutContainer} but still reports a one-row
     * preferred height, so a {@code BoxLayout} parent allocates one row and clips the rest.
     */
    private static final class WrapLayout extends FlowLayout
    {
        WrapLayout(int align, int hgap, int vgap)
        {
            super(align, hgap, vgap);
        }

        @Override
        public Dimension preferredLayoutSize(Container target)
        {
            return wrappedSize(target, true);
        }

        @Override
        public Dimension minimumLayoutSize(Container target)
        {
            return wrappedSize(target, false);
        }

        private Dimension wrappedSize(Container target, boolean preferred)
        {
            synchronized (target.getTreeLock())
            {
                Insets insets = target.getInsets();
                int maxRowWidth = availableWidth(target)
                    - insets.left - insets.right - getHgap() * 2;
                if (maxRowWidth <= 0) maxRowWidth = Integer.MAX_VALUE;

                int widest = 0;
                int totalHeight = 0;
                int rowWidth = 0;
                int rowHeight = 0;
                for (Component c : target.getComponents())
                {
                    if (!c.isVisible()) continue;
                    Dimension d = preferred ? c.getPreferredSize() : c.getMinimumSize();
                    if (rowWidth > 0 && rowWidth + getHgap() + d.width > maxRowWidth)
                    {
                        widest = Math.max(widest, rowWidth);
                        totalHeight += rowHeight + getVgap();
                        rowWidth = 0;
                        rowHeight = 0;
                    }
                    rowWidth += (rowWidth == 0 ? 0 : getHgap()) + d.width;
                    rowHeight = Math.max(rowHeight, d.height);
                }
                widest = Math.max(widest, rowWidth);
                totalHeight += rowHeight;

                return new Dimension(
                    widest + insets.left + insets.right + getHgap() * 2,
                    totalHeight + insets.top + insets.bottom + getVgap() * 2);
            }
        }

        // Width available to the row. The bar only ever renders in the fixed-width RuneLite
        // sidebar, so the row's real width is always close to PANEL_WIDTH (less the surrounding
        // 8 px panel insets). During early or transient layout passes the live width can briefly
        // collapse toward a single button; honouring that would wrap every icon onto its own row
        // and report a tall preferred height. The narrow row then drives a narrow preferred
        // *width*, which feeds back into an ever-narrower row -- a stuck state a later revalidate
        // cannot break, leaving a tall gap above the search field until the picker is toggled.
        // Trust the live width only once it is near the real sidebar width; otherwise fall back to
        // PANEL_WIDTH so the row stays a single line and the bar can grow back to full width.
        private static int availableWidth(Container target)
        {
            int live = target.getWidth();
            return live >= PluginPanel.PANEL_WIDTH - 32 ? live : PluginPanel.PANEL_WIDTH;
        }
    }
}

package com.waypointer.ui;

import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Component;
import java.awt.Cursor;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.LayoutManager;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import javax.swing.BorderFactory;
import javax.swing.JButton;
import javax.swing.JComboBox;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.JScrollBar;
import javax.swing.JScrollPane;
import javax.swing.JTextArea;
import javax.swing.JTextField;
import javax.swing.ScrollPaneConstants;
import javax.swing.event.DocumentEvent;
import javax.swing.event.DocumentListener;
import javax.swing.plaf.ScrollBarUI;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.laf.RuneLiteScrollBarUI;

// Styling helpers for panel + dialogs. Vanilla Swing components default to system LAF which
// clashes with RuneLite's dark theme; each entry applies the RuneLite palette while letting
// components inherit the system LAF font.
final class Styles
{
    private Styles() {}

    private static final int SCROLLBAR_PIN_WIDTH = 7;
    private static final String CP_SCROLLBAR_WIDTH = "JScrollBar.width";
    private static final String CP_SCROLLBAR_BUTTONS = "JScrollBar.showButtons";

    // Destructive-action red used on delete row buttons and the delete link. ERROR_RED is the
    // slightly lighter tint for inline form-validation messages.
    static final Color DELETE_RED = new Color(220, 80, 80);
    static final Color ERROR_RED = new Color(220, 90, 90);

    // Secondary text greys used across empty-states, footer, and no-match copy. MUTED is the
    // primary secondary-text colour; FAINT is the dimmer tier (e.g. the footer tip). Each has a
    // hex twin for the HTML <span style='color:...'> sites that can't take a java.awt.Color.
    static final Color  MUTED_TEXT = new Color(0x9b, 0x9b, 0x9b);
    static final Color  FAINT_TEXT = new Color(0x6e, 0x6e, 0x6e);
    static final String MUTED_HEX  = "#9b9b9b";
    static final String FAINT_HEX  = "#6e6e6e";

    static void secondaryButton(JButton b)
    {
        b.setBackground(ColorScheme.DARKER_GRAY_COLOR);
        b.setForeground(Color.WHITE);
        b.setFocusPainted(false);
        b.setBorder(BorderFactory.createCompoundBorder(
            BorderFactory.createLineBorder(ColorScheme.DARK_GRAY_COLOR.darker(), 1),
            BorderFactory.createEmptyBorder(8, 12, 8, 12)));
    }

    static void compactSecondaryButton(JButton b)
    {
        b.setBackground(ColorScheme.DARKER_GRAY_COLOR);
        b.setForeground(Color.WHITE);
        b.setFocusPainted(false);
        b.setBorder(BorderFactory.createCompoundBorder(
            BorderFactory.createLineBorder(ColorScheme.DARK_GRAY_COLOR.darker(), 1),
            BorderFactory.createEmptyBorder(2, 6, 2, 6)));
    }

    // Small text button for inline row actions (dev editors). Same dark chrome as
    // compactSecondaryButton with a caller-chosen foreground so actions can be colour-coded.
    static JButton compactActionButton(String text, Color fg, Runnable onClick)
    {
        JButton b = new JButton(text);
        compactSecondaryButton(b);
        b.setForeground(fg);
        b.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
        b.addActionListener(e -> onClick.run());
        return b;
    }

    // Clickable text styled as an HTML link: caller-chosen colour, hand cursor, click handler.
    // Used for the inline edit panel's footer actions.
    static JLabel link(String text, Color color, Runnable onClick)
    {
        JLabel l = new JLabel("<html><a href=''>" + text + "</a></html>");
        l.setForeground(color);
        l.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
        l.addMouseListener(new MouseAdapter()
        {
            @Override public void mouseClicked(MouseEvent e) { onClick.run(); }
        });
        return l;
    }

    static void primaryButton(JButton b)
    {
        b.setBackground(ColorScheme.BRAND_ORANGE);
        b.setForeground(Color.BLACK);
        b.setFocusPainted(false);
        b.setBorder(BorderFactory.createCompoundBorder(
            BorderFactory.createLineBorder(ColorScheme.BRAND_ORANGE.darker(), 1),
            BorderFactory.createEmptyBorder(8, 12, 8, 12)));
        b.setFont(b.getFont().deriveFont(Font.BOLD));
    }

    static void textField(JTextField f)
    {
        f.setBackground(ColorScheme.DARK_GRAY_COLOR);
        f.setForeground(Color.WHITE);
        f.setCaretColor(Color.WHITE);
        f.setBorder(BorderFactory.createCompoundBorder(
            BorderFactory.createLineBorder(ColorScheme.LIGHT_GRAY_COLOR, 1),
            BorderFactory.createEmptyBorder(2, 4, 2, 4)));
    }

    static void textArea(JTextArea a)
    {
        a.setBackground(ColorScheme.DARK_GRAY_COLOR);
        a.setForeground(Color.WHITE);
        a.setCaretColor(Color.WHITE);
        a.setBorder(BorderFactory.createLineBorder(ColorScheme.LIGHT_GRAY_COLOR, 1));
    }

    static void combo(JComboBox<?> c)
    {
        c.setBackground(ColorScheme.DARK_GRAY_COLOR);
        c.setForeground(Color.WHITE);
    }

    static JLabel fieldLabel(String text)
    {
        JLabel l = new JLabel(text);
        l.setForeground(Color.WHITE);
        return l;
    }

    // Width-unbounded, height-pinned maximum size. Return this from a component's
    // getMaximumSize() override so BoxLayout(Y_AXIS) stacks it at its preferred height
    // instead of stretching it into leftover column space.
    static Dimension capHeight(Component c)
    {
        return new Dimension(Integer.MAX_VALUE, c.getPreferredSize().height);
    }

    /**
     * A {@link JPanel} whose maximum height is pinned to its preferred height, so a
     * {@code BoxLayout(Y_AXIS)} parent does not stretch it vertically. Used for banners,
     * the footer, and the empty-state block.
     */
    public static JPanel cappedHeightPanel(LayoutManager lm)
    {
        return new JPanel(lm)
        {
            @Override public Dimension getMaximumSize()
            {
                return Styles.capHeight(this);
            }
        };
    }

    static DocumentListener documentListener(Runnable onChange)
    {
        return new DocumentListener()
        {
            @Override public void insertUpdate(DocumentEvent e)  { onChange.run(); }
            @Override public void removeUpdate(DocumentEvent e)  { onChange.run(); }
            @Override public void changedUpdate(DocumentEvent e) { onChange.run(); }
        };
    }

    // Builds a JScrollPane themed to match the dark plugin panel: no border, no horizontal bar,
    // and a thin (7-px) vertical bar with arrow buttons hidden. These panels are constructed
    // during loadCorePlugins() - before ClientUI.init() installs RuneLiteLAF - so the scrollbar's
    // UI delegate would otherwise inherit Metal defaults; the caller stores the bar and passes it
    // to reapplyScrollbarPin(...) from startUp() once the LAF is live.
    static JScrollPane pinnedScrollPane(Component view)
    {
        JScrollPane scroll = new JScrollPane(view);
        scroll.setHorizontalScrollBarPolicy(ScrollPaneConstants.HORIZONTAL_SCROLLBAR_NEVER);
        scroll.getViewport().setBackground(ColorScheme.DARK_GRAY_COLOR);
        scroll.setBorder(BorderFactory.createEmptyBorder());
        JScrollBar vBar = scroll.getVerticalScrollBar();
        vBar.putClientProperty(CP_SCROLLBAR_WIDTH, SCROLLBAR_PIN_WIDTH);
        vBar.putClientProperty(CP_SCROLLBAR_BUTTONS, Boolean.FALSE);
        vBar.setPreferredSize(new Dimension(SCROLLBAR_PIN_WIDTH, 0));
        vBar.setUI((ScrollBarUI) RuneLiteScrollBarUI.createUI(vBar));
        return scroll;
    }

    // Re-derives and re-pins a vertical scrollbar's UI delegate after RuneLiteLAF is installed.
    // updateUI() resets the preferred size and client properties, so they are re-applied here.
    // Null-safe so callers can invoke it unconditionally from startUp().
    static void reapplyScrollbarPin(JScrollBar bar)
    {
        if (bar == null) return;
        bar.updateUI();
        bar.setPreferredSize(new Dimension(SCROLLBAR_PIN_WIDTH, 0));
        bar.putClientProperty(CP_SCROLLBAR_WIDTH, SCROLLBAR_PIN_WIDTH);
        bar.putClientProperty(CP_SCROLLBAR_BUTTONS, Boolean.FALSE);
    }

    // Populates `target` as a one-line editable metadata row: name on the WEST, a coordinate/
    // detail string in the CENTER, and Go / Edit / Delete action buttons on the EAST. Used by
    // LandmarkRow and PresetWaypointRow, which keep their typed constructors and delegate here.
    static void editableMetaRow(JPanel target, String name, String detail,
        Runnable onGo, Runnable onEdit, Runnable onDelete)
    {
        target.setLayout(new BorderLayout(6, 0));
        target.setBackground(ColorScheme.DARKER_GRAY_COLOR);
        target.setBorder(BorderFactory.createEmptyBorder(4, 6, 4, 6));

        JLabel nameLabel = new JLabel(name);
        nameLabel.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
        nameLabel.setFont(FontManager.getRunescapeSmallFont());

        JLabel detailLabel = new JLabel(detail);
        detailLabel.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
        detailLabel.setFont(FontManager.getRunescapeSmallFont());

        JPanel right = new JPanel();
        right.setOpaque(false);
        right.add(compactActionButton("Go", ColorScheme.BRAND_ORANGE, onGo));
        right.add(compactActionButton("Edit", Color.WHITE, onEdit));
        right.add(compactActionButton("Delete", DELETE_RED, onDelete));

        target.add(nameLabel, BorderLayout.WEST);
        target.add(detailLabel, BorderLayout.CENTER);
        target.add(right, BorderLayout.EAST);
    }

}

package com.waypointer.ui;

import com.waypointer.service.BboxIndex;
import java.util.function.Consumer;
import javax.swing.JPanel;

final class LandmarkRow extends JPanel
{
    LandmarkRow(BboxIndex.Entry entry,
        Consumer<BboxIndex.Entry> onNavigate,
        Consumer<BboxIndex.Entry> onEdit,
        Consumer<BboxIndex.Entry> onDelete)
    {
        String tile = entry.x1 == entry.x2 && entry.y1 == entry.y2
            ? String.format("(%d, %d) p%d", entry.x1, entry.y1, entry.plane)
            : String.format("(%d, %d)-(%d, %d) p%d", entry.x1, entry.y1, entry.x2, entry.y2, entry.plane);
        Styles.editableMetaRow(this, entry.name, tile,
            () -> onNavigate.accept(entry),
            () -> onEdit.accept(entry),
            () -> onDelete.accept(entry));
    }
}

package com.waypointer.ui;

import com.waypointer.WaypointerConfig;
import com.waypointer.model.route.Route;
import com.waypointer.model.route.RouteStep;
import com.waypointer.service.RoutePlaybackEngine;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.util.ArrayList;
import java.util.List;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.client.ui.overlay.OverlayPanel;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.components.LineComponent;
import net.runelite.client.ui.overlay.components.TitleComponent;

/** Read-only in-game step box. The player never clicks it; advancement is via hotkey / sidebar. */
@Singleton
public class RouteOverlay extends OverlayPanel
{
    private final RoutePlaybackEngine engine;
    private final WaypointerConfig config;

    @Inject
    public RouteOverlay(RoutePlaybackEngine engine, WaypointerConfig config)
    {
        this.engine = engine;
        this.config = config;
        setPosition(OverlayPosition.TOP_LEFT);
    }

    @Override
    public Dimension render(Graphics2D graphics)
    {
        if (!config.showRouteOverlay()) return null;
        Route r = engine.getActiveRoute();
        if (r == null) return null;

        panelComponent.getChildren().clear();
        panelComponent.getChildren().add(TitleComponent.builder()
            .text(r.getName())
            .build());

        for (String line : buildLines(r, engine.getCurrentIndex(), engine.getLap()))
        {
            panelComponent.getChildren().add(LineComponent.builder()
                .left(line)
                .leftColor(line.startsWith("Next:") || line.startsWith("Step ")
                    ? Color.LIGHT_GRAY : Color.WHITE)
                .build());
        }
        return super.render(graphics);
    }

    /**
     * Pure display-line builder (testable without a Graphics2D). Returns: a step counter line,
     * the current step's text, and a dim "Next:" preview when a following step exists.
     */
    static List<String> buildLines(Route route, int currentIndex, int lap)
    {
        List<String> lines = new ArrayList<>();
        int total = route.getSteps().size();
        String counter = "Step " + (currentIndex + 1) + " / " + total;
        if (route.isRepeating()) counter += "  -  Lap " + lap;
        lines.add(counter);

        if (currentIndex >= 0 && currentIndex < total)
        {
            lines.add(route.getSteps().get(currentIndex).boxTextOrLabel());
        }
        int next = currentIndex + 1;
        if (next < total)
        {
            RouteStep n = route.getSteps().get(next);
            lines.add("Next: " + n.boxTextOrLabel());
        }
        return lines;
    }
}

package com.waypointer.ui;

import com.waypointer.model.WorldPointPacker;
