// One curated set, drawn as a collapsible section: a clickable header that toggles a
// stack of waypoint rows. Starts collapsed; rows are built lazily on first expand.
class PresetSection extends JPanel
{
    // U+25B8 right-pointing triangle (collapsed), U+25BE down-pointing triangle (expanded).
    private static final String CHEVRON_COLLAPSED = "▸";
    private static final String CHEVRON_EXPANDED = "▾";

    // Historical fallback width for the row label: used until componentResized fires with a
    // real container width. Derived from the old constant kept as a safety value for tests /
    // very early paint passes when getWidth() is still zero.
    private static final int FALLBACK_LABEL_WIDTH_PX = 107;
    // Row chrome reserved on either side of the label: border left (22) + border right (40)
    // + BorderLayout hgap (12) + AddRemoveToggle button (~23) + a small margin (6).
    private static final int ROW_RESERVED_PX = 22 + 40 + 12 + 23 + 6;
    private static final int MIN_LABEL_WIDTH_PX = 60;

    private final Preset preset;
    private final SpriteManager spriteManager;
    private final Map<Integer, UUID> existingIdByPacked;
    private final Function<PresetWaypoint, UUID> onAdd;
    private final Consumer<UUID> onRemove;
    private final JPanel rows = new JPanel();
    private final JLabel chevron = new JLabel(CHEVRON_COLLAPSED);
    private final List<JLabel> rowLabels = new ArrayList<>();
    private int labelWidthPx;
    private boolean expanded;

    PresetSection(Preset preset, SpriteManager spriteManager, Map<Integer, UUID> existingIdByPacked,
        Function<PresetWaypoint, UUID> onAdd, Consumer<UUID> onRemove)
    {
        this.preset = preset;
        this.spriteManager = spriteManager;
        this.existingIdByPacked = existingIdByPacked;
        this.onAdd = onAdd;
        this.onRemove = onRemove;

        setLayout(new BorderLayout());
        setBackground(ColorScheme.DARK_GRAY_COLOR);

        add(buildHeader(), BorderLayout.NORTH);

        rows.setLayout(new BoxLayout(rows, BoxLayout.Y_AXIS));
        rows.setBackground(ColorScheme.DARK_GRAY_COLOR);
        rows.setVisible(false);
        add(rows, BorderLayout.CENTER);

        // Recompute the row-label width as the container grows or shrinks. Drives
        // HTML wrap so descriptions stay inside the section instead of clipping at the
        // hard-coded 107 px the old constant used.
        addComponentListener(new ComponentAdapter()
        {
            @Override public void componentResized(ComponentEvent e)
            {
                int w = computeLabelWidth(getWidth());
                if (w == labelWidthPx) return;
                labelWidthPx = w;
                for (JLabel label : rowLabels) applyLabelWidth(label, labelWidthPx);
                rows.revalidate();
                rows.repaint();
            }
        });
    }

    private static int computeLabelWidth(int containerWidth)
    {
        if (containerWidth <= 0) return FALLBACK_LABEL_WIDTH_PX;
        return Math.max(MIN_LABEL_WIDTH_PX, containerWidth - ROW_RESERVED_PX);
    }

    private static void applyLabelWidth(JLabel label, int width)
    {
        if (width <= 0) return;
        View v = (View) label.getClientProperty(BasicHTML.propertyKey);
        if (v == null) return;
        v.setSize(width, 0);
        int h = (int) Math.ceil(v.getPreferredSpan(View.Y_AXIS));
        label.setPreferredSize(new Dimension(width, h));
    }

    // Cap the section to its own preferred height so the parent BoxLayout(Y_AXIS) stacks
    // sections tight instead of stretching them down the column.
    @Override
    public Dimension getMaximumSize()
    {
        return Styles.capHeight(this);
    }

    private JPanel buildHeader()
    {
        JPanel header = new JPanel(new BorderLayout(6, 0));
        header.setBackground(ColorScheme.DARKER_GRAY_COLOR);
        header.setBorder(BorderFactory.createEmptyBorder(7, 9, 7, 9));
        header.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));

        chevron.setForeground(Color.LIGHT_GRAY);

        JLabel name = new JLabel(preset.getCategory());
        name.setForeground(Color.WHITE);
        name.setFont(FontManager.getRunescapeBoldFont());

        JPanel left = new JPanel(new FlowLayout(FlowLayout.LEFT, 6, 0));
        left.setBackground(ColorScheme.DARKER_GRAY_COLOR);
        left.add(chevron);
        if (preset.getIcon() != null)
        {
            JLabel icon = new JLabel();
            SpriteIcons.apply(icon, preset.getIcon(), spriteManager);
            left.add(icon);
        }
        left.add(name);
        header.add(left, BorderLayout.CENTER);

        JLabel count = new JLabel(String.valueOf(preset.getWaypoints().size()));
        count.setForeground(Color.LIGHT_GRAY);
        count.setFont(FontManager.getRunescapeSmallFont());
        header.add(count, BorderLayout.EAST);

        header.addMouseListener(new MouseAdapter()
        {
            @Override
            public void mouseClicked(MouseEvent e)
            {
                toggle();
            }
        });
        return header;
    }

    private void toggle()
    {
        expanded = !expanded;
        applyExpandedState();
    }

    private void applyExpandedState()
    {
        chevron.setText(expanded ? CHEVRON_EXPANDED : CHEVRON_COLLAPSED);
        if (expanded && rows.getComponentCount() == 0)
        {
            buildRows();
        }
        rows.setVisible(expanded);
        revalidate();
        repaint();
    }

    String getPresetName() { return preset.getCategory(); }

    boolean isExpanded() { return expanded; }

    void setExpanded(boolean expand)
    {
        if (expand == expanded) return;
        expanded = expand;
        applyExpandedState();
    }

    private void buildRows()
    {
        rowLabels.clear();
        if (labelWidthPx <= 0) labelWidthPx = computeLabelWidth(getWidth());
        String desc = preset.getDescription();
        if (desc != null && !desc.trim().isEmpty())
        {
            JLabel descLabel = new JLabel("<html><div style='padding:4px 9px 4px 22px;'>"
                + Text.escapeHtml(desc) + "</div></html>");
            descLabel.setForeground(Styles.MUTED_TEXT);
            descLabel.setFont(FontManager.getRunescapeSmallFont());
            descLabel.setAlignmentX(LEFT_ALIGNMENT);
            rows.add(descLabel);
        }
        for (PresetWaypoint wp : preset.getWaypoints())
        {
            JPanel row = buildRow(wp);
            row.setAlignmentX(LEFT_ALIGNMENT);
            rows.add(row);
        }
    }

    private JPanel buildRow(PresetWaypoint wp)
    {
        JPanel row = new JPanel(new BorderLayout(12, 0))
        {
            @Override
            public Dimension getMaximumSize()
            {
                return Styles.capHeight(this);
            }
        };
        row.setBackground(ColorScheme.DARK_GRAY_COLOR);
        row.setBorder(BorderFactory.createEmptyBorder(5, 22, 5, 40));

        String descHtml = wp.getDescription() == null || wp.getDescription().trim().isEmpty()
            ? ""
            : "<br><span style='color:#7d7d7d;'>" + Text.escapeHtml(wp.getDescription())
                + "</span>";
        JLabel label = new JLabel("<html>"
            + Text.escapeHtml(wp.getName()) + descHtml + "</html>");
        label.setForeground(Color.WHITE);
        // BasicHTML's <div style='width:Npx'> trick is unreliable: JLabel still reports
        // its preferredSize at the unwrapped text width, which overflows the viewport and
        // clips the EAST button. Force the View to lay out at the current labelWidthPx,
        // then pin the label's preferredSize so BorderLayout honours the constraint. The
        // section's componentResized listener re-applies if the container resizes.
        applyLabelWidth(label, labelWidthPx);
        rowLabels.add(label);
        row.add(label, BorderLayout.CENTER);

        int packed = WorldPointPacker.pack(wp.getX(), wp.getY(), wp.getPlane());
        UUID existingId = existingIdByPacked.get(packed);
        AddRemoveToggle toggle = new AddRemoveToggle(
            existingId,
            () -> onAdd.apply(wp),
            id -> onRemove.accept(id));
        row.add(toggle, BorderLayout.EAST);
        return row;
    }
}

package com.waypointer.ui;

import com.waypointer.service.PresetImportResolver.Choice;
import com.waypointer.service.PresetImportResolver.PendingConflict;
import java.awt.BorderLayout;
import java.awt.FlowLayout;
import java.awt.Window;
import javax.swing.JButton;
import javax.swing.JCheckBox;
import javax.swing.JDialog;
import javax.swing.JLabel;
import javax.swing.JPanel;
import net.runelite.client.ui.ColorScheme;

public final class ImportConflictDialog
{
    public static final class Result
    {
        public final Choice choice;
        public final boolean applyToAll;
        public Result(Choice c, boolean a) { this.choice = c; this.applyToAll = a; }
    }

    public static Result prompt(Window owner, PendingConflict c)
    {
        Result[] out = { new Result(Choice.SKIP, false) };
        JDialog d = new JDialog(owner, "Conflict in " + c.category, JDialog.ModalityType.APPLICATION_MODAL);
        Dialogs.applyDarkContentPane(d);
        Dialogs.bindEscape(d);

        JLabel msg = new JLabel("'" + c.imported.getName() + "' already exists.");
        msg.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
        d.add(msg, BorderLayout.NORTH);

        JCheckBox applyAll = new JCheckBox("Apply to all conflicts");
        applyAll.setBackground(ColorScheme.DARK_GRAY_COLOR);
        applyAll.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
        d.add(applyAll, BorderLayout.CENTER);

        JPanel buttons = new JPanel(new FlowLayout(FlowLayout.RIGHT, 6, 0));
        buttons.setBackground(ColorScheme.DARK_GRAY_COLOR);
        JButton keep = new JButton("Keep existing");
        Styles.secondaryButton(keep);
        JButton repl = new JButton("Replace with imported");
        Styles.secondaryButton(repl);
        JButton skip = new JButton("Skip");
        Styles.secondaryButton(skip);
        keep.addActionListener(e -> { out[0] = new Result(Choice.KEEP_EXISTING, applyAll.isSelected()); d.dispose(); });
        repl.addActionListener(e -> { out[0] = new Result(Choice.REPLACE, applyAll.isSelected()); d.dispose(); });
        skip.addActionListener(e -> { out[0] = new Result(Choice.SKIP, applyAll.isSelected()); d.dispose(); });
        buttons.add(keep);
        buttons.add(repl);
        buttons.add(skip);
        d.add(buttons, BorderLayout.SOUTH);

        Dialogs.finish(d, owner);
        d.setVisible(true);
        return out[0];
    }
}

package com.waypointer.ui;

import com.waypointer.WaypointerConfig;
import com.waypointer.service.WaypointPathfinder;
import com.waypointer.service.WaypointStore;
import com.waypointer.util.Listeners;
import java.awt.BorderLayout;
import java.awt.CardLayout;
import java.awt.Dimension;
import javax.inject.Inject;
import javax.inject.Singleton;
import javax.swing.BoxLayout;
import javax.swing.JPanel;
import javax.swing.SwingUtilities;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.NavigationButton;
import net.runelite.client.ui.PluginPanel;

/**
 * Top-level panel hosting the {@link TabStrip}, the active path banner (moved up from
 * {@link WaypointerPanel}), and a {@link CardLayout} body holding the child panels.
 * Replaces {@link net.runelite.client.ui.MultiplexingPluginPanel} in the plugin's wiring.
 */
@Singleton
public class TabHost extends PluginPanel
{
    private static final String CARD_MY_WAYPOINTS = "my";
    private static final String CARD_PRESETS = "presets";
    private static final String CARD_ROUTES = "routes";

    private final WaypointerPanel waypointerPanel;
    private final PresetBrowserPanel presetBrowserPanel;
    private final RoutesPanel routesPanel;
    private final WaypointerConfig config;
    private final ClientToolbar clientToolbar;
    private NavigationButton navButton;
    private final ActivePathBanner banner;
    private final JPanel northStack;
    private TabStrip tabStrip;
    private java.util.List<TabStrip.Tab> visibleTabs;
    private final CardLayout cardLayout = new CardLayout();
    private final JPanel cards = new JPanel(cardLayout);
    private final ToastOverlay sharedToasts = new ToastOverlay(cards);

    private Listeners.Subscription pathSub;
    private TabStrip.Tab active = TabStrip.Tab.MY_WAYPOINTS;
    private String visibleCard = CARD_MY_WAYPOINTS;

    @Inject
    public TabHost(WaypointerPanel waypointerPanel, PresetBrowserPanel presetBrowserPanel,
        RoutesPanel routesPanel, WaypointPathfinder pathfinder,
        WaypointerConfig config, ClientToolbar clientToolbar, WaypointStore store)
    {
        super(false);
        this.waypointerPanel = waypointerPanel;
        this.presetBrowserPanel = presetBrowserPanel;
        this.routesPanel = routesPanel;
        this.config = config;
        this.clientToolbar = clientToolbar;
        this.banner = new ActivePathBanner(pathfinder, config, store::hasWaypointAt);

        setLayout(new BorderLayout());
        setBackground(ColorScheme.DARK_GRAY_COLOR);

        northStack = new JPanel();
        northStack.setLayout(new BoxLayout(northStack, BoxLayout.Y_AXIS));
        northStack.setBackground(ColorScheme.DARK_GRAY_COLOR);
        banner.setAlignmentX(LEFT_ALIGNMENT);
        northStack.add(banner);
        add(northStack, BorderLayout.NORTH);

        cards.setBackground(ColorScheme.DARK_GRAY_COLOR);
        cards.add(waypointerPanel, CARD_MY_WAYPOINTS);
        cards.add(presetBrowserPanel, CARD_PRESETS);
        cards.add(routesPanel, CARD_ROUTES);
        add(sharedToasts, BorderLayout.CENTER);
        routesPanel.setToasts(sharedToasts);

        rebuildStrip();

        pathSub = pathfinder.subscribe(() ->
            SwingUtilities.invokeLater(banner::refresh));
        banner.refresh();
    }

    // Same Windows-unmaximize regression guard as the inner panels.
    @Override public Dimension getPreferredSize() { return new Dimension(super.getPreferredSize().width, 0); }
    @Override public Dimension getMinimumSize() { return new Dimension(super.getMinimumSize().width, 0); }

    public void selectMyWaypoints()
    {
        if (active == TabStrip.Tab.MY_WAYPOINTS) return;
        active = TabStrip.Tab.MY_WAYPOINTS;
        visibleCard = CARD_MY_WAYPOINTS;
        tabStrip.setActive(active);
        cardLayout.show(cards, CARD_MY_WAYPOINTS);
        revalidate();
    }

    public void selectPresets()
    {
        if (active == TabStrip.Tab.PRESETS) return;
        active = TabStrip.Tab.PRESETS;
        visibleCard = CARD_PRESETS;
        tabStrip.setActive(active);
        cardLayout.show(cards, CARD_PRESETS);
        revalidate();
    }

    public void selectRoutes()
    {
        if (active == TabStrip.Tab.ROUTES) return;
        active = TabStrip.Tab.ROUTES;
        visibleCard = CARD_ROUTES;
        tabStrip.setActive(active);
        cardLayout.show(cards, CARD_ROUTES);
        revalidate();
    }

    /** The plugin sets this after building the nav button so openToCapture can open the panel. */
    public void setNavButton(NavigationButton navButton)
    {
        this.navButton = navButton;
    }

    /**
     * Right-click capture entry point: open the sidebar (if not already), switch to the Waypoints
     * tab, and pop the inline capture form prefilled for {@code packed}. The form stays inline
     * rather than modal so saving a waypoint never steals focus from the game canvas.
     */
    public void openToCapture(int packed, String defaultName, String npcName)
    {
        if (clientToolbar != null && navButton != null)
        {
            clientToolbar.openPanel(navButton);
        }
        selectMyWaypoints();
        waypointerPanel.showCaptureForm(packed, defaultName, npcName);
    }

    public void refreshScrollbarStyling()
    {
        waypointerPanel.refreshScrollbarStyling();
        presetBrowserPanel.refreshScrollbarStyling();
        routesPanel.refreshScrollbarStyling();
    }

    @Subscribe
    public void onConfigChanged(ConfigChanged e)
    {
        if (!"waypointer".equals(e.getGroup())) return;
        if ("showPathingBanner".equals(e.getKey()))
        {
            SwingUtilities.invokeLater(banner::refresh);
        }
        if ("routesEnabled".equals(e.getKey()))
        {
            SwingUtilities.invokeLater(this::rebuildStrip);
        }
    }

    public void dispose()
    {
        if (pathSub != null) { pathSub.close(); pathSub = null; }
        waypointerPanel.dispose();
        presetBrowserPanel.dispose();
        routesPanel.dispose();
    }

    private void rebuildStrip()
    {
        if (tabStrip != null) northStack.remove(tabStrip);
        java.util.List<TabStrip.Tab> tabs = new java.util.ArrayList<>();
        tabs.add(TabStrip.Tab.MY_WAYPOINTS);
        tabs.add(TabStrip.Tab.PRESETS);
        if (config.routesEnabled()) tabs.add(TabStrip.Tab.ROUTES);
        visibleTabs = tabs;
        tabStrip = new TabStrip(this::onTabSelected, visibleTabs);
        tabStrip.setAlignmentX(LEFT_ALIGNMENT);
        northStack.add(tabStrip, 0);
        if (!visibleTabs.contains(active))
        {
            active = TabStrip.Tab.MY_WAYPOINTS;
            visibleCard = CARD_MY_WAYPOINTS;
            cardLayout.show(cards, CARD_MY_WAYPOINTS);
        }
        tabStrip.setActive(active);
        northStack.revalidate();
        northStack.repaint();
    }

    private void onTabSelected(TabStrip.Tab tab)
    {
        switch (tab)
        {
            case MY_WAYPOINTS: selectMyWaypoints(); break;
            case PRESETS:      selectPresets();     break;
            case ROUTES:       selectRoutes();      break;
        }
    }

    // Test seams.
    TabStrip.Tab getActiveTabForTest() { return active; }
    String getVisibleCardNameForTest() { return visibleCard; }
    int visibleTabCountForTest() { return visibleTabs.size(); }
}

package com.waypointer.ui;

import com.waypointer.model.Library;
import com.waypointer.model.Waypoint;
import com.waypointer.model.WorldPointPacker;
import com.waypointer.preset.Preset;
import com.waypointer.preset.PresetCatalog;
import com.waypointer.preset.PresetImport;
import com.waypointer.preset.PresetWaypoint;
import com.waypointer.service.WaypointStore;
import com.waypointer.util.Listeners;
import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Dimension;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.UUID;
import javax.inject.Inject;
import javax.inject.Singleton;
import javax.swing.BorderFactory;
import javax.swing.Box;
import javax.swing.BoxLayout;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.JScrollBar;
import javax.swing.JScrollPane;
import javax.swing.SwingUtilities;
import net.runelite.client.game.SpriteManager;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.PluginPanel;

// Singleton preset browser. Lives for the lifetime of the plugin and reacts to store
// mutations from any source so the per-row "+" / "added" toggles stay in sync.
@Singleton
public class PresetBrowserPanel extends PluginPanel
{
    private final PresetCatalog catalog;
    private final WaypointStore store;
    private final SpriteManager spriteManager;
    private final JPanel body = new JPanel();
    private final ToastOverlay toastOverlay;
    private final JScrollBar bodyScrollBar;
    private String lastToastTextForTest;

    private Listeners.Subscription storeSub;
    private Listeners.Subscription catalogSub;
    private volatile boolean rebuildPending = false;

    @Inject
    public PresetBrowserPanel(PresetCatalog catalog, WaypointStore store,
        SpriteManager spriteManager)
    {
        super(false);
        this.catalog = catalog;
        this.store = store;
        this.spriteManager = spriteManager;

        setLayout(new BorderLayout());
        setBackground(ColorScheme.DARK_GRAY_COLOR);

        JPanel header = buildHeader();
        header.setAlignmentX(LEFT_ALIGNMENT);
        add(header, BorderLayout.NORTH);

        body.setLayout(new BoxLayout(body, BoxLayout.Y_AXIS));
        body.setBackground(ColorScheme.DARK_GRAY_COLOR);

        JPanel bodyHolder = new JPanel(new BorderLayout());
        bodyHolder.setBackground(ColorScheme.DARK_GRAY_COLOR);
        bodyHolder.add(body, BorderLayout.NORTH);

        // Constructed during loadCorePlugins(), before ClientUI.init() installs RuneLiteLAF,
        // so the scrollbar's UI delegate would inherit Metal defaults. Styles.pinnedScrollPane
        // applies the dark-theme pin now; refreshScrollbarStyling() re-derives it from startUp()
        // once the LAF is live.
        JScrollPane scroll = Styles.pinnedScrollPane(bodyHolder);
        this.bodyScrollBar = scroll.getVerticalScrollBar();
        toastOverlay = new ToastOverlay(scroll);
        add(toastOverlay, BorderLayout.CENTER);

        storeSub = store.subscribe(this::scheduleRebuild);
        catalogSub = catalog.subscribe(this::scheduleRebuild);
        rebuild();
    }

    // PluginPanel feeds its layout-computed height to ClientUI; the inner JScrollPane
    // handles overflow, so the height reported outward stays 0 and the frame size keeps
    // tracking the game canvas. See the WaypointerPanel.getPreferredSize comment for the
    // full Windows-unmaximize explanation.
    @Override
    public Dimension getPreferredSize()
    {
        return new Dimension(super.getPreferredSize().width, 0);
    }

    @Override
    public Dimension getMinimumSize()
    {
        return new Dimension(super.getMinimumSize().width, 0);
    }

    /** Called from {@link com.waypointer.WaypointerPlugin#startUp()} after LAF init. */
    public void refreshScrollbarStyling()
    {
        SwingUtilities.invokeLater(() -> Styles.reapplyScrollbarPin(bodyScrollBar));
    }

    public void dispose()
    {
        if (storeSub != null) { storeSub.close(); storeSub = null; }
        if (catalogSub != null) { catalogSub.close(); catalogSub = null; }
    }

    private JPanel buildHeader()
    {
        JPanel header = new JPanel(new BorderLayout(8, 0));
        header.setBackground(ColorScheme.DARK_GRAY_COLOR);
        header.setBorder(BorderFactory.createEmptyBorder(8, 8, 8, 8));

        JLabel title = new JLabel("Preset waypoints");
        title.setForeground(Color.WHITE);
        title.setFont(FontManager.getRunescapeBoldFont());
        header.add(title, BorderLayout.EAST);

        return header;
    }

    // Coalesce back-to-back rebuilds within one EDT cycle into a single call.
    // Mirrors WaypointerPanel.scheduleRebuild.
    private void scheduleRebuild()
    {
        if (rebuildPending) return;
        rebuildPending = true;
        SwingUtilities.invokeLater(() ->
        {
            rebuildPending = false;
            rebuild();
        });
    }

    // Test seam - drives the same rebuild path the store listener does, without
    // depending on SwingUtilities.invokeLater scheduling.
    void scheduleRebuildForTest()
    {
        rebuild();
    }

    private void rebuild()
    {
        Set<String> expandedPresetNames = snapshotExpandedPresetNames();
        body.removeAll();
        Map<Integer, UUID> existing = existingIdByPacked();
        List<Preset> presets = catalog.getPresets();
        if (presets.isEmpty())
        {
            JLabel none = new JLabel("<html><div style='text-align:center;padding:24px 12px;"
                + "color:" + Styles.MUTED_HEX + ";'>No presets available.</div></html>");
            none.setAlignmentX(LEFT_ALIGNMENT);
            none.setForeground(Color.LIGHT_GRAY);
            body.add(none);
        }
        else
        {
            for (Preset preset : presets)
            {
                PresetSection section = new PresetSection(
                    preset, spriteManager, existing,
                    wp -> addWaypoint(preset, wp),
                    id -> removeWaypoint(id));
                section.setAlignmentX(LEFT_ALIGNMENT);
                if (expandedPresetNames.contains(preset.getCategory()))
                {
                    // Restore previously-expanded state. PresetSection defaults to collapsed.
                    section.setExpanded(true);
                }
                body.add(section);
            }
        }
        body.add(Box.createVerticalGlue());
        body.revalidate();
        body.repaint();
    }

    private Set<String> snapshotExpandedPresetNames()
    {
        Set<String> out = new HashSet<>();
        for (java.awt.Component c : body.getComponents())
        {
            if (c instanceof PresetSection)
            {
                PresetSection s = (PresetSection) c;
                if (s.isExpanded())
                {
                    out.add(s.getPresetName());
                }
            }
        }
        return out;
    }

    private Map<Integer, UUID> existingIdByPacked()
    {
        Map<Integer, UUID> map = new HashMap<>();
        for (Waypoint w : store.getLibrary().getWaypoints())
        {
            map.put(w.getPackedWorldPoint(), w.getId());
        }
        return map;
    }

    UUID addWaypoint(Preset preset, PresetWaypoint wp)
    {
        store.importMerge(PresetImport.singleEntryLibrary(preset, wp));
        int packed = WorldPointPacker.pack(wp.getX(), wp.getY(), wp.getPlane());
        return findIdByPacked(store.getLibrary(), packed);
    }

    void removeWaypoint(UUID id)
    {
        Waypoint w = findWaypointById(store.getLibrary(), id);
        String name = w != null ? w.getName() : "waypoint";
        store.deleteWaypoint(id);
        String msg = "Removed " + name;
        lastToastTextForTest = msg;
        toastOverlay.show(msg);
    }

    private static UUID findIdByPacked(Library library, int packed)
    {
        for (Waypoint w : library.getWaypoints())
        {
            if (w.getPackedWorldPoint() == packed) return w.getId();
        }
        return null;
    }

    private static Waypoint findWaypointById(Library library, UUID id)
    {
        for (Waypoint w : library.getWaypoints())
        {
            if (w.getId().equals(id)) return w;
        }
        return null;
    }

    String lastToastTextForTest()
    {
        return lastToastTextForTest;
    }
}

