package com.waypointer.ui;

import com.waypointer.util.Text;
import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Cursor;
import java.awt.Dimension;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.awt.event.MouseListener;
import javax.swing.BorderFactory;
import javax.swing.JComponent;
import javax.swing.JLabel;
import javax.swing.JLayeredPane;
import javax.swing.JPanel;
import javax.swing.Timer;
import javax.swing.border.Border;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;

/**
 * Floating-toast host. Wraps a piece of panel content in a JLayeredPane so a
 * confirmation card can appear over the content without consuming layout space.
 * Implements {@link Toasts} so callers depend on the small API rather than the
 * Swing internals.
 */
public final class ToastOverlay extends JLayeredPane implements Toasts
{
    private static final int MARGIN_PX = 8;
    private static final int DEFAULT_DURATION_MS = 2500;
    private static final int ACTION_DURATION_MS = 6000;
    private static final int ANIMATION_FRAMES = 12;
    private static final int ANIMATION_FRAME_DELAY_MS = 15;

    private final JComponent content;
    private final JPanel card = new JPanel();
    private final JLabel message = new JLabel();
    private final JLabel actionLabel = new JLabel();
    private Timer autoHideTimer;
    private int entryAnimationCount;
    private Timer entryTimer;
    private int entryStartY;
    private int entryTargetY;
    private int entryFrame;
    private int currentCardY = -1;
    private static final int PULSE_DURATION_MS = 120;
    private static final Color RESTING_BORDER_COLOR = ColorScheme.LIGHT_GRAY_COLOR;
    private Timer pulseTimer;
    private int pulseCount;

    public ToastOverlay(JComponent content)
    {
        this.content = content;
        setLayout(null);
        add(content, JLayeredPane.DEFAULT_LAYER);

        card.setLayout(new BorderLayout(8, 0));
        card.setBackground(ColorScheme.DARKER_GRAY_COLOR);
        card.setBorder(cardBorder(RESTING_BORDER_COLOR));

        message.setFont(FontManager.getRunescapeSmallFont());
        card.add(message, BorderLayout.CENTER);

        actionLabel.setForeground(ColorScheme.BRAND_ORANGE);
        actionLabel.setFont(FontManager.getRunescapeSmallFont());
        actionLabel.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
        actionLabel.setVisible(false);
        card.add(actionLabel, BorderLayout.EAST);

        add(card, JLayeredPane.POPUP_LAYER);
        card.setVisible(false);
    }

    @Override
    public void doLayout()
    {
        Dimension size = getSize();
        content.setBounds(0, 0, size.width, size.height);
        if (card.isVisible()) positionCard();
    }

    @Override public Dimension getPreferredSize() { return content.getPreferredSize(); }
    @Override public Dimension getMinimumSize() { return content.getMinimumSize(); }

    private void positionCard()
    {
        Dimension size = getSize();
        if (size.width <= 0 || size.height <= 0) return;
        Dimension pref = card.getPreferredSize();
        int cardWidth = Math.max(0, size.width - 2 * MARGIN_PX);
        entryTargetY = Math.max(0, size.height - pref.height - MARGIN_PX);
        if (currentCardY < 0) currentCardY = entryTargetY;
        card.setBounds(MARGIN_PX, currentCardY, cardWidth, pref.height);
    }

    private void presentEntry()
    {
        if (card.isVisible())
        {
            // Replace-in-place: the card stays put, so a slide would be invisible. Flash the
            // border to brand orange briefly so two quick actions don't read as one.
            pulse();
            return;
        }
        entryAnimationCount++;
        Dimension size = getSize();
        Dimension pref = card.getPreferredSize();
        entryStartY = size.height; // just below the visible area
        currentCardY = entryStartY;
        card.setBounds(MARGIN_PX, currentCardY, Math.max(0, size.width - 2 * MARGIN_PX), pref.height);
        entryFrame = 0;

        if (entryTimer != null && entryTimer.isRunning()) entryTimer.stop();
        entryTimer = new Timer(ANIMATION_FRAME_DELAY_MS, e -> {
            entryFrame++;
            double t = Math.min(1.0, (double) entryFrame / ANIMATION_FRAMES);
            currentCardY = (int) Math.round(entryStartY + (entryTargetY - entryStartY) * t);
            card.setLocation(MARGIN_PX, currentCardY);
            if (entryFrame >= ANIMATION_FRAMES) ((Timer) e.getSource()).stop();
        });
        entryTimer.start();
    }

    private static Border cardBorder(Color line)
    {
        return BorderFactory.createCompoundBorder(
            BorderFactory.createLineBorder(line, 1),
            BorderFactory.createEmptyBorder(8, 12, 8, 12));
    }

    private void pulse()
    {
        pulseCount++;
        card.setBorder(cardBorder(ColorScheme.BRAND_ORANGE));
        if (pulseTimer != null && pulseTimer.isRunning()) pulseTimer.stop();
        pulseTimer = new Timer(PULSE_DURATION_MS, e -> card.setBorder(cardBorder(RESTING_BORDER_COLOR)));
        pulseTimer.setRepeats(false);
        pulseTimer.start();
    }

    private void restartAutoHide(int durationMs)
    {
        if (autoHideTimer != null && autoHideTimer.isRunning()) autoHideTimer.stop();
        autoHideTimer = new Timer(durationMs, e -> card.setVisible(false));
        autoHideTimer.setRepeats(false);
        autoHideTimer.start();
    }

    @Override
    public void show(String text)
    {
        show(text, Severity.SUCCESS);
    }

    @Override
    public void show(String text, Severity severity)
    {
        applyMessage(text, severity);
        actionLabel.setVisible(false);
        positionCard();
        presentEntry();
        card.setVisible(true);
        restartAutoHide(DEFAULT_DURATION_MS);
    }

    @Override
    public void show(String text, String actionLabel, Runnable onClick)
    {
        show(text, actionLabel, onClick, Severity.SUCCESS);
    }

    @Override
    public void show(String text, String actionLabelText, Runnable onClick, Severity severity)
    {
        applyMessage(text, severity);
        this.actionLabel.setText("<html><u>" + Text.escapeHtml(actionLabelText) + "</u></html>");
        this.actionLabel.setVisible(true);

        // Replace any previous listener so a stale runnable from the prior toast doesn't fire.
        for (MouseListener l : this.actionLabel.getMouseListeners())
        {
            this.actionLabel.removeMouseListener(l);
        }
        this.actionLabel.addMouseListener(new MouseAdapter()
        {
            @Override
            public void mouseClicked(MouseEvent e)
            {
                if (autoHideTimer != null) autoHideTimer.stop();
                card.setVisible(false);
                if (onClick != null) onClick.run();
            }
        });

        positionCard();
        presentEntry();
        card.setVisible(true);
        restartAutoHide(ACTION_DURATION_MS);
    }

    private void applyMessage(String text, Severity severity)
    {
        message.setForeground(colorFor(severity));
        String glyph = glyphFor(severity);
        message.setText("<html>" + Text.escapeHtml(glyph + "  " + text) + "</html>");
    }

    private static Color colorFor(Severity severity)
    {
        switch (severity)
        {
            case WARN:  return ColorScheme.BRAND_ORANGE;
            case ERROR: return ColorScheme.PROGRESS_ERROR_COLOR;
            case SUCCESS:
            default:    return ColorScheme.PROGRESS_COMPLETE_COLOR;
        }
    }

    private static String glyphFor(Severity severity)
    {
        switch (severity)
        {
            case WARN:  return "⚠"; // U+26A0 warning sign
            case ERROR: return "✕"; // U+2715 multiplication X
            case SUCCESS:
            default:    return "✓"; // U+2713 check mark
        }
    }

    boolean cardIsVisibleForTest() { return card.isVisible(); }
    String cardLabelTextForTest() { return message.getText(); }
    Timer autoHideTimerForTest() { return autoHideTimer; }
    JLabel actionLabelForTest() { return actionLabel; }
    int entryAnimationCountForTest() { return entryAnimationCount; }
    int pulseCountForTest() { return pulseCount; }

    int cardCurrentYForTest()
    {
        return card.getY();
    }

    void completeEntryAnimationForTest()
    {
        if (entryTimer == null) return;
        while (entryFrame < ANIMATION_FRAMES)
        {
            entryFrame++;
            double t = Math.min(1.0, (double) entryFrame / ANIMATION_FRAMES);
            currentCardY = (int) Math.round(entryStartY + (entryTargetY - entryStartY) * t);
            card.setLocation(MARGIN_PX, currentCardY);
        }
        entryTimer.stop();
    }
}

package com.waypointer.ui;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics;
import java.util.function.Consumer;
import javax.swing.BorderFactory;
import javax.swing.JComponent;
import javax.swing.JMenuItem;
import javax.swing.JPopupMenu;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;

/**
 * A compact palette of category accent colours. Fixed swatches chosen to read against the
 * RuneLite dark panel; none is brand orange, which signals active-path status elsewhere.
 * Reports the chosen packed RGB (or null for "None") to the supplied consumer.
 */
final class ColorPalettePopup
{
    // Packed RGB. Amber here is intentionally not BRAND_ORANGE.
    static final int[] SWATCHES = {
        0xCC4040, // muted red
        0xC8922A, // amber
        0x4F9D4F, // green
        0x3FA39A, // teal
        0x4477BB, // blue
        0x8A5FB0, // purple
        0xB05592, // magenta
        0x8A8F96, // grey
    };

    private ColorPalettePopup() {}

    static JPopupMenu build(Integer current, Consumer<Integer> onPick)
    {
        JPopupMenu popup = new JPopupMenu();
        popup.setBackground(ColorScheme.DARKER_GRAY_COLOR);
        popup.setBorder(BorderFactory.createLineBorder(ColorScheme.DARK_GRAY_COLOR));
        for (int rgb : SWATCHES)
        {
            JMenuItem item = new JMenuItem();
            item.setOpaque(true);
            item.setBackground(ColorScheme.DARKER_GRAY_COLOR);
            item.getAccessibleContext().setAccessibleName("Category colour " + String.format("#%06X", rgb));
            item.add(new Swatch(new Color(rgb), current != null && current == rgb));
            item.addActionListener(e -> onPick.accept(rgb));
            popup.add(item);
        }
        popup.addSeparator();
        JMenuItem none = new JMenuItem("None");
        none.setOpaque(true);
        none.setBackground(ColorScheme.DARKER_GRAY_COLOR);
        none.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
        none.setFont(FontManager.getRunescapeSmallFont());
        none.getAccessibleContext().setAccessibleName("Clear category colour");
        none.addActionListener(e -> onPick.accept(null));
        popup.add(none);
        return popup;
    }

    /** A fixed-size colour chip; outlined when it is the current selection. */
    private static final class Swatch extends JComponent
    {
        private final Color color;
        private final boolean selected;

        Swatch(Color color, boolean selected)
        {
            this.color = color;
            this.selected = selected;
            setOpaque(true);
            setBackground(ColorScheme.DARKER_GRAY_COLOR);
            setPreferredSize(new Dimension(96, 16));
            setBorder(BorderFactory.createEmptyBorder(2, 2, 2, 2));
        }

        @Override
        protected void paintComponent(Graphics g)
        {
            g.setColor(getBackground());
            g.fillRect(0, 0, getWidth(), getHeight());
            g.setColor(color);
            g.fillRect(2, 2, getWidth() - 4, getHeight() - 4);
            if (selected)
            {
                g.setColor(ColorScheme.LIGHT_GRAY_COLOR);
                g.drawRect(1, 1, getWidth() - 3, getHeight() - 3);
            }
        }
    }
}

package com.waypointer.ui;

import com.waypointer.codec.WaypointShareCodec;
import com.waypointer.model.Library;
import com.waypointer.service.LibrarySubsetBuilder;
import com.waypointer.service.WaypointStore;
import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Dialog;
import java.awt.Dimension;
import java.awt.FlowLayout;
import java.awt.Window;
import javax.swing.BorderFactory;
import javax.swing.JButton;
import javax.swing.JDialog;
import javax.swing.JLabel;
import javax.swing.JOptionPane;
import javax.swing.JPanel;
import javax.swing.JScrollPane;
import javax.swing.JTextArea;
import net.runelite.client.ui.ColorScheme;

/**
 * Modal import dialog. A source row at the top loads an incoming library from a pasted share code
 * ({@code WP1:} / {@code WPL1:}); the tree below then lets the recipient pick which categories /
 * waypoints to merge. {@code Import selected} stays disabled until a source is loaded and the
 * selection is non-empty. Decode/populate/import are package-private so they can be tested without
 * driving modal Swing.
 */
final class ImportPickerDialog extends JDialog
{
    private final WaypointStore store;
    private final WaypointShareCodec shareCodec;
    private final Toasts toasts;

    private final JTextArea codeArea = new JTextArea(3, 32);
    private final JPanel treeHolder = new JPanel(new BorderLayout());
    private final JButton importBtn = new JButton("Import selected");

    private Library incoming;            // null until a source loads
    private WaypointPickerModel model;   // null until a source loads

    ImportPickerDialog(Window owner, WaypointStore store, WaypointShareCodec shareCodec,
        Toasts toasts)
    {
        super(owner, "Import waypoints", Dialog.ModalityType.APPLICATION_MODAL);
        this.store = store;
        this.shareCodec = shareCodec;
        this.toasts = toasts == null ? Toasts.NO_OP : toasts;

        JPanel content = Dialogs.applyDarkContentPane(this);
        Dialogs.bindEscape(this);

        content.add(buildSourceRow(), BorderLayout.NORTH);

        treeHolder.setBackground(ColorScheme.DARK_GRAY_COLOR);
        treeHolder.setPreferredSize(new Dimension(320, 320));
        content.add(treeHolder, BorderLayout.CENTER);

        content.add(buildFooter(), BorderLayout.SOUTH);

        updateImportButton();
        getRootPane().setDefaultButton(importBtn);
        Dialogs.finish(this, owner);
    }

    private JPanel buildSourceRow()
    {
        JPanel wrap = new JPanel(new BorderLayout(4, 4));
        wrap.setBackground(ColorScheme.DARK_GRAY_COLOR);

        JLabel prompt = new JLabel("Paste a WP1: or WPL1: code:");
        prompt.setForeground(Color.WHITE);
        wrap.add(prompt, BorderLayout.NORTH);

        Styles.textArea(codeArea);
        JScrollPane codeScroll = new JScrollPane(codeArea);
        codeScroll.setBorder(BorderFactory.createLineBorder(ColorScheme.LIGHT_GRAY_COLOR, 1));
        wrap.add(codeScroll, BorderLayout.CENTER);

        JPanel buttons = new JPanel(new FlowLayout(FlowLayout.LEFT, 6, 0));
        buttons.setBackground(ColorScheme.DARK_GRAY_COLOR);
        JButton loadCode = new JButton("Load code");
        Styles.secondaryButton(loadCode);
        loadCode.addActionListener(e -> onLoadCode());
        buttons.add(loadCode);
        wrap.add(buttons, BorderLayout.SOUTH);
        return wrap;
    }

    private JPanel buildFooter()
    {
        JPanel footer = new JPanel(new FlowLayout(FlowLayout.RIGHT));
        footer.setBackground(ColorScheme.DARK_GRAY_COLOR);
        JButton cancel = new JButton("Cancel");
        Styles.secondaryButton(cancel);
        Styles.primaryButton(importBtn);
        cancel.addActionListener(e -> dispose());
        importBtn.addActionListener(e -> onImport());
        footer.add(cancel);
        footer.add(importBtn);
        return footer;
    }

    // ---- package-private seams (no dialogs popped; used by handlers and by tests) ----

    Library decodeCodeOrNull(String text)
    {
        try { return shareCodec.decodeLibrary(text); }
        catch (RuntimeException ex) { return null; }
    }

    void populate(Library loaded)
    {
        this.incoming = loaded;
        this.model = new WaypointPickerModel(loaded);
        WaypointTreePicker tree = new WaypointTreePicker(model, this::updateImportButton);
        JScrollPane scroll = new JScrollPane(tree);
        scroll.setBorder(BorderFactory.createLineBorder(ColorScheme.LIGHT_GRAY_COLOR, 1));
        scroll.getViewport().setBackground(ColorScheme.DARK_GRAY_COLOR);
        treeHolder.removeAll();
        treeHolder.add(scroll, BorderLayout.CENTER);
        treeHolder.revalidate();
        treeHolder.repaint();
        updateImportButton();
    }

    boolean hasLoadedSource() { return model != null; }

    WaypointStore.ImportResult importSelected()
    {
        if (model == null || incoming == null) return null;
        Library subset = LibrarySubsetBuilder.build(incoming,
            model.getSelectedWaypointIds(), model.getSelectedCategoryIds());
        return store.importMerge(subset);
    }

    // ---- handlers ----

    private void onLoadCode()
    {
        Library lib = decodeCodeOrNull(codeArea.getText());
        if (lib == null)
        {
            warn("Not a readable share code (expected WP1: or WPL1:).");
            return;
        }
        populate(lib);
    }

    private void onImport()
    {
        WaypointStore.ImportResult r = importSelected();
        if (r != null)
        {
            toasts.show(String.format("Imported %d waypoints, %d categories. Skipped %d.",
                r.waypointsAdded, r.categoriesAdded, r.waypointsSkipped));
        }
        dispose();
    }

    private void updateImportButton()
    {
        importBtn.setEnabled(model != null && !model.isEmptySelection());
    }

    private void warn(String msg)
    {
        JOptionPane.showMessageDialog(this, msg, "Waypointer", JOptionPane.WARNING_MESSAGE);
    }
}

package com.waypointer.ui;

import java.awt.Cursor;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import javax.swing.JPanel;
import javax.swing.SwingUtilities;
import net.runelite.client.ui.ColorScheme;

// Card-row pattern helpers. A "card" is a JPanel styled as a hover-aware row:
// DARKER_GRAY background, DARK_GRAY_HOVER on hover, HAND_CURSOR, and a left-click handler.
// Swing does not propagate mouse events from a child component with no listeners up to its
// parent, so callers must attach the returned MouseAdapter to any child label that should
// also be in the click hit region.
final class Cards
{
    private Cards() {}

    static MouseAdapter clickable(JPanel card, Runnable onClick)
    {
        card.setBackground(ColorScheme.DARKER_GRAY_COLOR);
        card.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
        MouseAdapter ma = new MouseAdapter()
        {
            @Override public void mouseEntered(MouseEvent e)
            {
                card.setBackground(ColorScheme.DARK_GRAY_HOVER_COLOR);
            }

            @Override public void mouseExited(MouseEvent e)
            {
                // mouseExited fires when the cursor crosses into a child component too, and the
                // event point arrives in that child's coordinate space. Convert to the card's
                // space before the bounds test, or exiting via a child whose bounds overlap the
                // card origin leaves the hover tint stuck (mirrors WaypointRow's select adapter).
                java.awt.Point p = SwingUtilities.convertPoint(e.getComponent(), e.getPoint(), card);
                if (card.contains(p)) return;
                card.setBackground(ColorScheme.DARKER_GRAY_COLOR);
            }

            @Override public void mouseClicked(MouseEvent e)
            {
                if (SwingUtilities.isLeftMouseButton(e)) onClick.run();
            }
        };
        card.addMouseListener(ma);
        return ma;
    }
}

package com.waypointer.ui;

import com.waypointer.model.route.RouteStep;
import com.waypointer.model.route.StepType;
import java.awt.BorderLayout;
import java.awt.Cursor;
import java.awt.Dimension;
import java.awt.FlowLayout;
import java.util.function.Consumer;
import javax.swing.BorderFactory;
import javax.swing.JButton;
import javax.swing.JLabel;
import javax.swing.JPanel;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;

/**
 * One step row in {@link RouteEditorPanel}: grip + index + type glyph + label, with edit and
 * delete buttons. Drag the grip to reorder; click the pencil (or the label) to edit.
 */
final class RouteStepRow extends JPanel
{
    // ◉ = filled circle (WAYPOINT), ▤ = note card (MANUAL), ⠿ = drag grip,
    // ✎ = pencil (edit), ✕ = multiply/close (delete)
    private static final String GLYPH_WAYPOINT = "◉";
    private static final String GLYPH_MANUAL   = "▤";
    private static final String GLYPH_GRIP     = "⠿";
    private static final String GLYPH_EDIT     = "✎";
    private static final String GLYPH_DELETE   = "✕";

    RouteStepRow(int index, RouteStep step, Runnable onEdit, Consumer<RouteStep> onDelete,
        RouteStepDragHandler dragHandler)
    {
        setLayout(new BorderLayout(6, 0));
        setBackground(ColorScheme.DARKER_GRAY_COLOR);
        setBorder(BorderFactory.createEmptyBorder(4, 6, 4, 6));

        // Grip handle (west): dragging it past the threshold starts a reorder.
        JLabel grip = new JLabel(GLYPH_GRIP);
        grip.setFont(FontManager.getRunescapeSmallFont());
        grip.setForeground(ColorScheme.LIGHT_GRAY_COLOR.darker());
        grip.setCursor(Cursor.getPredefinedCursor(Cursor.MOVE_CURSOR));
        grip.setBorder(BorderFactory.createEmptyBorder(0, 0, 0, 4));
        add(grip, BorderLayout.WEST);

        String labelText = step.getLabel() == null || step.getLabel().isEmpty()
            ? "(empty)" : step.getLabel();
        JLabel text = new JLabel((index + 1) + ". " + stepGlyph(step.getType()) + "  " + labelText);
        text.setFont(FontManager.getRunescapeSmallFont());
        text.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
        text.addMouseListener(new java.awt.event.MouseAdapter()
        {
            @Override public void mouseClicked(java.awt.event.MouseEvent e) { onEdit.run(); }
        });
        add(text, BorderLayout.CENTER);

        // East: edit (pencil) then delete (x). Pencil is the primary, visible edit affordance.
        JPanel actions = new JPanel(new FlowLayout(FlowLayout.RIGHT, 4, 0));
        actions.setBackground(ColorScheme.DARKER_GRAY_COLOR);

        JButton edit = new JButton(GLYPH_EDIT);
        Styles.compactSecondaryButton(edit);
        edit.getAccessibleContext().setAccessibleName("Edit step");
        edit.addActionListener(e -> onEdit.run());
        actions.add(edit);

        JButton del = new JButton(GLYPH_DELETE);
        Styles.compactSecondaryButton(del);
        del.getAccessibleContext().setAccessibleName("Delete step");
        del.addActionListener(e -> onDelete.accept(step));
        actions.add(del);

        add(actions, BorderLayout.EAST);

        dragHandler.attach(this, grip, step.getId());
    }

    static String stepGlyph(StepType type)
    {
        return type == StepType.WAYPOINT ? GLYPH_WAYPOINT : GLYPH_MANUAL;
    }

    @Override
    public Dimension getMaximumSize() { return Styles.capHeight(this); }
}

