import javax.swing.JComponent;
import javax.swing.JDialog;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.SwingConstants;
import javax.swing.SwingUtilities;
import net.runelite.client.game.SpriteManager;
import net.runelite.client.ui.ColorScheme;

/** Modal icon picker for a category or waypoint. Category dropdown drives a 5x10 grid
 *  paginated 50 per page. ESC closes without changing anything. Opens to the category and
 *  page containing the current icon when there is one. */
public class IconPickerDialog extends JDialog
{
    private static final int PAGE_SIZE = 50;
    private static final int GRID_COLS = 5;
    private static final int GRID_ROWS = 10;

    private final SpriteManager spriteManager;
    private final Consumer<Integer> onSelect;
    private final Integer currentIconId;
    private final List<JLabel> cellLabels = new ArrayList<>(PAGE_SIZE);

    private final List<CategoryView> categories;
    private int currentCategoryIdx;
    private int totalPages;
    private int currentPage;

    private JComboBox<String> categoryCombo;
    private JButton prevBtn;
    private JButton nextBtn;
    private JLabel pageLabel;

    public IconPickerDialog(Window owner, SpriteManager spriteManager, IconCatalog catalog,
        Integer currentIconId, Consumer<Integer> onSelect)
    {
        super(owner, "Pick icon", ModalityType.APPLICATION_MODAL);
        this.spriteManager = spriteManager;
        this.onSelect = onSelect;
        this.currentIconId = currentIconId;
        this.categories = buildCategoryViews(catalog);

        // Find the category that currently owns the active icon, if any.
        this.currentCategoryIdx = findCategoryFor(currentIconId);
        recomputePagination();

        setResizable(false);

        JPanel root = Dialogs.applyDarkContentPane(this, 0, 6);

        JLabel title = new JLabel("Choose an icon", SwingConstants.LEFT);
        title.setForeground(Color.WHITE);
        root.add(title, BorderLayout.NORTH);

        // Center stack: category combo + None row (NORTH), grid (CENTER), pagination (SOUTH).
        JPanel center = new JPanel(new BorderLayout(0, 6));
        center.setBackground(ColorScheme.DARK_GRAY_COLOR);

        JPanel topStack = new JPanel(new BorderLayout(0, 6));
        topStack.setBackground(ColorScheme.DARK_GRAY_COLOR);
        topStack.add(buildCategoryRow(), BorderLayout.NORTH);
        JPanel noneRow = new JPanel(new BorderLayout());
        noneRow.setBackground(ColorScheme.DARK_GRAY_COLOR);
        noneRow.add(buildNoneCell(currentIconId == null), BorderLayout.CENTER);
        topStack.add(noneRow, BorderLayout.SOUTH);
        center.add(topStack, BorderLayout.NORTH);

        JPanel grid = new JPanel(new GridLayout(GRID_ROWS, GRID_COLS, 4, 4));
        grid.setBackground(ColorScheme.DARK_GRAY_COLOR);
        for (int i = 0; i < PAGE_SIZE; i++)
        {
            JLabel cell = buildIconCell();
            cellLabels.add(cell);
            grid.add(cell);
        }
        center.add(grid, BorderLayout.CENTER);

        center.add(buildPaginationFooter(), BorderLayout.SOUTH);

        root.add(center, BorderLayout.CENTER);

        Dialogs.bindEscape(this);

        renderPage(currentPage);

        Dialogs.finish(this, owner);
    }

    private void recomputePagination()
    {
        List<Integer> ids = currentCategoryIds();
        this.totalPages = Math.max(1, (ids.size() + PAGE_SIZE - 1) / PAGE_SIZE);
        this.currentPage = computeInitialPage(currentIconId, ids, PAGE_SIZE);
    }

    private List<Integer> currentCategoryIds()
    {
        if (categories.isEmpty()) return Collections.emptyList();
        return categories.get(currentCategoryIdx).ids;
    }

    private int findCategoryFor(Integer iconId)
    {
        if (iconId == null) return 0;
        for (int i = 0; i < categories.size(); i++)
        {
            if (categories.get(i).ids.contains(iconId)) return i;
        }
        return 0;
    }

    static int computeInitialPage(Integer currentIconId, List<Integer> sortedIds, int pageSize)
    {
        if (currentIconId == null) return 0;
        int idx = Collections.binarySearch(sortedIds, currentIconId);
        if (idx < 0) return 0;
        return idx / pageSize;
    }

    private JComponent buildCategoryRow()
    {
        JPanel row = new JPanel(new BorderLayout(6, 0));
        row.setBackground(ColorScheme.DARK_GRAY_COLOR);
        JLabel label = new JLabel("Category:");
        label.setForeground(Color.LIGHT_GRAY);
        row.add(label, BorderLayout.WEST);

        String[] names = new String[categories.size()];
        for (int i = 0; i < categories.size(); i++) names[i] = categories.get(i).label;
        categoryCombo = new JComboBox<>(names);
        categoryCombo.setBackground(ColorScheme.DARKER_GRAY_COLOR);
        categoryCombo.setForeground(Color.WHITE);
        if (!categories.isEmpty()) categoryCombo.setSelectedIndex(currentCategoryIdx);
        categoryCombo.addActionListener(e -> {
            int sel = categoryCombo.getSelectedIndex();
            if (sel < 0 || sel == currentCategoryIdx) return;
            currentCategoryIdx = sel;
            // Start at page 0 on manual category switch; finding the current icon in the
            // newly-selected list rarely matches user intent.
            currentPage = 0;
            totalPages = Math.max(1, (currentCategoryIds().size() + PAGE_SIZE - 1) / PAGE_SIZE);
            renderPage(0);
        });
        row.add(categoryCombo, BorderLayout.CENTER);
        return row;
    }

    private JPanel buildPaginationFooter()
    {
        JPanel footer = new JPanel(new BorderLayout(6, 0));
        footer.setBackground(ColorScheme.DARK_GRAY_COLOR);

        prevBtn = new JButton("< Prev");
        Styles.secondaryButton(prevBtn);
        prevBtn.addActionListener(e -> {
            if (currentPage > 0) renderPage(currentPage - 1);
        });

        nextBtn = new JButton("Next >");
        Styles.secondaryButton(nextBtn);
        nextBtn.addActionListener(e -> {
            if (currentPage < totalPages - 1) renderPage(currentPage + 1);
        });

        pageLabel = new JLabel("", SwingConstants.CENTER);
        pageLabel.setForeground(Color.LIGHT_GRAY);

        footer.add(prevBtn, BorderLayout.WEST);
        footer.add(pageLabel, BorderLayout.CENTER);
        footer.add(nextBtn, BorderLayout.EAST);
        return footer;
    }

    private void renderPage(int page)
    {
        currentPage = page;
        List<Integer> ids = currentCategoryIds();
        int start = page * PAGE_SIZE;
        int end = Math.min(start + PAGE_SIZE, ids.size());

        for (int i = 0; i < PAGE_SIZE; i++)
        {
            JLabel cell = cellLabels.get(i);
            for (java.awt.event.MouseListener ml : cell.getMouseListeners())
            {
                cell.removeMouseListener(ml);
            }
            cell.setIcon(null);

            int globalIdx = start + i;
            if (globalIdx >= end)
            {
                cell.setVisible(false);
                cell.setToolTipText(null);
                styleCell(cell, false);
                continue;
            }

            cell.setVisible(true);
            final int spriteId = ids.get(globalIdx);
            boolean selected = currentIconId != null && currentIconId == spriteId;
            cell.setToolTipText("Sprite " + spriteId);
            styleCell(cell, selected);

            spriteManager.getSpriteAsync(spriteId, 0, img -> {
                if (img == null) return;
                SwingUtilities.invokeLater(() -> {
                    if (("Sprite " + spriteId).equals(cell.getToolTipText()))
                    {
                        cell.setIcon(new ImageIcon(img));
                        cell.revalidate();
                        cell.repaint();
                    }
                });
            });

            final boolean cellSelected = selected;
            cell.addMouseListener(new MouseAdapter() {
                @Override public void mouseClicked(MouseEvent e)
                {
                    onSelect.accept(spriteId);
                    dispose();
                }
                @Override public void mouseEntered(MouseEvent e)
                {
                    if (!cellSelected) hover(cell, true);
                }
                @Override public void mouseExited(MouseEvent e)
                {
                    if (!cellSelected) hover(cell, false);
                }
            });
        }

        if (prevBtn != null) prevBtn.setEnabled(currentPage > 0);
        if (nextBtn != null) nextBtn.setEnabled(currentPage < totalPages - 1);
        if (pageLabel != null)
        {
            pageLabel.setText(String.format("Page %d of %d (%d icons)",
                currentPage + 1, totalPages, ids.size()));
        }

        revalidate();
        repaint();
    }

    private JComponent buildNoneCell(boolean selected)
    {
        JLabel cell = new JLabel("None", SwingConstants.CENTER);
        cell.setOpaque(true);
        cell.setForeground(Color.LIGHT_GRAY);
        cell.setPreferredSize(new Dimension(0, 28));
        cell.setToolTipText("No icon");
        styleCell(cell, selected);
        cell.addMouseListener(new MouseAdapter() {
            @Override public void mouseClicked(MouseEvent e)
            {
                onSelect.accept(null);
                dispose();
            }
            @Override public void mouseEntered(MouseEvent e) { if (!selected) hover(cell, true); }
            @Override public void mouseExited(MouseEvent e) { if (!selected) hover(cell, false); }
        });
        return cell;
    }

    private JLabel buildIconCell()
    {
        JLabel cell = new JLabel("", SwingConstants.CENTER);
        cell.setOpaque(true);
        cell.setPreferredSize(new Dimension(28, 28));
        styleCell(cell, false);
        return cell;
    }

    private static void styleCell(Component c, boolean selected)
    {
        c.setBackground(selected ? ColorScheme.BRAND_ORANGE.darker() : ColorScheme.DARKER_GRAY_COLOR);
        if (c instanceof JComponent)
        {
            ((JComponent) c).setBorder(BorderFactory.createCompoundBorder(
                BorderFactory.createLineBorder(selected
                    ? ColorScheme.BRAND_ORANGE
                    : ColorScheme.DARK_GRAY_COLOR.darker(), 1),
                BorderFactory.createEmptyBorder(2, 2, 2, 2)));
        }
        c.setCursor(java.awt.Cursor.getPredefinedCursor(java.awt.Cursor.HAND_CURSOR));
    }

    private static void hover(JComponent c, boolean hovering)
    {
        c.setBackground(hovering
            ? ColorScheme.DARKER_GRAY_HOVER_COLOR
            : ColorScheme.DARKER_GRAY_COLOR);
    }

    private static List<CategoryView> buildCategoryViews(IconCatalog catalog)
    {
        List<CategoryView> out = new ArrayList<>();
        if (catalog != null)
        {
            for (IconCatalog.Category c : catalog.getCategories())
            {
                if (c.getSpriteIds().isEmpty()) continue;
                out.add(new CategoryView(
                    c.getName() + " (" + c.getSpriteIds().size() + ")",
                    c.getSpriteIds()));
            }
        }
        // If the bundled catalog is missing or malformed the picker simply shows no
        // categories; "None" stays selectable. This only happens with a corrupt jar.
        return out;
    }

    private static final class CategoryView
    {
        final String label;
        final List<Integer> ids;
        CategoryView(String label, List<Integer> ids) { this.label = label; this.ids = ids; }
    }
}

package com.waypointer.ui;

import com.google.gson.Gson;
import com.google.gson.JsonSyntaxException;
import com.google.gson.reflect.TypeToken;
import java.util.HashMap;
import java.util.Map;
import java.util.UUID;
import javax.inject.Inject;

/** Codec for the categoryCollapsedJson config string. Map<categoryId, collapsed?>. */
public class CollapseStateCodec
{
    private final Gson gson;

    @Inject
    public CollapseStateCodec(Gson gson) { this.gson = gson; }

    public Map<UUID, Boolean> decode(String s)
    {
        if (s == null || s.isEmpty()) return new HashMap<>();
        try
        {
            Map<String, Boolean> raw = gson.fromJson(s,
                new TypeToken<Map<String, Boolean>>(){}.getType());
            if (raw == null) return new HashMap<>();
            Map<UUID, Boolean> out = new HashMap<>();
            for (Map.Entry<String, Boolean> e : raw.entrySet())
            {
                try { out.put(UUID.fromString(e.getKey()), e.getValue()); }
                catch (IllegalArgumentException ignored) {}
            }
            return out;
        }
        catch (JsonSyntaxException e)
        {
            return new HashMap<>();
        }
    }

    public String encode(Map<UUID, Boolean> map)
    {
        Map<String, Boolean> raw = new HashMap<>();
        for (Map.Entry<UUID, Boolean> e : map.entrySet())
        {
            raw.put(e.getKey().toString(), e.getValue());
        }
        return gson.toJson(raw);
    }
}

package com.waypointer.ui;

import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.Insets;
import java.awt.RenderingHints;
import java.awt.event.FocusAdapter;
import java.awt.event.FocusEvent;
import javax.swing.JTextField;
import net.runelite.client.ui.ColorScheme;

/**
 * JTextField that paints a faded hint over the empty, unfocused field. The hint is paint-only
 * and never enters the field's document, so {@link #getText()} stays empty until the user
 * types. Callers that filter on the field contents need no special handling.
 */
class PlaceholderTextField extends JTextField
{
    private final String placeholder;

    PlaceholderTextField(String placeholder)
    {
        this.placeholder = placeholder == null ? "" : placeholder;
        // Explicit repaint on focus change; default JTextField repaint timing is LAF-dependent
        // and the hint must vanish the instant the field gains focus.
        addFocusListener(new FocusAdapter()
        {
            @Override public void focusGained(FocusEvent e) { repaint(); }
            @Override public void focusLost(FocusEvent e)   { repaint(); }
        });
    }

    String getPlaceholder()
    {
        return placeholder;
    }

    @Override
    protected void paintComponent(Graphics g)
    {
        super.paintComponent(g);
        if (placeholder.isEmpty() || !getText().isEmpty() || isFocusOwner())
        {
            return;
        }
        Graphics2D g2 = (Graphics2D) g.create();
        try
        {
            g2.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING,
                RenderingHints.VALUE_TEXT_ANTIALIAS_ON);
            g2.setFont(getFont());
            g2.setColor(ColorScheme.LIGHT_GRAY_COLOR);
            Insets in = getInsets();
            int x = in.left;
            int y = in.top + g2.getFontMetrics().getAscent();
            g2.drawString(placeholder, x, y);
        }
        finally
        {
            g2.dispose();
        }
    }
}

package com.waypointer.ui;

import com.waypointer.model.Waypoint;
import com.waypointer.util.Text;
import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Cursor;
import java.awt.Dimension;
import java.awt.FlowLayout;
import java.awt.Font;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import javax.swing.BorderFactory;
import javax.swing.JButton;
import javax.swing.JLabel;
import javax.swing.JMenuItem;
import javax.swing.JPanel;
import javax.swing.JPopupMenu;
import javax.swing.SwingUtilities;
import javax.swing.border.Border;
import net.runelite.client.game.SpriteManager;
import net.runelite.client.ui.ColorScheme;

/**
 * A single waypoint row, rendered as a clickable card. Click body -> expand inline edit.
 * Drag handle on the left initiates drag (not part of click hit region). Icon-only Play
 * button on the right (dark at rest, brand orange on hover or when this row is the active
 * path target). Custom sprite icons (when set) attach to the name label so icon + text
 * share JLabel's built-in vertical centering and align with the Play button.
 *
 * In select mode the left edge shows a checkbox instead of the drag handle, the right-side
 * Play button is hidden, and a body click toggles selection (shift = range) instead of
 * expanding the inline editor.
 */
public class WaypointRow extends JPanel implements DropIndicatable
{
    private final Waypoint waypoint;
    private final JLabel dragHandle;
    private final java.awt.Color restingBackground;
    private Border prevBorder;
    // Non-null only outside select mode (select mode hides the Play button). Held so the panel can
    // retint it in place on a path-target change instead of rebuilding the whole body tree (#67).
    private JButton playButton;
    private boolean activePathState;

    /** Start building a row for {@code waypoint}. Booleans default false; callbacks default no-op. */
    public static Spec spec(Waypoint waypoint)
    {
        return new Spec(waypoint);
    }

    /** Named, defaulted parameter object for {@link WaypointRow}. */
    public static final class Spec
    {
        private final Waypoint waypoint;
        private boolean active;
        private boolean isPinned;
        private boolean isWilderness;
        private boolean dragDisabled;
        private Runnable onPlay = () -> {};
        private Runnable onClickBody = () -> {};
        private Runnable onTogglePin = () -> {};
        private Runnable onDelete = () -> {};
        private SpriteManager spriteManager;
        private String originCategoryName;
        private boolean selectMode;
        private boolean selected;
        private java.util.function.Consumer<Boolean> onSelectClick = sel -> {};
        private Runnable onEnterSelectMode = () -> {};

        private Spec(Waypoint waypoint) { this.waypoint = waypoint; }

        public Spec active(boolean v) { this.active = v; return this; }
        public Spec pinned(boolean v) { this.isPinned = v; return this; }
        public Spec wilderness(boolean v) { this.isWilderness = v; return this; }
        public Spec dragDisabled(boolean v) { this.dragDisabled = v; return this; }
        public Spec onPlay(Runnable r) { this.onPlay = r; return this; }
        public Spec onClickBody(Runnable r) { this.onClickBody = r; return this; }
        public Spec onTogglePin(Runnable r) { this.onTogglePin = r; return this; }
        public Spec onDelete(Runnable r) { this.onDelete = r; return this; }
        public Spec spriteManager(SpriteManager sm) { this.spriteManager = sm; return this; }
        public Spec originCategoryName(String n) { this.originCategoryName = n; return this; }
        public Spec selectMode(boolean v) { this.selectMode = v; return this; }
        public Spec selected(boolean v) { this.selected = v; return this; }
        public Spec onSelectClick(java.util.function.Consumer<Boolean> c) { this.onSelectClick = c; return this; }
        public Spec onEnterSelectMode(Runnable r) { this.onEnterSelectMode = r; return this; }

        public WaypointRow build() { return new WaypointRow(this); }
    }

    private WaypointRow(Spec s)
    {
        this.waypoint = s.waypoint;
        setLayout(new BorderLayout(8, 0));
        setBorder(BorderFactory.createEmptyBorder(8, 10, 8, 10));
        setOpaque(true);

        // Body click: in select mode toggle selection (shift = range); otherwise expand inline.
        final MouseAdapter ma;
        if (s.selectMode)
        {
            setBackground(ColorScheme.DARKER_GRAY_COLOR);
            setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
            ma = new MouseAdapter()
            {
                @Override public void mouseEntered(MouseEvent e)
                {
                    setBackground(ColorScheme.DARK_GRAY_HOVER_COLOR);
                }
                @Override public void mouseExited(MouseEvent e)
                {
                    // ma is also attached to child components (checkbox, name label), so the
                    // event point is in the child's coordinate space. Convert to the row's
                    // space before the bounds test, or exiting via the small checkbox leaves
                    // the hover tint stuck.
                    java.awt.Point p = SwingUtilities.convertPoint(
                        e.getComponent(), e.getPoint(), WaypointRow.this);
                    if (contains(p)) return;
                    setBackground(ColorScheme.DARKER_GRAY_COLOR);
                }
                @Override public void mouseClicked(MouseEvent e)
                {
                    if (SwingUtilities.isLeftMouseButton(e)) s.onSelectClick.accept(e.isShiftDown());
                }
            };
            addMouseListener(ma);
        }
        else
        {
            ma = Cards.clickable(this, s.onClickBody);
        }

        // Right-click popup (pin / delete) stays available in both modes. Outside select mode it
        // also offers "Select multiple" -- the entry point for bulk selection now that the toolbar
        // toggle button is gone.
        JPopupMenu popup = new JPopupMenu();
        if (!s.selectMode)
        {
            JMenuItem selectItem = new JMenuItem("Select multiple");
            selectItem.addActionListener(e -> s.onEnterSelectMode.run());
            popup.add(selectItem);
            popup.addSeparator();
        }
        JMenuItem pinItem = new JMenuItem(s.isPinned ? "Unpin" : "Pin to top");
        pinItem.addActionListener(e -> s.onTogglePin.run());
        JMenuItem deleteItem = new JMenuItem("Delete");
        deleteItem.addActionListener(e -> s.onDelete.run());
        popup.add(pinItem);
        popup.addSeparator();
        popup.add(deleteItem);
        setComponentPopupMenu(popup);

        // WEST: checkbox in select mode; drag handle otherwise (when draggable).
        if (s.selectMode)
        {
            TriStateBox box = new TriStateBox();
            box.setState(s.selected ? TriStateBox.State.CHECKED : TriStateBox.State.UNCHECKED);
            box.addMouseListener(ma);
            JPanel west = new JPanel(new FlowLayout(FlowLayout.CENTER, 0, 0));
            west.setOpaque(false);
            west.setBorder(BorderFactory.createEmptyBorder(0, 0, 0, 4));
            west.add(box);
            add(west, BorderLayout.WEST);
            dragHandle = null;
        }
        else if (!s.dragDisabled)
        {
            dragHandle = new JLabel("⠿"); // braille pattern dots-123456
            dragHandle.setForeground(new Color(120, 120, 120));
            dragHandle.setOpaque(false);
            dragHandle.setBorder(BorderFactory.createEmptyBorder(4, 4, 4, 6));
            dragHandle.setCursor(Cursor.getPredefinedCursor(Cursor.MOVE_CURSOR));
            dragHandle.getAccessibleContext().setAccessibleName("Reorder waypoint");
            HoverHint.shared().attach(dragHandle, () -> "Drag to reorder");
            add(dragHandle, BorderLayout.WEST);
        }
        else
        {
            dragHandle = null;
        }

        // CENTER: bold name label, optionally prefixed with a 16x16 custom sprite.
        JLabel name = buildNameLabel(s, ma);
        add(name, BorderLayout.CENTER);

        this.restingBackground = getBackground();

        // EAST: Play button, hidden in select mode. Pin / Delete are reached via right-click.
        buildEastControls(s);
    }

    private JLabel buildNameLabel(Spec s, MouseAdapter ma)
    {
        String displayName = (s.isWilderness ? "☠ " : "") + s.waypoint.getName();
        JLabel name = new JLabel(displayName);
        name.setToolTipText(buildHoverTooltip(s.waypoint, s.originCategoryName));
        name.setForeground(s.isWilderness ? new Color(220, 130, 130) : Color.WHITE);
        name.setFont(name.getFont().deriveFont(Font.BOLD));
        name.getAccessibleContext().setAccessibleName(
            accessibleName(s.waypoint.getName(), s.isWilderness, s.isPinned));
        if (s.waypoint.getIconId() != null && s.spriteManager != null)
        {
            name.setIconTextGap(6);
            SpriteIcons.apply(name, s.waypoint.getIconId(), s.spriteManager);
        }
        name.addMouseListener(ma);
        return name;
    }

    private void buildEastControls(Spec s)
    {
        if (s.selectMode) return;
        JButton play = new JButton("▶"); // black right-pointing triangle
        this.playButton = play;
        this.activePathState = s.active;
        PlayButton.style(play, s.active);
        HoverHint.shared().attach(play, () -> activePathState ? "Stop pathing here" : "Path to here");
        play.getAccessibleContext().setAccessibleName(playAccessibleName(s.active));
        play.addActionListener(e -> s.onPlay.run());

        JPanel eastPanel = new JPanel(new FlowLayout(FlowLayout.RIGHT, 0, 0));
        eastPanel.setOpaque(false);
        eastPanel.add(play);
        add(eastPanel, BorderLayout.EAST);
    }

    /** Packed world point this row represents; used by the panel to find the active row. */
    public int getPackedWorldPoint()
    {
        return waypoint.getPackedWorldPoint();
    }

    /**
     * Retint the Play button to reflect whether this row is the active path target, in place.
     * No-op in select mode, where the Play button is hidden. Lets the panel respond to a
     * path-target change without rebuilding the body tree (#67).
     */
    public void setActive(boolean active)
    {
        if (playButton == null) return;
        activePathState = active;
        PlayButton.style(playButton, active);
        playButton.getAccessibleContext().setAccessibleName(playAccessibleName(active));
        playButton.repaint();
    }

    // "Stop pathing to X" while this row is the active target, "Path to X" otherwise, so the
    // screen-reader name tracks the same toggle the glyph and tooltip show.
    private String playAccessibleName(boolean active)
    {
        String n = waypoint.getName();
        if (n == null || n.isEmpty())
        {
            return active ? "Stop pathing to waypoint" : "Path to waypoint";
        }
        return (active ? "Stop pathing to " : "Path to ") + n;
    }

    public JLabel getDragHandle() { return dragHandle; }

    @Override
    public void setDropIndicator(DropIndicatorMode mode)
    {
        switch (mode)
        {
            case NONE:
                if (prevBorder != null) { setBorder(prevBorder); prevBorder = null; }
                setBackground(restingBackground);
                break;
            case TINT:
                setBackground(ColorScheme.DARK_GRAY_HOVER_COLOR);
                break;
            case BORDER_AND_TINT:
                if (prevBorder == null) prevBorder = getBorder();
                setBorder(BorderFactory.createCompoundBorder(
                    BorderFactory.createMatteBorder(2, 0, 0, 0, ColorScheme.BRAND_ORANGE),
                    prevBorder == null ? BorderFactory.createEmptyBorder() : prevBorder));
                setBackground(ColorScheme.DARK_GRAY_HOVER_COLOR);
                break;
        }
        repaint();
    }

    /**
     * Screen-reader name for a row: the waypoint name plus parenthetical state tags so the
     * wilderness skull and pinned glyph -- which are visual-only on the label -- are spoken.
     * Mirrors the Play button, which already names its path target.
     */
    static String accessibleName(String baseName, boolean wilderness, boolean pinned)
    {
        StringBuilder sb = new StringBuilder(baseName == null ? "" : baseName);
        if (wilderness) sb.append(" (in Wilderness)");
        if (pinned) sb.append(" (pinned)");
        return sb.toString();
    }

    /**
     * Hover tooltip: name on its own when notes are empty; with notes, shows the first
     * line of notes below the name (HTML-escaped).
     */
    static String buildHoverTooltip(Waypoint w)
    {
        String name = w.getName() == null ? "" : w.getName();
        String notes = w.getNotes();
        if (notes == null || notes.isEmpty()) return name;
        int nl = notes.indexOf('\n');
        String firstLine = nl < 0 ? notes : notes.substring(0, nl);
        firstLine = firstLine.trim();
        if (firstLine.isEmpty()) return name;
        return "<html>" + Text.escapeHtml(name) + "<br><span style='color:#bbb'>"
            + Text.escapeHtml(firstLine) + "</span></html>";
    }

    /** Extended tooltip with optional origin-category line. Null origin = same as the one-arg form. */
    static String buildHoverTooltip(Waypoint w, String originCategoryName)
    {
        if (originCategoryName == null || originCategoryName.isEmpty())
        {
            return buildHoverTooltip(w);
        }
        String name = w.getName() == null ? "" : w.getName();
        String notes = w.getNotes();
        StringBuilder html = new StringBuilder("<html>").append(Text.escapeHtml(name));
        if (notes != null && !notes.isEmpty())
        {
            int nl = notes.indexOf('\n');
            String firstLine = (nl < 0 ? notes : notes.substring(0, nl)).trim();
            if (!firstLine.isEmpty())
            {
                html.append("<br><span style='color:#bbb'>")
                    .append(Text.escapeHtml(firstLine))
                    .append("</span>");
            }
        }
        html.append("<br><span style='color:#bbb'><i>in ")
            .append(Text.escapeHtml(originCategoryName))
            .append("</i></span></html>");
        return html.toString();
    }

    @Override public Dimension getMaximumSize()
    {
        return Styles.capHeight(this);
    }
}

package com.waypointer.ui;

import com.waypointer.model.Category;
import com.waypointer.model.Waypoint;
import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Cursor;
import java.awt.Dimension;
import java.awt.FlowLayout;
import java.awt.Font;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.util.ArrayList;
import java.util.List;
import javax.swing.BorderFactory;
import javax.swing.Box;
import javax.swing.BoxLayout;
import javax.swing.JLabel;
import javax.swing.JPanel;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;

/**
 * Renders a {@link WaypointPickerModel} as a collapsible, dark-themed checkbox tree, reusing the
 * panel's section idiom instead of a {@code JTree} (which would fight the Metal LAF described in
 * CLAUDE.md). Category rows carry a tri-state box, an expand caret, the name, and a count;
 * waypoint leaves carry an indented box and a name. Toggling any box updates the model and fires
 * {@code onChange} so the host dialog can re-gate its confirm buttons.
 */
final class WaypointTreePicker extends JPanel
{
    private final WaypointPickerModel model;
    private final Runnable onChange;
    private final List<CategoryView> categoryViews = new ArrayList<>();

    WaypointTreePicker(WaypointPickerModel model, Runnable onChange)
    {
        this.model = model;
        this.onChange = onChange == null ? () -> {} : onChange;
        setLayout(new BoxLayout(this, BoxLayout.Y_AXIS));
        setBackground(ColorScheme.DARK_GRAY_COLOR);

        for (Category c : model.getOrderedCategories())
        {
            CategoryView cv = new CategoryView(c);
            categoryViews.add(cv);
            add(cv);
        }
        add(Box.createVerticalGlue());
    }

    /** Re-reads every box from the model. Called by the host dialog after Select all / none. */
    void refreshAll()
    {
        for (CategoryView cv : categoryViews) cv.refresh();
    }

    private void fireChanged()
    {
        onChange.run();
    }

    private final class CategoryView extends JPanel
    {
        private final Category category;
        private final TriStateBox headerBox = new TriStateBox();
        private final JPanel body = new JPanel();
        private final List<LeafView> leaves = new ArrayList<>();
        private final JLabel caret = new JLabel("▶"); // black right-pointing triangle
        private boolean collapsed = true;

        CategoryView(Category category)
        {
            this.category = category;
            setLayout(new BorderLayout());
            setBackground(ColorScheme.DARK_GRAY_COLOR);
            setAlignmentX(LEFT_ALIGNMENT);

            JPanel header = new JPanel(new FlowLayout(FlowLayout.LEFT, 4, 2));
            header.setBackground(ColorScheme.DARKER_GRAY_COLOR);
            header.setAlignmentX(LEFT_ALIGNMENT);

            headerBox.addMouseListener(new MouseAdapter() {
                @Override public void mouseClicked(MouseEvent e)
                {
                    boolean check = model.categoryState(category.getId())
                        != WaypointPickerModel.Tri.CHECKED;
                    model.setCategoryChecked(category.getId(), check);
                    refresh();
                    fireChanged();
                }
            });

            caret.setForeground(Color.LIGHT_GRAY);
            caret.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
            MouseAdapter toggle = new MouseAdapter() {
                @Override public void mouseClicked(MouseEvent e) { toggleCollapsed(); }
            };
            caret.addMouseListener(toggle);

            JLabel name = new JLabel(category.getName());
            name.setForeground(Color.WHITE);
            name.setFont(name.getFont().deriveFont(Font.BOLD));
            name.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
            name.addMouseListener(toggle);

            JLabel count = new JLabel("(" + model.waypointsOf(category.getId()).size() + ")");
            count.setForeground(Color.LIGHT_GRAY);
            count.setFont(FontManager.getRunescapeSmallFont());

            header.add(headerBox);
            header.add(caret);
            header.add(name);
            header.add(count);
            add(header, BorderLayout.NORTH);

            body.setLayout(new BoxLayout(body, BoxLayout.Y_AXIS));
            body.setBackground(ColorScheme.DARK_GRAY_COLOR);
            body.setAlignmentX(LEFT_ALIGNMENT);
            for (Waypoint w : model.waypointsOf(category.getId()))
            {
                LeafView lv = new LeafView(w, this);
                leaves.add(lv);
                body.add(lv);
            }
            body.setVisible(false);
            add(body, BorderLayout.CENTER);

            refresh();
        }

        private void toggleCollapsed()
        {
            collapsed = !collapsed;
            caret.setText(collapsed ? "▶" : "▼"); // right / down triangle
            body.setVisible(!collapsed);
            revalidate();
            repaint();
        }

        void refresh()
        {
            switch (model.categoryState(category.getId()))
            {
                case CHECKED:  headerBox.setState(TriStateBox.State.CHECKED); break;
                case PARTIAL:  headerBox.setState(TriStateBox.State.PARTIAL); break;
                default:       headerBox.setState(TriStateBox.State.UNCHECKED); break;
            }
            for (LeafView lv : leaves) lv.refresh();
        }

        @Override public Dimension getMaximumSize()
        {
            return Styles.capHeight(this);
        }
    }

    private final class LeafView extends JPanel
    {
        private final Waypoint waypoint;
        private final TriStateBox box = new TriStateBox();
        private final CategoryView owner;

        LeafView(Waypoint waypoint, CategoryView owner)
        {
            this.waypoint = waypoint;
            this.owner = owner;
            setLayout(new FlowLayout(FlowLayout.LEFT, 4, 1));
            setBackground(ColorScheme.DARK_GRAY_COLOR);
            setAlignmentX(LEFT_ALIGNMENT);
            setBorder(BorderFactory.createEmptyBorder(0, 18, 0, 0));
            setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));

            MouseAdapter toggle = new MouseAdapter() {
                @Override public void mouseClicked(MouseEvent e) { toggleChecked(); }
            };
            box.addMouseListener(toggle);
            addMouseListener(toggle);

            JLabel name = new JLabel(waypoint.getName());
            name.setForeground(Color.WHITE);
            name.addMouseListener(toggle);
            add(box);
            add(name);
        }

        private void toggleChecked()
        {
            model.setWaypointChecked(waypoint.getId(), !model.isWaypointChecked(waypoint.getId()));
            owner.refresh();
            fireChanged();
        }

        void refresh()
        {
            box.setState(model.isWaypointChecked(waypoint.getId())
                ? TriStateBox.State.CHECKED : TriStateBox.State.UNCHECKED);
        }

        @Override public Dimension getMaximumSize()
        {
            return Styles.capHeight(this);
        }
    }

}

package com.waypointer.ui;

import java.util.HashSet;
import java.util.Iterator;
import java.util.LinkedHashSet;
import java.util.Set;
import java.util.UUID;

/**
 * Per-drag state for sections auto-expanded by the spring-loaded hover logic.
 * Pure data: no Swing, no timers. The owning {@link DragAndDropHandler} drives
 * timing; this class decides which sections to revert vs confirm on each
 * drag event.
 */
final class AutoExpandController
{
    private final Set<UUID> autoExpanded = new LinkedHashSet<>();

    void recordTransientExpand(UUID id)
    {
        autoExpanded.add(id);
    }

    boolean isTransientlyExpanded(UUID id)
    {
        return autoExpanded.contains(id);
    }

    Set<UUID> onHover(UUID targetCategoryId)
    {
        Set<UUID> reverted = new HashSet<>();
        Iterator<UUID> it = autoExpanded.iterator();
        while (it.hasNext())
        {
            UUID id = it.next();
            if (!id.equals(targetCategoryId))
            {
                reverted.add(id);
                it.remove();
            }
        }
        return reverted;
    }

    DropResolution onDropAt(UUID destCategoryId)
    {
        UUID toConfirm = autoExpanded.contains(destCategoryId) ? destCategoryId : null;
        Set<UUID> toRevert = new HashSet<>(autoExpanded);
        if (toConfirm != null)
        {
            toRevert.remove(toConfirm);
        }
        autoExpanded.clear();
        return new DropResolution(toConfirm, toRevert);
    }

    Set<UUID> onDragEnd()
    {
        Set<UUID> reverted = new HashSet<>(autoExpanded);
        autoExpanded.clear();
        return reverted;
    }

    @lombok.Value
    static class DropResolution
    {
        UUID toConfirm;
        Set<UUID> toRevert;
    }
}

package com.waypointer.ui;

import com.waypointer.model.Category;
import com.waypointer.model.Waypoint;
import com.waypointer.model.WorldPointPacker;
import com.waypointer.service.IconCatalog;
import com.waypointer.service.WaypointCapture;
import com.waypointer.service.WaypointStore;
import java.awt.Color;
import java.awt.Cursor;
import java.awt.Dimension;
import java.awt.FlowLayout;
import java.awt.GridBagConstraints;
import java.awt.GridBagLayout;
import java.awt.Insets;
import java.awt.Window;
import java.awt.event.FocusAdapter;
import java.awt.event.FocusEvent;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.util.UUID;
import javax.swing.BorderFactory;
import javax.swing.JComboBox;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.JScrollPane;
import javax.swing.JTextArea;
import javax.swing.JTextField;
import javax.swing.SwingUtilities;
import net.runelite.client.game.SpriteManager;
import net.runelite.client.ui.ColorScheme;

// Form shown when a WaypointRow is expanded. Name and notes edits are deferred: the user
// types into local Swing fields, and on focus loss (or panel removal) the pending text is
// committed. This avoids the keystroke -> store-update -> panel-rebuild -> field-recreated
// -> cursor-lost loop the older synchronous variant had.
public class InlineEditPanel extends JPanel
{
    private final WaypointStore store;
    private final UUID waypointId;
    private final Toasts toasts;

    private final JTextField nameField;
    private final JTextArea notesArea;
    private final JComboBox<CategoryComboItem> categoryCombo;
    private boolean nameDirty = false;
    private boolean notesDirty = false;
    private boolean categoryDirty = false;

    public InlineEditPanel(Waypoint w, WaypointStore store, WaypointCapture capture,
        SpriteManager spriteManager, IconCatalog iconCatalog, Toasts toasts,
        Runnable onClose, Runnable onShowOnMap)
    {
        this.store = store;
        this.waypointId = w.getId();
        this.toasts = toasts;
        setLayout(new GridBagLayout());
        setBorder(BorderFactory.createEmptyBorder(4, 24, 4, 4));
        setBackground(ColorScheme.DARKER_GRAY_COLOR);
        GridBagConstraints g = new GridBagConstraints();
        g.fill = GridBagConstraints.HORIZONTAL;
        g.insets = new Insets(2, 2, 2, 2);

        // Top-right close affordance. Spans both columns so the X anchors to the panel edge.
        if (onClose != null)
        {
            g.gridx = 0; g.gridy = 0; g.gridwidth = 2; g.weightx = 1;
            g.anchor = GridBagConstraints.EAST; g.fill = GridBagConstraints.NONE;
            JLabel closeBtn = new JLabel("✕"); // U+2715 multiplication X
            closeBtn.setForeground(Color.LIGHT_GRAY);
            closeBtn.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
            closeBtn.setToolTipText("Close");
            closeBtn.getAccessibleContext().setAccessibleName("Close editor");
            closeBtn.addMouseListener(new MouseAdapter()
            {
                @Override public void mouseClicked(MouseEvent e)
                {
                    flushPending();
                    onClose.run();
                }
            });
            add(closeBtn, g);
            g.gridwidth = 1; g.anchor = GridBagConstraints.CENTER; g.fill = GridBagConstraints.HORIZONTAL;
        }

        g.gridx = 0; g.gridy = 1; g.weightx = 0;
        add(Styles.fieldLabel("Name"), g);
        nameField = new JTextField(w.getName());
        Styles.textField(nameField);
        nameField.getDocument().addDocumentListener(Styles.documentListener(() -> nameDirty = true));
        nameField.addFocusListener(new FocusAdapter()
        {
            @Override public void focusLost(FocusEvent e) { flushName(); }
        });
        g.gridx = 1; g.weightx = 1; add(nameField, g);

        g.gridx = 0; g.gridy++; g.weightx = 0; add(Styles.fieldLabel("Category"), g);
        categoryCombo = new JComboBox<>();
        Styles.combo(categoryCombo);
        for (Category c : store.getCategoriesOrdered()) categoryCombo.addItem(new CategoryComboItem(c));
        for (int i = 0; i < categoryCombo.getItemCount(); i++)
            if (categoryCombo.getItemAt(i).id().equals(w.getCategoryId())) categoryCombo.setSelectedIndex(i);
        // Deferred commit: track changes here, apply on focus loss / detach. An immediate
        // moveWaypointToCategory on every action would fire for any stray click or scroll-wheel
        // tick over the combo, with no way to undo without manually moving the row back.
        categoryCombo.addActionListener(e -> categoryDirty = true);
        categoryCombo.addFocusListener(new FocusAdapter()
        {
            @Override public void focusLost(FocusEvent e) { flushCategory(); }
        });
        g.gridx = 1; g.weightx = 1; add(categoryCombo, g);

        g.gridx = 0; g.gridy++; g.weightx = 0; add(Styles.fieldLabel("Notes"), g);
        notesArea = new JTextArea(w.getNotes(), 3, 12);
        notesArea.setLineWrap(true);
        notesArea.setWrapStyleWord(true);
        Styles.textArea(notesArea);
        notesArea.getDocument().addDocumentListener(Styles.documentListener(() -> notesDirty = true));
        notesArea.addFocusListener(new FocusAdapter()
        {
            @Override public void focusLost(FocusEvent e) { flushNotes(); }
        });
        JScrollPane notesScroll = new JScrollPane(notesArea);
        notesScroll.setBorder(null);
        notesScroll.getViewport().setBackground(ColorScheme.DARK_GRAY_COLOR);
        // Pin the notes pane to ~3 visible rows. The JTextArea(rows=3) hint flows up through
        // getPreferredScrollableViewportSize, but inside the outer body's JScrollPane it ends
        // up collapsing to a single visible row; setting an explicit preferred + minimum
        // height keeps the field at its intended size regardless of the surrounding chain.
        int rowH = notesArea.getFontMetrics(notesArea.getFont()).getHeight();
        Dimension notesPref = new Dimension(0, rowH * 3 + 6);
        notesScroll.setPreferredSize(notesPref);
        notesScroll.setMinimumSize(notesPref);
        g.gridx = 1; g.weightx = 1; add(notesScroll, g);

        g.gridx = 0; g.gridy++; g.weightx = 0; add(Styles.fieldLabel("Tile"), g);
        JLabel showOnMap = Styles.link("Show on world map", ColorScheme.BRAND_ORANGE,
            onShowOnMap == null ? () -> {} : onShowOnMap);
        g.gridx = 1; g.weightx = 1; add(showOnMap, g);

        // Footer: thin divider followed by a single FlowLayout row of links separated by ·
        g.gridx = 0; g.gridy++; g.gridwidth = 2; g.weightx = 1;
        add(makeDivider(), g);

        g.gridx = 0; g.gridy++; g.gridwidth = 2; g.weightx = 1;
        JPanel footer = new JPanel(new FlowLayout(FlowLayout.LEFT, 12, 0));
        footer.setOpaque(false);
        JLabel recapture = Styles.link("Recapture", ColorScheme.BRAND_ORANGE, () -> {
            // Flush any in-flight name/notes edits before swapping the tile under us.
            flushPending();
            capture.readCurrentLocation(packed -> {
                if (packed == WorldPointPacker.UNDEFINED) return;
                Waypoint cur = store.getWaypointById(waypointId);
                if (cur == null) return;
                String name = cur.getName();
                store.updateWaypointPoint(waypointId, packed);
                toasts.show("Recaptured '" + name + "'", "Undo", store::undoLast);
            });
        });
        JLabel setIcon = Styles.link("Set icon", ColorScheme.BRAND_ORANGE, () -> {
            Waypoint cur = store.getWaypointById(waypointId);
            if (cur == null) return;
            Window owner = SwingUtilities.getWindowAncestor(this);
            new IconPickerDialog(owner, spriteManager, iconCatalog, cur.getIconId(), iconId -> {
                store.updateWaypointIcon(waypointId, iconId);
            }).setVisible(true);
        });
        footer.add(recapture);
        footer.add(makeSeparator());
        footer.add(setIcon);
        footer.add(makeSeparator());
        JLabel delete = Styles.link("Delete", Styles.DELETE_RED, () -> {
            flushPending();
            WaypointerPanel.softDeleteWithUndo(store, store.getWaypointById(waypointId), toasts);
        });
        footer.add(delete);
        add(footer, g);
    }

    // Commits in-flight edits. Called on focus loss, on detach, and before recapture so the
    // swap doesn't drop the user's pending text.
    public void flushPending()
    {
        flushName();
        flushNotes();
        flushCategory();
    }

    private void flushName()
    {
        if (!nameDirty) return;
        nameDirty = false;
        store.renameWaypoint(waypointId, nameField.getText());
    }

    private void flushNotes()
    {
        if (!notesDirty) return;
        notesDirty = false;
        store.updateWaypointNotes(waypointId, notesArea.getText());
    }

    private void flushCategory()
    {
        if (!categoryDirty) return;
        categoryDirty = false;
        CategoryComboItem sel = (CategoryComboItem) categoryCombo.getSelectedItem();
        if (sel == null) return;
        Waypoint cur = store.getWaypointById(waypointId);
        if (cur == null || sel.id().equals(cur.getCategoryId())) return;
        store.moveWaypointToCategory(waypointId, sel.id());
    }

    // Safety net for parent rebuilds that fire before focus loss.
    @Override
    public void removeNotify()
    {
        flushPending();
        super.removeNotify();
    }

    // Cap vertical extent at preferred height so BoxLayout(Y_AXIS) in the parent stacks tight
    // instead of stretching us into leftover space.
    @Override
    public Dimension getMaximumSize()
    {
        return Styles.capHeight(this);
    }

    private static JPanel makeDivider()
    {
        JPanel d = new JPanel();
        d.setBackground(ColorScheme.LIGHT_GRAY_COLOR);
        Dimension dim = new Dimension(0, 1);
        d.setPreferredSize(dim);
        d.setMinimumSize(dim);
        d.setMaximumSize(new Dimension(Integer.MAX_VALUE, 1));
        return d;
    }

    private static JLabel makeSeparator()
    {
        JLabel sep = new JLabel("·"); // middle dot
        sep.setForeground(Color.LIGHT_GRAY);
        return sep;
    }

}

package com.waypointer.ui;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import javax.swing.BorderFactory;
import javax.swing.JButton;
import net.runelite.client.ui.ColorScheme;

/** Per-row Play button styling: dark at rest, brand-orange on hover, locked orange when active. */
final class PlayButton
{
    private PlayButton() {}

    private static final String CLIENT_PROP_ACTIVE = "waypointer.playActive";
    private static final String CLIENT_PROP_HOVER_ATTACHED = "waypointer.playHoverAttached";

    // Active flag is mirrored to a client property so the hover adapter can check it without
    // closure capture.
    static void style(JButton b, boolean active)
    {
        b.putClientProperty(CLIENT_PROP_ACTIVE, active);

        // Active row shows a stop square; resting shows the play triangle. Driven here so the
        // glyph follows every retint -- including when another row is played or the path
        // auto-clears on arrival.
        b.setText(active ? "■" : "▶");

        // U+25A0 is metrically smaller than the triangle at a given size, so the stop square gets
        // a larger point size to match the play arrow's visual weight.
        b.setFont(b.getFont().deriveFont(Font.BOLD, active ? 20f : 14f));
        Dimension size = new Dimension(36, 32);
        b.setPreferredSize(size);
        b.setMinimumSize(size);
        b.setFocusPainted(false);
        b.setOpaque(true);
        b.setBorderPainted(true);

        applyResting(b, active);

        // Attach the hover adapter once. Re-invocations on the same button would
        // otherwise stack listeners.
        if (b.getClientProperty(CLIENT_PROP_HOVER_ATTACHED) == null)
        {
            b.addMouseListener(new MouseAdapter()
            {
                @Override public void mouseEntered(MouseEvent e)
                {
                    if (Boolean.TRUE.equals(b.getClientProperty(CLIENT_PROP_ACTIVE))) return;
                    applyHover(b);
                }
                @Override public void mouseExited(MouseEvent e)
                {
                    if (Boolean.TRUE.equals(b.getClientProperty(CLIENT_PROP_ACTIVE))) return;
                    applyResting(b, false);
                }
            });
            b.putClientProperty(CLIENT_PROP_HOVER_ATTACHED, Boolean.TRUE);
        }
    }

    private static void applyResting(JButton b, boolean active)
    {
        if (active)
        {
            b.setBackground(ColorScheme.BRAND_ORANGE);
            b.setForeground(Color.BLACK);
            b.setBorder(BorderFactory.createCompoundBorder(
                BorderFactory.createLineBorder(ColorScheme.BRAND_ORANGE.darker(), 1),
                BorderFactory.createEmptyBorder(4, 8, 4, 8)));
        }
        else
        {
            b.setBackground(ColorScheme.DARKER_GRAY_COLOR);
            b.setForeground(ColorScheme.BRAND_ORANGE);
            b.setBorder(BorderFactory.createCompoundBorder(
                BorderFactory.createLineBorder(ColorScheme.DARK_GRAY_COLOR.darker(), 1),
                BorderFactory.createEmptyBorder(4, 8, 4, 8)));
        }
    }

    private static void applyHover(JButton b)
    {
        b.setBackground(ColorScheme.BRAND_ORANGE);
        b.setForeground(Color.BLACK);
        b.setBorder(BorderFactory.createCompoundBorder(
            BorderFactory.createLineBorder(ColorScheme.BRAND_ORANGE.darker(), 1),
            BorderFactory.createEmptyBorder(4, 8, 4, 8)));
    }
}

package com.waypointer.ui;

import java.awt.Color;
import java.awt.Cursor;
import java.awt.Font;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.util.UUID;
import java.util.function.Consumer;
import java.util.function.Supplier;
import javax.swing.BorderFactory;
import javax.swing.JLabel;
import javax.swing.SwingConstants;
import javax.swing.SwingUtilities;
import net.runelite.client.ui.ColorScheme;

/**
 * In-place toggle for adding / removing a preset waypoint. Flips state on click without
 * rebuilding the surrounding panel. Holds the UUID of the added waypoint while in REMOVE
 * state so the remove callback can target it directly.
 */
final class AddRemoveToggle extends JLabel
{
    private static final String ADD_GLYPH = "+";
    private static final String REMOVE_GLYPH = "−"; // U+2212 minus sign

    private final Supplier<UUID> onAdd;
    private final Consumer<UUID> onRemove;

    private UUID currentId;

    AddRemoveToggle(UUID initialId, Supplier<UUID> onAdd, Consumer<UUID> onRemove)
    {
        this.onAdd = onAdd;
        this.onRemove = onRemove;
        this.currentId = initialId;

        setOpaque(true);
        setBackground(ColorScheme.DARKER_GRAY_COLOR);
        setFont(getFont().deriveFont(Font.BOLD, 14f));
        setHorizontalAlignment(SwingConstants.CENTER);
        setBorder(BorderFactory.createCompoundBorder(
            BorderFactory.createLineBorder(ColorScheme.DARK_GRAY_COLOR.darker(), 1),
            BorderFactory.createEmptyBorder(4, 7, 4, 7)));
        setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
        applyState(false);
        HoverHint.shared().attach(this, () -> currentId == null ? "Add waypoint" : "Remove waypoint");

        addMouseListener(new MouseAdapter()
        {
            @Override
            public void mouseClicked(MouseEvent e)
            {
                if (!SwingUtilities.isLeftMouseButton(e)) return;
                if (currentId == null)
                {
                    currentId = onAdd.get();
                }
                else
                {
                    onRemove.accept(currentId);
                    currentId = null;
                }
                applyState(true);
            }

            @Override
            public void mouseEntered(MouseEvent e)
            {
                applyState(true);
            }

            @Override
            public void mouseExited(MouseEvent e)
            {
                applyState(false);
            }
        });
    }

    private void applyState(boolean hovering)
    {
        Color base;
        if (currentId == null)
        {
            setText(ADD_GLYPH);
            getAccessibleContext().setAccessibleName("Add to library");
            base = ColorScheme.PROGRESS_COMPLETE_COLOR;
        }
        else
        {
            setText(REMOVE_GLYPH);
            getAccessibleContext().setAccessibleName("Remove from library");
            base = ColorScheme.PROGRESS_ERROR_COLOR;
        }
        setForeground(hovering ? base.brighter() : base);
    }
}

package com.waypointer.ui;

import java.awt.BorderLayout;
import java.awt.Window;
import java.awt.event.ActionEvent;
import java.awt.event.KeyEvent;
import javax.swing.AbstractAction;
import javax.swing.BorderFactory;
import javax.swing.JComponent;
import javax.swing.JDialog;
import javax.swing.JPanel;
import javax.swing.KeyStroke;
import javax.swing.WindowConstants;
import net.runelite.client.ui.ColorScheme;

/**
 * Shared scaffolding for the plugin's modal dialogs: a dark content pane with the standard
 * border and gap, ESC-to-close, and pack/center. Keeps each dialog from re-deriving the same
 * dark-panel setup by hand.
 */
final class Dialogs
{
    private Dialogs()
    {
    }

    /** Dark content pane with the standard 8px gap and border. See the gap overload for exceptions. */
    static JPanel applyDarkContentPane(JDialog d)
    {
        return applyDarkContentPane(d, 8, 8);
    }

    /** Gap overload for dialogs that need tighter inner spacing than the 8px default. */
    static JPanel applyDarkContentPane(JDialog d, int hgap, int vgap)
    {
        d.setDefaultCloseOperation(WindowConstants.DISPOSE_ON_CLOSE);
        JPanel content = (JPanel) d.getContentPane();
        content.setLayout(new BorderLayout(hgap, vgap));
        content.setBorder(BorderFactory.createEmptyBorder(8, 8, 8, 8));
        content.setBackground(ColorScheme.DARK_GRAY_COLOR);
        return content;
    }

    /** Closes the dialog when ESC is pressed anywhere within it. */
    static void bindEscape(JDialog d)
    {
        JComponent root = d.getRootPane();
        root.getInputMap(JComponent.WHEN_IN_FOCUSED_WINDOW)
            .put(KeyStroke.getKeyStroke(KeyEvent.VK_ESCAPE, 0), "waypointer.dialog.close");
        root.getActionMap().put("waypointer.dialog.close", new AbstractAction()
        {
            @Override
            public void actionPerformed(ActionEvent e)
            {
                d.dispose();
            }
        });
    }

    /** Sizes the dialog to its contents and centers it over the owner. */
    static void finish(JDialog d, Window owner)
    {
        d.pack();
        d.setLocationRelativeTo(owner);
    }
}

package com.waypointer.ui;

import com.waypointer.model.Category;
import com.waypointer.model.Waypoint;
import com.waypointer.model.WorldPointPacker;
import com.waypointer.service.Wilderness;
import java.awt.BorderLayout;
import java.awt.Component;
import java.util.List;
import java.util.function.BiConsumer;
import java.util.function.Consumer;
import java.util.function.Function;
import javax.swing.BorderFactory;
import javax.swing.JPanel;
import net.runelite.client.game.SpriteManager;

/**
 * Synthetic top-of-panel section listing pinned waypoints. Reuses {@link WaypointRow} for
 * the rows. Differences from {@link CategorySection}: no drag source, no category-icon
 * slot, no popup menu on the header, no empty placeholder (caller skips rendering
 * when the list is empty). Rows are constructed with the drag handle disabled.
 */
public class PinnedSection extends CollapsibleSection
{
    public PinnedSection(
        List<Waypoint> pinned,
        int activePathTarget,
        boolean collapsed,
        Consumer<Boolean> onCollapseChange,
        BiConsumer<Waypoint, CategorySection.RowAction> onRowAction,
        Function<Waypoint, Component> inlineProvider,
        SpriteManager spriteManager,
        Function<Waypoint, Category> categoryLookup)
    {
        super(collapsed, onCollapseChange);
        setBorder(BorderFactory.createEmptyBorder(4, 0, 4, 0));

        JPanel headerRow = buildHeaderRow(pinned.size());
        add(headerRow, BorderLayout.NORTH);

        for (Waypoint w : pinned)
        {
            boolean active = activePathTarget != WorldPointPacker.UNDEFINED
                && w.getPackedWorldPoint() == activePathTarget;
            Category origin = categoryLookup.apply(w);
            String originName = origin == null ? null : origin.getName();
            WaypointRow row = WaypointRow.spec(w)
                .active(active)
                .pinned(true)
                .wilderness(Wilderness.isInWilderness(w.getPackedWorldPoint()))
                .dragDisabled(true)
                .onPlay(() -> onRowAction.accept(w, CategorySection.RowAction.PLAY))
                .onClickBody(() -> onRowAction.accept(w, CategorySection.RowAction.EXPAND))
                .onTogglePin(() -> onRowAction.accept(w, CategorySection.RowAction.TOGGLE_PIN))
                .onDelete(() -> onRowAction.accept(w, CategorySection.RowAction.DELETE))
                .onEnterSelectMode(() -> onRowAction.accept(w, CategorySection.RowAction.ENTER_SELECT))
                .spriteManager(spriteManager)
                .originCategoryName(originName)
                .build();
            addRow(row, w, inlineProvider);
        }

        attachBody();
    }

    @Override
    protected String headerText()
    {
        return (collapsed ? "▶" : "▼") + " Pinned";
    }
}

package com.waypointer.ui;

import com.google.gson.Gson;
import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import com.google.gson.JsonSyntaxException;
import com.waypointer.service.LandmarkType;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.EnumSet;
import java.util.List;
import java.util.Set;

/**
 * Ordered selection of landmark types for the in-panel landmark bar. Immutable; mutators
 * return new instances. {@link #order()} is the full 11-type picker-list order; the bar
 * shows the types for which {@link #isSelected(LandmarkType)} returns true, in {@link #order()} sequence.
 */
public final class LandmarkSelection
{
    /** Default selected set: BANK, ALTAR, SPIRIT_TREE, FAIRY_RING. */
    static final List<LandmarkType> DEFAULTS = Collections.unmodifiableList(Arrays.asList(
        LandmarkType.BANK,
        LandmarkType.ALTAR,
        LandmarkType.SPIRIT_TREE,
        LandmarkType.FAIRY_RING));

    private final List<LandmarkType> order;
    private final Set<LandmarkType> selected;

    private LandmarkSelection(List<LandmarkType> order, EnumSet<LandmarkType> selected)
    {
        this.order = Collections.unmodifiableList(new ArrayList<>(order));
        EnumSet<LandmarkType> copy = EnumSet.noneOf(LandmarkType.class);
        copy.addAll(selected);
        this.selected = Collections.unmodifiableSet(copy);
    }

    public static LandmarkSelection canonicalDefault()
    {
        List<LandmarkType> order = new ArrayList<>(DEFAULTS);
        for (LandmarkType t : LandmarkType.values())
        {
            if (!order.contains(t)) order.add(t);
        }
        EnumSet<LandmarkType> selected = EnumSet.copyOf(DEFAULTS);
        return new LandmarkSelection(order, selected);
    }

    public List<LandmarkType> order() { return order; }

    public boolean isSelected(LandmarkType t) { return selected.contains(t); }

    public static LandmarkSelection parse(String json, Gson gson)
    {
        if (json == null || json.isEmpty()) return canonicalDefault();

        JsonObject root;
        try
        {
            root = gson.fromJson(json, JsonObject.class);
        }
        catch (JsonSyntaxException e)
        {
            return canonicalDefault();
        }
        if (root == null) return canonicalDefault();

        List<LandmarkType> order = new ArrayList<>();
        if (root.has("order") && root.get("order").isJsonArray())
        {
            for (JsonElement el : root.getAsJsonArray("order"))
            {
                if (!el.isJsonPrimitive()) continue;
                LandmarkType t = parseTypeOrNull(el.getAsString());
                if (t != null && !order.contains(t)) order.add(t);
            }
        }
        for (LandmarkType t : LandmarkType.values())
        {
            if (!order.contains(t)) order.add(t);
        }

        EnumSet<LandmarkType> selected = EnumSet.noneOf(LandmarkType.class);
        if (root.has("selected") && root.get("selected").isJsonArray())
        {
            for (JsonElement el : root.getAsJsonArray("selected"))
            {
                if (!el.isJsonPrimitive()) continue;
                LandmarkType t = parseTypeOrNull(el.getAsString());
                if (t != null) selected.add(t);
            }
        }

        return new LandmarkSelection(order, selected);
    }

    public String toJson(Gson gson)
    {
        JsonObject root = new JsonObject();
        JsonArray orderArr = new JsonArray();
        for (LandmarkType t : order) orderArr.add(t.name());
        JsonArray selectedArr = new JsonArray();
        for (LandmarkType t : order) // iterate order so selected output is bar-order
        {
            if (selected.contains(t)) selectedArr.add(t.name());
        }
        root.add("order", orderArr);
        root.add("selected", selectedArr);
        return gson.toJson(root);
    }

    public List<LandmarkType> selectedInBarOrder()
    {
        List<LandmarkType> out = new ArrayList<>();
        for (LandmarkType t : order) if (selected.contains(t)) out.add(t);
        return out;
    }

    public LandmarkSelection withSelected(LandmarkType t, boolean include)
    {
        EnumSet<LandmarkType> next = EnumSet.noneOf(LandmarkType.class);
        next.addAll(selected);
        if (include) next.add(t); else next.remove(t);
        return new LandmarkSelection(order, next);
    }

    public LandmarkSelection withOrderMove(int fromIndex, int toIndex)
    {
        if (fromIndex < 0 || fromIndex >= order.size()) return this;
        if (toIndex < 0 || toIndex >= order.size()) return this;
        if (fromIndex == toIndex) return this;
        List<LandmarkType> next = new ArrayList<>(order);
        LandmarkType moved = next.remove(fromIndex);
        next.add(toIndex, moved);
        EnumSet<LandmarkType> sel = EnumSet.noneOf(LandmarkType.class);
        sel.addAll(selected);
        return new LandmarkSelection(next, sel);
    }

    private static LandmarkType parseTypeOrNull(String name)
    {
        try { return LandmarkType.valueOf(name); }
        catch (IllegalArgumentException e) { return null; }
    }
}

package com.waypointer.ui;

import java.awt.Cursor;
import java.awt.FontMetrics;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.Insets;
import java.awt.Rectangle;
import java.awt.RenderingHints;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.awt.event.MouseMotionAdapter;
import javax.swing.SwingUtilities;
import net.runelite.client.ui.ColorScheme;

/**
 * Search-style text field that paints a small clear glyph inside its right inset and
 * clears its contents when the glyph is clicked. The glyph appears only while the
 * field has text. Callers reserve room for it via the border's right inset; the paint
 * position and hit zone both derive from {@link #getInsets()} so any border tweak
 * keeps glyph + click in sync.
 */
class ClearableTextField extends PlaceholderTextField
{
    private static final String CLEAR_GLYPH = "✕"; // U+2715 multiplication X
    // How wide a slice of the right inset the click hit zone occupies. Sized generously
    // so the glyph remains comfortably clickable at default font metrics.
    private static final int HIT_BAND_PX = 16;

    private static final Cursor TEXT_CURSOR = Cursor.getPredefinedCursor(Cursor.TEXT_CURSOR);
    private static final Cursor HAND_CURSOR = Cursor.getPredefinedCursor(Cursor.HAND_CURSOR);

    ClearableTextField(String placeholder)
    {
        super(placeholder);

        addMouseMotionListener(new MouseMotionAdapter()
        {
            @Override public void mouseMoved(MouseEvent e)
            {
                setCursor(isOverClearGlyph(e) ? HAND_CURSOR : TEXT_CURSOR);
            }
        });
        addMouseListener(new MouseAdapter()
        {
            @Override public void mousePressed(MouseEvent e)
            {
                if (!SwingUtilities.isLeftMouseButton(e)) return;
                if (!isOverClearGlyph(e)) return;
                setText("");
                e.consume();
            }
        });
    }

    private boolean isOverClearGlyph(MouseEvent e)
    {
        if (getText().isEmpty()) return false;
        Rectangle hit = clearGlyphHitBox();
        return hit != null && hit.contains(e.getPoint());
    }

    // Hit zone occupies a HIT_BAND_PX-wide stripe at the right edge, just inside the border.
    private Rectangle clearGlyphHitBox()
    {
        Insets in = getInsets();
        int w = getWidth();
        int h = getHeight();
        int left = Math.max(in.left, w - in.right - HIT_BAND_PX);
        return new Rectangle(left, in.top, w - in.right - left, h - in.top - in.bottom);
    }

    @Override
    protected void paintComponent(Graphics g)
    {
        super.paintComponent(g);
        if (getText().isEmpty()) return;

        Graphics2D g2 = (Graphics2D) g.create();
        try
        {
            g2.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING,
                RenderingHints.VALUE_TEXT_ANTIALIAS_ON);
            g2.setFont(getFont());
            FontMetrics fm = g2.getFontMetrics();
            int glyphW = fm.stringWidth(CLEAR_GLYPH);
            Insets in = getInsets();
            // Centre the glyph horizontally within the band, vertically on the baseline.
            int bandCenterX = getWidth() - in.right - HIT_BAND_PX / 2;
            int x = bandCenterX - glyphW / 2;
            int y = (getHeight() + fm.getAscent() - fm.getDescent()) / 2;
            g2.setColor(ColorScheme.LIGHT_GRAY_COLOR);
            g2.drawString(CLEAR_GLYPH, x, y);
        }
        finally
        {
            g2.dispose();
        }
    }
}

package com.waypointer.ui;

/**
 * Surface used by callers that want to display a transient confirmation message.
 * Decouples those callers from the JLayeredPane-based ToastOverlay implementation
 * and lets tests substitute a capturing fake.
 */
public interface Toasts
{
    /**
     * Visual treatment for a toast: drives the message colour and the leading glyph
     * the {@link ToastOverlay} prepends. Callers that don't care about styling can
     * use the non-severity overloads, which default to {@link #SUCCESS}.
     */
    enum Severity { SUCCESS, WARN, ERROR }

    /** Show a self-dismissing message with the default short duration. */
    void show(String text);

    /**
     * Show a message with a clickable action label (e.g. "Undo"). The message
     * stays on screen longer so the user has time to click. Clicking the label
     * runs onClick and hides the toast immediately.
     */
    void show(String text, String actionLabel, Runnable onClick);

    /** Severity-flavoured variant. Default routes to {@link #show(String)} so legacy implementations still compile. */
    default void show(String text, Severity severity) { show(text); }

    /** Severity-flavoured variant with an action label. */
    default void show(String text, String actionLabel, Runnable onClick, Severity severity)
    {
        show(text, actionLabel, onClick);
    }

    /** Drop-in target for components that don't have a real overlay wired yet. */
    Toasts NO_OP = new Toasts()
    {
        @Override public void show(String text) {}
        @Override public void show(String text, String actionLabel, Runnable onClick) {}
    };
}

package com.waypointer.ui;

import java.awt.BorderLayout;
import java.awt.Component;
import java.awt.Dimension;
import javax.swing.BorderFactory;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.SwingConstants;
import net.runelite.client.ui.ColorScheme;

/**
 * Footer strip: a centered count line plus one static tip, appended as the last body child after
 * the vertical glue so on a short list the glue pins it to the bottom of the viewport and on a
 * long list it scrolls in after the last section. Height-capped like the banners so the body's
 * {@code BoxLayout(Y_AXIS)} does not stretch it. Never hidden -- renders in every state. The
 * waypoint count is the full library total; the category count is non-empty categories only.
 * Neither count changes with the active search filter.
 */
final class FooterStrip extends JPanel
{
    // One static tip chosen once per instance (one plugin-enable). No timer, no rotation at
    // runtime. The index varies across restarts via the nanoTime seed. The tips are verified
    // against current features (export lives on the overflow menu).
    private static final String[] TIPS = {
        "Drag the dot-grip to reorder",
        "Click a row to edit it inline",
        "Open the ⋮ menu to import or export",
        "Pin a waypoint to keep it up top",
        "Use Select for bulk move and delete",
        "Right-click a waypoint for quick actions",
        "Search by name or category",
    };

    private final int tipIndex = Math.floorMod(System.nanoTime(), TIPS.length);
    private final JLabel label = new JLabel("", SwingConstants.CENTER);

    FooterStrip()
    {
        setLayout(new BorderLayout());
        setBackground(ColorScheme.DARK_GRAY_COLOR);
        setAlignmentX(Component.LEFT_ALIGNMENT);
        setBorder(BorderFactory.createEmptyBorder(8, 10, 8, 10));
        add(label, BorderLayout.CENTER);
    }

    // Pure count-line formatter. Package-private so it is unit-testable without constructing
    // the Swing panel. Separator is U+00B7 (middle dot).
    static String countText(int waypoints, int categories)
    {
        return waypoints + (waypoints == 1 ? " waypoint" : " waypoints")
            + " · "
            + categories + (categories == 1 ? " category" : " categories");
    }

    /** Refresh the label from counts the caller already computed. {@code waypoints} is the full
     * library total; {@code categories} is non-empty categories only. */
    void refresh(int waypoints, int categories)
    {
        label.setText("<html><div style='text-align:center;'>"
            + "<span style='color:" + Styles.MUTED_HEX + ";'>" + countText(waypoints, categories) + "</span><br>"
            + "<span style='color:" + Styles.FAINT_HEX + ";font-style:italic;'>" + TIPS[tipIndex] + "</span>"
            + "</div></html>");
    }

    // Cap height to preferred so the body's BoxLayout(Y_AXIS) does not stretch the footer.
    @Override public Dimension getMaximumSize()
    {
        return Styles.capHeight(this);
    }
}

package com.waypointer.ui;

import com.waypointer.codec.WaypointShareCodec;
import com.waypointer.model.Category;
import com.waypointer.model.Waypoint;
import com.waypointer.service.WaypointStore;
import java.awt.Window;
import java.util.ArrayList;
import java.util.List;
import java.util.UUID;

/**
 * Owns the panel's bulk select mode: the {@link BulkSelection} model, the select-mode flag, the
 * shift-range anchor, and the {@link BulkActionBar}. Splits the selection orchestration out of
 * {@link WaypointerPanel}; every Swing side effect routes back through {@link Host}.
 */
final class BulkSelectController
{
    /** Hooks back into the panel for the side effects the controller cannot perform itself. */
    interface Host
    {
        /** Request a (coalesced) body rebuild so rows re-render with current checkbox state. */
        void rebuild();

        /** Revalidate + repaint the panel after the action bar's visibility or size changes. */
        void revalidateAndRepaint();

        /** Window ancestor used as the export dialog's owner; may be null in tests. */
        Window windowAncestor();
    }

    private final WaypointStore store;
    private final Toasts toasts;
    private final WaypointShareCodec shareCodec;
    private final Host host;
    private final BulkActionBar bar;

    private final BulkSelection selection = new BulkSelection();
    private boolean selectMode = false;
    private UUID lastClickedId;
    // Ordered ids of the waypoints currently rendered in real categories (Pinned excluded),
    // refreshed every render pass so shift-range select honours the active filter and sort.
    private final List<UUID> visibleOrderedIds = new ArrayList<>();

    BulkSelectController(WaypointStore store, Toasts toasts,
        WaypointShareCodec shareCodec, Host host)
    {
        this.store = store;
        this.toasts = toasts;
        this.shareCodec = shareCodec;
        this.host = host;
        this.bar = new BulkActionBar(
            this::exitSelectMode,
            store::getCategoriesOrdered,
            this::bulkMoveTo,
            this::bulkDelete,
            this::bulkExport);
        bar.setVisible(false);
    }

    /** The SOUTH-docked action bar; added to the panel by {@link WaypointerPanel}. */
    BulkActionBar bar() { return bar; }

    boolean isSelectMode() { return selectMode; }

    BulkSelection selection() { return selection; }

    /** Replace the visible-row order used for shift-range selection. Called at the end of each rebuild. */
    void setVisibleOrderedIds(List<UUID> ids)
    {
        visibleOrderedIds.clear();
        visibleOrderedIds.addAll(ids);
    }

    // A row was clicked in select mode: shift extends the range from the last click; a plain
    // click toggles. Keyed by id so it is filter/sort independent.
    void onRowSelectClicked(Waypoint w, boolean shift)
    {
        UUID id = w.getId();
        if (shift && lastClickedId != null)
        {
            selection.selectRange(visibleOrderedIds, lastClickedId, id);
        }
        else
        {
            selection.toggle(id);
        }
        lastClickedId = id;
        afterSelectionChanged();
    }

    void onHeaderSelectToggle(List<UUID> ids, boolean select)
    {
        selection.setCategory(ids, select);
        afterSelectionChanged();
    }

    /** Enter select mode. Triggered by the "Select multiple" right-click entry. */
    void enterSelectMode() { setSelectMode(true); }

    /** Exit select mode. Triggered by the action bar's Done button. */
    void exitSelectMode() { setSelectMode(false); }

    void toggleSelectMode() { setSelectMode(!selectMode); }

    private void setSelectMode(boolean on)
    {
        if (selectMode == on) return;
        selectMode = on;
        if (!selectMode)
        {
            selection.clear();
            lastClickedId = null;
        }
        host.rebuild();
        refreshBulkBar();
    }

    void refreshBulkBar()
    {
        bar.setVisible(selectMode);
        if (selectMode)
        {
            bar.setCount(selection.size());
            bar.setActionsEnabled(!selection.isEmpty());
        }
        host.revalidateAndRepaint();
    }

    private void bulkMoveTo(UUID targetId)
    {
        if (selection.isEmpty()) return;
        Category target = store.getCategoryById(targetId);
        int n = selection.size();
        store.moveWaypointsToCategory(selection.ids(), targetId);
        selection.clear();
        lastClickedId = null;
        afterSelectionChanged();
        toasts.show("Moved " + n + " to " + (target == null ? "category" : target.getName()),
            null, null);
    }

    private void bulkDelete()
    {
        if (selection.isEmpty()) return;
        int n = selection.size();
        store.deleteWaypoints(selection.ids());
        selection.clear();
        lastClickedId = null;
        afterSelectionChanged();
        toasts.show(n + " deleted", "Undo", store::undoLast);
    }

    private void bulkExport()
    {
        if (selection.isEmpty()) return;
        Window owner = host.windowAncestor();
        new ExportPickerDialog(owner, store, shareCodec, toasts,
            selection.ids()).setVisible(true);
        // Selection is non-destructive for export; leave it intact.
    }

    private void afterSelectionChanged()
    {
        host.rebuild();
        refreshBulkBar();
    }

    // Test seams: exercise the non-modal action paths without driving the popup menu / dialog.
    void bulkDeleteForTest() { bulkDelete(); }
    void bulkMoveToForTest(UUID targetId) { bulkMoveTo(targetId); }
}

package com.waypointer.ui;

import com.waypointer.model.route.Route;
import com.waypointer.model.route.RouteStep;
import com.waypointer.service.RouteStore;
import java.awt.BorderLayout;
import java.awt.FlowLayout;
import java.util.UUID;
import javax.swing.BorderFactory;
import javax.swing.Box;
import javax.swing.BoxLayout;
import javax.swing.JButton;
import javax.swing.JCheckBox;
import javax.swing.JLabel;
import javax.swing.JOptionPane;
import javax.swing.JPanel;
import javax.swing.JTextField;
import net.runelite.client.ui.ColorScheme;

/**
 * Edits one route's steps: an ordered list of {@link RouteStepRow}s plus add-step controls and a
 * repeating toggle. All mutations go through {@link RouteStore} so they persist and notify.
 */
final class RouteEditorPanel extends JPanel
{
    private final RouteStore store;
    private final UUID routeId;
    private final Runnable onBack;
    private final Runnable onMarkCurrentLocation;
    private final Runnable onAddFromLibrary;
    private final JPanel stepList = new JPanel();

    RouteEditorPanel(RouteStore store, UUID routeId, Runnable onBack,
        Runnable onMarkCurrentLocation, Runnable onAddFromLibrary)
    {
        this.store = store;
        this.routeId = routeId;
        this.onBack = onBack;
        this.onMarkCurrentLocation = onMarkCurrentLocation;
        this.onAddFromLibrary = onAddFromLibrary;
        setLayout(new BorderLayout());
        setBackground(ColorScheme.DARK_GRAY_COLOR);

        // Nav row and the add-step controls both sit at the top: the add-step buttons are the
        // primary action here, so they belong above the step list rather than buried in a footer.
        JPanel top = new JPanel();
        top.setLayout(new BoxLayout(top, BoxLayout.Y_AXIS));
        top.setBackground(ColorScheme.DARK_GRAY_COLOR);
        top.add(buildNavRow());
        top.add(buildAddStepBar());
        add(top, BorderLayout.NORTH);

        stepList.setLayout(new BoxLayout(stepList, BoxLayout.Y_AXIS));
        stepList.setBackground(ColorScheme.DARK_GRAY_COLOR);
        add(Styles.pinnedScrollPane(stepList), BorderLayout.CENTER);

        rebuild();
    }

    private JPanel buildNavRow()
    {
        JPanel header = new JPanel(new FlowLayout(FlowLayout.LEFT, 6, 4));
        header.setBackground(ColorScheme.DARK_GRAY_COLOR);
        // ◀ = left-pointing triangle for back navigation
        JButton back = new JButton("◀ Routes");
        Styles.compactSecondaryButton(back);
        back.addActionListener(e -> onBack.run());
        header.add(back);

        Route r = store.getRouteById(routeId);
        JCheckBox repeating = new JCheckBox("Repeating", r != null && r.isRepeating());
        repeating.setBackground(ColorScheme.DARK_GRAY_COLOR);
        repeating.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
        repeating.addActionListener(e -> store.setRepeating(routeId, repeating.isSelected()));
        header.add(repeating);
        return header;
    }

    private JPanel buildAddStepBar()
    {
        JPanel bar = new JPanel();
        bar.setLayout(new BoxLayout(bar, BoxLayout.Y_AXIS));
        bar.setBackground(ColorScheme.DARK_GRAY_COLOR);
        bar.setBorder(BorderFactory.createEmptyBorder(4, 6, 4, 6));

        // ◉ = waypoint glyph; capture the player's current tile as a step
        bar.add(fullWidthButton("◉ Mark location", e -> onMarkCurrentLocation.run()));
        bar.add(Box.createVerticalStrut(4));
        bar.add(fullWidthButton("◉ From saved", e -> onAddFromLibrary.run()));
        bar.add(Box.createVerticalStrut(4));
        // ▤ = note-card glyph for a manual (text-only) step
        bar.add(fullWidthButton("▤ Add manual step", e -> {
            String text = JOptionPane.showInputDialog(this, "Instruction:");
            if (text != null && !text.trim().isEmpty()) store.addManualStep(routeId, text.trim());
        }));
        return bar;
    }

    // Full-width button for the vertical add-step bar: the height is capped so the Y_AXIS
    // BoxLayout does not stretch it, while the width expands to fill the column.
    private JButton fullWidthButton(String text, java.awt.event.ActionListener onClick)
    {
        JButton b = new JButton(text);
        Styles.secondaryButton(b);
        b.setAlignmentX(LEFT_ALIGNMENT);
        b.setMaximumSize(Styles.capHeight(b));
        b.addActionListener(onClick);
        return b;
    }

    /** Rebuild the step list from the store. Call after any mutation. */
    void rebuild()
    {
        stepList.removeAll();
        Route r = store.getRouteById(routeId);
        if (r != null)
        {
            RouteStepDragHandler dragHandler = new RouteStepDragHandler(store, routeId);
            int i = 0;
            for (RouteStep s : r.getSteps())
            {
                stepList.add(new RouteStepRow(i++, s,
                    () -> editStep(s),
                    step -> {
                        String[] options = {"Cancel", "Delete"};
                        int choice = JOptionPane.showOptionDialog(this,
                            "Delete this step?", "Delete step",
                            JOptionPane.DEFAULT_OPTION, JOptionPane.WARNING_MESSAGE,
                            null, options, options[0]);
                        if (choice == 1) store.deleteStep(routeId, step.getId());
                    },
                    dragHandler));
            }
        }
        stepList.revalidate();
        stepList.repaint();
    }

    private void editStep(RouteStep s)
    {
        JTextField nameField = new JTextField(s.getLabel() == null ? "" : s.getLabel(), 20);
        JTextField boxField = new JTextField(s.getBoxText() == null ? "" : s.getBoxText(), 20);

        JPanel form = new JPanel();
        form.setLayout(new BoxLayout(form, BoxLayout.Y_AXIS));
        form.add(new JLabel("Name (sidebar)"));
        form.add(nameField);
        form.add(Box.createVerticalStrut(8));
        form.add(new JLabel("In-game box text (blank = use name)"));
        form.add(boxField);

        int result = JOptionPane.showConfirmDialog(this, form, "Edit step",
            JOptionPane.OK_CANCEL_OPTION, JOptionPane.PLAIN_MESSAGE);
        if (result == JOptionPane.OK_OPTION)
        {
            store.updateStepText(routeId, s.getId(),
                nameField.getText().trim(), boxField.getText().trim());
        }
    }
}

package com.waypointer.ui;

import com.waypointer.codec.WaypointShareCodec;
import com.waypointer.model.Library;
import com.waypointer.service.WaypointStore;
import java.awt.Component;
import javax.inject.Inject;
import javax.inject.Singleton;
import javax.swing.JMenuItem;
import javax.swing.JOptionPane;
import javax.swing.JPopupMenu;
import javax.swing.SwingUtilities;

/**
 * Builds the panel's "⋮" overflow menu. Constructed by Guice with all of its services so the
 * panel doesn't need to hold them just to forward them in. The panel passes its own component
 * as the anchor at {@link #show(Component, Component)} time so JOption dialogs land on the
 * right window.
 */
@Singleton
final class OverflowMenu
{
    private final WaypointStore store;
    private final WaypointShareCodec shareCodec;

    @Inject
    OverflowMenu(WaypointStore store, WaypointShareCodec shareCodec)
    {
        this.store = store;
        this.shareCodec = shareCodec;
    }

    /** Show the popup anchored just below {@code near}; uses {@code panel} as JOption parent. */
    void show(Component near, WaypointerPanel panel, Toasts toasts)
    {
        Component anchor = panel;
        JPopupMenu menu = new JPopupMenu();

        JMenuItem newCategory = new JMenuItem("New category...");
        newCategory.addActionListener(e -> {
            String name = JOptionPane.showInputDialog(anchor, "Category name:", "New category",
                JOptionPane.PLAIN_MESSAGE);
            if (name == null || name.trim().isEmpty()) return;
            try { store.createCategory(name.trim()); }
            catch (IllegalArgumentException ex) {
                JOptionPane.showMessageDialog(anchor, ex.getMessage(), "Waypointer",
                    JOptionPane.WARNING_MESSAGE);
            }
        });
        menu.add(newCategory);

        // Expand all / Collapse all: one toggle whose label flips based on current state.
        // Majority-collapsed → "Expand all"; otherwise "Collapse all". Walks both Pinned and
        // real categories via WaypointerPanel.setAllSectionsExpanded.
        boolean expandLabel = panel.isMajorityCollapsed();
        JMenuItem expandToggle = new JMenuItem(expandLabel ? "Expand all" : "Collapse all");
        expandToggle.addActionListener(e -> panel.setAllSectionsExpanded(expandLabel));
        menu.add(expandToggle);
        menu.addSeparator();

        JMenuItem exportItem = new JMenuItem("Export...");
        exportItem.addActionListener(e ->
            new ExportPickerDialog(SwingUtilities.getWindowAncestor(anchor), store, shareCodec,
                toasts, null).setVisible(true));
        menu.add(exportItem);

        JMenuItem importItem = new JMenuItem("Import...");
        importItem.addActionListener(e ->
            new ImportPickerDialog(SwingUtilities.getWindowAncestor(anchor), store, shareCodec,
                toasts).setVisible(true));
        menu.add(importItem);

        menu.addSeparator();

        JMenuItem reset = new JMenuItem("Reset library...");
        reset.addActionListener(e -> {
            // Custom options with Cancel as the default-focused button so a stray Enter
            // can't wipe the whole library - there is no undo for this.
            String[] options = {"Cancel", "Delete everything"};
            int choice = JOptionPane.showOptionDialog(anchor,
                "Delete ALL waypoints and categories? This cannot be undone.",
                "Reset library", JOptionPane.DEFAULT_OPTION, JOptionPane.WARNING_MESSAGE,
                null, options, options[0]);
            if (choice == 1) store.bootstrap(new Library());
        });
        menu.add(reset);

        menu.show(near, 0, near.getHeight());
    }
}

