/**
 * Immediate-hover hint: a dark-themed borderless {@link JWindow} with a single styled
 * {@link JLabel} that appears the instant the cursor enters an attached component, four
 * pixels above it. The house style for affordance hints across the panel, replacing the
 * native (delayed, light-on-dark) Swing tooltip.
 *
 * <p>Most call sites use the process-shared instance via {@link #shared()} -- one reused
 * window for the whole plugin UI, never more than one visible at a time. The instance API
 * (constructor + {@link #attach} + {@link #dispose}) is retained for unit tests.
 *
 * <p>Headless safety: tests run without a display, so visibility is tracked in
 * {@code visibleIntent} and {@link JWindow#setVisible} calls are skipped in headless
 * environments. Production code reads visibility through the window; tests read it
 * through {@link #visibleIntentForTest()}.
 */
final class HoverHint
{
	private static HoverHint shared;

	/**
	 * Process-shared hint. Lazily created on first use and kept for the JVM session: a single
	 * invisible window is cheap and is reused across every panel rebuild and plugin
	 * enable/disable cycle, so nothing accumulates. {@code attach} only ever adds a listener to
	 * the (freshly built) target component, so re-enabling the plugin re-attaches new components
	 * to the same window without stacking.
	 * Do not call {@link #dispose()} on the shared instance -- {@code disposed} is sticky and would permanently silence all hints for the session.
	 */
	static HoverHint shared()
	{
		if (shared == null) shared = new HoverHint();
		return shared;
	}

	private final JWindow window;
	private final JLabel label;
	private boolean visibleIntent;
	private boolean disposed;

	HoverHint()
	{
		this.label = new JLabel("");
		this.label.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		this.label.setFont(FontManager.getRunescapeSmallFont());
		this.label.setBorder(BorderFactory.createCompoundBorder(
			BorderFactory.createLineBorder(ColorScheme.LIGHT_GRAY_COLOR, 1),
			BorderFactory.createEmptyBorder(4, 6, 4, 6)));
		this.label.setOpaque(true);
		this.label.setBackground(ColorScheme.DARKER_GRAY_COLOR);

		if (displayAvailable())
		{
			this.window = new JWindow();
			this.window.setFocusableWindowState(false);
			this.window.getContentPane().add(label);
			this.window.pack();
		}
		else
		{
			this.window = null;
		}
	}

	boolean visibleIntentForTest() { return visibleIntent; }
	String labelTextForTest() { return label.getText(); }

	private static boolean displayAvailable()
	{
		return !GraphicsEnvironment.isHeadless();
	}

	/**
	 * Attach this hint to {@code target}. While the cursor is inside the target, the hint shows
	 * {@code textSupplier.get()} four pixels above it, horizontally centred. The supplier is
	 * re-read on every enter so the text follows late updates (e.g. a button changing meaning).
	 *
	 * <p>Attach is single-use per target component: calling it twice on the same target registers
	 * two listeners which would race on every hover. Callers rebuild their components from scratch
	 * on every panel rebuild, so re-attaching is naturally avoided.
	 *
	 * <p>Attach is a no-op after {@link #dispose()}.
	 */
	void attach(JComponent target, Supplier<String> textSupplier)
	{
		target.addMouseListener(new MouseAdapter()
		{
			@Override public void mouseEntered(MouseEvent e)
			{
				if (disposed) return;
				String text = textSupplier.get();
				label.setText(text == null ? "" : text);
				visibleIntent = true;
				if (window == null) return;
				window.pack();
				positionAbove(target);
				window.setVisible(true);
			}

			@Override public void mouseExited(MouseEvent e)
			{
				if (disposed) return;
				visibleIntent = false;
				if (window != null) window.setVisible(false);
			}
		});
	}

	private void positionAbove(JComponent target)
	{
		if (window == null) return;
		if (!target.isShowing()) return;
		Point onScreen = target.getLocationOnScreen();
		int gap = 4;
		int x = onScreen.x + (target.getWidth() - window.getWidth()) / 2;
		int y = onScreen.y - window.getHeight() - gap;
		window.setLocation(x, y);
	}

	/**
	 * Releases the hint's {@link JWindow}. Subsequent {@link #attach} calls still register
	 * listeners but those listeners short-circuit because {@code disposed} is sticky. Safe to
	 * call multiple times.
	 */
	void dispose()
	{
		if (disposed) return;
		disposed = true;
		visibleIntent = false;
		if (window != null) window.dispose();
	}
}

package com.waypointer.ui;

import com.waypointer.model.Category;
import com.waypointer.service.WaypointCapture;
import com.waypointer.service.WaypointStore;
import java.awt.BorderLayout;
import java.awt.Component;
import java.awt.FlowLayout;
import java.awt.GridBagConstraints;
import java.awt.GridBagLayout;
import java.awt.Insets;
import java.awt.event.ActionEvent;
import java.awt.event.KeyEvent;
import java.util.UUID;
import javax.swing.AbstractAction;
import javax.swing.BorderFactory;
import javax.swing.BoxLayout;
import javax.swing.JButton;
import javax.swing.JComboBox;
import javax.swing.JComponent;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.JRootPane;
import javax.swing.JTextField;
import javax.swing.KeyStroke;
import net.runelite.client.ui.ColorScheme;

/**
 * Inline capture form parked at the top of the body, shown by the panel's Mark button and by
 * right-click capture. Kept inline rather than modal so saving a waypoint never steals focus
 * from the game canvas.
 */
class CaptureForm extends JPanel
{
    private final WaypointStore store;
    private final WaypointCapture capture;

    private final JTextField nameField = new JTextField();
    private final JComboBox<CategoryComboItem> categoryCombo = new JComboBox<>();
    private final JPanel stack = new JPanel();
    private final JButton saveBtn = new JButton("Save");
    private final JButton cancelBtn = new JButton("Cancel");

    private final JPanel newCategoryRow = new JPanel(new GridBagLayout());
    private final JTextField newCategoryName = new JTextField();
    private final JButton newCategoryCreate = new JButton("Create");
    private final JButton newCategoryCancel = new JButton("Cancel");
    private final JLabel errorLabel = new JLabel(" ");
    private CategoryComboController categoryController;

    private int packedPoint;
    private String targetNpcName;

    CaptureForm(WaypointStore store, WaypointCapture capture)
    {
        this.store = store;
        this.capture = capture;

        setLayout(new BorderLayout(0, 4));
        setBackground(ColorScheme.DARK_GRAY_COLOR);
        setBorder(BorderFactory.createCompoundBorder(
            BorderFactory.createLineBorder(ColorScheme.DARK_GRAY_COLOR.darker(), 1),
            BorderFactory.createEmptyBorder(6, 6, 6, 6)));

        stack.setLayout(new BoxLayout(stack, BoxLayout.Y_AXIS));
        stack.setBackground(ColorScheme.DARK_GRAY_COLOR);

        JLabel caption = new JLabel("Save waypoint");
        caption.setForeground(java.awt.Color.WHITE);
        caption.setAlignmentX(Component.LEFT_ALIGNMENT);
        stack.add(caption);

        JPanel form = new JPanel(new GridBagLayout());
        form.setBackground(ColorScheme.DARK_GRAY_COLOR);
        form.setAlignmentX(Component.LEFT_ALIGNMENT);
        GridBagConstraints g = new GridBagConstraints();
        g.fill = GridBagConstraints.HORIZONTAL;
        g.insets = new Insets(2, 2, 2, 2);

        g.gridx = 0; g.gridy = 0; g.weightx = 0;
        form.add(Styles.fieldLabel("Name"), g);
        Styles.textField(nameField);
        g.gridx = 1; g.weightx = 1;
        form.add(nameField, g);

        g.gridx = 0; g.gridy = 1; g.weightx = 0;
        form.add(Styles.fieldLabel("Category"), g);
        Styles.combo(categoryCombo);
        categoryController = new CategoryComboController(categoryCombo, store);
        g.gridx = 1; g.weightx = 1;
        form.add(categoryCombo, g);

        stack.add(form);

        newCategoryRow.setBackground(ColorScheme.DARK_GRAY_COLOR);
        newCategoryRow.setAlignmentX(Component.LEFT_ALIGNMENT);
        newCategoryRow.setVisible(false);
        Styles.textField(newCategoryName);
        Styles.compactSecondaryButton(newCategoryCreate);
        Styles.compactSecondaryButton(newCategoryCancel);
        newCategoryCreate.addActionListener(e -> doCreateInlineCategory());
        newCategoryCancel.addActionListener(e -> cancelInlineCategory());
        GridBagConstraints gn = new GridBagConstraints();
        gn.fill = GridBagConstraints.HORIZONTAL;
        gn.insets = new Insets(2, 2, 2, 2);
        gn.gridx = 0; gn.gridy = 0; gn.weightx = 1;
        newCategoryRow.add(newCategoryName, gn);
        gn.gridx = 1; gn.weightx = 0;
        newCategoryRow.add(newCategoryCreate, gn);
        gn.gridx = 2;
        newCategoryRow.add(newCategoryCancel, gn);
        stack.add(newCategoryRow);

        errorLabel.setForeground(Styles.ERROR_RED);
        errorLabel.setAlignmentX(LEFT_ALIGNMENT);
        errorLabel.setVisible(false);
        stack.add(errorLabel);

        add(stack, BorderLayout.CENTER);

        JPanel buttons = new JPanel(new FlowLayout(FlowLayout.RIGHT, 4, 0));
        buttons.setBackground(ColorScheme.DARK_GRAY_COLOR);
        Styles.secondaryButton(cancelBtn);
        cancelBtn.addActionListener(e -> dismiss());
        Styles.primaryButton(saveBtn);
        saveBtn.addActionListener(e -> doSave());
        buttons.add(cancelBtn);
        buttons.add(saveBtn);
        add(buttons, BorderLayout.SOUTH);

        // ESC cancels, ENTER on the name field saves. Both bound on the form's own
        // input map so they don't fire when focus is somewhere else in the panel.
        getInputMap(JComponent.WHEN_ANCESTOR_OF_FOCUSED_COMPONENT)
            .put(KeyStroke.getKeyStroke(KeyEvent.VK_ESCAPE, 0), "captureCancel");
        getActionMap().put("captureCancel", new AbstractAction()
        {
            @Override public void actionPerformed(ActionEvent e) { dismiss(); }
        });
        nameField.getInputMap(JComponent.WHEN_FOCUSED)
            .put(KeyStroke.getKeyStroke(KeyEvent.VK_ENTER, 0), "captureSave");
        nameField.getActionMap().put("captureSave", new AbstractAction()
        {
            @Override public void actionPerformed(ActionEvent e) { saveBtn.doClick(); }
        });

        categoryCombo.addActionListener(e -> onCategorySelectionChanged());
        setVisible(false);
    }

    @Override
    public void addNotify()
    {
        super.addNotify();
        JRootPane root = getRootPane();
        if (root != null) root.setDefaultButton(saveBtn);
    }

    void show(int packed)
    {
        show(packed, null, null);
    }

    void show(int packed, String defaultName, String npcName)
    {
        this.packedPoint = packed;
        this.targetNpcName = npcName;
        newCategoryRow.setVisible(false);
        newCategoryName.setText("");
        errorLabel.setVisible(false);
        errorLabel.setText(" ");
        categoryController.rebuild(store.getUncategorized().getId());
        String prefill = (defaultName != null && !defaultName.isEmpty())
            ? defaultName : capture.defaultName(packed);
        nameField.setText(prefill);
        nameField.selectAll();
        setVisible(true);
        nameField.requestFocusInWindow();
        revalidate();
        repaint();
    }

    void dismiss()
    {
        setVisible(false);
        revalidate();
        repaint();
    }

    String getNameText()
    {
        return nameField.getText();
    }

    private void onCategorySelectionChanged()
    {
        if (!categoryController.isSentinelSelected())
        {
            CategoryComboItem sel = (CategoryComboItem) categoryCombo.getSelectedItem();
            if (sel != null) categoryController.setLastNonSentinel(sel);
            newCategoryRow.setVisible(false);
            errorLabel.setVisible(false);
            revalidate();
            repaint();
            return;
        }
        newCategoryName.setText("");
        newCategoryRow.setVisible(true);
        revalidate();
        repaint();
        newCategoryName.requestFocusInWindow();
    }

    private void doCreateInlineCategory()
    {
        String name = newCategoryName.getText();
        if (name == null || name.trim().isEmpty()) return;
        try
        {
            Category created = store.createCategory(name.trim());
            categoryController.rebuild(created.getId());
            newCategoryRow.setVisible(false);
            errorLabel.setVisible(false);
            errorLabel.setText(" ");
        }
        catch (IllegalArgumentException ex)
        {
            errorLabel.setText(ex.getMessage());
            errorLabel.setVisible(true);
        }
        revalidate();
        repaint();
    }

    private void cancelInlineCategory()
    {
        CategoryComboItem last = categoryController.lastNonSentinel();
        UUID revertTo = last != null ? last.id() : store.getUncategorized().getId();
        categoryController.rebuild(revertTo);
        newCategoryRow.setVisible(false);
        errorLabel.setVisible(false);
        revalidate();
        repaint();
    }

    private void doSave()
    {
        String typed = nameField.getText();
        String trimmed = typed == null ? "" : typed.trim();
        if (trimmed.isEmpty()) trimmed = capture.defaultName(packedPoint);

        UUID categoryId = categoryController.resolveSelectedId();

        store.createWaypoint(packedPoint, trimmed, categoryId, targetNpcName);
        dismiss();
    }

    void setNameText(String text)
    {
        nameField.setText(text);
    }

    void selectCategoryByName(String name)
    {
        for (int i = 0; i < categoryCombo.getItemCount(); i++)
        {
            CategoryComboItem item = categoryCombo.getItemAt(i);
            if (!item.isSentinel() && name.equals(item.toString()))
            {
                categoryCombo.setSelectedIndex(i);
                return;
            }
        }
        throw new IllegalArgumentException("No category named: " + name);
    }

    void clickSave()
    {
        saveBtn.doClick();
    }

    void clickCancel()
    {
        cancelBtn.doClick();
    }

    boolean isNewCategoryRowVisible()
    {
        return newCategoryRow.isVisible();
    }

    void selectNewCategorySentinel()
    {
        for (int i = 0; i < categoryCombo.getItemCount(); i++)
        {
            if (categoryCombo.getItemAt(i).isSentinel())
            {
                categoryCombo.setSelectedIndex(i);
                return;
            }
        }
    }

    void setNewCategoryNameText(String text)
    {
        newCategoryName.setText(text);
    }

    void clickCreateNewCategory()
    {
        newCategoryCreate.doClick();
    }

    void clickCancelNewCategory()
    {
        newCategoryCancel.doClick();
    }

    Object selectedCategoryItem()
    {
        return categoryCombo.getSelectedItem();
    }

    String getErrorText()
    {
        return errorLabel.getText();
    }
}

package com.waypointer.ui;

import com.waypointer.model.Waypoint;
import java.awt.Component;
import java.awt.GridLayout;
import javax.inject.Singleton;
import javax.swing.JCheckBox;
import javax.swing.JLabel;
import javax.swing.JOptionPane;
import javax.swing.JPanel;

/** Production gate: opens a Swing confirm dialog. Test code uses a fake impl of the interface. */
@Singleton
public class SwingWildernessConfirmGate implements WildernessConfirmGate
{
    @Override
    public Result prompt(Component parent, Waypoint w)
    {
        JPanel msg = new JPanel(new GridLayout(0, 1, 0, 4));
        msg.setOpaque(false);
        msg.add(new JLabel("Path to '" + w.getName() + "'?"));
        msg.add(new JLabel("This destination is in the Wilderness."));
        JCheckBox dontAsk = new JCheckBox("Don't ask again for this waypoint");
        msg.add(dontAsk);

        // Cancel is the default-focused button so a stray Enter does not start a Wilderness path.
        String[] options = {"Path anyway", "Cancel"};
        int choice = JOptionPane.showOptionDialog(parent, msg, "Wilderness destination",
            JOptionPane.DEFAULT_OPTION, JOptionPane.WARNING_MESSAGE, null, options, options[1]);
        return new Result(choice == 0, dontAsk.isSelected());
    }
}

package com.waypointer.ui;

import com.waypointer.codec.RouteShareCodec;
import com.waypointer.model.route.Route;
import com.waypointer.model.route.RouteStep;
import com.waypointer.model.route.StepType;
import com.waypointer.service.RoutePlaybackEngine;
import com.waypointer.service.RouteRecorder;
import com.waypointer.service.RouteStore;
import com.waypointer.service.RouteStorePersistence;
import com.waypointer.util.Listeners;
import java.awt.BorderLayout;
import java.awt.CardLayout;
import java.awt.Dimension;
import java.awt.FlowLayout;
import java.util.UUID;
import javax.inject.Inject;
import javax.inject.Singleton;
import javax.swing.BoxLayout;
import javax.swing.JButton;
import javax.swing.JMenuItem;
import javax.swing.JOptionPane;
import javax.swing.JPanel;
import javax.swing.JPopupMenu;
import javax.swing.SwingUtilities;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.PluginPanel;

/** The Routes tab body: a list of routes, a playback bar, and create/edit nav. */
@Singleton
public class RoutesPanel extends JPanel
{
    private static final String CARD_LIST = "list";
    private static final String CARD_EDITOR = "editor";

    private final RouteStore store;
    private final RoutePlaybackEngine engine;
    private final RouteRecorder recorder;
    private final RouteShareCodec shareCodec;
    private final com.waypointer.service.WaypointStore waypointStore;
    private final RouteStorePersistence persistence;
    private final RoutePlaybackBar playbackBar;

    private final CardLayout cards = new CardLayout();
    private final JPanel cardHost = new JPanel(cards);
    private final JPanel listCard = new JPanel(new BorderLayout());
    private final JPanel routeList = new JPanel();
    private final JPanel editorHost = new JPanel(new BorderLayout());

    private final javax.swing.JScrollBar routeListScrollBar;
    private Listeners.Subscription storeSub;
    private Listeners.Subscription engineSub;
    private RouteEditorPanel openEditor;
    private Toasts toasts = Toasts.NO_OP;

    @Inject
    public RoutesPanel(RouteStore store, RoutePlaybackEngine engine, RouteRecorder recorder,
        RouteShareCodec shareCodec, com.waypointer.service.WaypointStore waypointStore,
        RouteStorePersistence persistence)
    {
        this.store = store;
        this.engine = engine;
        this.recorder = recorder;
        this.shareCodec = shareCodec;
        this.waypointStore = waypointStore;
        this.persistence = persistence;
        this.playbackBar = new RoutePlaybackBar(engine);

        setLayout(new BorderLayout());
        setBackground(ColorScheme.DARK_GRAY_COLOR);

        JPanel north = new JPanel();
        north.setLayout(new BoxLayout(north, BoxLayout.Y_AXIS));
        north.setBackground(ColorScheme.DARK_GRAY_COLOR);
        playbackBar.setAlignmentX(LEFT_ALIGNMENT);
        north.add(playbackBar);
        add(north, BorderLayout.NORTH);

        routeList.setLayout(new BoxLayout(routeList, BoxLayout.Y_AXIS));
        routeList.setBackground(ColorScheme.DARK_GRAY_COLOR);
        listCard.setBackground(ColorScheme.DARK_GRAY_COLOR);
        listCard.add(buildListHeader(), BorderLayout.NORTH);
        // The panel is built before RuneLiteLAF installs, so pin the dark scrollbar now and
        // re-derive it from startUp() via refreshScrollbarStyling() once the LAF is live.
        javax.swing.JScrollPane listScroll = Styles.pinnedScrollPane(routeList);
        this.routeListScrollBar = listScroll.getVerticalScrollBar();
        listCard.add(listScroll, BorderLayout.CENTER);

        editorHost.setBackground(ColorScheme.DARK_GRAY_COLOR);

        cardHost.add(listCard, CARD_LIST);
        cardHost.add(editorHost, CARD_EDITOR);
        add(cardHost, BorderLayout.CENTER);

        storeSub = store.subscribe(() -> SwingUtilities.invokeLater(this::rebuildList));
        engineSub = engine.subscribe(() -> SwingUtilities.invokeLater(playbackBar::refresh));

        rebuildList();
        playbackBar.refresh();
        cards.show(cardHost, CARD_LIST);
    }

    private JPanel buildListHeader()
    {
        JPanel header = new JPanel(new FlowLayout(FlowLayout.LEFT, 6, 4));
        header.setBackground(ColorScheme.DARK_GRAY_COLOR);
        JButton create = new JButton("New route");
        Styles.secondaryButton(create);
        create.addActionListener(e -> {
            String name = JOptionPane.showInputDialog(this, "Route name:");
            if (name != null && !name.trim().isEmpty())
            {
                Route r = store.createRoute(name.trim());
                openEditorFor(r.getId());
            }
        });
        header.add(create);

        JButton importBtn = new JButton("Import");
        Styles.secondaryButton(importBtn);
        importBtn.addActionListener(e -> importFromCode());
        header.add(importBtn);
        return header;
    }

    private void rebuildList()
    {
        routeList.removeAll();
        if (persistence.isRefusingSaves())
        {
            routeList.add(PanelBanners.routeLoadFailedReset(persistence, store, this));
        }
        for (Route r : store.getRoutesOrdered())
        {
            UUID id = r.getId();
            routeList.add(new RouteRow(r,
                () -> engine.start(store.getRouteById(id)),
                () -> openEditorFor(id),
                () -> showOverflow(id)));
        }
        if (openEditor != null) openEditor.rebuild();
        routeList.revalidate();
        routeList.repaint();
    }

    private void openEditorFor(UUID routeId)
    {
        editorHost.removeAll();
        openEditor = new RouteEditorPanel(store, routeId, this::showList,
            () -> recorder.addCurrentLocationTo(routeId),
            () -> addFromLibrary(routeId));
        editorHost.add(openEditor, BorderLayout.CENTER);
        editorHost.revalidate();
        editorHost.repaint();
        cards.show(cardHost, CARD_EDITOR);
    }

    private void showList()
    {
        openEditor = null;
        cards.show(cardHost, CARD_LIST);
        rebuildList();
    }

    private void showOverflow(UUID routeId)
    {
        JPopupMenu menu = new JPopupMenu();
        menu.add(menuItem("Export (copy code)", () -> exportToClipboard(routeId)));
        menu.add(menuItem("Rename", () -> {
            Route r = store.getRouteById(routeId);
            String name = JOptionPane.showInputDialog(this, "Rename route:", r == null ? "" : r.getName());
            if (name != null && !name.trim().isEmpty()) store.renameRoute(routeId, name.trim());
        }));
        menu.add(menuItem("Duplicate", () -> store.duplicateRoute(routeId)));
        menu.add(menuItem("Delete", () -> {
            Route r = store.getRouteById(routeId);
            String name = r == null ? "this route" : "'" + r.getName() + "'";
            String[] options = {"Cancel", "Delete"};
            int choice = JOptionPane.showOptionDialog(this,
                "Delete " + name + "? This cannot be undone.",
                "Delete route", JOptionPane.DEFAULT_OPTION, JOptionPane.WARNING_MESSAGE,
                null, options, options[0]);
            if (choice == 1) store.deleteRoute(routeId);
        }));
        menu.show(this, getWidth() / 2, 40);
    }

    private void exportToClipboard(UUID routeId)
    {
        Route r = store.getRouteById(routeId);
        if (r == null) return;
        String code = shareCodec.encodeRoute(r);
        java.awt.Toolkit.getDefaultToolkit().getSystemClipboard()
            .setContents(new java.awt.datatransfer.StringSelection(code), null);
        toasts.show("Route code copied to clipboard.");
    }

    private void importFromCode()
    {
        String code = JOptionPane.showInputDialog(this, "Paste a route code (RT1:...):");
        if (code == null || code.trim().isEmpty()) return;
        final Route imported;
        try
        {
            imported = shareCodec.decodeRoute(code.trim());
        }
        catch (RouteShareCodec.MalformedCodeException ex)
        {
            JOptionPane.showMessageDialog(this, "That is not a valid route code.",
                "Import failed", JOptionPane.WARNING_MESSAGE);
            return;
        }
        // Re-create through the store so the imported route gets fresh ids and persists.
        Route created = store.createRoute(imported.getName());
        store.setRepeating(created.getId(), imported.isRepeating());
        for (RouteStep s : imported.getSteps())
        {
            if (s.getType() == StepType.WAYPOINT)
            {
                store.addWaypointStep(created.getId(), s.getPackedWorldPoint(), s.getLabel(), null);
            }
            else
            {
                store.addManualStep(created.getId(), s.getLabel());
            }
        }
        toasts.show("Imported route: " + imported.getName());
    }

    /**
     * Pick a saved waypoint from the library and append it as a route step, snapshotting the
     * tile + name and recording the source waypoint id (hybrid sourcing: snapshot is
     * authoritative, so deleting the library waypoint never breaks the route).
     */
    private void addFromLibrary(UUID routeId)
    {
        java.util.List<com.waypointer.model.Waypoint> all = waypointStore.getLibrary().getWaypoints();
        if (all.isEmpty())
        {
            toasts.show("No saved waypoints to choose from.");
            return;
        }
        java.util.List<WaypointChoice> choices = new java.util.ArrayList<>();
        for (com.waypointer.model.Waypoint w : all) choices.add(new WaypointChoice(w));
        choices.sort((a, b) -> a.toString().compareToIgnoreCase(b.toString()));
        Object picked = JOptionPane.showInputDialog(this, "Pick a saved waypoint:", "From saved",
            JOptionPane.QUESTION_MESSAGE, null, choices.toArray(), choices.get(0));
        if (!(picked instanceof WaypointChoice)) return;
        com.waypointer.model.Waypoint w = ((WaypointChoice) picked).waypoint;
        store.addWaypointStep(routeId, w.getPackedWorldPoint(), w.getName(), w.getId());
    }

    /** Wraps a library waypoint so the chooser shows its name; carries the waypoint for selection. */
    private static final class WaypointChoice
    {
        final com.waypointer.model.Waypoint waypoint;
        WaypointChoice(com.waypointer.model.Waypoint waypoint) { this.waypoint = waypoint; }
        @Override public String toString() { return waypoint.getName(); }
    }

    private static JMenuItem menuItem(String text, Runnable action)
    {
        JMenuItem item = new JMenuItem(text);
        item.addActionListener(e -> action.run());
        return item;
    }

    /** Re-derive the dark scrollbar styling once RuneLiteLAF is live (called from startUp). */
    public void refreshScrollbarStyling()
    {
        SwingUtilities.invokeLater(() -> Styles.reapplyScrollbarPin(routeListScrollBar));
    }

    /** Called from the plugin shutDown to release subscriptions. */
    public void dispose()
    {
        if (storeSub != null) { storeSub.close(); storeSub = null; }
        if (engineSub != null) { engineSub.close(); engineSub = null; }
    }

    /** Injected by {@link TabHost} after the shared overlay is built. */
    void setToasts(Toasts toasts)
    {
        this.toasts = toasts == null ? Toasts.NO_OP : toasts;
    }

    // Test seams.
    Toasts getToastsForTest() { return toasts; }
    void addFromLibraryForTest(UUID routeId) { addFromLibrary(routeId); }

    @Override public Dimension getPreferredSize() { return new Dimension(PluginPanel.PANEL_WIDTH, 0); }
    @Override public Dimension getMinimumSize() { return new Dimension(PluginPanel.PANEL_WIDTH, 0); }
}

package com.waypointer.ui;

import com.waypointer.model.Waypoint;
import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Component;
import java.awt.Cursor;
import java.awt.Dimension;
import java.awt.FlowLayout;
import java.awt.Font;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.util.function.Consumer;
import java.util.function.Function;
import javax.swing.BorderFactory;
import javax.swing.BoxLayout;
import javax.swing.JComponent;
import javax.swing.JLabel;
import javax.swing.JPanel;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;

// Base for collapsible panel sections: a clickable chevron header that toggles a vertically
// stacked body. Subclasses supply the title via headerText() and fill the protected `body`
// field; the base owns collapse state, the collapse-on-click wiring, the transient-expand
// hooks used by drag auto-expand, and the height cap that keeps a BoxLayout(Y_AXIS) parent
// from stretching each section into leftover column space.
abstract class CollapsibleSection extends JPanel
{
    protected final JPanel body = new JPanel();
    protected JLabel headerLabel;
    protected boolean collapsed;
    private final Consumer<Boolean> onCollapseChange;

    protected CollapsibleSection(boolean collapsed, Consumer<Boolean> onCollapseChange)
    {
        this.collapsed = collapsed;
        this.onCollapseChange = onCollapseChange;
        setLayout(new BorderLayout());
        setBackground(ColorScheme.DARK_GRAY_COLOR);
        // BoxLayout in the parent horizontal-stretches us to the column width but must not
        // centre us. Pin to the left edge.
        setAlignmentX(LEFT_ALIGNMENT);

        body.setLayout(new BoxLayout(body, BoxLayout.Y_AXIS));
        body.setBackground(ColorScheme.DARK_GRAY_COLOR);
        body.setAlignmentX(LEFT_ALIGNMENT);
    }

    // Builds the header row: a BorderLayout panel whose CENTER holds the chevron+title label
    // and a "(count)" label, every surface wired to toggle collapse on click. Returns the row
    // so subclasses can add WEST/EAST decorations before placing it via add(..., NORTH).
    // Assigns this.headerLabel as a side effect (headerText() is read here, so subclass fields
    // it depends on must be set before calling this).
    protected JPanel buildHeaderRow(int count)
    {
        JPanel headerRow = new JPanel(new BorderLayout(4, 0));
        headerRow.setBackground(ColorScheme.DARKER_GRAY_COLOR);
        headerRow.setBorder(BorderFactory.createEmptyBorder(2, 4, 2, 4));
        headerRow.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));

        MouseAdapter collapseOnClick = new MouseAdapter()
        {
            @Override public void mouseClicked(MouseEvent e) { toggleCollapse(); }
        };
        headerRow.addMouseListener(collapseOnClick);

        headerLabel = new JLabel(headerText());
        headerLabel.setForeground(Color.WHITE);
        headerLabel.setFont(headerLabel.getFont().deriveFont(Font.BOLD));
        headerLabel.setOpaque(false);
        headerLabel.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
        headerLabel.addMouseListener(collapseOnClick);

        JLabel countLabel = new JLabel("(" + count + ")");
        countLabel.setForeground(Color.LIGHT_GRAY);
        countLabel.setFont(FontManager.getRunescapeSmallFont());
        countLabel.addMouseListener(collapseOnClick);

        JPanel centerWrap = new JPanel(new FlowLayout(FlowLayout.LEFT, 6, 0));
        centerWrap.setOpaque(false);
        centerWrap.addMouseListener(collapseOnClick);
        centerWrap.add(headerLabel);
        centerWrap.add(countLabel);
        headerRow.add(centerWrap, BorderLayout.CENTER);
        return headerRow;
    }

    // Places the (already-populated) body to CENTER, honouring the current collapse state.
    // Subclasses add the header to NORTH themselves (after decorating it), then call this once
    // the body rows are built.
    protected void attachBody()
    {
        body.setVisible(!collapsed);
        add(body, BorderLayout.CENTER);
    }

    protected abstract String headerText();

    protected void toggleCollapse()
    {
        collapsed = !collapsed;
        body.setVisible(!collapsed);
        headerLabel.setText(headerText());
        revalidate();
        repaint();
        onCollapseChange.accept(collapsed);
    }

    // Cap vertical extent at preferred height so BoxLayout(Y_AXIS) in the parent stacks
    // sections tight instead of stretching each one to fill leftover space.
    @Override
    public Dimension getMaximumSize()
    {
        return Styles.capHeight(this);
    }

    // Appends a built row plus its optional inline editor to the body, both left-aligned. Shared
    // by CategorySection and PinnedSection, which build their own WaypointRow.spec(...) (the spec
    // config differs) but stack rows identically.
    protected void addRow(WaypointRow row, Waypoint w, Function<Waypoint, Component> inlineProvider)
    {
        row.setAlignmentX(LEFT_ALIGNMENT);
        body.add(row);
        if (inlineProvider != null)
        {
            Component inline = inlineProvider.apply(w);
            if (inline != null)
            {
                if (inline instanceof JComponent)
                {
                    ((JComponent) inline).setAlignmentX(LEFT_ALIGNMENT);
                }
                body.add(inline);
            }
        }
    }

    public boolean isCollapsed() { return collapsed; }

    // Flip collapsed state WITHOUT persisting (no onCollapseChange fired). Used by the
    // spring-loaded auto-expand during a drag; persistence happens via confirmTransientExpand()
    // when a drop confirms the expansion.
    public void setExpandedTransient(boolean expanded)
    {
        if (collapsed == !expanded) return;
        collapsed = !expanded;
        body.setVisible(expanded);
        headerLabel.setText(headerText());
        revalidate();
        repaint();
    }

    // Promote a transient expansion to persistent: fire onCollapseChange(false) once so the
    // panel's persisted collapse map reflects "user wants this open". No-op if collapsed.
    public void confirmTransientExpand()
    {
        if (!collapsed) onCollapseChange.accept(false);
    }
}

package com.waypointer.ui;

import com.waypointer.model.Category;
import com.waypointer.model.CategorySortMode;
import com.waypointer.model.Waypoint;
import com.waypointer.model.WorldPointPacker;
import com.waypointer.service.Wilderness;
import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Component;
import java.awt.Cursor;
import java.awt.Dimension;
import java.awt.FlowLayout;
import java.awt.Font;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.util.ArrayList;
import java.util.List;
import java.util.UUID;
import java.util.function.BiConsumer;
import java.util.function.Consumer;
import java.util.function.Function;
import javax.swing.BorderFactory;
import javax.swing.JCheckBoxMenuItem;
import javax.swing.JLabel;
import javax.swing.JMenu;
import javax.swing.JMenuItem;
import javax.swing.JPanel;
import javax.swing.JPopupMenu;
import javax.swing.border.Border;
import net.runelite.client.game.SpriteManager;
import net.runelite.client.ui.ColorScheme;

// Collapsible section: chevron header + body of WaypointRows. Header is a BorderLayout with
// up to three children: optional 16x16 icon on the left, title label in the center (click
// target for collapse, drag source for reorder), and a vertical ellipsis menu trigger on
// the right (rename / delete / set-icon).
public class CategorySection extends CollapsibleSection
{
    private static final int COLOUR_STRIPE_WIDTH = 3;

    private final Category category;

    public CategorySection(Category category, List<Waypoint> waypoints, int activePathTarget,
        boolean collapsed,
        Consumer<Boolean> onCollapseChange,
        BiConsumer<Waypoint, RowAction> onRowAction,
        Function<Waypoint, Component> inlineProvider,
        DragAndDropHandler dnd,
        Actions actions,
        SpriteManager spriteManager,
        boolean selectMode,
        BulkSelection selection,
        BiConsumer<Waypoint, Boolean> onRowSelectClick,
        BiConsumer<List<UUID>, Boolean> onHeaderSelectToggle)
    {
        super(collapsed, onCollapseChange);
        this.category = category;
        Integer accent = category.getColor();
        if (accent != null)
        {
            setBorder(BorderFactory.createCompoundBorder(
                BorderFactory.createMatteBorder(0, COLOUR_STRIPE_WIDTH, 0, 0, new Color(accent)),
                BorderFactory.createEmptyBorder(4, 0, 4, 0)));
        }
        else
        {
            // Reserve the stripe width even when uncoloured so rows don't shift when a colour
            // is set or cleared.
            setBorder(BorderFactory.createEmptyBorder(4, COLOUR_STRIPE_WIDTH, 4, 0));
        }

        JPanel headerRow = buildHeaderRow(waypoints.size());
        final Border restingHeaderBorder = headerRow.getBorder();
        final Color restingHeaderBg = headerRow.getBackground();

        // Drag must come from the label only; on headerRow, a click on the menu trigger
        // would accidentally start a drag.
        DropIndicatable headerIndicator = mode ->
        {
            switch (mode)
            {
                case NONE:
                    headerRow.setBorder(restingHeaderBorder);
                    headerRow.setBackground(restingHeaderBg);
                    break;
                case TINT:
                    headerRow.setBackground(ColorScheme.DARK_GRAY_HOVER_COLOR);
                    break;
                case BORDER_AND_TINT:
                    headerRow.setBorder(BorderFactory.createCompoundBorder(
                        BorderFactory.createMatteBorder(2, 0, 0, 0, ColorScheme.BRAND_ORANGE),
                        restingHeaderBorder == null
                            ? BorderFactory.createEmptyBorder()
                            : restingHeaderBorder));
                    headerRow.setBackground(ColorScheme.DARK_GRAY_HOVER_COLOR);
                    break;
            }
            headerRow.repaint();
        };
        if (dnd != null) dnd.attachCategoryHeader(headerLabel, headerIndicator, category.getId(), this, headerRow);

        // Optional icon on the LEFT of the header row.
        if (!selectMode && category.getIconId() != null && spriteManager != null)
        {
            JLabel iconLabel = new JLabel();
            iconLabel.setPreferredSize(new Dimension(16, 16));
            iconLabel.setOpaque(false);
            SpriteIcons.apply(iconLabel, category.getIconId(), spriteManager);
            headerRow.add(iconLabel, BorderLayout.WEST);
        }

        // Select-mode tri-state checkbox at the header's left edge. Clicking it selects or
        // deselects all of this category's currently-visible waypoints.
        if (selectMode)
        {
            List<UUID> catIds = new ArrayList<>();
            for (Waypoint w : waypoints) catIds.add(w.getId());
            TriStateBox headerBox = new TriStateBox();
            switch (selection.categoryState(catIds))
            {
                case ALL:     headerBox.setState(TriStateBox.State.CHECKED); break;
                case PARTIAL: headerBox.setState(TriStateBox.State.PARTIAL); break;
                default:      headerBox.setState(TriStateBox.State.UNCHECKED); break;
            }
            headerBox.addMouseListener(new MouseAdapter()
            {
                @Override public void mouseClicked(MouseEvent e)
                {
                    boolean allSelected = selection.categoryState(catIds) == BulkSelection.TriState.ALL;
                    onHeaderSelectToggle.accept(catIds, !allSelected);
                }
            });
            JPanel headerWest = new JPanel(new FlowLayout(FlowLayout.CENTER, 0, 0));
            headerWest.setOpaque(false);
            headerWest.setBorder(BorderFactory.createEmptyBorder(0, 2, 0, 2));
            headerWest.add(headerBox);
            headerRow.add(headerWest, BorderLayout.WEST);
        }

        // Build the popup menu and the trigger glyph on the RIGHT.
        if (!category.isUncategorized())
        {
            JPopupMenu menu = new JPopupMenu();
            JMenuItem rename = new JMenuItem("Rename");
            rename.addActionListener(e -> actions.onRename.run());
            JMenuItem setIcon = new JMenuItem("Set icon...");
            setIcon.addActionListener(e -> { if (actions.onSetIcon != null) actions.onSetIcon.run(); });
            JMenuItem setColour = new JMenuItem("Set colour...");
            setColour.addActionListener(e -> { if (actions.onSetColour != null) actions.onSetColour.run(); });

            JMenu sortBy = new JMenu("Sort by");
            CategorySortMode active =
                category.getSortMode() == null ? CategorySortMode.MANUAL : category.getSortMode();
            sortBy.add(buildSortItem("Manual",
                CategorySortMode.MANUAL, active, actions));
            sortBy.add(buildSortItem("Name (A-Z)",
                CategorySortMode.NAME, active, actions));
            sortBy.add(buildSortItem("Date added (newest first)",
                CategorySortMode.DATE_ADDED, active, actions));

            JMenuItem selectMultiple = new JMenuItem("Select multiple");
            selectMultiple.addActionListener(e -> { if (actions.onEnterSelect != null) actions.onEnterSelect.run(); });

            JMenuItem delete = new JMenuItem("Delete category");
            delete.addActionListener(e -> actions.onDelete.run());
            menu.add(rename);
            menu.add(setIcon);
            menu.add(setColour);
            menu.add(sortBy);
            menu.addSeparator();
            menu.add(selectMultiple);
            menu.add(delete);
            // Right-click on the label still opens the popup (legacy discoverability).
            headerLabel.setComponentPopupMenu(menu);

            JLabel menuTrigger = new JLabel("⋮"); // U+22EE vertical ellipsis
            menuTrigger.setForeground(Color.LIGHT_GRAY);
            menuTrigger.setFont(menuTrigger.getFont().deriveFont(Font.BOLD));
            menuTrigger.setBorder(BorderFactory.createEmptyBorder(4, 8, 4, 6));
            menuTrigger.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
            menuTrigger.getAccessibleContext().setAccessibleName("Category options");
            HoverHint.shared().attach(menuTrigger, () -> "Category options");
            menuTrigger.addMouseListener(new MouseAdapter() {
                @Override public void mouseClicked(MouseEvent e)
                {
                    menu.show(menuTrigger, 0, menuTrigger.getHeight());
                }
            });
            headerRow.add(menuTrigger, BorderLayout.EAST);
        }

        add(headerRow, BorderLayout.NORTH);

        // Hide the drag handle when the row can't actually be dragged: either the category
        // sort mode is non-MANUAL (reorder is auto), or the panel passed a null dnd because
        // a search filter is active and drop targets would refer to invisible neighbours.
        boolean sortDisablesDrag = category.getSortMode() != null
            && category.getSortMode() != CategorySortMode.MANUAL;
        boolean dragDisabled = sortDisablesDrag || dnd == null;

        for (Waypoint w : waypoints)
        {
            boolean active = activePathTarget != WorldPointPacker.UNDEFINED
                && w.getPackedWorldPoint() == activePathTarget;
            WaypointRow row = WaypointRow.spec(w)
                .active(active)
                .pinned(w.isPinned())
                .wilderness(Wilderness.isInWilderness(w.getPackedWorldPoint()))
                .dragDisabled(dragDisabled)
                .onPlay(() -> onRowAction.accept(w, RowAction.PLAY))
                .onClickBody(() -> onRowAction.accept(w, RowAction.EXPAND))
                .onTogglePin(() -> onRowAction.accept(w, RowAction.TOGGLE_PIN))
                .onDelete(() -> onRowAction.accept(w, RowAction.DELETE))
                .onEnterSelectMode(() -> onRowAction.accept(w, RowAction.ENTER_SELECT))
                .spriteManager(spriteManager)
                .selectMode(selectMode)
                .selected(selection.ids().contains(w.getId()))
                .onSelectClick(shift -> onRowSelectClick.accept(w, shift))
                .build();
            if (dnd != null) dnd.attachWaypointRow(row, row.getDragHandle(), row, w.getId(), category.getId());
            addRow(row, w, inlineProvider);
        }
        if (waypoints.isEmpty())
        {
            EmptyDropZone empty = new EmptyDropZone();
            body.add(empty);
            // When dnd == null (a search filter is active) the zone is shown for affordance
            // but not wired as a drop target, mirroring the non-empty tail zone.
            if (dnd != null) dnd.attachTailZone(empty, empty, category.getId());
        }
        else
        {
            TailDropZone tail = new TailDropZone();
            body.add(tail);
            if (dnd != null) dnd.attachTailZone(tail, tail, category.getId());
        }
        attachBody();
    }

    @Override
    protected String headerText()
    {
        String chevron = collapsed ? "▶" : "▼";
        return chevron + " " + category.getName();
    }

    public UUID getCategoryId()
    {
        return category.getId();
    }

    private static JMenuItem buildSortItem(String label,
        CategorySortMode mode,
        CategorySortMode active,
        Actions actions)
    {
        JCheckBoxMenuItem item = new JCheckBoxMenuItem(label, mode == active);
        item.addActionListener(e -> {
            if (actions.onSetSortMode != null) actions.onSetSortMode.accept(mode);
        });
        return item;
    }

    /** Row-level user actions plumbed up from {@link WaypointRow} to the panel. */
    public enum RowAction { PLAY, EXPAND, DELETE, TOGGLE_PIN, ENTER_SELECT }

    /** The category-level menu actions, bundled so the constructor stays readable. */
    public static final class Actions
    {
        final Runnable onRename;
        final Runnable onDelete;
        final Runnable onSetIcon;
        final Runnable onSetColour;
        final Consumer<CategorySortMode> onSetSortMode;
        final Runnable onEnterSelect;

        public Actions(Runnable onRename, Runnable onDelete, Runnable onSetIcon,
            Runnable onSetColour,
            Consumer<CategorySortMode> onSetSortMode,
            Runnable onEnterSelect)
        {
            this.onRename = onRename;
            this.onDelete = onDelete;
            this.onSetIcon = onSetIcon;
            this.onSetColour = onSetColour;
            this.onSetSortMode = onSetSortMode;
            this.onEnterSelect = onEnterSelect;
        }
    }

    /**
     * Thin (~8 px) hit zone appended after the last waypoint row in an expanded section.
     * Invisible at rest; paints a 2 px top border in {@link ColorScheme#BRAND_ORANGE}
     * when {@link DropIndicatable#setDropIndicator} is called with
     * {@link DropIndicatorMode#BORDER_AND_TINT}. Mirrors the existing indicator
     * vocabulary from {@code DragAndDropHandler}.
     */
    private static final class TailDropZone extends JPanel implements DropIndicatable
    {
        private static final int HEIGHT = 8;
        private final Border resting;

        TailDropZone()
        {
            setOpaque(false);
            setAlignmentX(LEFT_ALIGNMENT);
            setPreferredSize(new Dimension(0, HEIGHT));
            setMaximumSize(new Dimension(Integer.MAX_VALUE, HEIGHT));
            resting = BorderFactory.createEmptyBorder();
            setBorder(resting);
        }

        @Override
        public void setDropIndicator(DropIndicatorMode mode)
        {
            switch (mode)
            {
                case BORDER_AND_TINT:
                    setBorder(BorderFactory.createMatteBorder(2, 0, 0, 0, ColorScheme.BRAND_ORANGE));
                    break;
                case NONE:
                case TINT:
                default:
                    setBorder(resting);
                    break;
            }
            repaint();
        }
    }

    /**
     * Visible drop affordance shown in place of rows when a category is empty. Carries the
     * "(empty - drag here)" hint with a dashed resting border so it reads as a target, and
     * lights up with the shared orange-top-border + tint vocabulary when a waypoint is dragged
     * over it. Wired through {@link DragAndDropHandler#attachTailZone}, so a drop appends the
     * waypoint to this category -- matching {@link TailDropZone} on non-empty categories.
     */
    private static final class EmptyDropZone extends JPanel implements DropIndicatable
    {
        private final Border resting = BorderFactory.createCompoundBorder(
            BorderFactory.createDashedBorder(Styles.MUTED_TEXT),
            BorderFactory.createEmptyBorder(2, 10, 2, 4));

        EmptyDropZone()
        {
            setLayout(new BorderLayout());
            setOpaque(false);
            setAlignmentX(LEFT_ALIGNMENT);
            setBorder(resting);
            JLabel label = new JLabel("(empty - drag here)");
            label.setForeground(Styles.MUTED_TEXT);
            add(label, BorderLayout.WEST);
        }

        @Override
        public void setDropIndicator(DropIndicatorMode mode)
        {
            switch (mode)
            {
                case BORDER_AND_TINT:
                    setOpaque(true);
                    setBackground(ColorScheme.DARK_GRAY_HOVER_COLOR);
                    setBorder(BorderFactory.createCompoundBorder(
                        BorderFactory.createMatteBorder(2, 0, 0, 0, ColorScheme.BRAND_ORANGE),
                        BorderFactory.createEmptyBorder(2, 10, 2, 4)));
                    break;
                case NONE:
                case TINT:
                default:
                    setOpaque(false);
                    setBorder(resting);
                    break;
            }
            repaint();
        }

        @Override public Dimension getMaximumSize()
        {
            return Styles.capHeight(this);
        }
    }
}

