package com.waypointer.service;

import com.waypointer.model.Category;
import com.waypointer.model.Waypoint;
import java.util.Locale;

// Search-filter logic, factored out of the panel for unit testing. Match scope is
// case-insensitive substring against waypoint name, waypoint notes, and the containing
// category name. A category-name match counts every waypoint in that category.
public final class WaypointFilter
{
    private WaypointFilter() {}

    public static boolean matches(Waypoint w, Category c, String filter)
    {
        if (filter == null || filter.isEmpty()) return true;
        return matchesLowered(w, c, filter.toLowerCase(Locale.ROOT));
    }

    public static boolean categoryNameMatches(Category c, String filter)
    {
        if (filter == null || filter.isEmpty()) return true;
        return categoryNameMatchesLowered(c, filter.toLowerCase(Locale.ROOT));
    }

    // Takes an already-lowercased filter; loweredFilter MUST be .toLowerCase(Locale.ROOT).
    // Used in hot paths so the filter isn't re-lowercased per row.
    public static boolean matchesLowered(Waypoint w, Category c, String loweredFilter)
    {
        if (loweredFilter == null || loweredFilter.isEmpty()) return true;
        if (c != null && c.getName() != null
            && c.getName().toLowerCase(Locale.ROOT).contains(loweredFilter)) return true;
        if (w != null && w.getName() != null
            && w.getName().toLowerCase(Locale.ROOT).contains(loweredFilter)) return true;
        if (w != null && w.getNotes() != null
            && w.getNotes().toLowerCase(Locale.ROOT).contains(loweredFilter)) return true;
        return false;
    }

    public static boolean categoryNameMatchesLowered(Category c, String loweredFilter)
    {
        if (loweredFilter == null || loweredFilter.isEmpty()) return true;
        return c != null && c.getName() != null
            && c.getName().toLowerCase(Locale.ROOT).contains(loweredFilter);
    }
}

package com.waypointer.service;

import com.waypointer.model.WorldPointPacker;
import java.util.UUID;
import java.util.function.Consumer;
import java.util.function.IntFunction;
import java.util.function.Supplier;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.Player;
import net.runelite.api.coords.WorldPoint;
import net.runelite.client.callback.ClientThread;

/**
 * Appends the player's current tile to a route as a waypoint step, naming it with the same
 * smart default the waypoint capture flow uses ({@link WaypointCapture#defaultName(int)}).
 * The tile read touches {@link Client}, which asserts the client thread, so the read runs there.
 */
@Singleton
public class RouteRecorder
{
    private final RouteStore store;
    private final Supplier<WorldPoint> playerLocation;
    // Runs the tile read on the client thread in production; runs inline in tests.
    private final Consumer<Runnable> clientThreadRunner;
    // Maps a packed tile to a default step label (nearest landmark, else coords).
    private final IntFunction<String> nameForPacked;

    /** Production constructor: reads the player tile on the client thread, names via capture. */
    @Inject
    public RouteRecorder(RouteStore store, Client client, ClientThread clientThread,
        WaypointCapture capture)
    {
        this(store, () -> {
            Player p = client.getLocalPlayer();
            return p == null ? null : p.getWorldLocation();
        }, clientThread::invoke, capture::defaultName);
    }

    /** Test constructor: tile and naming supplied directly, captured inline (no client thread). */
    RouteRecorder(RouteStore store, Supplier<WorldPoint> playerLocation,
        IntFunction<String> nameForPacked)
    {
        this(store, playerLocation, Runnable::run, nameForPacked);
    }

    private RouteRecorder(RouteStore store, Supplier<WorldPoint> playerLocation,
        Consumer<Runnable> clientThreadRunner, IntFunction<String> nameForPacked)
    {
        this.store = store;
        this.playerLocation = playerLocation;
        this.clientThreadRunner = clientThreadRunner;
        this.nameForPacked = nameForPacked;
    }

    /**
     * Append the player's current tile as an auto-named waypoint step to {@code routeId}. The
     * store mutation drives the UI refresh, so no listener fire here.
     */
    public void addCurrentLocationTo(UUID routeId)
    {
        if (routeId == null) return;
        clientThreadRunner.accept(() -> {
            WorldPoint wp = playerLocation.get();
            if (wp == null) return;
            int packed = WorldPointPacker.pack(wp);
            store.addWaypointStep(routeId, packed, nameForPacked.apply(packed), null);
        });
    }
}

package com.waypointer.service;

import com.waypointer.model.Waypoint;
import com.waypointer.model.WorldPointPacker;
import java.util.function.Consumer;
import java.util.function.IntConsumer;
import javax.annotation.Nullable;
import javax.inject.Inject;
import javax.inject.Singleton;
import javax.swing.SwingUtilities;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Player;
import net.runelite.api.coords.WorldPoint;
import net.runelite.client.callback.ClientThread;

/**
 * Encapsulates waypoint creation paths so the panel can stay UI-only.
 *
 * Reads of the local player's location must happen on RuneLite's client thread (the assertion
 * {@code must be called on client thread} fires otherwise in dev mode), so the public capture
 * methods are async: they hop to the client thread, read the WorldPoint, then call back on the
 * EDT where Swing components and the WaypointStore can be touched safely.
 */
@Singleton
public class WaypointCapture
{
    private final Client client;
    private final WaypointStore store;
    private final ClientThread clientThread;
    private final LandmarkLookup landmarkLookup;

    @Inject
    public WaypointCapture(Client client, WaypointStore store, ClientThread clientThread,
        LandmarkLookup landmarkLookup)
    {
        this.client = client;
        this.store = store;
        this.clientThread = clientThread;
        this.landmarkLookup = landmarkLookup;
    }

    /**
     * Computes the smart default name for a packed tile. Point hits (a curated entry or a
     * nearby POI) return just the name; area hits (sub-area / city) return name plus coords
     * to disambiguate; no match falls back to coords alone.
     */
    public String defaultName(int packed)
    {
        LookupHit hit = landmarkLookup.lookup(packed);
        int x = WorldPointPacker.getX(packed);
        int y = WorldPointPacker.getY(packed);
        if (hit == null)
        {
            return String.format("(%d, %d)", x, y);
        }
        switch (hit.getTier())
        {
            case CURATED:
            case POI:
                return hit.getName();
            case SUB_AREA:
            case CITY:
            default:
                return String.format("%s (%d, %d)", hit.getName(), x, y);
        }
    }

    /**
     * Reads the local player's tile on the client thread, creates a waypoint in Uncategorized,
     * and invokes {@code onResult} on the EDT with the new waypoint (or null if not logged in).
     */
    public void captureCurrentLocation(Consumer<Waypoint> onResult)
    {
        clientThread.invoke(() -> {
            Integer packed = readCurrentPackedPointOnClientThread();
            SwingUtilities.invokeLater(() ->
                onResult.accept(packed == null ? null : captureFromPackedPoint(packed)));
            return true;
        });
    }

    /**
     * Reads the local player's packed tile on the client thread and invokes {@code onResult}
     * on the EDT with the packed int (or {@link WorldPointPacker#UNDEFINED} if not logged in).
     * Used by recapture flows that don't want to create a new waypoint.
     */
    public void readCurrentLocation(IntConsumer onResult)
    {
        clientThread.invoke(() -> {
            Integer packed = readCurrentPackedPointOnClientThread();
            SwingUtilities.invokeLater(() ->
                onResult.accept(packed == null ? WorldPointPacker.UNDEFINED : packed));
            return true;
        });
    }

    /** Captures from an arbitrary packed point (used by world-map and tile right-click flows). */
    public Waypoint captureFromPackedPoint(int packed)
    {
        String name = defaultName(packed);
        return store.createWaypoint(packed, name, store.getUncategorized().getId());
    }

    /**
     * Caller MUST already be on the client thread. Returns the packed local player tile, or
     * {@code null} if not logged in / player not present.
     */
    @Nullable
    Integer readCurrentPackedPointOnClientThread()
    {
        if (client.getGameState() != GameState.LOGGED_IN) return null;
        Player p = client.getLocalPlayer();
        if (p == null) return null;
        WorldPoint wp = p.getWorldLocation();
        if (wp == null) return null;
        return WorldPointPacker.pack(wp);
    }
}

package com.waypointer.service;

import com.waypointer.WaypointerConfig;
import com.waypointer.model.WorldPointPacker;
import com.waypointer.ui.TabHost;
import javax.inject.Inject;
import javax.inject.Singleton;
import javax.swing.SwingUtilities;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.KeyCode;
import net.runelite.api.MenuAction;
import net.runelite.api.MenuEntry;
import net.runelite.api.Point;
import net.runelite.api.Tile;
import net.runelite.api.coords.LocalPoint;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.events.MenuEntryAdded;
import net.runelite.api.events.MenuOpened;
import net.runelite.api.widgets.ComponentID;
import net.runelite.api.widgets.Widget;
import net.runelite.api.worldmap.WorldMap;
import net.runelite.client.eventbus.Subscribe;

// Adds a "Save as Waypoint" right-click entry in three contexts:
//   1. Over the world-map widget (Shift held); converts cursor canvas position to a world tile.
//   2. On a 3D-world tile when the corresponding config is on (Shift held).
//   3. On an NPC or game object when the corresponding config is on. Objects require Shift;
//      NPCs do not, because holding Shift hides NPCs from selection.
// Mirrors the world-map coord math from shortest-path's ShortestPathPlugin#calculateMapPoint.
@Slf4j
@Singleton
@SuppressWarnings("deprecation") // ComponentID + getSelectedSceneTile still used by shortest-path; migrate together later.
public class WaypointMenuHandler
{
    private static final String OPTION = "Save as Waypoint";
    private static final String TARGET = "<col=ff9040>Waypointer</col>";

    private final Client client;
    private final WaypointerConfig config;
    private final TabHost tabHost;

    private Point lastMenuOpenedPoint;

    @Inject
    public WaypointMenuHandler(Client client, WaypointerConfig config, TabHost tabHost)
    {
        this.client = client;
        this.config = config;
        this.tabHost = tabHost;
    }

    @Subscribe
    public void onMenuOpened(MenuOpened event)
    {
        // Cache the cursor position at menu-open time; by the time the user clicks "Save as
        // Waypoint" the cursor has moved. Mirrors shortest-path.
        lastMenuOpenedPoint = client.getMouseCanvasPosition();
    }

    @Subscribe
    public void onMenuEntryAdded(MenuEntryAdded event)
    {
        if (tryAddWorldMapEntry()) return;
        if (tryAddTileEntry(event)) return;
        tryAddEntityEntry(event);
    }

    private boolean tryAddWorldMapEntry()
    {
        if (!client.isKeyPressed(KeyCode.KC_SHIFT)) return false;
        Widget map = client.getWidget(ComponentID.WORLD_MAP_MAPVIEW);
        if (map == null) return false;
        Point mouse = client.getMouseCanvasPosition();
        if (mouse == null) return false;
        if (!map.getBounds().contains(mouse.getX(), mouse.getY())) return false;
        addEntry(0, this::onSaveFromMap);
        return true;
    }

    private boolean tryAddTileEntry(MenuEntryAdded event)
    {
        if (!config.tileRightClickEnabled()) return false;
        if (!client.isKeyPressed(KeyCode.KC_SHIFT)) return false;
        if (event.getType() != MenuAction.WALK.getId()) return false;
        addEntry(1, this::onSaveFromTile);
        return true;
    }

    private void tryAddEntityEntry(MenuEntryAdded event)
    {
        if (!config.entityRightClickEnabled()) return;

        MenuEntry source = event.getMenuEntry();
        net.runelite.api.NPC npc = source.getNpc();
        if (npc != null)
        {
            // No Shift gate for NPCs: holding Shift in RuneLite suppresses NPC hover and
            // selection, so a Shift-only entry could never be reached. The entry appears on a
            // plain right-click whenever the setting is on.
            addEntry(1, e -> onSaveFromNpc(npc));
            return;
        }
        // Objects keep the Shift gate so the entry doesn't crowd ordinary object menus.
        if (!client.isKeyPressed(KeyCode.KC_SHIFT)) return;
        if (isObjectAction(source.getType()))
        {
            int sceneX = source.getParam0();
            int sceneY = source.getParam1();
            int plane = client.getPlane();
            String name = net.runelite.client.util.Text.removeTags(source.getTarget());
            addEntry(1, e -> onSaveFromObject(sceneX, sceneY, plane, name));
        }
    }

    private static boolean isObjectAction(MenuAction type)
    {
        return type == MenuAction.GAME_OBJECT_FIRST_OPTION
            || type == MenuAction.GAME_OBJECT_SECOND_OPTION
            || type == MenuAction.GAME_OBJECT_THIRD_OPTION
            || type == MenuAction.GAME_OBJECT_FOURTH_OPTION
            || type == MenuAction.GAME_OBJECT_FIFTH_OPTION;
    }

    private void addEntry(int idx, java.util.function.Consumer<MenuEntry> onClick)
    {
        // MenuEntryAdded fires once per game-generated entry every cycle, so a menu with
        // several entries would otherwise accumulate one "Save as Waypoint" per entry.
        // Bail if ours is already present this cycle. Mirrors shortest-path's addMenuEntry.
        for (MenuEntry existing : client.getMenu().getMenuEntries())
        {
            if (OPTION.equals(existing.getOption()) && TARGET.equals(existing.getTarget()))
            {
                return;
            }
        }
        client.getMenu().createMenuEntry(idx)
            .setOption(OPTION)
            .setTarget(TARGET)
            .setType(MenuAction.RUNELITE)
            .onClick(onClick::accept);
    }

    private void onSaveFromMap(MenuEntry entry)
    {
        Point p = lastMenuOpenedPoint != null ? lastMenuOpenedPoint : client.getMouseCanvasPosition();
        if (p == null) return;
        int packed = calculateMapPoint(p.getX(), p.getY());
        if (packed == WorldPointPacker.UNDEFINED) return;
        openCapture(packed);
    }

    private void onSaveFromTile(MenuEntry entry)
    {
        Tile tile = client.getSelectedSceneTile();
        if (tile == null) return;
        LocalPoint local = tile.getLocalLocation();
        if (local == null) return;
        WorldPoint wp = WorldPoint.fromLocalInstance(client, local);
        if (wp == null) return;
        openCapture(WorldPointPacker.pack(wp));
    }

    private void onSaveFromNpc(net.runelite.api.NPC npc)
    {
        // Menu click callbacks run on the client thread, so reading the NPC location is safe.
        WorldPoint wp = npc.getWorldLocation();
        if (wp == null) return;
        String npcName = npc.getName();
        openCapture(WorldPointPacker.pack(wp), npcName, npcName);
    }

    private void onSaveFromObject(int sceneX, int sceneY, int plane, String name)
    {
        WorldPoint wp = WorldPoint.fromScene(client, sceneX, sceneY, plane);
        if (wp == null) return;
        openCapture(WorldPointPacker.pack(wp), name, null);
    }

    private void openCapture(int packed)
    {
        openCapture(packed, null, null);
    }

    private void openCapture(int packed, String defaultName, String targetNpcName)
    {
        if (packed == WorldPointPacker.UNDEFINED) return;
        SwingUtilities.invokeLater(() -> tabHost.openToCapture(packed, defaultName, targetNpcName));
    }

    // Converts canvas (x, y) over the world map widget to a packed WorldPoint.
    // Faithful copy of shortest-path's calculateMapPoint.
    int calculateMapPoint(int pointX, int pointY)
    {
        WorldMap worldMap = client.getWorldMap();
        if (worldMap == null) return WorldPointPacker.UNDEFINED;
        float zoom = worldMap.getWorldMapZoom();
        if (zoom <= 0f) return WorldPointPacker.UNDEFINED;

        Point centerWp = worldMap.getWorldMapPosition();
        if (centerWp == null) return WorldPointPacker.UNDEFINED;
        int centerPacked = WorldPointPacker.pack(centerWp.getX(), centerWp.getY(), 0);
        int middleX = mapWorldPointToGraphicsPointX(centerPacked);
        int middleY = mapWorldPointToGraphicsPointY(centerPacked);
        if (pointX == Integer.MIN_VALUE || pointY == Integer.MIN_VALUE
            || middleX == Integer.MIN_VALUE || middleY == Integer.MIN_VALUE)
        {
            return WorldPointPacker.UNDEFINED;
        }
        int dx = (int) ((pointX - middleX) / zoom);
        int dy = (int) ((-(pointY - middleY)) / zoom);
        int x = WorldPointPacker.getX(centerPacked) + dx;
        int y = WorldPointPacker.getY(centerPacked) + dy;
        if (x < 0 || y < 0) return WorldPointPacker.UNDEFINED;
        return WorldPointPacker.pack(x, y, 0);
    }

    private int mapWorldPointToGraphicsPointX(int packed)
    {
        WorldMap worldMap = client.getWorldMap();
        Widget map = client.getWidget(ComponentID.WORLD_MAP_MAPVIEW);
        if (worldMap == null || map == null) return Integer.MIN_VALUE;
        float zoom = worldMap.getWorldMapZoom();
        Point center = worldMap.getWorldMapPosition();
        if (center == null) return Integer.MIN_VALUE;
        int dx = WorldPointPacker.getX(packed) - center.getX();
        return (int) (map.getBounds().x + map.getBounds().width / 2.0f + dx * zoom);
    }

    private int mapWorldPointToGraphicsPointY(int packed)
    {
        WorldMap worldMap = client.getWorldMap();
        Widget map = client.getWidget(ComponentID.WORLD_MAP_MAPVIEW);
        if (worldMap == null || map == null) return Integer.MIN_VALUE;
        float zoom = worldMap.getWorldMapZoom();
        Point center = worldMap.getWorldMapPosition();
        if (center == null) return Integer.MIN_VALUE;
        int dy = WorldPointPacker.getY(packed) - center.getY();
        return (int) (map.getBounds().y + map.getBounds().height / 2.0f - dy * zoom);
    }
}

package com.waypointer.service;

import com.waypointer.codec.RouteJsonCodec;
import com.waypointer.model.route.RouteLibrary;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.config.ConfigManager;

/**
 * Account-global route persistence backed by the RuneLite config system, replacing the old on-disk
 * routes.json. Stores a single JSON blob under (group {@code waypointer}, key {@code routes}). A
 * decode failure freezes saves until the routes reset banner clears it.
 */
@Slf4j
@Singleton
public class RouteStorePersistence
{
    static final String GROUP = "waypointer";
    static final String KEY = "routes";

    private final ConfigManager configManager;
    private final RouteJsonCodec codec;
    private volatile boolean refuseSavesUntilReset = false;

    @Inject
    public RouteStorePersistence(ConfigManager configManager, RouteJsonCodec codec)
    {
        this.configManager = configManager;
        this.codec = codec;
    }

    public RouteLibrary load()
    {
        String json = configManager.getConfiguration(GROUP, KEY);
        if (json == null || json.isEmpty()) return new RouteLibrary();
        try
        {
            return codec.decode(json);
        }
        catch (RuntimeException e)
        {
            log.error("Routes config value unreadable; refusing saves until reset", e);
            refuseSavesUntilReset = true;
            return new RouteLibrary();
        }
    }

    public void save(RouteLibrary lib)
    {
        if (refuseSavesUntilReset)
        {
            log.warn("Route save refused: config is in a corrupt state pending reset");
            return;
        }
        configManager.setConfiguration(GROUP, KEY, codec.encode(lib));
    }

    public void clear()
    {
        configManager.unsetConfiguration(GROUP, KEY);
        refuseSavesUntilReset = false;
    }

    public boolean isRefusingSaves() { return refuseSavesUntilReset; }

    public void allowSavesAfterReset() { refuseSavesUntilReset = false; }
}

package com.waypointer.service;

import com.google.gson.Gson;
import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.Reader;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;

/** Loads icon-categories.json once and exposes it as an ordered list of named categories.
 *  Each category is a sorted, immutable list of sprite ids. Used by IconPickerDialog so the
 *  user sees a curated set rather than every SpriteID. Returns an empty list if the resource
 *  is missing or malformed; the picker then shows no categories ("None" stays selectable). */
@Singleton
@Slf4j
public final class IconCatalog
{
    private static final String RESOURCE = "/com/waypointer/icon-categories.json";

    private final List<Category> categories;

    @Inject
    public IconCatalog(Gson gson)
    {
        this.categories = Collections.unmodifiableList(load(gson));
    }

    public List<Category> getCategories() { return categories; }

    private static List<Category> load(Gson gson)
    {
        try (InputStream in = IconCatalog.class.getResourceAsStream(RESOURCE))
        {
            if (in == null)
            {
                log.warn("Icon catalog resource not found: {}", RESOURCE);
                return new ArrayList<>();
            }
            try (Reader r = new InputStreamReader(in, StandardCharsets.UTF_8))
            {
                JsonObject root = gson.fromJson(r, JsonObject.class);
                if (root == null || !root.has("categories")) return new ArrayList<>();
                JsonArray cats = root.getAsJsonArray("categories");
                List<Category> out = new ArrayList<>(cats.size());
                for (JsonElement el : cats)
                {
                    if (!el.isJsonObject()) continue;
                    JsonObject co = el.getAsJsonObject();
                    String name = co.has("name") ? co.get("name").getAsString() : "";
                    if (name.isEmpty()) continue;
                    JsonArray icons = co.has("icons") ? co.getAsJsonArray("icons") : new JsonArray();
                    List<Integer> ids = new ArrayList<>(icons.size());
                    for (JsonElement ic : icons)
                    {
                        if (!ic.isJsonObject()) continue;
                        JsonObject io = ic.getAsJsonObject();
                        if (!io.has("id")) continue;
                        try { ids.add(io.get("id").getAsInt()); }
                        catch (Exception ignored) {}
                    }
                    Collections.sort(ids);
                    out.add(new Category(name, Collections.unmodifiableList(ids)));
                }
                return out;
            }
        }
        catch (Exception e)
        {
            log.warn("Failed to load icon catalog; icon picker will show no categories.", e);
            return new ArrayList<>();
        }
    }

    public static final class Category
    {
        private final String name;
        private final List<Integer> spriteIds;

        Category(String name, List<Integer> spriteIds)
        {
            this.name = name;
            this.spriteIds = spriteIds;
        }

        public String getName() { return name; }
        public List<Integer> getSpriteIds() { return spriteIds; }
    }
}

package com.waypointer.service;

import java.util.Objects;

public final class LookupHit
{
    public enum Tier { CURATED, POI, SUB_AREA, CITY }

    private final String name;
    private final Tier tier;

    public LookupHit(String name, Tier tier)
    {
        this.name = name;
        this.tier = tier;
    }

    public String getName() { return name; }
    public Tier getTier() { return tier; }

    @Override
    public boolean equals(Object o)
    {
        if (this == o) return true;
        if (!(o instanceof LookupHit)) return false;
        LookupHit h = (LookupHit) o;
        return Objects.equals(name, h.name) && tier == h.tier;
    }

    @Override
    public int hashCode() { return Objects.hash(name, tier); }

    @Override
    public String toString() { return name + " (" + tier + ")"; }
}

package com.waypointer.service;

import com.waypointer.model.Category;
import com.waypointer.model.Library;
import com.waypointer.model.Waypoint;
import java.util.HashSet;
import java.util.Set;
import java.util.UUID;

/**
 * Builds a fresh {@link Library} holding a chosen subset of an existing library's waypoints and
 * categories. Stateless and side-effect-free: it never mutates {@code source}, and copies every
 * model object it carries over. Shared by the export picker, the import picker, and bulk export.
 */
public final class LibrarySubsetBuilder
{
    private LibrarySubsetBuilder() {}

    /**
     * @param source       library to copy from; left untouched.
     * @param waypointIds  ids of waypoints to include (null treated as empty).
     * @param categoryIds  ids of categories to include even when they carry no selected
     *                     waypoint (null treated as empty). A category referenced by an
     *                     included waypoint is pulled in regardless of this set, so the
     *                     receiving {@code importMerge} can rebind by name.
     * @return a new library (schemaVersion = CURRENT) with copied categories + waypoints.
     */
    public static Library build(Library source, Set<UUID> waypointIds, Set<UUID> categoryIds)
    {
        Set<UUID> wantWaypoints = waypointIds == null ? new HashSet<>() : new HashSet<>(waypointIds);
        Set<UUID> wantCategories = categoryIds == null ? new HashSet<>() : new HashSet<>(categoryIds);

        Library out = new Library();
        for (Waypoint w : source.getWaypoints())
        {
            if (wantWaypoints.contains(w.getId()))
            {
                out.getWaypoints().add(copyOf(w));
                wantCategories.add(w.getCategoryId());
            }
        }
        // Waypoints whose categoryId has no matching Category in source carry no category row;
        // importMerge will route them to Uncategorized on the receiving end.
        for (Category c : source.getCategories())
        {
            if (wantCategories.contains(c.getId()))
            {
                out.getCategories().add(copyOf(c));
            }
        }
        return out;
    }

    private static Waypoint copyOf(Waypoint w)
    {
        return new Waypoint(
            w.getId(), w.getName(), w.getPackedWorldPoint(), w.getCategoryId(),
            w.getIconId(), w.getNotes(), w.getCreatedAt(), w.getSortOrder(),
            w.isPinned(), w.getPinnedAt(), w.isBypassWildernessConfirm());
    }

    private static Category copyOf(Category c)
    {
        Category copy = new Category(c.getId(), c.getName(), c.getSortOrder(),
            c.isUncategorized(), c.getIconId(), c.isBundled());
        copy.setSortMode(c.getSortMode());
        return copy;
    }
}

package com.waypointer.service;

import com.waypointer.WaypointerConfig;
import com.waypointer.model.WorldPointPacker;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.Player;
import net.runelite.api.WorldView;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.events.ActorDeath;
import net.runelite.client.eventbus.Subscribe;

/**
 * Starts a path back to the tile the local player died on. Off by default; enabled via the
 * "Auto-path to death location" config toggle. Detection bridges {@link ActorDeath} to the
 * Shortest Path plugin through {@link WaypointPathfinder}.
 */
@Singleton
public class DeathAutoPathfinder
{
    private static final String DEATH_DESTINATION_NAME = "Death location";

    private final Client client;
    private final WaypointPathfinder pathfinder;
    private final WaypointerConfig config;

    @Inject
    public DeathAutoPathfinder(Client client, WaypointPathfinder pathfinder, WaypointerConfig config)
    {
        this.client = client;
        this.pathfinder = pathfinder;
        this.config = config;
    }

    @Subscribe
    public void onActorDeath(ActorDeath e)
    {
        if (!config.autoPathOnDeath()) return;
        if (!pathfinder.isAvailable()) return;

        Player local = client.getLocalPlayer();
        // Only the local player's death matters; ActorDeath also fires for NPCs and other players.
        if (local == null || e.getActor() != local) return;

        // Instance coords don't map to real-world tiles, and instances have no death-tile
        // gravestone (items go to Death's office / the instance exit), so pathing would target
        // a meaningless tile.
        WorldView worldView = client.getTopLevelWorldView();
        if (worldView != null && worldView.isInstance()) return;

        WorldPoint deathLocation = local.getWorldLocation();
        if (deathLocation == null) return;

        // requestPath bypasses the wilderness-confirm gate (that lives in the panel's row
        // handler), which is the intended "auto-path anyway, no dialog" behavior on death.
        pathfinder.requestPath(WorldPointPacker.pack(deathLocation), DEATH_DESTINATION_NAME);
    }
}

package com.waypointer.service;

import com.waypointer.model.WorldPointPacker;
import com.waypointer.util.Listeners;
import java.io.BufferedReader;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.Collection;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import javax.annotation.Nullable;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;

@Slf4j
@Singleton
public class BboxIndex
{
    private static final class ResourceEntry
    {
        final String path;
        @Nullable
        final LandmarkType type;

        ResourceEntry(String path, @Nullable LandmarkType type)
        {
            this.path = path;
            this.type = type;
        }
    }

    private static final ResourceEntry[] RESOURCES = {
        new ResourceEntry("/com/waypointer/landmarks/banks-bboxes.tsv",          LandmarkType.BANK),
        new ResourceEntry("/com/waypointer/landmarks/bank-chests-bboxes.tsv",    LandmarkType.BANK),
        new ResourceEntry("/com/waypointer/landmarks/altars-bboxes.tsv",         LandmarkType.ALTAR),
        new ResourceEntry("/com/waypointer/landmarks/anvils-bboxes.tsv",         LandmarkType.ANVIL),
        new ResourceEntry("/com/waypointer/landmarks/furnaces-bboxes.tsv",       LandmarkType.FURNACE),
        new ResourceEntry("/com/waypointer/landmarks/looms-bboxes.tsv",          LandmarkType.LOOM),
        new ResourceEntry("/com/waypointer/landmarks/spinning-wheels-bboxes.tsv", LandmarkType.SPINNING_WHEEL),
        new ResourceEntry("/com/waypointer/landmarks/tanners-bboxes.tsv",        LandmarkType.TANNER),
        new ResourceEntry("/com/waypointer/landmarks/spirit-trees-bboxes.tsv",   LandmarkType.SPIRIT_TREE),
        new ResourceEntry("/com/waypointer/landmarks/charter-ships-bboxes.tsv",  LandmarkType.CHARTER_SHIP),
        new ResourceEntry("/com/waypointer/landmarks/fairy-rings-bboxes.tsv",    LandmarkType.FAIRY_RING),
        new ResourceEntry("/com/waypointer/landmarks/slayer-masters-bboxes.tsv", LandmarkType.SLAYER_MASTER),
        new ResourceEntry("/com/waypointer/landmarks/landmarks-bboxes.tsv",      null),
    };

    public static final class Entry
    {
        public final int x1, y1, x2, y2, plane, area;
        public final String name;
        @Nullable
        public final LandmarkType type;

        Entry(int x1, int y1, int x2, int y2, int plane, String name)
        {
            this(x1, y1, x2, y2, plane, name, null);
        }

        Entry(int x1, int y1, int x2, int y2, int plane, String name,
            @Nullable LandmarkType type)
        {
            this.x1 = x1;
            this.y1 = y1;
            this.x2 = x2;
            this.y2 = y2;
            this.plane = plane;
            this.name = name;
            this.type = type;
            this.area = (x2 - x1 + 1) * (y2 - y1 + 1);
        }
    }

    private final Map<Integer, List<Entry>> byPlane = new HashMap<>();
    private final Listeners listeners = new Listeners();
    private int total;

    @Inject
    public BboxIndex()
    {
        for (ResourceEntry res : RESOURCES) loadResource(res);
        log.info("BboxIndex loaded {} bbox entries across {} planes", total, byPlane.size());
    }

    private BboxIndex(boolean skipResourceLoad)
    {
        // Test seam: forTesting() builds an index from explicit entries.
    }

    public Listeners.Subscription subscribe(Runnable r)
    {
        return listeners.subscribe(r);
    }

    static BboxIndex forTesting(Collection<Entry> entries)
    {
        BboxIndex idx = new BboxIndex(true);
        for (Entry e : entries) idx.addEntry(e);
        return idx;
    }

    @Nullable
    public String lookup(int packedPoint)
    {
        int x = WorldPointPacker.getX(packedPoint);
        int y = WorldPointPacker.getY(packedPoint);
        int plane = WorldPointPacker.getPlane(packedPoint);
        List<Entry> candidates = byPlane.get(plane);
        if (candidates == null) return null;

        Entry best = null;
        for (Entry e : candidates)
        {
            if (x < e.x1 || x > e.x2 || y < e.y1 || y > e.y2) continue;
            if (best == null || e.area < best.area) best = e;
        }
        return best == null ? null : best.name;
    }

    public static final class Hit
    {
        public final int packed;
        public final String name;
        public final int distance;

        public Hit(int packed, String name, int distance)
        {
            this.packed = packed;
            this.name = name;
            this.distance = distance;
        }
    }

    /**
     * Returns the entry of the requested type whose bbox is closest to {@code fromPacked}
     * in Chebyshev tile distance, plane-agnostic. Distance ranks by the nearest part of the
     * bbox (clamped), but the returned {@link Hit#packed} is the bbox CENTRE tile, carrying the
     * bbox's plane -- quick-nav should walk you to the middle of the landmark, not to a corner
     * of its bounding box. Returns null if the index holds no entries of that type.
     */
    @Nullable
    public Hit nearest(LandmarkType type, int fromPacked)
    {
        int fx = WorldPointPacker.getX(fromPacked);
        int fy = WorldPointPacker.getY(fromPacked);

        Entry best = null;
        int bestDist = Integer.MAX_VALUE;

        for (List<Entry> bucket : byPlane.values())
        {
            for (Entry e : bucket)
            {
                if (e.type != type) continue;
                int cx = Math.max(e.x1, Math.min(fx, e.x2));
                int cy = Math.max(e.y1, Math.min(fy, e.y2));
                int dx = Math.abs(cx - fx);
                int dy = Math.abs(cy - fy);
                int d = Math.max(dx, dy);
                if (d < bestDist)
                {
                    bestDist = d;
                    best = e;
                }
            }
        }
        if (best == null) return null;
        int centreX = (best.x1 + best.x2) / 2;
        int centreY = (best.y1 + best.y2) / 2;
        return new Hit(WorldPointPacker.pack(centreX, centreY, best.plane), best.name, bestDist);
    }

    private void addEntry(Entry e)
    {
        addEntryInternal(e);
    }

    private void addEntryInternal(Entry e)
    {
        byPlane.computeIfAbsent(e.plane, k -> new ArrayList<>()).add(e);
        total++;
    }

    private void loadResource(ResourceEntry res)
    {
        try (InputStream in = BboxIndex.class.getResourceAsStream(res.path))
        {
            if (in == null)
            {
                log.warn("Bbox resource not found: {}", res.path);
                return;
            }
            try (BufferedReader r = new BufferedReader(new InputStreamReader(in, StandardCharsets.UTF_8)))
            {
                String line;
                while ((line = r.readLine()) != null)
                {
                    if (line.isEmpty() || line.startsWith("#")) continue;
                    int tab = line.indexOf('\t');
                    if (tab < 0) continue;
                    String coordPart = line.substring(0, tab).trim();
                    String name = line.substring(tab + 1).trim();
                    if (name.isEmpty()) continue;
                    String[] parts = coordPart.split("\\s+");
                    if (parts.length < 5) continue;
                    try
                    {
                        int x1 = Integer.parseInt(parts[0]);
                        int y1 = Integer.parseInt(parts[1]);
                        int x2 = Integer.parseInt(parts[2]);
                        int y2 = Integer.parseInt(parts[3]);
                        int plane = Integer.parseInt(parts[4]);
                        addEntry(new Entry(x1, y1, x2, y2, plane, name, res.type));
                    }
                    catch (NumberFormatException ex)
                    {
                        log.warn("Malformed bbox row in {}: {}", res.path, line);
                    }
                }
            }
        }
        catch (Exception e)
        {
            log.warn("Failed to load bbox resource {}", res.path, e);
        }
    }
}

package com.waypointer.service;

import com.waypointer.preset.Preset;
import com.waypointer.preset.PresetWaypoint;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.Objects;

// Stateless resolver: given currently-known presets and imported presets, compute conflicts
// (same category+name) and staged adds. Caller iterates conflicts() and calls resolve() for
// each; staged() returns the final list of imports to apply.
public final class PresetImportResolver
{
    public enum Choice { KEEP_EXISTING, REPLACE, SKIP }

    public static final class PendingConflict
    {
        public final String category;
        public final PresetWaypoint imported;
        public final PresetWaypoint existing;
        PendingConflict(String c, PresetWaypoint imp, PresetWaypoint ex)
        {
            this.category = c;
            this.imported = imp;
            this.existing = ex;
        }
    }

    private final List<PendingConflict> conflicts = new ArrayList<>();
    private final List<PresetWaypoint> staged = new ArrayList<>();
    private final Map<String, List<PresetWaypoint>> currentByCat = new HashMap<>();

    public PresetImportResolver(List<Preset> current, List<Preset> imported)
    {
        for (Preset p : current) currentByCat.put(p.getCategory(), p.getWaypoints());
        for (Preset p : imported)
        {
            List<PresetWaypoint> existing = currentByCat.getOrDefault(p.getCategory(), new ArrayList<>());
            for (PresetWaypoint imp : p.getWaypoints())
            {
                PresetWaypoint dup = findByName(existing, imp.getName());
                if (dup == null) staged.add(imp);
                else conflicts.add(new PendingConflict(p.getCategory(), imp, dup));
            }
        }
    }

    public List<PendingConflict> conflicts() { return conflicts; }
    public List<PresetWaypoint> staged() { return staged; }

    public void resolve(PendingConflict c, Choice choice)
    {
        if (choice == Choice.REPLACE) staged.add(c.imported);
    }

    private static PresetWaypoint findByName(List<PresetWaypoint> list, String name)
    {
        for (PresetWaypoint w : list) if (Objects.equals(w.getName(), name)) return w;
        return null;
    }
}

package com.waypointer.service;

import com.waypointer.model.Category;
import com.waypointer.model.CategorySortMode;
import com.waypointer.model.Library;
import com.waypointer.model.Waypoint;
import com.waypointer.util.Listeners;
import java.time.Instant;
import java.util.ArrayList;
import java.util.Collection;
import java.util.Collections;
import java.util.Comparator;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.UUID;
import java.util.stream.Collectors;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;

/**
 * In-memory CRUD over a {@link Library}. Mutations are confined to the EDT and notify
 * registered listeners synchronously. Persistence is layered on by
 * {@link WaypointStorePersistence}.
 */
@Slf4j
@Singleton
public class WaypointStore
{
    private static final String UNCATEGORIZED_NAME = "Uncategorized";

    /**
     * Live in-memory library. {@code volatile} for safe publication of the reference to the
     * render thread's NPC-name snapshot reads; multi-step mutations remain EDT-confined.
     */
    private volatile Library library = new Library();
    private final Listeners listeners = new Listeners();
    private final LibraryViews views = new LibraryViews(() -> library);

    // Packed-point -> NPC name for waypoints that target an NPC. Read from the client thread by
    // NpcHighlightOverlay.render() (~50fps); rebuilt eagerly on every mutation in fireChanged().
    // volatile so the eagerly-built reference publishes safely to the render thread without the
    // overlay copying the live (EDT-mutated) waypoint list each frame.
    private volatile Map<Integer, String> npcNamesByPacked = Collections.emptyMap();

    /**
     * Single-slot undo buffer. Holds the inverse of the most recent destructive op
     * ({@link #deleteWaypoint(UUID)}, {@link #deleteWaypoints(Collection)},
     * {@link #updateWaypointPoint(UUID, int)}, {@link #deleteCategory(UUID, boolean)}), each of
     * which arms it via {@link #armUndoAndNotify(Runnable)}. Every other successful mutation goes
     * through {@link #notifyChanged()}, which clears the slot. A mutation that no-ops or is
     * rejected before firing leaves the slot untouched. Survives toast hide; does not survive
     * plugin disable/enable.
     */
    private Runnable lastUndo;

    /**
     * Default notify path for every mutation: clears the undo slot, then fires. Clearing here
     * makes "no undo" the default for any successful mutation that fires listeners. Methods that
     * want their inverse to survive must opt in via {@link #armUndoAndNotify(Runnable)} instead.
     */
    private void notifyChanged()
    {
        lastUndo = null;
        fireChanged();
    }

    /** Arms the single-slot undo buffer with {@code inverse}, then fires without clearing it. */
    private void armUndoAndNotify(Runnable inverse)
    {
        lastUndo = inverse;
        fireChanged();
    }

    private void fireChanged()
    {
        views.invalidate();
        rebuildNpcNameSnapshot();
        listeners.fire();
    }

    // Eagerly rebuild the packed->NPC-name snapshot on the mutating thread (the live list is only
    // touched here, where mutation is single-threaded). Most waypoints are plain tiles, so the map
    // is typically tiny. Published via the volatile field for the render thread.
    private void rebuildNpcNameSnapshot()
    {
        Map<Integer, String> snapshot = new HashMap<>();
        for (Waypoint w : library.getWaypoints())
        {
            // If two NPC waypoints share a packed tile, last in list order wins. Duplicates are
            // rare and either choice is arbitrary; this just avoids a surprised future reader.
            if (w.getTargetNpcName() != null)
            {
                snapshot.put(w.getPackedWorldPoint(), w.getTargetNpcName());
            }
        }
        npcNamesByPacked = Collections.unmodifiableMap(snapshot);
    }

    @Inject
    public WaypointStore() {}

    /** Initializes the store with a library, ensuring the Uncategorized sentinel is present. */
    public void bootstrap(Library lib)
    {
        this.library = lib;
        ensureUncategorized();
        // Notify so any listener attached before bootstrap (e.g. the panel built by Guice
        // before WaypointerPlugin.startUp() calls bootstrap with the loaded library) re-renders
        // against the freshly-loaded data.
        notifyChanged();
    }

    // Live in-memory library. NOT a defensive copy; callers that mutate it bypass listeners
    // and risk corrupting state. Read-only outside of test fixtures.
    public Library getLibrary() { return library; }

    /**
     * Current packed-point -> NPC-name snapshot. Backed by a volatile reference rebuilt on every
     * mutation, so it is safe to read from the client thread. Never mutated after publication.
     */
    public Map<Integer, String> npcNamesSnapshot()
    {
        return npcNamesByPacked;
    }

    public Category getUncategorized()
    {
        return library.getCategories().stream()
            .filter(Category::isUncategorized)
            .findFirst()
            .orElseThrow(() -> new IllegalStateException("Uncategorized sentinel missing"));
    }

    public Category getCategoryById(UUID id) { return views.getCategoryById(id); }

    public Category getCategoryByName(String name)
    {
        return library.getCategories().stream()
            .filter(c -> c.getName().equalsIgnoreCase(name))
            .findFirst().orElse(null);
    }

    public Waypoint getWaypointById(UUID id) { return views.getWaypointById(id); }

    /** True if any saved waypoint sits on {@code packed}. Used to suppress the path banner when
     *  the active target already has a row whose Play/Stop button covers it. */
    public boolean hasWaypointAt(int packed)
    {
        return library.getWaypoints().stream().anyMatch(w -> w.getPackedWorldPoint() == packed);
    }

    public List<Category> getCategoriesOrdered() { return views.getCategoriesOrdered(); }

    public List<Waypoint> getWaypointsInCategory(UUID categoryId) { return views.getWaypointsInCategory(categoryId); }

    public Category createCategory(String name)
    {
        if (getCategoryByName(name) != null)
        {
            throw new IllegalArgumentException("Category name already exists: " + name);
        }
        int nextOrder = library.getCategories().stream()
            .mapToInt(Category::getSortOrder).max().orElse(-1) + 1;
        Category c = new Category(UUID.randomUUID(), name, nextOrder, false, null, false);
        library.getCategories().add(c);
        notifyChanged();
        return c;
    }

    public void renameCategory(UUID id, String newName)
    {
        Category c = getCategoryById(id);
        if (c == null) return;
        if (c.isUncategorized())
        {
            throw new IllegalArgumentException("Cannot rename Uncategorized");
        }
        Category collision = getCategoryByName(newName);
        if (collision != null && !collision.getId().equals(id))
        {
            throw new IllegalArgumentException("Category name already exists: " + newName);
        }
        c.setName(newName);
        notifyChanged();
    }

    public void deleteCategory(UUID id, boolean moveChildrenToUncategorized)
    {
        Category c = getCategoryById(id);
        if (c == null)
        {
            return;
        }
        if (c.isUncategorized())
        {
            throw new IllegalArgumentException("Cannot delete Uncategorized");
        }
        Category snapshotCategory = c;
        Runnable inverse;
        if (moveChildrenToUncategorized)
        {
            // Capture each affected waypoint's previous categoryId AND sortOrder so the
            // undo restores them exactly. The destructive path overwrites BOTH below.
            List<Waypoint> affected = new ArrayList<>(getWaypointsInCategory(id));
            Map<UUID, Integer> prevSort = new HashMap<>();
            for (Waypoint w : affected) prevSort.put(w.getId(), w.getSortOrder());

            UUID uId = getUncategorized().getId();
            int nextOrder = nextWaypointSortOrder(uId);
            for (Waypoint w : affected)
            {
                w.setCategoryId(uId);
                w.setSortOrder(nextOrder++);
            }
            library.getCategories().removeIf(cc -> cc.getId().equals(id));

            UUID origCategoryId = id;
            inverse = () -> {
                library.getCategories().add(snapshotCategory);
                for (Waypoint w : affected)
                {
                    w.setCategoryId(origCategoryId);
                    Integer s = prevSort.get(w.getId());
                    if (s != null) w.setSortOrder(s);
                }
                notifyChanged();
            };
        }
        else
        {
            List<Waypoint> deletedChildren = new ArrayList<>();
            for (Waypoint w : library.getWaypoints())
            {
                if (w.getCategoryId().equals(id)) deletedChildren.add(w);
            }
            library.getWaypoints().removeIf(w -> w.getCategoryId().equals(id));
            library.getCategories().removeIf(cc -> cc.getId().equals(id));

            inverse = () -> {
                library.getCategories().add(snapshotCategory);
                library.getWaypoints().addAll(deletedChildren);
                notifyChanged();
            };
        }
        armUndoAndNotify(inverse);
    }

    public void setCategoryIcon(UUID categoryId, Integer iconId)
    {
        Category c = getCategoryById(categoryId);
        if (c == null) return;
        c.setIconId(iconId);
        notifyChanged();
    }

    public void setCategoryColor(UUID categoryId, Integer color)
    {
        Category c = getCategoryById(categoryId);
        if (c == null) return;
        c.setColor(color);
        notifyChanged();
    }

    public void setCategorySortMode(UUID categoryId, CategorySortMode mode)
    {
        Category c = getCategoryById(categoryId);
        if (c == null) return;
        c.setSortMode(mode);
        notifyChanged();
    }

    public void reorderCategories(List<UUID> idsInNewOrder)
    {
        Map<UUID, Integer> rank = new HashMap<>();
        for (int i = 0; i < idsInNewOrder.size(); i++) rank.put(idsInNewOrder.get(i), i);
        for (Category c : library.getCategories())
        {
            Integer r = rank.get(c.getId());
            if (r != null) c.setSortOrder(r);
        }
        notifyChanged();
    }

    public Waypoint createWaypoint(int packed, String name, UUID categoryId)
    {
        return createWaypoint(packed, name, categoryId, null);
    }

    public Waypoint createWaypoint(int packed, String name, UUID categoryId, String targetNpcName)
    {
        Waypoint w = new Waypoint(
            UUID.randomUUID(),
            name,
            packed,
            categoryId,
            null,
            "",
            Instant.now(),
            nextWaypointSortOrder(categoryId),
            false,
            null,
            false);
        w.setTargetNpcName(targetNpcName);
        library.getWaypoints().add(w);
        notifyChanged();
        return w;
    }

    public void renameWaypoint(UUID id, String newName)
    {
        Waypoint w = getWaypointById(id);
        if (w == null) return;
        w.setName(newName);
        notifyChanged();
    }

    public void updateWaypointIcon(UUID id, Integer iconId)
    {
        Waypoint w = getWaypointById(id);
        if (w == null) return;
        w.setIconId(iconId);
        notifyChanged();
    }

    public void setWaypointPinned(UUID id, boolean pinned)
    {
        Waypoint w = getWaypointById(id);
        if (w == null) return;
        if (pinned == w.isPinned()) return;
        w.setPinned(pinned);
        w.setPinnedAt(pinned ? Instant.now() : null);
        notifyChanged();
    }

    public void setWaypointBypassWildernessConfirm(UUID id, boolean bypass)
    {
        Waypoint w = getWaypointById(id);
        if (w == null) return;
        if (bypass == w.isBypassWildernessConfirm()) return;
        w.setBypassWildernessConfirm(bypass);
        notifyChanged();
    }

    /**
     * Derived view: all pinned waypoints sorted by {@code pinnedAt}.
     *
     * @param newestAtTop true = descending (most recently pinned first);
     *                    false = ascending (most recently pinned last).
     *                    Waypoints with null pinnedAt sort as Instant.EPOCH.
     */
    public List<Waypoint> getPinnedWaypoints(boolean newestAtTop)
    {
        List<Waypoint> pinned = new ArrayList<>();
        for (Waypoint w : library.getWaypoints())
        {
            if (w.isPinned()) pinned.add(w);
        }
        Comparator<Waypoint> byPinnedAt = Comparator.comparing(
            w -> w.getPinnedAt() == null ? Instant.EPOCH : w.getPinnedAt());
        pinned.sort(newestAtTop ? byPinnedAt.reversed() : byPinnedAt);
        return Collections.unmodifiableList(pinned);
    }

    public void updateWaypointNotes(UUID id, String notes)
    {
        Waypoint w = getWaypointById(id);
        if (w == null) return;
        w.setNotes(notes == null ? "" : notes);
        notifyChanged();
    }

    public void updateWaypointPoint(UUID id, int packed)
    {
        Waypoint w = getWaypointById(id);
        if (w == null)
        {
            return;
        }
        int oldPacked = w.getPackedWorldPoint();
        w.setPackedWorldPoint(packed);
        UUID targetId = id;
        armUndoAndNotify(() -> {
            Waypoint cur = getWaypointById(targetId);
            if (cur != null)
            {
                cur.setPackedWorldPoint(oldPacked);
                notifyChanged();
            }
        });
    }

    public void deleteWaypoint(UUID id)
    {
        Waypoint w = getWaypointById(id);
        if (w == null)
        {
            return;
        }
        library.getWaypoints().removeIf(x -> x.getId().equals(id));
        Waypoint snapshot = w;
        armUndoAndNotify(() -> {
            library.getWaypoints().add(snapshot);
            notifyChanged();
        });
    }

    /**
     * Batch delete. Snapshots every found waypoint and arms ONE undo that re-adds them all;
     * unknown ids are skipped, and if none are found the undo slot is cleared without firing.
     * Mirrors the single-item {@link #deleteWaypoint(UUID)}.
     */
    public void deleteWaypoints(Collection<UUID> ids)
    {
        Set<UUID> idSet = new HashSet<>(ids);
        List<Waypoint> removed = new ArrayList<>();
        for (Waypoint w : library.getWaypoints())
        {
            if (idSet.contains(w.getId())) removed.add(w);
        }
        if (removed.isEmpty())
        {
            return;
        }
        library.getWaypoints().removeIf(w -> idSet.contains(w.getId()));
        armUndoAndNotify(() -> {
            library.getWaypoints().addAll(removed);
            notifyChanged();
        });
    }

    public void moveWaypointToCategory(UUID waypointId, UUID newCategoryId)
    {
        Waypoint w = getWaypointById(waypointId);
        if (w == null) return;
        if (getCategoryById(newCategoryId) == null) return;
        w.setCategoryId(newCategoryId);
        w.setSortOrder(nextWaypointSortOrder(newCategoryId));
        notifyChanged();
    }

    /**
     * Batch reparent. Validates the target once; each found waypoint is moved to the tail of
     * {@code targetId} with ascending sortOrder. Unknown ids are skipped. Non-undoable, matching
     * the single-item {@link #moveWaypointToCategory(UUID, UUID)}.
     */
    public void moveWaypointsToCategory(Collection<UUID> ids, UUID targetId)
    {
        if (getCategoryById(targetId) == null) return;
        int order = nextWaypointSortOrder(targetId);
        boolean any = false;
        for (UUID id : ids)
        {
            Waypoint w = getWaypointById(id);
            if (w == null) continue;
            w.setCategoryId(targetId);
            w.setSortOrder(order++);
            any = true;
        }
        if (any) notifyChanged();
    }

    public void reorderWithinCategory(UUID categoryId, List<UUID> waypointIdsInOrder)
    {
        Map<UUID, Integer> rank = new HashMap<>();
        for (int i = 0; i < waypointIdsInOrder.size(); i++) rank.put(waypointIdsInOrder.get(i), i);
        for (Waypoint w : library.getWaypoints())
        {
            if (!w.getCategoryId().equals(categoryId)) continue;
            Integer r = rank.get(w.getId());
            if (r != null) w.setSortOrder(r);
        }
        notifyChanged();
    }

    /** Merge another library into this one. Dedupe by id; rebind incoming categoryIds by name. */
    public ImportResult importMerge(Library incoming)
    {
        ImportResult result = new ImportResult();
        Map<UUID, UUID> categoryIdRemap = new HashMap<>();

        // Phase 1: categories
        for (Category c : incoming.getCategories())
        {
            if (c.isUncategorized()) continue; // never duplicate the sentinel
            Category existingById = getCategoryById(c.getId());
            if (existingById != null) continue;
            Category existingByName = getCategoryByName(c.getName());
            if (existingByName != null)
            {
                categoryIdRemap.put(c.getId(), existingByName.getId());
            }
            else
            {
                int nextOrder = library.getCategories().stream()
                    .mapToInt(Category::getSortOrder).max().orElse(-1) + 1;
                library.getCategories().add(new Category(
                    c.getId(), c.getName(), nextOrder, false, c.getIconId(), c.isBundled()));
                result.categoriesAdded++;
            }
        }

        // Phase 1 mutated library.getCategories() directly, so the categoryIndex cache
        // populated by the getCategoryById call above is now stale. Without this, Phase 2's
        // category-exists check below returns null for every freshly-added category and the
        // waypoint falls through to Uncategorized.
        views.invalidateIndexes();

        // Phase 2: waypoints
        Set<UUID> existingWpIds = library.getWaypoints().stream()
            .map(Waypoint::getId).collect(Collectors.toCollection(HashSet::new));
        for (Waypoint w : incoming.getWaypoints())
        {
            if (existingWpIds.contains(w.getId()))
            {
                result.waypointsSkipped++;
                continue;
            }
            UUID resolvedCat = categoryIdRemap.getOrDefault(w.getCategoryId(), w.getCategoryId());
            // If incoming categoryId is the Uncategorized sentinel id from the source side, map
            // it to OUR uncategorized id.
            Category srcCat = findInList(incoming.getCategories(), w.getCategoryId());
            if (srcCat != null && srcCat.isUncategorized())
            {
                resolvedCat = getUncategorized().getId();
            }
            if (getCategoryById(resolvedCat) == null)
            {
                resolvedCat = getUncategorized().getId();
            }
            int sortOrder = nextWaypointSortOrder(resolvedCat);
            library.getWaypoints().add(new Waypoint(
                w.getId(), w.getName(), w.getPackedWorldPoint(),
                resolvedCat, w.getIconId(), w.getNotes() == null ? "" : w.getNotes(),
                w.getCreatedAt() == null ? Instant.now() : w.getCreatedAt(),
                sortOrder,
                false,
                null,
                false));
            result.waypointsAdded++;
        }

        // Also fire when only categories were added: a categories-only import (e.g. defaults
        // with an empty waypoints list) would otherwise skip the rebuild + save and the new
        // categories would vanish on the next plugin reload.
        if (result.waypointsAdded > 0 || result.categoriesAdded > 0 || !categoryIdRemap.isEmpty())
        {
            notifyChanged();
        }
        return result;
    }

    public Listeners.Subscription subscribe(Runnable r) { return listeners.subscribe(r); }

    public boolean hasUndoable() { return lastUndo != null; }

    /**
     * Run the inverse of the most recent destructive op, if any. Clears the slot before
     * running so the runnable's direct-to-library writes don't re-clear it themselves.
     */
    public void undoLast()
    {
        Runnable u = lastUndo;
        lastUndo = null;
        if (u != null) u.run();
    }

    // Package-private test seam: arm the slot with an arbitrary runnable so tests can
    // verify that non-undoable mutations clear it. Production code never calls this.
    void testArmUndoSlot(Runnable r) { this.lastUndo = r; }

    /** Test seam: number of currently-subscribed listeners. */
    public int listenerCountForTest()
    {
        return listeners.size();
    }

    // ---- Persistence wiring (write-through) ----

    private Listeners.Subscription saveSub;

    /**
     * Subscribe a write-through saver fired synchronously on every mutation. Idempotent. The
     * saver should read the live library (e.g. {@code () -> persistence.save(getLibrary())}); a
     * later {@link #bootstrap(Library)} that swaps the library is picked up automatically.
     */
    public void enablePersistence(Runnable saver)
    {
        if (saveSub != null) return;
        saveSub = listeners.subscribe(saver);
    }

    /**
     * Detach the saver. Idempotent. Called from {@link com.waypointer.WaypointerPlugin#shutDown()}
     * so plugin reload cycles do not stack savers.
     */
    public void disablePersistence()
    {
        if (saveSub != null)
        {
            saveSub.close();
            saveSub = null;
        }
    }

    private int nextWaypointSortOrder(UUID categoryId)
    {
        return library.getWaypoints().stream()
            .filter(w -> w.getCategoryId().equals(categoryId))
            .mapToInt(Waypoint::getSortOrder).max().orElse(-1) + 1;
    }

    private void ensureUncategorized()
    {
        Category existing = library.getCategories().stream()
            .filter(Category::isUncategorized).findFirst().orElse(null);
        if (existing == null)
        {
            Category u = new Category(UUID.randomUUID(), UNCATEGORIZED_NAME, 0, true, null, false);
            // Top-of-list ordering is enforced later by getCategoriesOrdered's tier sort, not here.
            library.getCategories().add(u);
        }
    }

    private static Category findInList(List<Category> list, UUID id)
    {
        for (Category c : list) if (c.getId().equals(id)) return c;
        return null;
    }

    public static class ImportResult
    {
        public int waypointsAdded;
        public int waypointsSkipped;
        public int categoriesAdded;
    }

}

package com.waypointer.service;

import javax.annotation.Nullable;
import javax.inject.Inject;
import javax.inject.Singleton;

/**
 * Composer over the two landmark indices. Lookups consult the wiki-sourced bbox index first
 * (specific named POIs like "Edgeville Bank") and fall back to the cache-label index for
 * city / sub-area / region names.
 */
@Singleton
public class LandmarkLookup
{
    private final BboxIndex bbox;
    private final CacheLabelIndex cache;

    @Inject
    public LandmarkLookup(BboxIndex bbox, CacheLabelIndex cache)
    {
        this.bbox = bbox;
        this.cache = cache;
    }

    @Nullable
    public LookupHit lookup(int packedPoint)
    {
        String bboxName = bbox.lookup(packedPoint);
        if (bboxName != null)
        {
            return new LookupHit(bboxName, LookupHit.Tier.CURATED);
        }
        return cache.lookup(packedPoint);
    }
}

package com.waypointer.service;

import com.waypointer.model.WorldPointPacker;
import com.waypointer.model.route.Route;
import com.waypointer.model.route.RouteStep;
import com.waypointer.model.route.StepType;
import com.waypointer.util.Listeners;
import javax.annotation.Nullable;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Player;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.client.eventbus.Subscribe;

/**
 * Runs the active route as a linear state machine. Waypoint steps auto-advance when the player
 * arrives (3-tile radius, same arithmetic as {@link WaypointPathfinder}); manual steps advance via
 * {@link #advance()} (the Next button / hotkey). Path drawing is delegated to the pathfinder.
 *
 * <p>{@code @Singleton}, so it outlives plugin lifecycle: it registers with the EventBus in the
 * plugin's startUp and unregisters in shutDown. {@code client} is left null in unit tests, which
 * drive {@link #handleTick(WorldPoint)} directly.
 */
@Slf4j
@Singleton
public class RoutePlaybackEngine
{
    private static final int ARRIVAL_RADIUS_TILES = 3;

    private final WaypointPathfinder pathfinder;
    private final RouteStore store;
    private final Listeners listeners = new Listeners();
    @Nullable private volatile Client client;
    private Listeners.Subscription storeSub;

    // Volatile for cross-thread visibility: these three fields are mutated from both the EDT
    // (playback-bar buttons -> start/advance/back/stop) and the client thread (tick auto-advance
    // via handleTick). They are not updated as an atomic group, so a reader (the playback bar)
    // can briefly observe a transitional combination during a button-vs-tick race; that is
    // visually benign and corrected on the next listeners.fire(). Fully closing the race would
    // mean confining all mutation to one thread (deferred).
    private volatile Route active;
    private volatile int currentIndex;
    private volatile int lap;

    @Inject
    public RoutePlaybackEngine(WaypointPathfinder pathfinder, RouteStore store)
    {
        this.pathfinder = pathfinder;
        this.store = store;
    }

    /** Production wiring sets the client and a store subscription; tests skip this. */
    public void attach(Client client)
    {
        this.client = client;
        if (storeSub == null)
        {
            storeSub = store.subscribe(this::onStoreChanged);
        }
    }

    public void detach()
    {
        if (storeSub != null) { storeSub.close(); storeSub = null; }
        this.client = null;
        stop();
    }

    public Listeners.Subscription subscribe(Runnable r) { return listeners.subscribe(r); }

    public boolean isActive() { return active != null; }
    public int getCurrentIndex() { return currentIndex; }
    public int getLap() { return lap; }
    @Nullable public Route getActiveRoute() { return active; }

    @Nullable
    public RouteStep getCurrentStep()
    {
        Route r = active;
        if (r == null || currentIndex < 0 || currentIndex >= r.getSteps().size()) return null;
        return r.getSteps().get(currentIndex);
    }

    public void start(Route route)
    {
        if (route == null || route.getSteps().isEmpty()) return;
        this.active = route;
        this.currentIndex = 0;
        this.lap = 1;
        enterCurrentStep();
        listeners.fire();
    }

    public void stop()
    {
        if (active == null) { return; }
        active = null;
        currentIndex = 0;
        lap = 1;
        pathfinder.clearPath();
        listeners.fire();
    }

    /** Advance / skip to the next step. Wraps + increments lap for repeating routes; else stops. */
    public void advance()
    {
        Route r = active;
        if (r == null) return;
        int next = currentIndex + 1;
        if (next >= r.getSteps().size())
        {
            if (r.isRepeating())
            {
                currentIndex = 0;
                lap++;
                enterCurrentStep();
                listeners.fire();
            }
            else
            {
                stop();
            }
            return;
        }
        currentIndex = next;
        enterCurrentStep();
        listeners.fire();
    }

    public void back()
    {
        Route r = active;
        if (r == null) return;
        if (currentIndex == 0) return;
        currentIndex--;
        enterCurrentStep();
        listeners.fire();
    }

    private void enterCurrentStep()
    {
        RouteStep s = getCurrentStep();
        if (s == null) return;
        if (s.getType() == StepType.WAYPOINT && s.getPackedWorldPoint() != WorldPointPacker.UNDEFINED)
        {
            pathfinder.requestPath(s.getPackedWorldPoint(), s.getLabel());
        }
        else
        {
            pathfinder.clearPath();
        }
    }

    /** Package-private test seam + production tick body. Advances a waypoint step on arrival. */
    void handleTick(WorldPoint playerLoc)
    {
        RouteStep s = getCurrentStep();
        if (s == null || s.getType() != StepType.WAYPOINT) return;
        int target = s.getPackedWorldPoint();
        if (target == WorldPointPacker.UNDEFINED || playerLoc == null) return;
        if (WorldPointPacker.arrived(target, playerLoc, ARRIVAL_RADIUS_TILES))
        {
            advance();
        }
    }

    // Package-private so tests can drive the store-deletion path without a live store subscription.
    void onStoreChanged()
    {
        Route r = active;
        if (r != null && store.getRouteById(r.getId()) == null)
        {
            stop();
        }
    }

    @Subscribe
    public void onGameTick(GameTick e)
    {
        if (active == null || client == null) return;
        if (client.getGameState() != GameState.LOGGED_IN) return;
        Player p = client.getLocalPlayer();
        if (p == null) return;
        handleTick(p.getWorldLocation());
    }

    @Subscribe
    public void onGameStateChanged(GameStateChanged e)
    {
        if (active == null) return;
        GameState s = e.getGameState();
        if (s == GameState.LOGIN_SCREEN || s == GameState.HOPPING || s == GameState.CONNECTION_LOST)
        {
            stop();
        }
    }
}

package com.waypointer.service;

import com.waypointer.codec.LibraryJsonCodec;
import com.waypointer.model.Library;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.config.ConfigManager;

/**
 * Per-account library persistence backed by the RuneLite config system (RSProfile-scoped),
 * replacing the old on-disk library.json. {@link #load()} / {@link #save(Library)} read and write a
 * single JSON blob under (group {@code waypointer}, key {@code library}) for the logged-in account;
 * {@link #clear()} unsets it. A decode failure freezes saves so a corrupt value is not overwritten
 * before the user resets via the panel banner.
 */
@Slf4j
@Singleton
public class WaypointStorePersistence
{
    static final String GROUP = "waypointer";
    static final String KEY = "library";

    private final ConfigManager configManager;
    private final LibraryJsonCodec codec;
    private volatile boolean refuseSavesUntilReset = false;

    @Inject
    public WaypointStorePersistence(ConfigManager configManager, LibraryJsonCodec codec)
    {
        this.configManager = configManager;
        this.codec = codec;
    }

    /**
     * Loads the current account's library from RSProfile config. Returns an empty library when not
     * logged in (no RS profile) or when nothing has been saved. Only a decode failure (corruption)
     * freezes saves; an absent value is a clean empty.
     */
    public Library load()
    {
        String json = configManager.getRSProfileConfiguration(GROUP, KEY);
        if (json == null || json.isEmpty()) return new Library();
        try
        {
            return codec.decode(json);
        }
        catch (RuntimeException e)
        {
            log.error("Library config value unreadable; refusing saves until reset", e);
            refuseSavesUntilReset = true;
            return new Library();
        }
    }

    /** Write-through save of the live library to the logged-in account's RSProfile config. */
    public void save(Library lib)
    {
        if (refuseSavesUntilReset)
        {
            log.warn("Save refused: library config is in a corrupt state pending user reset");
            return;
        }
        configManager.setRSProfileConfiguration(GROUP, KEY, codec.encode(lib));
    }

    /** Clears the current account's stored library and lifts the corrupt-state freeze. */
    public void clear()
    {
        configManager.unsetRSProfileConfiguration(GROUP, KEY);
        refuseSavesUntilReset = false;
    }

    public boolean isRefusingSaves() { return refuseSavesUntilReset; }

    public void allowSavesAfterReset() { refuseSavesUntilReset = false; }
}

package com.waypointer.service;

import com.waypointer.model.Category;
import com.waypointer.model.CategorySortMode;
import com.waypointer.model.Library;
import com.waypointer.model.Waypoint;
import java.time.Instant;
import java.util.ArrayList;
import java.util.Collections;
import java.util.Comparator;
import java.util.HashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.UUID;
import java.util.function.Supplier;

/**
 * Memoized derived views over the live {@link Library}: the tier-sorted category list, the
 * per-category waypoint buckets, and the UUID->object indexes. Caches are lazy and dropped by
 * {@link WaypointStore#fireChanged()} on every mutation, so the store stays focused on
 * mutation + undo.
 */
final class LibraryViews
{
    private final Supplier<Library> library;

    private List<Category> cachedCategoriesOrdered;
    private Map<UUID, List<Waypoint>> cachedWaypointsByCategory;
    private Map<UUID, Category> categoryIndex;
    private Map<UUID, Waypoint> waypointIndex;

    LibraryViews(Supplier<Library> library)
    {
        this.library = library;
    }

    /** Drops every cache + index. Called from the store's fireChanged(). */
    void invalidate()
    {
        cachedCategoriesOrdered = null;
        cachedWaypointsByCategory = null;
        categoryIndex = null;
        waypointIndex = null;
    }

    /** Drops only the UUID indexes. Called mid-importMerge after a direct category mutation. */
    void invalidateIndexes()
    {
        categoryIndex = null;
        waypointIndex = null;
    }

    Category getCategoryById(UUID id)
    {
        if (categoryIndex == null)
        {
            Library lib = library.get();
            Map<UUID, Category> idx = new HashMap<>(lib.getCategories().size() * 2);
            for (Category c : lib.getCategories()) idx.put(c.getId(), c);
            categoryIndex = idx;
        }
        return categoryIndex.get(id);
    }

    Waypoint getWaypointById(UUID id)
    {
        if (waypointIndex == null)
        {
            Library lib = library.get();
            Map<UUID, Waypoint> idx = new HashMap<>(lib.getWaypoints().size() * 2);
            for (Waypoint w : lib.getWaypoints()) idx.put(w.getId(), w);
            waypointIndex = idx;
        }
        return waypointIndex.get(id);
    }

    List<Category> getCategoriesOrdered()
    {
        if (cachedCategoriesOrdered == null)
        {
            List<Category> sorted = new ArrayList<>(library.get().getCategories());
            sorted.sort((a, b) -> {
                int tierA = a.isUncategorized() ? 0 : (a.isBundled() ? 2 : 1);
                int tierB = b.isUncategorized() ? 0 : (b.isBundled() ? 2 : 1);
                if (tierA != tierB) return Integer.compare(tierA, tierB);
                return Integer.compare(a.getSortOrder(), b.getSortOrder());
            });
            cachedCategoriesOrdered = Collections.unmodifiableList(sorted);
        }
        return cachedCategoriesOrdered;
    }

    List<Waypoint> getWaypointsInCategory(UUID categoryId)
    {
        if (cachedWaypointsByCategory == null)
        {
            Map<UUID, List<Waypoint>> grouped = new HashMap<>();
            for (Waypoint w : library.get().getWaypoints())
            {
                grouped.computeIfAbsent(w.getCategoryId(), k -> new ArrayList<>()).add(w);
            }
            for (Map.Entry<UUID, List<Waypoint>> e : grouped.entrySet())
            {
                // getCategoryById may build categoryIndex as a side-effect; both caches self-init lazily.
                Category cat = getCategoryById(e.getKey());
                CategorySortMode mode = cat == null ? null : cat.getSortMode();
                e.getValue().sort(comparatorFor(mode));
            }
            cachedWaypointsByCategory = grouped;
        }
        List<Waypoint> bucket = cachedWaypointsByCategory.get(categoryId);
        return bucket == null ? Collections.emptyList() : Collections.unmodifiableList(bucket);
    }

    private static Comparator<Waypoint> comparatorFor(CategorySortMode mode)
    {
        if (mode == null || mode == CategorySortMode.MANUAL)
        {
            return Comparator.comparingInt(Waypoint::getSortOrder);
        }
        if (mode == CategorySortMode.NAME)
        {
            return Comparator
                .comparing((Waypoint w) -> w.getName() == null ? "" : w.getName().toLowerCase(Locale.ROOT))
                .thenComparing(w -> w.getCreatedAt() == null ? Instant.EPOCH : w.getCreatedAt())
                .thenComparing(Waypoint::getId);
        }
        return Comparator
            .comparing((Waypoint w) -> w.getCreatedAt() == null ? Instant.EPOCH : w.getCreatedAt(),
                Comparator.reverseOrder())
            .thenComparing(w -> w.getName() == null ? "" : w.getName().toLowerCase(Locale.ROOT))
            .thenComparing(Waypoint::getId);
    }
}

package com.waypointer.service;

import com.waypointer.model.WorldPointPacker;
import java.io.BufferedReader;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.Collection;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import javax.annotation.Nullable;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;

@Slf4j
@Singleton
public class CacheLabelIndex
{
    private static final String RESOURCE = "/com/waypointer/landmarks/map-labels-raw.tsv";
    private static final int CHUNK_SHIFT = 4;

    private static final int POI_RADIUS = 3;
    private static final int SUB_AREA_RADIUS = 50;
    private static final int CITY_RADIUS = 200;

    static final class Entry
    {
        final int packed;
        final String name;
        final int textScale;

        Entry(int packed, String name, int textScale)
        {
            this.packed = packed;
            this.name = name;
            this.textScale = textScale;
        }
    }

    private final List<Entry> all = new ArrayList<>();
    private final Map<Long, List<Entry>> byChunk = new HashMap<>();
    private final Map<String, Integer> nameCounts = new HashMap<>();

    @Inject
    public CacheLabelIndex()
    {
        load();
        log.info("CacheLabelIndex loaded {} cache-label entries", all.size());
    }

    /** Visible for tests: build an index from a literal list of entries instead of the TSV. */
    static CacheLabelIndex forTesting(Collection<Entry> entries)
    {
        CacheLabelIndex idx = new CacheLabelIndex(true);
        for (Entry e : entries)
        {
            idx.addEntry(e);
        }
        return idx;
    }

    private CacheLabelIndex(boolean skipResourceLoad)
    {
        // Test seam: only forTesting() calls this.
    }

    public int size() { return all.size(); }

    @Nullable
    public LookupHit lookup(int packedPoint)
    {
        int x = WorldPointPacker.getX(packedPoint);
        int y = WorldPointPacker.getY(packedPoint);
        int plane = WorldPointPacker.getPlane(packedPoint);

        Entry best = null;
        int bestRank = Integer.MAX_VALUE;
        int bestDist = Integer.MAX_VALUE;
        int bestCount = Integer.MAX_VALUE;

        int chunks = (CITY_RADIUS >> CHUNK_SHIFT) + 1;
        int cx = x >> CHUNK_SHIFT;
        int cy = y >> CHUNK_SHIFT;
        for (int dxc = -chunks; dxc <= chunks; dxc++)
        {
            for (int dyc = -chunks; dyc <= chunks; dyc++)
            {
                List<Entry> bucket = byChunk.get(rawChunkKey(cx + dxc, cy + dyc, plane));
                if (bucket == null) continue;
                for (Entry e : bucket)
                {
                    if (WorldPointPacker.getPlane(e.packed) != plane) continue;
                    int dist = Math.max(
                        Math.abs(WorldPointPacker.getX(e.packed) - x),
                        Math.abs(WorldPointPacker.getY(e.packed) - y));

                    // Unique-name POIs get sub-area radius so they're not eclipsed by a city label
                    // just because the player is more than 3 tiles from the exact label tile.
                    boolean promoted = e.textScale == 0 && nameCounts.getOrDefault(e.name, 1) == 1;
                    int radius = promoted ? SUB_AREA_RADIUS : radiusFor(e.textScale);
                    if (dist > radius) continue;

                    int rank = promoted ? 1 : rankFor(e.textScale);
                    int count = nameCounts.getOrDefault(e.name, 1);
                    // Lower rank = tighter tier; tie-break by lower name count; then closer distance.
                    if (rank < bestRank
                        || (rank == bestRank && count < bestCount)
                        || (rank == bestRank && count == bestCount && dist < bestDist))
                    {
                        best = e;
                        bestRank = rank;
                        bestDist = dist;
                        bestCount = count;
                    }
                }
            }
        }
        if (best == null) return null;
        return new LookupHit(best.name, tierFor(best.textScale));
    }

    private static int radiusFor(int textScale)
    {
        switch (textScale)
        {
            case 0: return POI_RADIUS;
            case 1: return SUB_AREA_RADIUS;
            default: return CITY_RADIUS;
        }
    }

    private static int rankFor(int textScale)
    {
        switch (textScale)
        {
            case 0: return 0; // POI wins ties against sub-area / city
            case 1: return 1;
            default: return 2;
        }
    }

    private static LookupHit.Tier tierFor(int textScale)
    {
        switch (textScale)
        {
            case 0: return LookupHit.Tier.POI;
            case 1: return LookupHit.Tier.SUB_AREA;
            default: return LookupHit.Tier.CITY;
        }
    }

    private void addEntry(Entry e)
    {
        all.add(e);
        int x = WorldPointPacker.getX(e.packed);
        int y = WorldPointPacker.getY(e.packed);
        int plane = WorldPointPacker.getPlane(e.packed);
        byChunk.computeIfAbsent(rawChunkKey(x >> CHUNK_SHIFT, y >> CHUNK_SHIFT, plane),
            k -> new ArrayList<>()).add(e);
        nameCounts.merge(e.name, 1, Integer::sum);
    }

    private static long rawChunkKey(int cx, int cy, int plane)
    {
        return ((long) plane << 40) | ((long) cy << 20) | (cx & 0xFFFFF);
    }

    private void load()
    {
        try (InputStream in = CacheLabelIndex.class.getResourceAsStream(RESOURCE))
        {
            if (in == null)
            {
                log.warn("Cache-label resource not found: {}", RESOURCE);
                return;
            }
            try (BufferedReader r = new BufferedReader(new InputStreamReader(in, StandardCharsets.UTF_8)))
            {
                String line;
                while ((line = r.readLine()) != null)
                {
                    if (line.isEmpty() || line.startsWith("#")) continue;
                    String[] tabs = line.split("\t");
                    if (tabs.length < 5) continue;
                    String[] coord = tabs[0].split("\\s+");
                    if (coord.length < 3) continue;
                    try
                    {
                        int x = Integer.parseInt(coord[0]);
                        int y = Integer.parseInt(coord[1]);
                        int plane = Integer.parseInt(coord[2]);
                        String name = tabs[1].trim();
                        int textScale = Integer.parseInt(tabs[4].trim());
                        if (name.isEmpty()) continue;
                        addEntry(new Entry(WorldPointPacker.pack(x, y, plane), name, textScale));
                    }
                    catch (NumberFormatException ignored) {}
                }
            }
        }
        catch (Exception e)
        {
            log.warn("Failed to load cache-label resource {}", RESOURCE, e);
        }
    }
}

package com.waypointer.service;

import com.waypointer.model.WorldPointPacker;
import com.waypointer.util.Listeners;
import java.util.HashMap;
import java.util.Map;
import javax.annotation.Nullable;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Player;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.EventBus;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.events.PluginMessage;

/** Bridge to the shortest-path plugin via PluginMessage. Detects shortest-path by
 *  listening for inbound messages in its namespace, or by probing ConfigManager.
 *  Class.forName can't see across plugin-hub classloaders. Availability is sticky
 *  once detected. */
@Slf4j
@Singleton
public class WaypointPathfinder
{
    private static final String SP_NAMESPACE = "shortestpath";
    private static final String MSG_PATH = "path";
    private static final String MSG_CLEAR = "clear";
    private static final String DATA_TARGET = "target";
    private static final int ARRIVAL_RADIUS_TILES = 3;
    // Config keys shortest-path persists early. recalculateDistance is read every game tick;
    // drawTransports is a fallback probe.
    private static final String[] CONFIG_PROBE_KEYS = { "recalculateDistance", "drawTransports" };

    private final EventBus eventBus;
    private final ClientThread clientThread;
    private final Client client;
    private final ConfigManager configManager;
    private final Listeners listeners = new Listeners();
    private volatile boolean available;
    private volatile int activeTarget = WorldPointPacker.UNDEFINED;
    private volatile String activeName = null;

    @Inject
    public WaypointPathfinder(EventBus eventBus, ClientThread clientThread, Client client,
        ConfigManager configManager)
    {
        this.eventBus = eventBus;
        this.clientThread = clientThread;
        this.client = client;
        this.configManager = configManager;
        if (probeConfig()) markAvailable("config probe at construction");
    }

    public boolean isAvailable() { return available; }

    public int getActiveTarget() { return activeTarget; }

    @Nullable
    public String getActiveName() { return activeName; }

    public Listeners.Subscription subscribe(Runnable r) { return listeners.subscribe(r); }

    @Subscribe
    public void onGameStateChanged(GameStateChanged e)
    {
        // Drop the active target on logout/hop/login screen, otherwise the banner sticks
        // until the player happens to path elsewhere.
        if (activeTarget == WorldPointPacker.UNDEFINED) return;
        GameState s = e.getGameState();
        if (s == GameState.LOGIN_SCREEN || s == GameState.HOPPING || s == GameState.CONNECTION_LOST)
        {
            activeTarget = WorldPointPacker.UNDEFINED;
            activeName = null;
            listeners.fire();
        }
    }

    @Subscribe
    public void onGameTick(GameTick e)
    {
        if (activeTarget == WorldPointPacker.UNDEFINED) return;
        if (client.getGameState() != GameState.LOGGED_IN) return;
        Player p = client.getLocalPlayer();
        if (p == null) return;
        WorldPoint pp = p.getWorldLocation();
        if (pp == null) return;
        // Don't auto-clear across planes, or a 2nd-floor waypoint vanishes the moment the
        // player walks under the building - WorldPointPacker.arrived enforces same-plane.
        if (WorldPointPacker.arrived(activeTarget, pp, ARRIVAL_RADIUS_TILES))
        {
            activeTarget = WorldPointPacker.UNDEFINED;
            activeName = null;
            listeners.fire();
        }
    }

    public void requestPath(int packedTarget, String displayName)
    {
        requestPath(packedTarget, displayName, null);
    }

    public void requestPath(int packedTarget, String displayName, Map<String, Object> configOverride)
    {
        Map<String, Object> data = new HashMap<>();
        data.put(DATA_TARGET, packedTarget);
        if (configOverride != null && !configOverride.isEmpty())
        {
            data.put("config", new HashMap<>(configOverride));
        }
        // shortest-path's handler reads client state, so post from the client thread.
        clientThread.invoke(() -> {
            eventBus.post(new PluginMessage(SP_NAMESPACE, MSG_PATH, data));
            this.activeTarget = packedTarget;
            this.activeName = displayName;
            listeners.fire();
            return true;
        });
    }

    public void clearPath()
    {
        clientThread.invoke(() -> {
            eventBus.post(new PluginMessage(SP_NAMESPACE, MSG_CLEAR, new HashMap<>()));
            this.activeTarget = WorldPointPacker.UNDEFINED;
            this.activeName = null;
            listeners.fire();
            return true;
        });
    }

    @Subscribe
    public void onPluginMessage(PluginMessage e)
    {
        if (available) return;
        if (!SP_NAMESPACE.equals(e.getNamespace())) return;
        // EventBus echoes our own posts back, so filter out the path/clear messages we just sent.
        // Only inbound messages shortest-path itself emits (e.g. transports) count as proof.
        String name = e.getName();
        if (MSG_PATH.equals(name) || MSG_CLEAR.equals(name)) return;
        markAvailable("inbound PluginMessage: " + name);
    }

    @Subscribe
    public void onConfigChanged(ConfigChanged e)
    {
        if (!available && SP_NAMESPACE.equals(e.getGroup()))
        {
            markAvailable("ConfigChanged in shortestpath group");
        }
    }

    private boolean probeConfig()
    {
        if (configManager == null) return false;
        for (String key : CONFIG_PROBE_KEYS)
        {
            if (configManager.getConfiguration(SP_NAMESPACE, key) != null) return true;
        }
        return false;
    }

    private void markAvailable(String reason)
    {
        available = true;
        log.info("shortest-path detected via {}", reason);
        listeners.fire();
    }
}

package com.waypointer.service;

/**
 * Categories of landmarks the bundled bbox dataset exposes for "nearest of type" queries.
 * One value per typed TSV under {@code /com/waypointer/landmarks/}; the untyped
 * {@code landmarks-bboxes.tsv} (unique landmarks) is intentionally not represented.
 * Bank chests fold into {@link #BANK}.
 */
public enum LandmarkType
{
    BANK("Bank"),
    ALTAR("Altar"),
    ANVIL("Anvil"),
    FURNACE("Furnace"),
    LOOM("Loom"),
    SPINNING_WHEEL("Spinning wheel"),
    TANNER("Tanner"),
    SPIRIT_TREE("Spirit tree"),
    CHARTER_SHIP("Charter ship"),
    FAIRY_RING("Fairy ring"),
    SLAYER_MASTER("Slayer master");

    private final String displayName;

    LandmarkType(String displayName)
    {
        this.displayName = displayName;
    }

    public String displayName()
    {
        return displayName;
    }
}

package com.waypointer.service;

import com.waypointer.model.route.Route;
import com.waypointer.model.route.RouteLibrary;
import com.waypointer.model.route.RouteStep;
import com.waypointer.model.route.StepType;
import com.waypointer.util.Listeners;
import java.time.Instant;
import java.util.ArrayList;
import java.util.Collections;
import java.util.Comparator;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.UUID;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;

/**
 * In-memory CRUD over a {@link RouteLibrary}. Mutations notify listeners synchronously.
 * Write-through persistence is layered on via {@link #enablePersistence}.
 */
@Slf4j
@Singleton
public class RouteStore
{
    // volatile: safe publication of the reference; mutations remain EDT-confined.
    private volatile RouteLibrary library = new RouteLibrary();
    private final Listeners listeners = new Listeners();

    @Inject
    public RouteStore() {}

    public void bootstrap(RouteLibrary lib)
    {
        this.library = lib;
        notifyChanged();
    }

    public RouteLibrary getLibrary() { return library; }

    public Listeners.Subscription subscribe(Runnable r) { return listeners.subscribe(r); }

    public List<Route> getRoutesOrdered()
    {
        List<Route> sorted = new ArrayList<>(library.getRoutes());
        sorted.sort(Comparator.comparingInt(Route::getSortOrder));
        return Collections.unmodifiableList(sorted);
    }

    public Route getRouteById(UUID id)
    {
        for (Route r : library.getRoutes()) if (r.getId().equals(id)) return r;
        return null;
    }

    public Route createRoute(String name)
    {
        int nextOrder = library.getRoutes().stream().mapToInt(Route::getSortOrder).max().orElse(-1) + 1;
        Route r = new Route(UUID.randomUUID(), name, new ArrayList<>(), false, Instant.now(), nextOrder);
        library.getRoutes().add(r);
        notifyChanged();
        return r;
    }

    public void renameRoute(UUID id, String newName)
    {
        Route r = getRouteById(id);
        if (r == null) return;
        r.setName(newName);
        notifyChanged();
    }

    public void setRepeating(UUID id, boolean repeating)
    {
        Route r = getRouteById(id);
        if (r == null) return;
        r.setRepeating(repeating);
        notifyChanged();
    }

    public void deleteRoute(UUID id)
    {
        if (library.getRoutes().removeIf(r -> r.getId().equals(id))) notifyChanged();
    }

    public Route duplicateRoute(UUID id)
    {
        Route src = getRouteById(id);
        if (src == null) return null;
        List<RouteStep> copies = new ArrayList<>();
        for (RouteStep s : src.getSteps())
        {
            RouteStep copy = new RouteStep(UUID.randomUUID(), s.getType(), s.getLabel(),
                s.getPackedWorldPoint(), s.getSourceWaypointId(), s.getIconId());
            copy.setBoxText(s.getBoxText());
            copies.add(copy);
        }
        int nextOrder = library.getRoutes().stream().mapToInt(Route::getSortOrder).max().orElse(-1) + 1;
        Route copy = new Route(UUID.randomUUID(), src.getName() + " (copy)", copies,
            src.isRepeating(), Instant.now(), nextOrder);
        library.getRoutes().add(copy);
        notifyChanged();
        return copy;
    }

    public void reorderRoutes(List<UUID> idsInNewOrder)
    {
        Map<UUID, Integer> rank = new HashMap<>();
        for (int i = 0; i < idsInNewOrder.size(); i++) rank.put(idsInNewOrder.get(i), i);
        for (Route r : library.getRoutes())
        {
            Integer rk = rank.get(r.getId());
            if (rk != null) r.setSortOrder(rk);
        }
        notifyChanged();
    }

    public void addWaypointStep(UUID routeId, int packed, String label, UUID sourceWaypointId)
    {
        Route r = getRouteById(routeId);
        if (r == null) return;
        r.getSteps().add(new RouteStep(UUID.randomUUID(),
            StepType.WAYPOINT, label, packed, sourceWaypointId, null));
        notifyChanged();
    }

    public void addManualStep(UUID routeId, String text)
    {
        Route r = getRouteById(routeId);
        if (r == null) return;
        r.getSteps().add(RouteStep.manual(text));
        notifyChanged();
    }

    public void updateStepLabel(UUID routeId, UUID stepId, String label)
    {
        RouteStep s = findStep(routeId, stepId);
        if (s == null) return;
        s.setLabel(label);
        notifyChanged();
    }

    public void updateStepWaypoint(UUID routeId, UUID stepId, int packed, String label)
    {
        RouteStep s = findStep(routeId, stepId);
        if (s == null) return;
        s.setPackedWorldPoint(packed);
        if (label != null) s.setLabel(label);
        notifyChanged();
    }

    public void updateStepText(UUID routeId, UUID stepId, String name, String boxText)
    {
        RouteStep s = findStep(routeId, stepId);
        if (s == null) return;
        s.setLabel(name);
        s.setBoxText(boxText);
        notifyChanged();
    }

    public void deleteStep(UUID routeId, UUID stepId)
    {
        Route r = getRouteById(routeId);
        if (r == null) return;
        if (r.getSteps().removeIf(s -> s.getId().equals(stepId))) notifyChanged();
    }

    public void reorderSteps(UUID routeId, List<UUID> stepIdsInOrder)
    {
        Route r = getRouteById(routeId);
        if (r == null) return;
        Map<UUID, RouteStep> byId = new HashMap<>();
        for (RouteStep s : r.getSteps()) byId.put(s.getId(), s);
        List<RouteStep> reordered = new ArrayList<>();
        for (UUID id : stepIdsInOrder)
        {
            RouteStep s = byId.remove(id);
            if (s != null) reordered.add(s);
        }
        reordered.addAll(byId.values()); // any not listed keep tail order
        r.setSteps(reordered);
        notifyChanged();
    }

    private RouteStep findStep(UUID routeId, UUID stepId)
    {
        Route r = getRouteById(routeId);
        if (r == null) return null;
        for (RouteStep s : r.getSteps()) if (s.getId().equals(stepId)) return s;
        return null;
    }

    private void notifyChanged()
    {
        listeners.fire();
    }

    // ---- Persistence wiring (write-through) ----

    private Listeners.Subscription saveSub;

    public void enablePersistence(Runnable saver)
    {
        if (saveSub != null) return;
        saveSub = listeners.subscribe(saver);
    }

    public void disablePersistence()
    {
        if (saveSub != null)
        {
            saveSub.close();
            saveSub = null;
        }
    }
}

package com.waypointer.service;

import com.waypointer.model.WorldPointPacker;

/**
 * Static check: is a packed tile inside the Wilderness? Bboxes are best-effort against
 * the standard OSRS map. Surface main wilderness uses the well-known Y >= 3525 boundary
 * (the ditch sits at Y=3523; Y=3520-3524 is the safe ditch zone). Underground caves use
 * plane-0 packing per OSRS map convention.
 */
public final class Wilderness
{
    private Wilderness() {}

    // Inclusive bboxes: {xMin, yMin, xMax, yMax, plane}.
    private static final int[][] BBOXES = {
        {2944, 3525, 3392, 3967, 0},   // surface main wilderness
        {2944, 9925, 3392, 10367, 0},  // Wilderness Slayer Cave
        {3072, 10112, 3327, 10239, 0}, // Revenants Cave / Forinthry Dungeon
    };

    public static boolean isInWilderness(int packed)
    {
        int x = WorldPointPacker.getX(packed);
        int y = WorldPointPacker.getY(packed);
        int plane = WorldPointPacker.getPlane(packed);
        for (int[] b : BBOXES)
        {
            if (plane == b[4] && x >= b[0] && x <= b[2] && y >= b[1] && y <= b[3]) return true;
        }
        return false;
    }
}

package com.waypointer;

import com.google.inject.Provides;
import com.waypointer.service.DeathAutoPathfinder;
import com.waypointer.service.WaypointMenuHandler;
import com.waypointer.service.WaypointPathfinder;
import com.waypointer.service.WaypointStore;
import com.waypointer.service.WaypointStorePersistence;
import com.waypointer.ui.Icon;
import com.waypointer.ui.NpcHighlightOverlay;
import com.waypointer.ui.TabHost;
import com.waypointer.ui.WaypointerPanel;
import java.awt.image.BufferedImage;
import javax.inject.Inject;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.EventBus;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;
import net.runelite.client.ui.overlay.OverlayManager;

@Slf4j
@PluginDescriptor(
    name = "Waypointer",
    description = "Save in-game locations and one-click path to them via Shortest Path.",
    tags = {"map", "travel", "pathfinding", "waypoints"}
)
public class WaypointerPlugin extends Plugin
{
    @Inject private WaypointerConfig config;
    @Inject private ClientToolbar clientToolbar;
    @Inject private WaypointerPanel panel;
    @Inject private WaypointStore store;
    @Inject private WaypointStorePersistence persistence;
    @Inject private EventBus eventBus;
    @Inject private WaypointMenuHandler menuHandler;
    @Inject private WaypointPathfinder pathfinderService;
    @Inject private DeathAutoPathfinder deathAutoPathfinder;
    @Inject private TabHost tabHost;
    @Inject private NpcHighlightOverlay npcHighlightOverlay;
    @Inject private OverlayManager overlayManager;
    @Inject private com.waypointer.service.RouteStore routeStore;
    @Inject private com.waypointer.service.RouteStorePersistence routePersistence;
    @Inject private com.waypointer.service.RoutePlaybackEngine routePlaybackEngine;
    @Inject private com.waypointer.ui.RouteOverlay routeOverlay;
    @Inject private net.runelite.api.Client client;
    @Inject private net.runelite.client.input.KeyManager keyManager;

    private NavigationButton navButton;
    private net.runelite.client.input.KeyListener routeHotkeyListener;

    @Override
    protected void startUp() throws Exception
    {
        // Load from config first so the panel (subscribed at construction) renders the saved data,
        // then attach the write-through saver so the bootstrap itself does not re-save.
        store.bootstrap(persistence.load());
        store.enablePersistence(() -> persistence.save(store.getLibrary()));
        routeStore.bootstrap(routePersistence.load());
        routeStore.enablePersistence(() -> routePersistence.save(routeStore.getLibrary()));
        routePlaybackEngine.attach(client);
        eventBus.register(routePlaybackEngine);
        overlayManager.add(routeOverlay);

        routeHotkeyListener = new net.runelite.client.input.KeyListener()
        {
            @Override public void keyTyped(java.awt.event.KeyEvent e) {}
            @Override public void keyReleased(java.awt.event.KeyEvent e) {}
            @Override public void keyPressed(java.awt.event.KeyEvent e)
            {
                if (!routePlaybackEngine.isActive()) return;
                if (config.routeAdvanceHotkey().matches(e))
                {
                    routePlaybackEngine.advance();
                    e.consume();
                }
            }
        };
        keyManager.registerKeyListener(routeHotkeyListener);

        BufferedImage icon = Icon.getSize32();
        navButton = NavigationButton.builder()
            .tooltip("Waypointer")
            .icon(icon)
            .priority(7)
            .panel(tabHost)
            .build();
        tabHost.setNavButton(navButton);
        clientToolbar.addNavigation(navButton);
        eventBus.register(menuHandler);
        eventBus.register(pathfinderService);
        eventBus.register(deathAutoPathfinder);
        eventBus.register(panel);
        eventBus.register(tabHost);

        // Pick up RuneLiteLAF's scrollbar colors now that the LAF is installed (the panel
        // was constructed earlier, against Metal's UIDefaults).
        tabHost.refreshScrollbarStyling();

        overlayManager.add(npcHighlightOverlay);

        log.info("Waypointer started: {} waypoints loaded",
            store.getLibrary().getWaypoints().size());
    }

    @Override
    protected void shutDown() throws Exception
    {
        if (routeHotkeyListener != null)
        {
            keyManager.unregisterKeyListener(routeHotkeyListener);
            routeHotkeyListener = null;
        }
        eventBus.unregister(routePlaybackEngine);
        routePlaybackEngine.detach();
        overlayManager.remove(routeOverlay);
        routeStore.disablePersistence();
        store.disablePersistence();

        eventBus.unregister(menuHandler);
        eventBus.unregister(pathfinderService);
        eventBus.unregister(deathAutoPathfinder);
        eventBus.unregister(panel);
        eventBus.unregister(tabHost);

        clientToolbar.removeNavigation(navButton);
        tabHost.dispose();
        overlayManager.remove(npcHighlightOverlay);
        log.info("Waypointer stopped");
    }

    @Subscribe
    public void onRuneScapeProfileChanged(net.runelite.client.events.RuneScapeProfileChanged e)
    {
        // ConfigManager has already switched the active RS profile by the time this fires, so a
        // fresh load() reads the newly-logged-in account's library. The write-through saver stays
        // attached and targets the now-current profile. Marshal the swap to the EDT.
        javax.swing.SwingUtilities.invokeLater(() -> store.bootstrap(persistence.load()));
    }

    @Provides
    WaypointerConfig provideConfig(ConfigManager cm)
    {
        return cm.getConfig(WaypointerConfig.class);
    }
}

package com.waypointer.util;

/** Small string helpers shared across the UI: HTML escaping and filename sanitization. */
public final class Text
{
    private Text() {}

    // Returns s with characters that are illegal in filenames on Windows / macOS removed
    // (/ \ : * ? " < > |), plus leading/trailing dots and whitespace trimmed. Falls back to
    // "untitled" when the input is null, empty, or reduces to nothing.
    public static String sanitizeFilenameSegment(String s)
    {
        if (s == null) return "untitled";
        StringBuilder b = new StringBuilder(s.length());
        for (int i = 0; i < s.length(); i++)
        {
            char ch = s.charAt(i);
            switch (ch)
            {
                case '/': case '\\': case ':': case '*': case '?':
                case '"': case '<': case '>': case '|':
                    continue;
                default:
                    b.append(ch);
            }
        }
        // Strip outer whitespace and dots, alternating until stable. A single pass misses
        // inputs like ". .name. ." where dots and spaces interleave at the boundary.
        String result = b.toString();
        String prev;
        do
        {
            prev = result;
            result = result.trim();
            int start = 0, end = result.length();
            while (start < end && result.charAt(start) == '.') start++;
            while (end > start && result.charAt(end - 1) == '.') end--;
            result = result.substring(start, end);
        } while (!result.equals(prev));
        return result.isEmpty() ? "untitled" : result;
    }

    // Escapes s for embedding in HTML. Handles <, >, &, ", and '. Returns "" when s is null.
    public static String escapeHtml(String s)
    {
        if (s == null) return "";
        StringBuilder b = new StringBuilder(s.length());
        for (int i = 0; i < s.length(); i++)
        {
            char ch = s.charAt(i);
            switch (ch)
            {
                case '<':  b.append("&lt;");   break;
                case '>':  b.append("&gt;");   break;
                case '&':  b.append("&amp;");  break;
                case '"':  b.append("&quot;"); break;
                case '\'': b.append("&#39;");  break;
                default:   b.append(ch);
            }
        }
        return b.toString();
    }
}

package com.waypointer.util;

import java.util.List;
import java.util.concurrent.CopyOnWriteArrayList;
import lombok.extern.slf4j.Slf4j;

// Reusable list of Runnable listeners with safe iteration. A listener throwing doesn't stop
// later listeners. Backed by CopyOnWriteArrayList so iteration is snapshot-stable even when
// listeners add or remove themselves during fire(). Register with subscribe() and hold the
// returned Subscription to remove the listener later.
@Slf4j
public final class Listeners
{
    private final List<Runnable> listeners = new CopyOnWriteArrayList<>();

    public int size() { return listeners.size(); }

    // Registers r and returns a token whose close() removes it. Use with anonymous lambdas
    // so the caller doesn't need to keep a reference to the original.
    public Subscription subscribe(Runnable r)
    {
        listeners.add(r);
        return () -> listeners.remove(r);
    }

    public void fire()
    {
        for (Runnable r : listeners)
        {
            try { r.run(); }
            catch (Exception e) { log.warn("Listener threw", e); }
        }
    }

    @FunctionalInterface
    public interface Subscription extends AutoCloseable
    {
        @Override void close();
    }
}

