/**
 * Schema-version migration hook. Today every supported version maps straight through, so this
 * is an identity passthrough -- the {@code fromVersion} argument is unused on purpose. It exists
 * as the stable seam to slot real migration steps into when the on-disk schema next changes;
 * it is not dead code and is not live migration logic.
 */
public final class LibraryMigrator
{
    private LibraryMigrator() {}

    public static JsonObject migrate(JsonObject obj, int fromVersion)
    {
        return obj;
    }
}

package com.waypointer.codec;

import com.google.gson.Gson;
import com.google.gson.JsonParseException;
import com.waypointer.model.route.Route;
import javax.inject.Inject;

/**
 * Encodes/decodes a single route share code:
 *   RT1:&lt;base64(gzip(json))&gt;
 *
 * Soft cap: gunzipped payload must be &lt; 1 MiB. Mirrors {@link WaypointShareCodec}.
 */
public class RouteShareCodec
{
    public static final String ROUTE_MAGIC = "RT1:";

    private final Gson gson;

    @Inject
    public RouteShareCodec(Gson gson) { this.gson = gson; }

    public String encodeRoute(Route route)
    {
        return ROUTE_MAGIC + ShareCodecSupport.gzipBase64(gson.toJson(route));
    }

    public Route decodeRoute(String input)
    {
        String body = ShareCodecSupport.stripMagic(input, ROUTE_MAGIC, MalformedCodeException::new);
        String json = ShareCodecSupport.ungzipBase64(body, MalformedCodeException::new);
        final Route route;
        try
        {
            route = gson.fromJson(json, Route.class);
        }
        catch (JsonParseException e)
        {
            throw new MalformedCodeException("Bad JSON inside route code");
        }
        if (route == null || route.getName() == null)
        {
            throw new MalformedCodeException("Route decoded as null or nameless");
        }
        if (route.getSteps() == null) route.setSteps(new java.util.ArrayList<>());
        return route;
    }

    public static class MalformedCodeException extends RuntimeException
    {
        public MalformedCodeException(String msg) { super(msg); }
    }
}

package com.waypointer.codec;

import com.google.gson.Gson;
import com.google.gson.JsonObject;
import com.google.gson.JsonParseException;
import com.google.gson.JsonParser;
import java.util.function.Function;
import java.util.function.IntFunction;

/**
 * Shared JSON-decode skeleton for the versioned library codecs. Holds the one tolerated
 * {@code new JsonParser()} deprecation so the per-entity codecs stay clean. Each codec keeps
 * its own exception types and supplies them as factories, preserving its public catch contract.
 */
final class JsonDecodeSupport
{
    private JsonDecodeSupport() {}

    /** Migration seam matching {@code LibraryMigrator}/{@code RouteMigrator}'s static signature. */
    @FunctionalInterface
    interface Migrator
    {
        JsonObject migrate(JsonObject obj, int fromVersion);
    }

    /**
     * Parse JSON to an object, wrapping any parse failure via {@code onMalformed}. The single
     * tolerated deprecated {@code JsonParser} call lives here (RuneLite's Gson 2.8.5 predates
     * {@code JsonParser.parseString}).
     */
    static JsonObject parseObject(String json, Function<Throwable, RuntimeException> onMalformed)
    {
        try
        {
            @SuppressWarnings("deprecation")
            JsonObject parsed = new JsonParser().parse(json).getAsJsonObject();
            return parsed;
        }
        catch (JsonParseException | IllegalStateException e)
        {
            throw onMalformed.apply(e);
        }
    }

    /**
     * The shared parse -> version-guard -> migrate -> bind skeleton. Per-entity field defaults
     * stay in the caller (they differ per codec) and run on the returned object.
     */
    static <T> T decode(
        Gson gson,
        String json,
        int currentSchemaVersion,
        Migrator migrator,
        Class<T> type,
        Function<Throwable, RuntimeException> onMalformed,
        IntFunction<RuntimeException> onUnsupported)
    {
        JsonObject obj = parseObject(json, onMalformed);

        // Treat a missing schemaVersion as 0 (pre-versioned) so the migrator runs. Trusting the
        // current version here would silently skip every future migration on legacy files.
        int version = obj.has("schemaVersion") ? obj.get("schemaVersion").getAsInt() : 0;
        if (version > currentSchemaVersion)
        {
            throw onUnsupported.apply(version);
        }
        return gson.fromJson(migrator.migrate(obj, version), type);
    }
}

package com.waypointer.codec;

import com.google.gson.JsonElement;
import com.google.gson.JsonObject;

/**
 * Schema-version migration for {@link com.waypointer.model.route.RouteLibrary}.
 *
 * <p>v1 -> v2: route steps gained a {@code boxText} field (the in-game route-box text, distinct
 * from the sidebar {@code label}). Older files have only {@code label}; backfill {@code boxText}
 * from it so existing routes read identically in the box.
 */
public final class RouteMigrator
{
    private RouteMigrator() {}

    public static JsonObject migrate(JsonObject obj, int fromVersion)
    {
        if (fromVersion < 2)
        {
            backfillBoxText(obj);
            obj.addProperty("schemaVersion", 2);
        }
        return obj;
    }

    private static void backfillBoxText(JsonObject obj)
    {
        if (!obj.has("routes") || !obj.get("routes").isJsonArray()) return;
        for (JsonElement routeEl : obj.getAsJsonArray("routes"))
        {
            if (!routeEl.isJsonObject()) continue;
            JsonObject route = routeEl.getAsJsonObject();
            if (!route.has("steps") || !route.get("steps").isJsonArray()) continue;
            for (JsonElement stepEl : route.getAsJsonArray("steps"))
            {
                if (!stepEl.isJsonObject()) continue;
                JsonObject step = stepEl.getAsJsonObject();
                if (!step.has("boxText") && step.has("label"))
                {
                    step.add("boxText", step.get("label"));
                }
            }
        }
    }
}

package com.waypointer.codec;

import com.google.gson.Gson;
import com.waypointer.model.Library;
import javax.inject.Inject;

/** Encodes/decodes a Library to/from JSON. Handles schema version checks and missing fields. */
public class LibraryJsonCodec
{
    private final Gson gson;

    @Inject
    public LibraryJsonCodec(Gson injectedGson)
    {
        this.gson = injectedGson;
    }

    public String encode(Library lib)
    {
        return gson.toJson(lib);
    }

    public Library decode(String json)
    {
        Library lib = JsonDecodeSupport.decode(
            gson, json, Library.CURRENT_SCHEMA_VERSION, LibraryMigrator::migrate, Library.class,
            e -> new MalformedLibraryException("Failed to parse library JSON", e),
            v -> new UnsupportedSchemaException(
                "Library schemaVersion " + v + " is newer than supported "
                    + Library.CURRENT_SCHEMA_VERSION));
        // Defensive: Gson may leave nulls if fields were absent.
        if (lib.getCategories() == null) lib.setCategories(new java.util.ArrayList<>());
        if (lib.getWaypoints() == null) lib.setWaypoints(new java.util.ArrayList<>());
        if (lib.getSchemaVersion() == 0) lib.setSchemaVersion(Library.CURRENT_SCHEMA_VERSION);
        return lib;
    }

    public static class MalformedLibraryException extends RuntimeException
    {
        public MalformedLibraryException(String msg, Throwable cause) { super(msg, cause); }
    }

    public static class UnsupportedSchemaException extends RuntimeException
    {
        public UnsupportedSchemaException(String msg) { super(msg); }
    }
}

